/// Reserve one bounded replay slot without evicting an operation whose
/// successful Result still names a live resource. Retired settlements leave
/// FIFO tombstones until newer admitted operations consume the advertised
/// horizon.
fn make_operation_replay_room<T>(
    values: &mut HashMap<[u8; 16], T>,
    order: &mut VecDeque<[u8; 16]>,
    capacity: usize,
    reserved: usize,
    mut is_live: impl FnMut(&T) -> bool,
) -> bool {
    while values.len().saturating_add(reserved) >= capacity {
        let Some(index) = order.iter().position(|operation_id| {
            values
                .get(operation_id)
                .is_some_and(|replay| !is_live(replay))
        }) else {
            return false;
        };
        let operation_id = order
            .remove(index)
            .expect("replay order index remains valid");
        values.remove(&operation_id);
    }
    true
}

fn insert_operation_replay<T>(
    values: &mut HashMap<[u8; 16], T>,
    order: &mut VecDeque<[u8; 16]>,
    operation_id: [u8; 16],
    replay: T,
) {
    if values.insert(operation_id, replay).is_none() {
        order.push_back(operation_id);
    }
}

static MONOTONIC_EPOCH: LazyLock<Instant> = LazyLock::new(Instant::now);

async fn finish_native_shutdown(
    state: AppState,
    coordinator: Arc<ShutdownCoordinator>,
    grace_ns: u64,
    close_deadline_server_ns: u64,
    acknowledgements: Vec<oneshot::Receiver<()>>,
) {
    if grace_ns == 0 {
        // Immediate remains orderly: give every healthy writer a bounded
        // chance to put GOAWAY on the stream before cancelling native tasks.
        let _ = tokio::time::timeout(CORE_CONTROL_WRITE_TIMEOUT, async {
            for acknowledgement in acknowledgements {
                let _ = acknowledgement.await;
            }
        })
        .await;
    } else {
        drop(acknowledgements);
        let remaining = close_deadline_server_ns.saturating_sub(monotonic_ns());
        if remaining != 0 {
            tokio::time::sleep(Duration::from_nanos(remaining)).await;
        }
    }
    // Core's advertised deadline applies to every native session before common
    // process teardown begins.
    coordinator.cancel_sessions();
    begin_server_shutdown(&state).await;
}

fn upload_stage_deadline() -> Result<u64, ()> {
    monotonic_ns()
        .checked_add(yas_wire::transfer::MAX_UPLOAD_STAGE_LIFETIME_NS)
        .ok_or(())
}

fn upload_stage_extensions(staging_handle: u64, expires_server_ns: u64) -> Result<Extensions, ()> {
    let upload = UploadStage {
        staging_handle,
        expires_server_ns,
    }
    .extension()
    .map_err(|_| ())?;
    Ok(Extensions(vec![
        Extension {
            tag: yas_wire::schema::transfer::SENSITIVE_CONTENT_EXTENSION as u16,
            required: true,
            value: Vec::new(),
        },
        upload,
    ]))
}

/// Session-global Selection authority shared by native clients.
/// Individual wire sessions keep only staging resources; committed slot identity,
/// revisions, bytes, and operation replay live here so two YAS connections
/// observe one clipboard rather than parallel per-connection mirrors.
#[derive(Clone)]
pub(crate) struct SelectionStore {
    inner: Arc<std::sync::Mutex<SelectionStoreInner>>,
    updates: tokio::sync::watch::Sender<SelectionSnapshot>,
}

struct SelectionStoreInner {
    snapshot: SelectionSnapshot,
    operations: HashMap<([u8; 16], u16, [u8; 16]), SelectionOperationReplay>,
    next_drag_handle: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct SelectionSnapshot {
    revision: u64,
    slots: BTreeMap<u8, SelectionSlot>,
    drags: BTreeMap<u64, yas_selection::DragRecord>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct SelectionSlot {
    record: yas_selection::SelectionRecord,
    items: BTreeMap<String, Arc<Vec<u8>>>,
}

enum SelectionItem {
    Retained(Arc<Vec<u8>>),
    Compositor(u64),
}

struct SelectionOperationReplay {
    fingerprint: [u8; 32],
    status: Status,
    handle: u64,
    revision: u64,
}

fn make_selection_operation_room(inner: &mut SelectionStoreInner) -> bool {
    if inner.operations.len() < MAX_SELECTION_OPERATION_REPLAYS {
        return true;
    }
    // An operation that installed either currently visible slot remains
    // replayable for the lifetime of that selection. Older clipboard state
    // is no longer an affected resource and can leave the bounded boot cache.
    let stale = inner.operations.iter().find_map(|(key, replay)| {
        (!inner
            .snapshot
            .slots
            .values()
            .any(|slot| slot.record.revision == replay.revision)
            && !inner
                .snapshot
                .drags
                .values()
                .any(|drag| drag.revision == replay.revision))
        .then_some(*key)
    });
    if let Some(stale) = stale {
        inner.operations.remove(&stale);
    }
    inner.operations.len() < MAX_SELECTION_OPERATION_REPLAYS
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SelectionStoreError {
    Conflict,
    Stale,
    NotFound,
    ResourceExhausted,
}

impl SelectionStore {
    pub(crate) fn new() -> Self {
        let slots = [
            yas_wire::schema::selection::SLOT_CLIPBOARD as u8,
            yas_wire::schema::selection::SLOT_PRIMARY as u8,
        ]
        .into_iter()
        .map(|slot| {
            (
                slot,
                SelectionSlot {
                    record: yas_selection::SelectionRecord {
                        slot,
                        owner_kind: yas_wire::schema::selection::OWNER_NONE as u8,
                        owner_handle: 0,
                        revision: 1,
                        mime_types: Vec::new(),
                        extensions: Extensions::default(),
                    },
                    items: BTreeMap::new(),
                },
            )
        })
        .collect();
        let snapshot = SelectionSnapshot {
            revision: 1,
            slots,
            drags: BTreeMap::new(),
        };
        let (updates, _) = tokio::sync::watch::channel(snapshot.clone());
        Self {
            inner: Arc::new(std::sync::Mutex::new(SelectionStoreInner {
                snapshot,
                operations: HashMap::new(),
                next_drag_handle: 1,
            })),
            updates,
        }
    }

    fn snapshot(&self) -> SelectionSnapshot {
        self.inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .snapshot
            .clone()
    }

    fn subscribe(&self) -> tokio::sync::watch::Receiver<SelectionSnapshot> {
        self.updates.subscribe()
    }

    /// Replace the clipboard record with the offer owned by a Wayland data
    /// source. Its bytes stay in that source and are fetched through the
    /// compositor only when a Selection client issues GET.
    pub(crate) fn set_compositor_clipboard(&self, generation: u64, mut mime_types: Vec<String>) {
        mime_types.retain(|mime| !mime.is_empty() && mime.len() <= yas_selection::MAX_MIME_BYTES);
        mime_types.sort();
        mime_types.dedup();
        mime_types.truncate(yas_selection::MAX_ITEMS);

        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let revision = inner.snapshot.revision.saturating_add(1).max(1);
        inner.snapshot.revision = revision;
        inner.snapshot.slots.insert(
            yas_wire::schema::selection::SLOT_CLIPBOARD as u8,
            SelectionSlot {
                record: yas_selection::SelectionRecord {
                    slot: yas_wire::schema::selection::SLOT_CLIPBOARD as u8,
                    owner_kind: yas_wire::schema::selection::OWNER_EXTERNAL as u8,
                    owner_handle: generation,
                    revision,
                    mime_types,
                    extensions: Extensions::default(),
                },
                items: BTreeMap::new(),
            },
        );
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
    }

    /// Withdraw a compositor-owned clipboard without disturbing a browser or
    /// CLI selection whose publication generated the same owner notification.
    pub(crate) fn clear_compositor_clipboard(&self) {
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let slot = yas_wire::schema::selection::SLOT_CLIPBOARD as u8;
        if inner.snapshot.slots.get(&slot).is_none_or(|current| {
            current.record.owner_kind != yas_wire::schema::selection::OWNER_EXTERNAL as u8
        }) {
            return;
        }
        let revision = inner.snapshot.revision.saturating_add(1).max(1);
        inner.snapshot.revision = revision;
        inner.snapshot.slots.insert(
            slot,
            SelectionSlot {
                record: yas_selection::SelectionRecord {
                    slot,
                    owner_kind: yas_wire::schema::selection::OWNER_NONE as u8,
                    owner_handle: 0,
                    revision,
                    mime_types: Vec::new(),
                    extensions: Extensions::default(),
                },
                items: BTreeMap::new(),
            },
        );
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
    }

    fn set(
        &self,
        session_id: [u8; 16],
        operation_kind: u16,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        slot: u8,
        items: BTreeMap<String, Arc<Vec<u8>>>,
    ) -> Result<(u64, bool), SelectionStoreError> {
        let key = (session_id, operation_kind, operation_id);
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(replay) = inner.operations.get(&key) {
            if replay.fingerprint != fingerprint {
                return Err(SelectionStoreError::Conflict);
            }
            return if replay.status == Status::Ok {
                Ok((replay.revision, true))
            } else {
                Err(SelectionStoreError::Conflict)
            };
        }
        if !make_selection_operation_room(&mut inner) {
            return Err(SelectionStoreError::ResourceExhausted);
        }
        let revision = inner.snapshot.revision.saturating_add(1).max(1);
        let owner_handle = selection_owner_handle(session_id);
        let record = yas_selection::SelectionRecord {
            slot,
            owner_kind: yas_wire::schema::selection::OWNER_SESSION as u8,
            owner_handle,
            revision,
            mime_types: items.keys().cloned().collect(),
            extensions: Extensions::default(),
        };
        inner.snapshot.revision = revision;
        inner
            .snapshot
            .slots
            .insert(slot, SelectionSlot { record, items });
        inner.operations.insert(
            key,
            SelectionOperationReplay {
                fingerprint,
                status: Status::Ok,
                handle: 0,
                revision,
            },
        );
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        Ok((revision, false))
    }

    fn clear(
        &self,
        session_id: [u8; 16],
        operation_kind: u16,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        slot: u8,
        observed_revision: u64,
    ) -> Result<(u64, bool), SelectionStoreError> {
        let key = (session_id, operation_kind, operation_id);
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(replay) = inner.operations.get(&key) {
            if replay.fingerprint != fingerprint {
                return Err(SelectionStoreError::Conflict);
            }
            return if replay.status == Status::Ok {
                Ok((replay.revision, true))
            } else {
                Err(SelectionStoreError::Conflict)
            };
        }
        if !make_selection_operation_room(&mut inner) {
            return Err(SelectionStoreError::ResourceExhausted);
        }
        if inner
            .snapshot
            .slots
            .get(&slot)
            .is_none_or(|current| current.record.revision != observed_revision)
        {
            return Err(SelectionStoreError::Stale);
        }
        let revision = inner.snapshot.revision.saturating_add(1).max(1);
        inner.snapshot.revision = revision;
        inner.snapshot.slots.insert(
            slot,
            SelectionSlot {
                record: yas_selection::SelectionRecord {
                    slot,
                    owner_kind: yas_wire::schema::selection::OWNER_NONE as u8,
                    owner_handle: 0,
                    revision,
                    mime_types: Vec::new(),
                    extensions: Extensions::default(),
                },
                items: BTreeMap::new(),
            },
        );
        inner.operations.insert(
            key,
            SelectionOperationReplay {
                fingerprint,
                status: Status::Ok,
                handle: 0,
                revision,
            },
        );
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        Ok((revision, false))
    }

    fn get(
        &self,
        slot: u8,
        revision: u64,
        mime: &str,
    ) -> Result<SelectionItem, SelectionStoreError> {
        let inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let current = inner
            .snapshot
            .slots
            .get(&slot)
            .ok_or(SelectionStoreError::Stale)?;
        if current.record.revision != revision {
            return Err(SelectionStoreError::Stale);
        }
        if let Some(bytes) = current.items.get(mime) {
            return Ok(SelectionItem::Retained(bytes.clone()));
        }
        if current.record.owner_kind == yas_wire::schema::selection::OWNER_EXTERNAL as u8
            && current
                .record
                .mime_types
                .iter()
                .any(|offered| offered == mime)
        {
            return Ok(SelectionItem::Compositor(current.record.owner_handle));
        }
        Err(SelectionStoreError::NotFound)
    }

    fn drag_begin(
        &self,
        session_id: [u8; 16],
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        source_actions: u16,
        items: Vec<yas_selection::DragItem>,
        maximum_active: usize,
    ) -> Result<(u64, u64, bool), SelectionStoreError> {
        let key = (
            session_id,
            yas_wire::schema::selection::request::DRAG_BEGIN,
            operation_id,
        );
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(replay) = inner.operations.get(&key) {
            if replay.fingerprint != fingerprint {
                return Err(SelectionStoreError::Conflict);
            }
            return if replay.status == Status::Ok {
                Ok((replay.handle, replay.revision, true))
            } else {
                Err(SelectionStoreError::Conflict)
            };
        }
        if inner
            .snapshot
            .drags
            .values()
            .filter(|drag| drag.owner_session == session_id)
            .count()
            >= maximum_active
            || !make_selection_operation_room(&mut inner)
        {
            return Err(SelectionStoreError::ResourceExhausted);
        }
        let drag_handle = inner.next_drag_handle;
        if drag_handle == 0 {
            return Err(SelectionStoreError::ResourceExhausted);
        }
        inner.next_drag_handle = drag_handle
            .checked_add(1)
            .ok_or(SelectionStoreError::ResourceExhausted)?;
        let revision = inner.snapshot.revision.saturating_add(1).max(1);
        inner.snapshot.revision = revision;
        inner.snapshot.drags.insert(
            drag_handle,
            yas_selection::DragRecord {
                drag_handle,
                revision,
                owner_session: session_id,
                source_actions,
                selected_action: 0,
                target_surface: 0,
                items,
                extensions: Extensions::default(),
            },
        );
        inner.operations.insert(
            key,
            SelectionOperationReplay {
                fingerprint,
                status: Status::Ok,
                handle: drag_handle,
                revision,
            },
        );
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        Ok((drag_handle, revision, false))
    }

    fn drag_record(
        &self,
        session_id: [u8; 16],
        drag_handle: u64,
        revision: u64,
    ) -> Result<yas_selection::DragRecord, SelectionStoreError> {
        let inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let record = inner
            .snapshot
            .drags
            .get(&drag_handle)
            .ok_or(SelectionStoreError::NotFound)?;
        if record.owner_session != session_id || record.revision != revision {
            return Err(SelectionStoreError::Stale);
        }
        Ok(record.clone())
    }

    fn drag_update_target(
        &self,
        session_id: [u8; 16],
        drag_handle: u64,
        revision: u64,
        target_surface: u64,
    ) -> Result<yas_selection::DragRecord, SelectionStoreError> {
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let record = inner
            .snapshot
            .drags
            .get_mut(&drag_handle)
            .ok_or(SelectionStoreError::NotFound)?;
        if record.owner_session != session_id || record.revision != revision {
            return Err(SelectionStoreError::Stale);
        }
        if record.target_surface == target_surface {
            return Ok(record.clone());
        }
        record.target_surface = target_surface;
        let record = record.clone();
        inner.snapshot.revision = inner.snapshot.revision.saturating_add(1).max(1);
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        Ok(record)
    }

    fn drag_set_drop_metadata(
        &self,
        session_id: [u8; 16],
        drag_handle: u64,
        revision: u64,
        selected_action: u16,
        items: Vec<yas_selection::DragItem>,
    ) -> Result<yas_selection::DragRecord, SelectionStoreError> {
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let record = inner
            .snapshot
            .drags
            .get_mut(&drag_handle)
            .ok_or(SelectionStoreError::NotFound)?;
        if record.owner_session != session_id || record.revision != revision {
            return Err(SelectionStoreError::Stale);
        }
        if selected_action == 0 || selected_action & !record.source_actions != 0 {
            return Err(SelectionStoreError::Conflict);
        }
        record.selected_action = selected_action;
        record.items = items;
        let record = record.clone();
        inner.snapshot.revision = inner.snapshot.revision.saturating_add(1).max(1);
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        Ok(record)
    }

    fn drag_operation_replay(
        &self,
        session_id: [u8; 16],
        operation_kind: u16,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
    ) -> Result<Option<Status>, SelectionStoreError> {
        let inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Some(replay) = inner
            .operations
            .get(&(session_id, operation_kind, operation_id))
        else {
            return Ok(None);
        };
        if replay.fingerprint != fingerprint {
            return Err(SelectionStoreError::Conflict);
        }
        Ok(Some(replay.status))
    }

    #[allow(clippy::too_many_arguments)]
    fn drag_finish(
        &self,
        session_id: [u8; 16],
        operation_kind: u16,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        drag_handle: u64,
        revision: u64,
        status: Status,
    ) -> Result<(), SelectionStoreError> {
        let key = (session_id, operation_kind, operation_id);
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(replay) = inner.operations.get(&key) {
            if replay.fingerprint != fingerprint {
                return Err(SelectionStoreError::Conflict);
            }
            return Ok(());
        }
        if !make_selection_operation_room(&mut inner) {
            return Err(SelectionStoreError::ResourceExhausted);
        }
        let record = inner
            .snapshot
            .drags
            .get(&drag_handle)
            .ok_or(SelectionStoreError::NotFound)?;
        if record.owner_session != session_id || record.revision != revision {
            return Err(SelectionStoreError::Stale);
        }
        inner.snapshot.drags.remove(&drag_handle);
        inner.snapshot.revision = inner.snapshot.revision.saturating_add(1).max(1);
        inner.operations.insert(
            key,
            SelectionOperationReplay {
                fingerprint,
                status,
                handle: drag_handle,
                revision,
            },
        );
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        Ok(())
    }

    fn remove_session_drags(&self, session_id: [u8; 16]) -> bool {
        let mut inner = self
            .inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let before = inner.snapshot.drags.len();
        inner
            .snapshot
            .drags
            .retain(|_, drag| drag.owner_session != session_id);
        if inner.snapshot.drags.len() == before {
            return false;
        }
        inner.snapshot.revision = inner.snapshot.revision.saturating_add(1).max(1);
        let snapshot = inner.snapshot.clone();
        drop(inner);
        self.updates.send_replace(snapshot);
        true
    }
}

fn selection_owner_handle(session_id: [u8; 16]) -> u64 {
    let digest = blake3::hash(&session_id);
    u64::from_le_bytes(digest.as_bytes()[..8].try_into().expect("fixed digest")) | 1
}

#[cfg(test)]
struct TerminalWriterGate {
    armed: AtomicBool,
    reached: Notify,
    release: Notify,
}

#[cfg(test)]
impl TerminalWriterGate {
    fn new() -> Self {
        Self {
            armed: AtomicBool::new(true),
            reached: Notify::new(),
            release: Notify::new(),
        }
    }

    async fn wait_until_reached(&self) {
        self.reached.notified().await;
    }

    fn release(&self) {
        self.release.notify_one();
    }
}

#[cfg(test)]
struct OutboundWriterGate {
    family: u16,
    kind: u16,
    request_id: u32,
    discard: bool,
    armed: AtomicBool,
    reached: Notify,
    release: Notify,
}

#[cfg(test)]
impl OutboundWriterGate {
    fn result(family: u16, kind: u16, request_id: u32, discard: bool) -> Self {
        Self {
            family,
            kind,
            request_id,
            discard,
            armed: AtomicBool::new(true),
            reached: Notify::new(),
            release: Notify::new(),
        }
    }

    fn matches(&self, frame: &Frame) -> bool {
        frame.header.class == Class::Result
            && frame.header.family == self.family
            && frame.header.kind == self.kind
            && frame.header.request_id == Some(self.request_id)
    }

    async fn wait_until_reached(&self) {
        self.reached.notified().await;
    }

    fn release(&self) {
        self.release.notify_one();
    }
}

