#[cfg(test)]
#[derive(Default)]
struct SurfaceWatchPublicationProbe {
    generation: AtomicU64,
    changed: Notify,
}

#[cfg(test)]
impl SurfaceWatchPublicationProbe {
    fn generation(&self) -> u64 {
        self.generation.load(Ordering::Acquire)
    }

    fn published(&self) {
        self.generation.fetch_add(1, Ordering::AcqRel);
        self.changed.notify_waiters();
    }

    async fn wait_after(&self, generation: u64) {
        loop {
            let changed = self.changed.notified();
            if self.generation() > generation {
                return;
            }
            changed.await;
        }
    }
}

#[derive(Clone)]
struct Services {
    app_state: Option<AppState>,
    ping_interval: Duration,
    diagnostics: Arc<super::ServerDiagnosticsRegistry>,
    shutdown: Option<Arc<ShutdownCoordinator>>,
    server_name: String,
    /// Canonical automatic endpoint with a literal `{name}` placeholder,
    /// published to extensions as `YAS_SOCKET_TEMPLATE` (see
    /// [`super::Config::automatic_ipc_template`]).
    automatic_ipc_template: String,
    boot_id: [u8; 16],
    relay_catalogue: Option<Arc<RelayRouteCatalog>>,
    relay_connector: Arc<dyn RelayConnector>,
    font_catalogue: Option<super::font::Catalog>,
    font_fetch_slots: Arc<Semaphore>,
    env_enabled: bool,
    kv_enabled: bool,
    channel_enabled: bool,
    net_enabled: bool,
    net_policy: super::net::Policy,
    events: Option<super::yas_events::Runtime>,
    fs: Option<super::yas_fs::Runtime>,
    git: Option<super::yas_git_adapter::Runtime>,
    lsp: Option<super::yas_lsp_adapter::Runtime>,
    extension: Option<super::yas_extension::Runtime>,
    process: Option<super::yas_process::Runtime>,
    selection: Option<SelectionStore>,
    #[cfg(test)]
    env_snapshot_override: Option<Vec<yas_wire::env::Entry>>,
    #[cfg(test)]
    receive_max_buffered_override: Option<u64>,
    #[cfg(test)]
    outbound_max_override: Option<u64>,
    #[cfg(test)]
    terminal_writer_gate: Option<Arc<TerminalWriterGate>>,
    #[cfg(test)]
    outbound_writer_gate: Option<Arc<OutboundWriterGate>>,
    #[cfg(test)]
    events_stream_publication_probe: Option<Arc<EventsStreamPublicationProbe>>,
    #[cfg(test)]
    terminal_frame_drop_probe: Option<Arc<TerminalFrameDropProbe>>,
    #[cfg(test)]
    surface_watch_publication_probe: Option<Arc<SurfaceWatchPublicationProbe>>,
    /// Deterministic public-wire Media input backend for qualification tests.
    /// Production builds always use the compositor/PipeWire backend below.
    #[cfg(all(test, target_os = "linux"))]
    media_input_lease_override: Option<
        Arc<dyn Fn(super::media_input::InputStart) -> super::media_input::InputLease + Send + Sync>,
    >,
}

impl Services {
    fn from_state(state: &AppState) -> Self {
        let mut boot_material = Vec::new();
        boot_material.extend_from_slice(&state.boot_generation.to_le_bytes());
        boot_material.extend_from_slice(state.config.name.as_str().as_bytes());
        let digest = blake3::hash(&boot_material);
        let mut boot_id = [0; 16];
        boot_id.copy_from_slice(&digest.as_bytes()[..16]);
        Self {
            app_state: Some(state.clone()),
            ping_interval: state.config.ping_interval,
            diagnostics: Arc::clone(&state.diagnostics),
            shutdown: Some(Arc::clone(&state.yas_shutdown)),
            server_name: state.config.name.as_str().to_owned(),
            automatic_ipc_template: state.config.automatic_ipc_template.clone(),
            boot_id,
            relay_catalogue: state.relay.catalogue(),
            relay_connector: state.relay.connector(),
            font_catalogue: state.fonts.catalog(),
            font_fetch_slots: state.fonts.fetch_slots(),
            env_enabled: !std::env::var("YAS_ENV").is_ok_and(|value| value == "0"),
            kv_enabled: !std::env::var("YAS_KV").is_ok_and(|value| value == "0"),
            channel_enabled: super::channels_enabled(),
            net_enabled: !std::env::var("YAS_NET").is_ok_and(|value| value == "0"),
            net_policy: super::net::Policy::new(
                state.config.allow_forward_insecure,
                &state.config.allow_forward,
            ),
            events: Some(super::yas_events::Runtime::new(state.events.clone())),
            fs: Some(super::yas_fs::Runtime::new(state.clone())),
            git: Some(super::yas_git_adapter::Runtime::new(state.clone())),
            lsp: Some(super::yas_lsp_adapter::Runtime::new(state.clone())),
            extension: Some(super::yas_extension::Runtime::new(state.clone())),
            process: Some(super::yas_process::Runtime::new(
                state.process_server.clone(),
            )),
            selection: Some(state.selection.clone()),
            #[cfg(test)]
            env_snapshot_override: None,
            #[cfg(test)]
            receive_max_buffered_override: None,
            #[cfg(test)]
            outbound_max_override: None,
            #[cfg(test)]
            terminal_writer_gate: None,
            #[cfg(test)]
            outbound_writer_gate: None,
            #[cfg(test)]
            events_stream_publication_probe: None,
            #[cfg(test)]
            terminal_frame_drop_probe: None,
            #[cfg(test)]
            surface_watch_publication_probe: None,
            #[cfg(all(test, target_os = "linux"))]
            media_input_lease_override: None,
        }
    }

    fn environment_snapshot(&self) -> Vec<yas_wire::env::Entry> {
        #[cfg(test)]
        if let Some(entries) = &self.env_snapshot_override {
            let mut entries = entries
                .iter()
                .cloned()
                .map(|entry| (entry.key, entry.value))
                .collect::<BTreeMap<_, _>>();
            entries.insert(
                b"YAS_SERVER_NAME".to_vec(),
                self.server_name.as_bytes().to_vec(),
            );
            entries.insert(
                b"YAS_SOCKET_TEMPLATE".to_vec(),
                self.automatic_ipc_template.as_bytes().to_vec(),
            );
            return entries
                .into_iter()
                .map(|(key, value)| yas_wire::env::Entry { key, value })
                .collect();
        }

        let mut entries = std::env::vars_os()
            .map(|(key, value)| {
                #[cfg(unix)]
                {
                    use std::os::unix::ffi::OsStringExt;
                    (key.into_vec(), value.into_vec())
                }
                #[cfg(not(unix))]
                {
                    (
                        key.to_string_lossy().into_owned().into_bytes(),
                        value.to_string_lossy().into_owned().into_bytes(),
                    )
                }
            })
            .collect::<BTreeMap<_, _>>();
        // This is the effective configured identity, not merely the value the
        // parent process happened to export before configuration was loaded.
        entries.insert(
            b"YAS_SERVER_NAME".to_vec(),
            self.server_name.as_bytes().to_vec(),
        );
        // How to spell *another* named server's endpoint. An extension that
        // supervises servers (muster) has to name the socket of an instance
        // that does not exist yet, and the naming rule is this process's to
        // know, not something a configuration file should restate. Absent
        // when this build could not derive one, which a reader must handle
        // rather than substituting a guess.
        if !self.automatic_ipc_template.is_empty() {
            entries.insert(
                b"YAS_SOCKET_TEMPLATE".to_vec(),
                self.automatic_ipc_template.as_bytes().to_vec(),
            );
        }
        entries
            .into_iter()
            .map(|(key, value)| yas_wire::env::Entry { key, value })
            .collect()
    }

    fn diagnostics_snapshot(&self) -> yas_wire::core::ServerDiagnostics {
        self.diagnostics.snapshot()
    }
}

