impl ProcessRuntime {
    fn new(
        service: super::yas_process::Runtime,
        session_id: [u8; 16],
        session_env: Option<super::app_env::SessionEnv>,
    ) -> Option<Self> {
        let session = service.session(session_id, session_env).ok()?;
        Some(Self {
            service,
            session,
            attachments: HashMap::new(),
            transfer_to_attachment: HashMap::new(),
            operations: HashMap::new(),
            operation_order: VecDeque::new(),
        })
    }

    fn make_operation_room(&mut self, reserved: usize) -> bool {
        let attachments = &self.attachments;
        make_operation_replay_room(
            &mut self.operations,
            &mut self.operation_order,
            MAX_PROCESS_OPERATION_REPLAYS,
            reserved,
            |replay| {
                replay.attachment_id.is_some_and(|attachment_id| {
                    attachments.get(&attachment_id).is_some_and(|attachment| {
                        attachment.stream_bundle_replayable.load(Ordering::Acquire)
                    })
                })
            },
        )
    }
}

