enum FsQueryRequest {
    Read(yas_fs_wire::Read),
    Search(yas_fs_wire::Search),
    Index(yas_fs_wire::Index),
    Grep(yas_fs_wire::Grep),
}

fn is_fs_semantic_operation(kind: u16) -> bool {
    matches!(
        kind,
        yas_wire::schema::fs::request::OPEN
            | yas_wire::schema::fs::request::WATCH
            | yas_wire::schema::fs::request::FETCH
            | yas_wire::schema::fs::request::READ
            | yas_wire::schema::fs::request::SEARCH
            | yas_wire::schema::fs::request::INDEX
            | yas_wire::schema::fs::request::GREP
            | yas_wire::schema::fs::request::COMMIT
            | yas_wire::schema::fs::request::APPLY
    )
}

impl FsQueryRequest {
    fn initial_receive_credit(&self) -> u64 {
        match self {
            Self::Read(request) => request.initial_receive_credit,
            Self::Search(request) => request.initial_receive_credit,
            Self::Index(request) => request.initial_receive_credit,
            Self::Grep(request) => request.initial_receive_credit,
        }
    }

    async fn execute(
        self,
        session: super::yas_fs::Session,
    ) -> Result<super::yas_fs::QueryData, super::yas_fs::Error> {
        match self {
            Self::Read(request) => session.read(&request).await,
            Self::Search(request) => session.search(&request).await,
            Self::Index(request) => session.index(&request).await,
            Self::Grep(request) => session.grep(&request).await,
        }
    }
}

