#[derive(Clone)]
enum NativeMessageSocket {
    #[cfg(unix)]
    Unix(Arc<super::net::NativeUnixSeqpacket>),
    #[cfg(windows)]
    Windows(Arc<super::net::NativeWindowsMessagePipe>),
}

impl NativeMessageSocket {
    async fn send(&self, payload: &[u8]) -> std::io::Result<usize> {
        match self {
            #[cfg(unix)]
            Self::Unix(socket) => socket.send(payload).await,
            #[cfg(windows)]
            Self::Windows(socket) => socket.send(payload).await,
        }
    }

    async fn recv(&self, payload: &mut [u8]) -> std::io::Result<usize> {
        match self {
            #[cfg(unix)]
            Self::Unix(socket) => socket.recv(payload).await,
            #[cfg(windows)]
            Self::Windows(socket) => socket.recv(payload).await,
        }
    }

    fn shutdown_write(&self) -> std::io::Result<()> {
        match self {
            #[cfg(unix)]
            Self::Unix(socket) => socket.shutdown_write(),
            #[cfg(windows)]
            Self::Windows(socket) => socket.shutdown_write(),
        }
    }
}

enum NativeDatagramSocket {
    Udp(Arc<tokio::net::UdpSocket>),
    #[cfg(unix)]
    Unix {
        socket: Arc<tokio::net::UnixDatagram>,
        _owner: super::net::NativeUnixDatagram,
    },
}

impl NativeDatagramSocket {
    async fn send(&self, payload: &[u8]) -> std::io::Result<usize> {
        match self {
            Self::Udp(socket) => socket.send(payload).await,
            #[cfg(unix)]
            Self::Unix { socket, .. } => socket.send(payload).await,
        }
    }

    async fn recv(&self, payload: &mut [u8]) -> std::io::Result<usize> {
        match self {
            Self::Udp(socket) => socket.recv(payload).await,
            #[cfg(unix)]
            Self::Unix { socket, .. } => socket.recv(payload).await,
        }
    }
}

