impl SelectionRuntime {
    fn new(store: SelectionStore) -> Self {
        Self {
            store,
            next_staging_handle: 1,
            stages: HashMap::new(),
            transfer_to_stage: HashMap::new(),
            begin_operations: HashMap::new(),
            begin_operation_order: VecDeque::new(),
            commit_operations: HashMap::new(),
            next_get_request_id: 1,
            pending_gets: HashMap::new(),
            pending_drops: HashMap::new(),
            drag_transfers: HashMap::new(),
            drag_positions: HashMap::new(),
            drag_files: HashMap::new(),
        }
    }

    fn prepare_drag_files(
        &mut self,
        drag_handle: u64,
        names: &[&str],
    ) -> std::io::Result<Vec<Option<std::path::PathBuf>>> {
        if names.iter().all(|name| name.is_empty()) {
            return Ok(vec![None; names.len()]);
        }
        if let std::collections::hash_map::Entry::Vacant(entry) = self.drag_files.entry(drag_handle)
        {
            entry.insert(super::yas_drag_files::DragFiles::new()?);
        }
        self.drag_files
            .get_mut(&drag_handle)
            .unwrap()
            .prepare(names)
    }

    fn alloc_staging_handle(&mut self) -> Option<u64> {
        let handle = self.next_staging_handle;
        if handle == 0 {
            return None;
        }
        self.next_staging_handle = handle.checked_add(1)?;
        Some(handle)
    }

    fn alloc_get_request_id(&mut self) -> Option<u32> {
        for _ in 0..u32::MAX {
            let request_id = self.next_get_request_id.max(1);
            self.next_get_request_id = self.next_get_request_id.wrapping_add(1).max(1);
            if request_id != heartbeat::REQUEST_ID && !self.pending_gets.contains_key(&request_id) {
                return Some(request_id);
            }
        }
        None
    }

    fn make_begin_operation_room(&mut self) -> bool {
        let stages = &self.stages;
        make_operation_replay_room(
            &mut self.begin_operations,
            &mut self.begin_operation_order,
            MAX_SELECTION_OPERATION_REPLAYS,
            0,
            |replay| {
                stages
                    .get(&replay.staging_handle)
                    .is_some_and(|stage| stage.items.iter().all(|item| !item.sealed))
            },
        )
    }
}

