#[derive(Clone, Debug, PartialEq, Eq)]
struct TerminalCatalogue {
    revision: u64,
    records: HashMap<u64, yas_terminal::TerminalRecord>,
}

impl TerminalCatalogue {
    fn state_records(&self, kind: RecordKind) -> Result<Vec<yas_wire::state::Record>, ()> {
        let mut records = self.records.values().collect::<Vec<_>>();
        records.sort_by_key(|record| record.terminal_handle);
        records
            .into_iter()
            .map(|record| record.state_record(kind).map_err(|_| ()))
            .collect()
    }
}

