#[cfg(target_os = "linux")]
enum AppSocketAddSubmission {
    Applied,
    Rejected,
    Disconnected,
}

#[cfg(target_os = "linux")]
enum AppSocketRemoveSubmission {
    Applied,
    Disconnected,
}

#[cfg(target_os = "linux")]
async fn submit_app_socket_add_command(
    sender: yas_compositor::CompositorCommandSender,
    command: yas_compositor::CompositorCommand,
    applied: std::sync::mpsc::Receiver<Result<(), ()>>,
) -> Result<AppSocketAddSubmission, ()> {
    tokio::task::spawn_blocking(move || {
        if sender.send(command).is_err() {
            return AppSocketAddSubmission::Disconnected;
        }
        match applied.recv() {
            Ok(Ok(())) => AppSocketAddSubmission::Applied,
            Ok(Err(())) => AppSocketAddSubmission::Rejected,
            Err(_) => AppSocketAddSubmission::Disconnected,
        }
    })
    .await
    .map_err(|_| ())
}

#[cfg(target_os = "linux")]
async fn submit_app_socket_remove_command<F>(
    sender: yas_compositor::CompositorCommandSender,
    command: yas_compositor::CompositorCommand,
    applied: std::sync::mpsc::Receiver<()>,
    after_admission: F,
) -> Result<AppSocketRemoveSubmission, ()>
where
    F: FnOnce() + Send + 'static,
{
    tokio::task::spawn_blocking(move || {
        if sender.send(command).is_err() {
            return AppSocketRemoveSubmission::Disconnected;
        }
        // Revoke the pathname immediately after bounded-queue admission, but
        // do not claim listener cleanup until the compositor applies Remove.
        after_admission();
        match applied.recv() {
            Ok(()) => AppSocketRemoveSubmission::Applied,
            Err(_) => AppSocketRemoveSubmission::Disconnected,
        }
    })
    .await
    .map_err(|_| ())
}

#[cfg(target_os = "linux")]
fn complete_app_socket_add_submission(
    path: &std::path::Path,
    submission: Result<AppSocketAddSubmission, ()>,
) -> Result<(), Status> {
    let status = match submission {
        Ok(AppSocketAddSubmission::Applied) => return Ok(()),
        Ok(AppSocketAddSubmission::Rejected) | Ok(AppSocketAddSubmission::Disconnected) => {
            Status::Unavailable
        }
        Err(()) => Status::Internal,
    };
    let _ = std::fs::remove_file(path);
    Err(status)
}

#[cfg(target_os = "linux")]
fn complete_app_socket_remove_submission(
    submission: Result<AppSocketRemoveSubmission, ()>,
) -> Result<(), ()> {
    match submission {
        Ok(AppSocketRemoveSubmission::Applied) | Ok(AppSocketRemoveSubmission::Disconnected) => {
            Ok(())
        }
        Err(()) => Err(()),
    }
}

struct NativeSurfaceView {
    surface_handle: u64,
    surface_id: u16,
    backend_client_id: u64,
    width: u16,
    height: u16,
    max_fps: u16,
    decoder_capacity: u8,
    codec_version: u16,
    next_sequence: u64,
    acknowledged_sequence: u64,
    needs_keyframe: bool,
    keyframe_requested: bool,
    // The peer may retain every advertised in-flight decoded frame. Keep that
    // exact worst-case window in the session's aggregate outbound budget for
    // the whole view lifetime.
    outbound_credit: CreditLease,
    // Reliable Surface fragments share the Data lane. A receipt for the
    // newest reliable frame therefore covers every older reliable frame for
    // this view; datagram frames remain deliberately lossy and reorderable.
    last_frame_written: Option<oneshot::Receiver<()>>,
}

/// An admitted view waiting for its first frame to select the encoder codec.
/// Ownership includes the provisional backend, even if the client disconnects before
/// a Result can publish the view into the session's live view map.
struct PendingSurfaceOpen {
    header: FrameHeader,
    view_id: u32,
    view: Option<NativeSurfaceView>,
    state: AppState,
    timeout: Option<tokio::task::JoinHandle<()>>,
}

impl PendingSurfaceOpen {
    async fn release(&mut self) {
        if let Some(view) = self.view.as_ref() {
            super::yas_surface_backend::remove(&self.state, view.backend_client_id).await;
            self.view.take();
        }
    }
}

impl Drop for PendingSurfaceOpen {
    fn drop(&mut self) {
        if let Some(task) = self.timeout.take() {
            task.abort();
        }
        if let Some(view) = self.view.take()
            && let Ok(runtime) = tokio::runtime::Handle::try_current()
        {
            let state = self.state.clone();
            runtime.spawn(async move {
                super::yas_surface_backend::remove(&state, view.backend_client_id).await;
            });
        }
    }
}

impl SurfaceRuntime {
    fn new(catalogue: SurfaceCatalogue) -> Self {
        Self {
            published_catalogue: catalogue.clone(),
            catalogue,
            pending_catalogue_boundaries: BTreeMap::new(),
            next_catalogue_boundary_id: 1,
            updates: HashMap::new(),
            next_view_id: 1,
            views: HashMap::new(),
            next_app_handle: 1,
            app_endpoints: HashMap::new(),
            operations: HashMap::new(),
            resource_operations: HashMap::new(),
            operation_index: HashMap::new(),
        }
    }

    fn alloc_view(&mut self) -> Option<u32> {
        for _ in 0..u32::MAX {
            let view_id = self.next_view_id.max(1);
            self.next_view_id = self.next_view_id.wrapping_add(1).max(1);
            if !self.views.contains_key(&view_id) {
                return Some(view_id);
            }
        }
        None
    }

    fn alloc_catalogue_boundary(&mut self, retired_surface_handles: &[u64]) -> Option<u64> {
        let blocked_removals = retired_surface_handles
            .iter()
            .filter_map(|surface_handle| {
                self.published_catalogue
                    .records
                    .get(surface_handle)
                    .cloned()
                    .map(|record| (*surface_handle, record))
            })
            .collect::<BTreeMap<_, _>>();
        for _ in 0..=self.pending_catalogue_boundaries.len() {
            let boundary_id = self.next_catalogue_boundary_id.max(1);
            self.next_catalogue_boundary_id = boundary_id.wrapping_add(1).max(1);
            if let std::collections::btree_map::Entry::Vacant(entry) =
                self.pending_catalogue_boundaries.entry(boundary_id)
            {
                entry.insert(blocked_removals);
                return Some(boundary_id);
            }
        }
        None
    }

    fn publish_catalogue(&mut self, mut catalogue: SurfaceCatalogue) -> bool {
        // Surface FRAME events use the Data lane while catalogue State uses
        // Control. Retain only records whose REMOVE is waiting on reliable EOS;
        // unrelated ADD and REPLACE generations remain publishable while the
        // Data writer is backpressured.
        for blocked_removals in self.pending_catalogue_boundaries.values() {
            for (&surface_handle, record) in blocked_removals {
                catalogue
                    .records
                    .entry(surface_handle)
                    .or_insert_with(|| record.clone());
            }
        }
        if catalogue.records == self.published_catalogue.records {
            return false;
        }
        let minimum_revision = self.published_catalogue.revision.saturating_add(1).max(1);
        if catalogue.revision < minimum_revision {
            catalogue.revision = minimum_revision;
            self.catalogue.revision = self.catalogue.revision.max(minimum_revision);
        }
        self.published_catalogue = catalogue.clone();
        for updates in self.updates.values_mut() {
            updates.send_replace(catalogue.clone());
        }
        true
    }

    fn alloc_app_handle(&mut self) -> Option<u64> {
        for _ in 0..u16::MAX {
            let app_handle = self.next_app_handle.max(1);
            self.next_app_handle = self.next_app_handle.checked_add(1)?;
            if !self.app_endpoints.contains_key(&app_handle) {
                return Some(app_handle);
            }
        }
        None
    }

    fn replay(&self, operation_id: [u8; 16], fingerprint: [u8; 32]) -> Option<(Status, Vec<u8>)> {
        match *self.operation_index.get(&operation_id)? {
            SurfaceReplayLocation::Ordinary => {
                let replay = self.operations.get(&operation_id)?;
                if replay.fingerprint != fingerprint {
                    return Some((Status::Conflict, Vec::new()));
                }
                if let Some(endpoint) = &replay.app_endpoint
                    && (!endpoint.live || !self.app_endpoints.contains_key(&endpoint.app_handle))
                {
                    return Some((Status::Stale, Vec::new()));
                }
                Some((replay.status, replay.body.clone()))
            }
            SurfaceReplayLocation::AppEndpointRelease {
                create_operation_id,
            } => {
                let release = self
                    .operations
                    .get(&create_operation_id)?
                    .app_endpoint
                    .as_ref()?
                    .release
                    .as_ref()?;
                if release.fingerprint != fingerprint {
                    Some((Status::Conflict, Vec::new()))
                } else if release.cleanup_pending {
                    None
                } else {
                    Some((release.status, release.body.clone()))
                }
            }
            SurfaceReplayLocation::Resource {
                surface_handle,
                kind,
            } => {
                let replay = self.resource_operations.get(&(surface_handle, kind))?;
                Some(if replay.fingerprint == fingerprint {
                    (replay.status, replay.body.clone())
                } else {
                    (Status::Conflict, Vec::new())
                })
            }
        }
    }

    fn record_replay(
        &mut self,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        status: Status,
        body: Vec<u8>,
    ) {
        if self.operations.len() < MAX_SURFACE_OPERATION_REPLAYS {
            debug_assert!(!self.operation_index.contains_key(&operation_id));
            self.operations.insert(
                operation_id,
                SurfaceReplay {
                    fingerprint,
                    status,
                    body,
                    app_endpoint: None,
                },
            );
            self.operation_index
                .insert(operation_id, SurfaceReplayLocation::Ordinary);
        }
    }

    fn record_app_endpoint_create(
        &mut self,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        app_handle: u64,
        body: Vec<u8>,
    ) {
        debug_assert!(self.operations.len() < MAX_SURFACE_OPERATION_REPLAYS);
        debug_assert!(!self.operation_index.contains_key(&operation_id));
        self.operations.insert(
            operation_id,
            SurfaceReplay {
                fingerprint,
                status: Status::Ok,
                body,
                app_endpoint: Some(SurfaceAppEndpointReplay {
                    app_handle,
                    live: true,
                    release: None,
                }),
            },
        );
        self.operation_index
            .insert(operation_id, SurfaceReplayLocation::Ordinary);
    }

    fn release_app_endpoint(
        &mut self,
        app_handle: u64,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
    ) -> Result<Option<SurfaceAppEndpoint>, Status> {
        let create_operation_id = self.operations.iter().find_map(|(&operation_id, replay)| {
            replay
                .app_endpoint
                .as_ref()
                .is_some_and(|endpoint| endpoint.app_handle == app_handle)
                .then_some(operation_id)
        });
        if let Some(create_operation_id) = create_operation_id {
            let replay = self
                .operations
                .get_mut(&create_operation_id)
                .expect("Surface app-endpoint replay disappeared");
            let endpoint = replay
                .app_endpoint
                .as_mut()
                .expect("Surface app-endpoint replay changed kind");
            if endpoint.release.as_ref().is_some_and(|release| {
                release.cleanup_pending
                    && self
                        .operation_index
                        .get(&operation_id)
                        .is_some_and(|location| {
                            matches!(
                                location,
                                SurfaceReplayLocation::AppEndpointRelease {
                                    create_operation_id: indexed,
                                } if *indexed == create_operation_id
                            )
                        })
            }) {
                return Ok(self.app_endpoints.remove(&app_handle));
            }
            if endpoint.release.is_none() {
                endpoint.live = false;
                endpoint.release = Some(SurfaceNestedReplay {
                    fingerprint,
                    status: Status::Internal,
                    body: Vec::new(),
                    cleanup_pending: true,
                });
                self.operation_index.insert(
                    operation_id,
                    SurfaceReplayLocation::AppEndpointRelease {
                        create_operation_id,
                    },
                );
                return Ok(self.app_endpoints.remove(&app_handle));
            }
        }
        if self.operations.len() >= MAX_SURFACE_OPERATION_REPLAYS {
            return Err(Status::ResourceExhausted);
        }
        let endpoint = self.app_endpoints.remove(&app_handle);
        self.record_replay(operation_id, fingerprint, Status::Ok, Vec::new());
        Ok(endpoint)
    }

    fn update_replay_status(&mut self, operation_id: [u8; 16], status: Status) {
        match self.operation_index.get(&operation_id).copied() {
            Some(SurfaceReplayLocation::Ordinary) => {
                if let Some(replay) = self.operations.get_mut(&operation_id) {
                    replay.status = status;
                }
            }
            Some(SurfaceReplayLocation::AppEndpointRelease {
                create_operation_id,
            }) => {
                if let Some(release) = self
                    .operations
                    .get_mut(&create_operation_id)
                    .and_then(|replay| replay.app_endpoint.as_mut())
                    .and_then(|endpoint| endpoint.release.as_mut())
                {
                    release.status = status;
                    release.cleanup_pending = false;
                }
            }
            Some(SurfaceReplayLocation::Resource {
                surface_handle,
                kind,
            }) => {
                if let Some(replay) = self.resource_operations.get_mut(&(surface_handle, kind)) {
                    replay.status = status;
                }
            }
            None => {}
        }
    }

    fn has_resource_replay(&self, surface_handle: u64, kind: u16) -> bool {
        self.resource_operations
            .contains_key(&(surface_handle, kind))
    }

    fn record_resource_replay(
        &mut self,
        surface_handle: u64,
        kind: u16,
        operation_id: [u8; 16],
        fingerprint: [u8; 32],
        status: Status,
        body: Vec<u8>,
    ) {
        debug_assert!(self.catalogue.records.contains_key(&surface_handle));
        debug_assert!(!self.operation_index.contains_key(&operation_id));
        let key = (surface_handle, kind);
        if let Some(previous) = self.resource_operations.insert(
            key,
            SurfaceResourceReplay {
                operation_id,
                fingerprint,
                status,
                body,
            },
        ) {
            self.operation_index.remove(&previous.operation_id);
        }
        self.operation_index.insert(
            operation_id,
            SurfaceReplayLocation::Resource {
                surface_handle,
                kind,
            },
        );
        debug_assert!(
            self.resource_operations.len() <= self.catalogue.records.len().saturating_mul(3),
        );
    }

    fn retire_surface_replays(&mut self, surface_handle: u64) {
        for kind in [
            yas_wire::schema::surface::request::RESIZE,
            yas_wire::schema::surface::request::FOCUS,
            yas_wire::schema::surface::request::CLOSE,
        ] {
            if let Some(replay) = self.resource_operations.remove(&(surface_handle, kind)) {
                self.operation_index.remove(&replay.operation_id);
            }
        }
    }

    fn clear_resource_replays(&mut self) {
        for replay in self.resource_operations.drain().map(|(_, replay)| replay) {
            self.operation_index.remove(&replay.operation_id);
        }
    }

    fn retire_app_endpoint(&mut self, app_handle: u64) -> Option<SurfaceAppEndpoint> {
        for replay in self.operations.values_mut() {
            if let Some(endpoint) = replay.app_endpoint.as_mut()
                && endpoint.app_handle == app_handle
            {
                endpoint.live = false;
                break;
            }
        }
        self.app_endpoints.remove(&app_handle)
    }

    fn restore_retiring_app_endpoint(&mut self, app_handle: u64, endpoint: SurfaceAppEndpoint) {
        debug_assert!(self.operations.values().any(|replay| {
            replay
                .app_endpoint
                .as_ref()
                .is_some_and(|endpoint| endpoint.app_handle == app_handle && !endpoint.live)
        }));
        self.app_endpoints.insert(app_handle, endpoint);
    }

    fn app_endpoint_environment(
        &self,
        app_handle: u64,
    ) -> Option<Vec<yas_surface::EnvironmentOverride>> {
        let live = self.operations.values().any(|replay| {
            replay
                .app_endpoint
                .as_ref()
                .is_some_and(|endpoint| endpoint.app_handle == app_handle && endpoint.live)
        });
        if !live {
            return None;
        }
        self.app_endpoints
            .get(&app_handle)
            .map(|endpoint| endpoint.environment.clone())
    }

    fn expire_app_endpoints(&mut self, now: u64) -> Vec<(u64, SurfaceAppEndpoint)> {
        let expired = self
            .app_endpoints
            .iter()
            .filter_map(|(&handle, endpoint)| (endpoint.expires_server_ns <= now).then_some(handle))
            .collect::<Vec<_>>();
        expired
            .into_iter()
            .filter_map(|handle| {
                self.retire_app_endpoint(handle)
                    .map(|endpoint| (handle, endpoint))
            })
            .collect()
    }

    fn drain_app_endpoints(&mut self) -> Vec<(u64, SurfaceAppEndpoint)> {
        let handles = self.app_endpoints.keys().copied().collect::<Vec<_>>();
        handles
            .into_iter()
            .filter_map(|handle| {
                self.retire_app_endpoint(handle)
                    .map(|endpoint| (handle, endpoint))
            })
            .collect()
    }
}

