#[cfg(target_os = "linux")]
impl MediaRuntime {
    fn new(owner_session: [u8; 16], backend_owner: u64) -> Self {
        let mut runtime = Self {
            owner_session,
            backend_owner,
            catalogue: MediaCatalogue {
                revision: 1,
                devices: BTreeMap::new(),
                leases: BTreeMap::new(),
                portals: BTreeMap::new(),
                players: BTreeMap::new(),
            },
            updates: HashMap::new(),
            backend_state: None,
            backend_video_codecs: MEDIA_VIDEO_CODEC_MJPEG,
            mpris: super::MprisBackendState::default(),
            player_handles: HashMap::new(),
            player_backend_ids: HashMap::new(),
            assets: HashMap::new(),
            asset_bytes: 0,
            portals: HashMap::new(),
            portal_by_request: HashMap::new(),
            streams: HashMap::new(),
            pending_acquires: HashMap::new(),
            cancelled_acquires: BTreeSet::new(),
            pending_actions: HashMap::new(),
            operations: HashMap::new(),
            next_nonce: 1,
            next_stream_handle: 1,
        };
        rebuild_media_devices(&mut runtime);
        runtime
    }

    fn alloc_nonce(&mut self) -> Option<u32> {
        for _ in 0..u32::MAX {
            let nonce = self.next_nonce.max(1);
            self.next_nonce = self.next_nonce.wrapping_add(1).max(1);
            if !self.pending_acquires.contains_key(&nonce)
                && !self.pending_actions.contains_key(&nonce)
            {
                return Some(nonce);
            }
        }
        None
    }

    fn player_handle(&mut self, backend_id: u32) -> Option<u64> {
        if let Some(&handle) = self.player_handles.get(&backend_id) {
            return Some(handle);
        }
        // MPRIS backend IDs are allocated monotonically for the server's
        // lifetime. Keep their opaque wire handles stable across client
        // connections so a handle printed by the CLI remains actionable.
        let handle = MEDIA_PLAYER_HANDLE_BASE | u64::from(backend_id);
        self.player_handles.insert(backend_id, handle);
        self.player_backend_ids.insert(handle, backend_id);
        Some(handle)
    }

    fn player_backend_id(&self, handle: u64) -> Option<u32> {
        self.player_backend_ids.get(&handle).copied()
    }

    fn alloc_stream_handle(&mut self) -> Option<u64> {
        for _ in 0..u64::MAX {
            let handle = self.next_stream_handle.max(1);
            self.next_stream_handle = self.next_stream_handle.wrapping_add(1).max(1);
            if !self.streams.contains_key(&handle) {
                return Some(handle);
            }
        }
        None
    }
}

