struct TerminalView {
    view_id: u32,
    terminal_handle: u64,
    pty_id: u16,
    backend_view: u64,
    rows: u16,
    cols: u16,
    max_fps: u16,
    // Declared to the peer at OPEN_VIEW and reserved by it for the life of the
    // view. Frames are encoded against this same budget, and CONFIGURE_VIEW
    // refuses a geometry that would outgrow it.
    frame_bound: u32,
    presentation_metrics: Option<yas_terminal::PresentationMetrics>,
    max_inflight_frames: u8,
    queue_target: u8,
    decoder_queue_depth: u8,
    available_frame_slots: u8,
    frame_owed: bool,
    frame_owed_final_guard: Option<super::yas_terminal_backend::FrameGuard>,
    next_sequence: u32,
    acknowledged_sequence: u32,
    scroll_offset: i64,
    focused: bool,
    final_state: bool,
    // Terminal advertises a small in-flight decoded-frame window. This
    // reservation shares the peer's aggregate receive budget with State,
    // Transfer, and Surface.
    _outbound_credit: CreditLease,
    // The writer preserves FIFO within the Data lane. A receipt for the
    // newest queued frame therefore covers every older frame for this view.
    last_frame_written: Option<TerminalFrameReceipt>,
}

#[derive(Clone)]
struct TerminalFrameReceipt {
    view_id: u32,
    sequence: u32,
    final_state: bool,
    completion: Arc<TerminalFrameWriteCompletion>,
}

impl TerminalRuntime {
    fn new(catalogue: TerminalCatalogue) -> Self {
        Self {
            catalogue,
            app_handles: HashMap::new(),
            launches: HashMap::new(),
            operations: HashMap::new(),
            next_view_id: 1,
            views: HashMap::new(),
        }
    }

    fn alloc_view(&mut self) -> Option<u32> {
        for _ in 0..u32::MAX {
            let view_id = self.next_view_id.max(1);
            self.next_view_id = self.next_view_id.wrapping_add(1).max(1);
            if !self.views.contains_key(&view_id) {
                return Some(view_id);
            }
        }
        None
    }
}

async fn terminal_catalogue_snapshot(state: &AppState) -> TerminalCatalogue {
    let mut session = state.session.lock().await;
    let backend_ids = session.ptys.keys().copied().collect::<BTreeSet<_>>();
    session
        .terminal_handles
        .retain_backends(|backend_id| backend_ids.contains(&backend_id));
    let handles = backend_ids
        .iter()
        .filter_map(|&backend_id| {
            session
                .terminal_handles
                .get_or_insert(backend_id)
                .map(|handle| (backend_id, handle))
        })
        .collect::<HashMap<_, _>>();
    let records = session
        .ptys
        .iter()
        .filter_map(|(&pty_id, pty)| {
            let terminal_handle = *handles.get(&pty_id)?;
            let (rows, cols) = pty.driver.size();
            let mut extensions = vec![
                Extension {
                    tag: yas_wire::schema::terminal::STATE_TITLE_EXTENSION as u16,
                    required: false,
                    value: truncate_utf8(pty.driver.title(), MAX_TERMINAL_STATE_TITLE_BYTES)
                        .into_bytes(),
                },
                Extension {
                    tag: yas_wire::schema::terminal::STATE_JOURNAL_CURSOR_EXTENSION as u16,
                    required: false,
                    value: pty.journal.next_index().to_le_bytes().to_vec(),
                },
                Extension {
                    tag: yas_wire::schema::terminal::STATE_RESOURCE_TAG_EXTENSION as u16,
                    required: false,
                    value: pty.tag.as_bytes().to_vec(),
                },
            ];
            if let Some(cwd) = super::resolve_term_cwd(pty.osc7_cwd.as_deref(), || {
                super::pty::pty_cwd(&pty.handle)
            }) {
                extensions.push(Extension {
                    tag: yas_wire::schema::terminal::STATE_CWD_EXTENSION as u16,
                    required: false,
                    value: truncate_utf8(&cwd, MAX_TERMINAL_STATE_CWD_BYTES).into_bytes(),
                });
            }
            if let Some(command) = &pty.command {
                extensions.push(Extension {
                    tag: yas_wire::schema::terminal::STATE_COMMAND_DISPLAY_EXTENSION as u16,
                    required: false,
                    value: truncate_utf8(command, MAX_TERMINAL_STATE_COMMAND_DISPLAY_BYTES)
                        .into_bytes(),
                });
            }
            if pty.exited {
                let exit = if pty.exit_status == yas_terminal_model::EXIT_STATUS_UNKNOWN {
                    yas_terminal::ExitRecord::Other {
                        detail: String::from("exit status unavailable"),
                    }
                } else {
                    #[cfg(unix)]
                    if pty.exit_status < 0 {
                        let native_signal = pty.exit_status.saturating_neg();
                        let reason = match native_signal {
                            libc::SIGINT => yas_terminal::ExitReason::Interrupt,
                            libc::SIGTERM => yas_terminal::ExitReason::Terminate,
                            libc::SIGKILL => yas_terminal::ExitReason::Kill,
                            libc::SIGHUP => yas_terminal::ExitReason::Hangup,
                            _ => yas_terminal::ExitReason::Unknown,
                        };
                        yas_terminal::ExitRecord::Signal {
                            reason,
                            native_signal,
                            detail: if pty.exit_reason == yas_terminal_model::EXIT_REASON_DEADLINE {
                                String::from("deadline")
                            } else {
                                String::new()
                            },
                        }
                    } else {
                        yas_terminal::ExitRecord::Code {
                            code: pty.exit_status,
                            detail: String::new(),
                        }
                    }
                    #[cfg(windows)]
                    yas_terminal::ExitRecord::Code {
                        code: pty.exit_status,
                        detail: String::new(),
                    }
                };
                extensions.push(Extension {
                    tag: yas_wire::schema::terminal::STATE_EXIT_EXTENSION as u16,
                    required: false,
                    value: exit.encode().expect("server Terminal exit record is valid"),
                });
            }
            if let Some(deadline) = pty.deadline {
                let remaining = deadline.saturating_duration_since(Instant::now());
                let deadline_server_ns = monotonic_ns()
                    .saturating_add(u64::try_from(remaining.as_nanos()).unwrap_or(u64::MAX));
                extensions.push(Extension {
                    tag: yas_wire::schema::terminal::STATE_DEADLINE_SERVER_NS_EXTENSION as u16,
                    required: false,
                    value: deadline_server_ns.to_le_bytes().to_vec(),
                });
            }
            extensions.sort_unstable_by_key(|extension| extension.tag);
            let record = yas_terminal::TerminalRecord {
                terminal_handle,
                lifecycle: if pty.exited {
                    yas_terminal::Lifecycle::Exited
                } else {
                    yas_terminal::Lifecycle::Running
                },
                rows: rows.max(1),
                cols: cols.max(1),
                generation: u32::try_from(pty.generation).unwrap_or(u32::MAX).max(1),
                used_rows: u32::from(pty.driver.used_rows()),
                extensions: Extensions(extensions),
            };
            Some((record.terminal_handle, record))
        })
        .collect();
    TerminalCatalogue {
        revision: 1,
        records,
    }
}

fn synthetic_client_id(boot_id: [u8; 16], client_id: u64, domain: &[u8]) -> [u8; 16] {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"yas.client.synthetic.v1\0");
    hasher.update(domain);
    hasher.update(&boot_id);
    hasher.update(&client_id.to_le_bytes());
    let mut value = [0; 16];
    value.copy_from_slice(&hasher.finalize().as_bytes()[..16]);
    if value == [0; 16] {
        value[15] = 1;
    }
    value
}

fn native_client_session_id(
    boot_id: [u8; 16],
    client_id: u64,
    client: &super::ClientState,
) -> [u8; 16] {
    client.native_identity.as_ref().map_or_else(
        || synthetic_client_id(boot_id, client_id, b"session"),
        |identity| identity.session_id,
    )
}

fn bounded_native_active_subscriptions(
    mut terminals: Vec<yas_client::TerminalSubscription>,
    mut surfaces: Vec<yas_client::SurfaceSubscription>,
    mut auxiliary: Vec<yas_client::AuxiliarySubscription>,
) -> yas_client::ActiveSubscriptions {
    terminals.sort_unstable_by_key(|value| (value.terminal_handle, value.view_id));
    surfaces.sort_unstable_by_key(|value| (value.surface_handle, value.view_id));
    auxiliary
        .sort_unstable_by_key(|value| (value.family, value.subscription_id, value.resource_handle));

    // The family limit bounds the represented subscriptions, not the
    // resources a client may own. Retain a deterministic prefix in canonical
    // extension order when the live total exceeds that representation cap.
    let mut remaining = yas_wire::schema::client::MAX_ACTIVE_SUBSCRIPTIONS as usize;
    terminals.truncate(remaining);
    remaining -= terminals.len();
    surfaces.truncate(remaining);
    remaining -= surfaces.len();
    auxiliary.truncate(remaining);

    yas_client::ActiveSubscriptions {
        terminals,
        surfaces,
        auxiliary,
    }
}

fn native_surface_subscription(
    view_id: u32,
    view: &NativeSurfaceView,
) -> yas_client::SurfaceSubscription {
    yas_client::SurfaceSubscription {
        surface_handle: view.surface_handle,
        view_id,
        width: u32::from(view.width),
        height: u32::from(view.height),
        // OPEN_VIEW and CONFIGURE_VIEW provide pixel dimensions but no
        // independent scale. Native presentation treats those dimensions as
        // 1x, expressed in 120ths.
        scale_120: NATIVE_SURFACE_SCALE_120,
    }
}

#[derive(Clone, Copy, Default)]
struct NativeAuxiliaryResources<'a> {
    fs: Option<&'a HashMap<u32, u64>>,
    git: Option<&'a HashMap<u32, u64>>,
    git_query: Option<&'a HashMap<u32, u64>>,
    lsp: Option<&'a HashMap<u32, u64>>,
}

impl NativeAuxiliaryResources<'_> {
    fn handle(self, family_id: u16, subscription_id: u32, kv_namespace: Option<u64>) -> u64 {
        match family_id {
            family::KV => kv_namespace.unwrap_or(0),
            family::FS => self
                .fs
                .and_then(|values| values.get(&subscription_id))
                .copied()
                .unwrap_or(0),
            family::GIT => self
                .git
                .and_then(|values| values.get(&subscription_id))
                .or_else(|| {
                    self.git_query
                        .and_then(|values| values.get(&subscription_id))
                })
                .copied()
                .unwrap_or(0),
            family::LSP => self
                .lsp
                .and_then(|values| values.get(&subscription_id))
                .copied()
                .unwrap_or(0),
            _ => 0,
        }
    }
}

fn typed_client_origin(origin: &ConnectionOrigin) -> yas_client::Origin {
    match origin {
        ConnectionOrigin::Extension {
            extension_id,
            definition_revision,
            attempt,
            task_id,
            name,
        } => yas_client::Origin::Extension {
            extension_id: *extension_id,
            definition_revision: *definition_revision,
            attempt: *attempt,
            task_id: *task_id,
            name: name.clone(),
        },
        // The kernel's own answer to "who is this", which for a browser is the
        // edge relaying it and for `yas` is the CLI. The socket path is left
        // empty: every native session arrives on this server's one endpoint, so
        // restating it per client says nothing a reader did not already know.
        #[cfg(unix)]
        ConnectionOrigin::Local(credentials) => yas_client::Origin::Unix {
            peer_pid: credentials.pid,
            peer_uid: credentials.uid,
            peer_gid: credentials.gid,
            socket_path: Vec::new(),
        },
        // A transport this build cannot describe. Preserve that uncertainty
        // instead of inventing credentials for it.
        ConnectionOrigin::Network => yas_client::Origin::UnknownOptional {
            kind: u16::MAX,
            body: Vec::new(),
        },
    }
}

async fn client_catalogue_snapshot(
    state: &AppState,
    boot_id: [u8; 16],
) -> BTreeMap<[u8; 16], yas_client::ClientRecord> {
    let now = monotonic_ns();
    let session = state.session.lock().await;
    let mut records = BTreeMap::new();
    for (&client_id, client) in session
        .clients
        .iter()
        .filter(|(_, client)| client.catalog_visible)
    {
        let session_id = native_client_session_id(boot_id, client_id, client);
        let (client_instance, name, release) = client.native_identity.as_ref().map_or_else(
            || {
                (
                    synthetic_client_id(boot_id, client_id, b"instance"),
                    "yas-client".to_owned(),
                    String::new(),
                )
            },
            |identity| {
                (
                    identity.client_instance,
                    identity.name.clone(),
                    identity.release.clone(),
                )
            },
        );
        let elapsed_ns =
            u64::try_from(client.connected_at.elapsed().as_nanos()).unwrap_or(u64::MAX);
        let rates = yas_client::BandwidthRates {
            received_bytes_per_second: client.inbound_bytes_per_sec,
            sent_bytes_per_second: client.outbound_bytes_per_sec,
            sample_window_ns: 1_000_000_000,
        }
        .extension()
        .expect("fixed Client bandwidth window is valid");
        records.insert(
            session_id,
            yas_client::ClientRecord {
                session_id,
                client_instance,
                connected_server_ns: now.saturating_sub(elapsed_ns),
                idle_ns: 0,
                bytes_received: client.inbound_bytes.load(Ordering::Relaxed),
                bytes_sent: client.outbound_bytes.load(Ordering::Relaxed),
                name,
                release,
                label: client.origin.label().to_owned(),
                origin: typed_client_origin(&client.origin),
                extensions: Extensions(vec![rates]),
            },
        );
    }
    for (&session_id, client) in &session.native_yas_clients {
        let elapsed_ns =
            u64::try_from(client.connected_at.elapsed().as_nanos()).unwrap_or(u64::MAX);
        let subscription_snapshot = client.active_subscriptions.snapshot();
        let mut subscription_extensions = vec![
            subscription_snapshot
                .active
                .extension()
                .expect("validated native Client subscriptions"),
        ];
        if !subscription_snapshot.auxiliary_details.entries.is_empty() {
            subscription_extensions.push(
                subscription_snapshot
                    .auxiliary_details
                    .extension()
                    .expect("validated native Client subscription details"),
            );
        }
        let extensions = Extensions(subscription_extensions);
        records.insert(
            session_id,
            yas_client::ClientRecord {
                session_id,
                client_instance: client.identity.client_instance,
                connected_server_ns: now.saturating_sub(elapsed_ns),
                idle_ns: 0,
                bytes_received: client.inbound_bytes.load(Ordering::Relaxed),
                bytes_sent: client.outbound_bytes.load(Ordering::Relaxed),
                name: client.identity.name.clone(),
                release: client.identity.release.clone(),
                label: client.origin.label().to_owned(),
                origin: typed_client_origin(&client.origin),
                // Direct native counters are exact cumulative values.  A
                // sampled rate extension is omitted until two samples exist;
                // clients must not synthesize a lifetime average.
                extensions,
            },
        );
    }
    records
}

fn fixed_32_32_to_f64(value: i64) -> f64 {
    value as f64 / 4_294_967_296.0
}

fn surface_cursor_extension(cursor: &yas_surface::CursorState) -> Option<Extension> {
    cursor.extension().ok()
}

fn surface_text_input_extension(text_input: &CachedSurfaceTextInput) -> Option<Extension> {
    yas_surface::TextInputState {
        enabled: true,
        requested: false,
        content_hint: text_input.hint,
        content_purpose: text_input.purpose,
        cursor_rect: text_input
            .cursor_rect
            .map(|(x, y, width, height)| yas_surface::CursorRect {
                x: i32::from(x),
                y: i32::from(y),
                width: i32::from(width),
                height: i32::from(height),
            }),
    }
    .extension()
    .ok()
}

async fn surface_catalogue_snapshot(state: &AppState) -> SurfaceCatalogue {
    let mut session = state.session.lock().await;
    let Some(compositor) = session.compositor.as_ref() else {
        session.surface_handles.retain_backends(|_| false);
        return SurfaceCatalogue {
            revision: 1,
            records: BTreeMap::new(),
        };
    };
    let backend_ids = compositor.surfaces.keys().copied().collect::<BTreeSet<_>>();
    session
        .surface_handles
        .retain_backends(|backend_id| backend_ids.contains(&backend_id));
    let handles = backend_ids
        .iter()
        .filter_map(|&backend_id| {
            session
                .surface_handles
                .get_or_insert(backend_id)
                .map(|handle| (backend_id, handle))
        })
        .collect::<HashMap<_, _>>();
    let compositor = session
        .compositor
        .as_ref()
        .expect("Surface compositor disappeared while locked");
    let records = compositor
        .surfaces
        .iter()
        .filter_map(|(&surface_id, info)| {
            let surface_handle = *handles.get(&surface_id)?;
            let logical_width = if info.logical_width == 0 {
                info.width.max(1)
            } else {
                info.logical_width
            };
            let logical_height = if info.logical_height == 0 {
                info.height.max(1)
            } else {
                info.logical_height
            };
            let mut extensions = Vec::new();
            if let Some(&(width, height)) = session.surface_minimum_sizes.get(&surface_id) {
                let mut value = width.to_le_bytes().to_vec();
                value.extend_from_slice(&height.to_le_bytes());
                extensions.push(Extension {
                    tag: yas_wire::schema::surface::STATE_MINIMUM_SIZE_EXTENSION as u16,
                    required: false,
                    value,
                });
            }
            if let Some((active_surface, revision)) = compositor.surface_activation
                && active_surface == surface_id
            {
                extensions.push(Extension {
                    tag: yas_wire::schema::surface::STATE_ACTIVATION_REVISION_EXTENSION as u16,
                    required: false,
                    value: revision.to_le_bytes().to_vec(),
                });
            }
            if let Some(cursor) = compositor.surface_cursors.get(&surface_id)
                && let Some(extension) = surface_cursor_extension(cursor)
            {
                extensions.push(extension);
            }
            if let Some(text_input) = compositor.surface_text_inputs.get(&surface_id)
                && let Some(extension) = surface_text_input_extension(text_input)
            {
                extensions.push(extension);
                if text_input.request_revision != 0 {
                    extensions.push(Extension {
                        tag: yas_wire::schema::surface::STATE_TEXT_INPUT_REQUEST_REVISION_EXTENSION
                            as u16,
                        required: false,
                        value: text_input.request_revision.to_le_bytes().to_vec(),
                    });
                }
            }
            extensions.sort_unstable_by_key(|extension| extension.tag);
            let record = yas_surface::SurfaceRecord {
                surface_handle,
                revision: 1,
                parent_handle: if info.parent_id != 0 {
                    handles.get(&info.parent_id).copied().unwrap_or(0)
                } else {
                    0
                },
                app_handle: 0,
                lifecycle: 0,
                composite_width: u32::from(info.width.max(1)),
                composite_height: u32::from(info.height.max(1)),
                logical_width_32_32: i64::from(logical_width) << 32,
                logical_height_32_32: i64::from(logical_height) << 32,
                application_id: info
                    .origin
                    .as_ref()
                    .map_or_else(|| info.app_id.clone(), |origin| origin.app_id.clone()),
                title: info.title.clone(),
                extensions: Extensions(extensions),
            };
            Some((record.surface_handle, record))
        })
        .collect();
    SurfaceCatalogue {
        revision: 1,
        records,
    }
}

fn surface_backend_codec(codec_version: u16) -> Option<super::yas_surface_backend::Codec> {
    match codec_version {
        value if value == yas_wire::schema::surface::CODEC_H264_V1 as u16 => {
            Some(super::yas_surface_backend::Codec::H264)
        }
        value if value == yas_wire::schema::surface::CODEC_AV1_V1 as u16 => {
            Some(super::yas_surface_backend::Codec::Av1)
        }
        _ => None,
    }
}

fn surface_codec_version(codec: super::yas_surface_backend::Codec) -> u16 {
    match codec {
        super::yas_surface_backend::Codec::H264 => yas_wire::schema::surface::CODEC_H264_V1 as u16,
        super::yas_surface_backend::Codec::Av1 => yas_wire::schema::surface::CODEC_AV1_V1 as u16,
    }
}

/// Codec families both the peer and this server configuration permit.
/// Actual preference remains the encoder list's order and is resolved by the
/// backend's host probes.
fn surface_codec_support(codec_versions: &[u16], preferences: &[SurfaceEncoderPreference]) -> u8 {
    let av1 = yas_wire::schema::surface::CODEC_AV1_V1 as u16;
    let h264 = yas_wire::schema::surface::CODEC_H264_V1 as u16;
    let configured = |codec_support| {
        preferences.is_empty()
            || preferences
                .iter()
                .any(|preference| preference.supported_by_client(codec_support))
    };
    let mut support = 0;
    if codec_versions.contains(&h264) && configured(super::CODEC_SUPPORT_H264) {
        support |= super::CODEC_SUPPORT_H264;
    }
    if codec_versions.contains(&av1) && configured(super::CODEC_SUPPORT_AV1) {
        support |= super::CODEC_SUPPORT_AV1;
    }
    support
}

fn sole_surface_codec(codec_support: u8) -> Option<super::yas_surface_backend::Codec> {
    match codec_support {
        super::CODEC_SUPPORT_H264 => Some(super::yas_surface_backend::Codec::H264),
        super::CODEC_SUPPORT_AV1 => Some(super::yas_surface_backend::Codec::Av1),
        _ => None,
    }
}

fn surface_operation_fingerprint(kind: u16, payload: &[u8]) -> [u8; 32] {
    let mut hasher = blake3::Hasher::new();
    hasher.update(&kind.to_le_bytes());
    hasher.update(payload);
    *hasher.finalize().as_bytes()
}

fn positive_fixed_to_physical_u16(value: i64, scale_120: u16) -> Option<u16> {
    if value <= 0 || scale_120 == 0 {
        return None;
    }
    let numerator = u128::try_from(value).ok()? * u128::from(scale_120);
    let denominator = u128::from(120_u64 << 32);
    let pixels = numerator.div_ceil(denominator);
    u16::try_from(pixels).ok().filter(|value| *value != 0)
}

fn fixed_to_f64(value: i64) -> f64 {
    value as f64 / 4_294_967_296.0
}

/// Decode the current frame-relative pointer representation while retaining
/// Surface v1 compatibility.  V1 originally specified physical composite
/// pixels; clients briefly shipped a 0..=1 frame-relative representation
/// without negotiating a new family version.  If both axes fit in the unit
/// square they are frame-relative.  Otherwise treat the pair as legacy native
/// pixels and convert it against the current authoritative composite extent.
fn surface_pointer_coordinates(
    x_32_32: i64,
    y_32_32: i64,
    width: u32,
    height: u32,
) -> Option<(f64, f64)> {
    let x = fixed_to_f64(x_32_32);
    let y = fixed_to_f64(y_32_32);
    if (0.0..=1.0).contains(&x) && (0.0..=1.0).contains(&y) {
        return Some((x, y));
    }
    if width == 0 || height == 0 {
        return None;
    }
    Some((
        (x / f64::from(width)).clamp(0.0, 1.0),
        (y / f64::from(height)).clamp(0.0, 1.0),
    ))
}

fn monotonic_millis(monotonic_ns: u64) -> u32 {
    u32::try_from(monotonic_ns / 1_000_000).unwrap_or(u32::MAX)
}

