#[derive(Clone, Copy)]
struct SurfaceFeedbackUpdate {
    backend_client_id: u64,
    surface_id: u16,
    acknowledged: u64,
    decoder_queue_depth: u16,
    reset: bool,
}

fn apply_surface_feedback(
    view: &mut NativeSurfaceView,
    feedback: &yas_surface::FrameFeedback,
) -> Result<SurfaceFeedbackUpdate, ()> {
    let last_sent = view.next_sequence.saturating_sub(1);
    if feedback.presented_sequence > last_sent {
        return Err(());
    }
    let acknowledged = feedback
        .presented_sequence
        .saturating_sub(view.acknowledged_sequence);
    view.acknowledged_sequence = view.acknowledged_sequence.max(feedback.presented_sequence);
    let outstanding = view
        .next_sequence
        .saturating_sub(1)
        .saturating_sub(view.acknowledged_sequence);
    let reset = view.needs_keyframe
        && !view.keyframe_requested
        && outstanding < u64::from(view.decoder_capacity);
    if reset {
        view.keyframe_requested = true;
    }
    Ok(SurfaceFeedbackUpdate {
        backend_client_id: view.backend_client_id,
        surface_id: view.surface_id,
        acknowledged,
        decoder_queue_depth: feedback.decoder_queue_depth,
        reset,
    })
}

fn prepare_terminal_launch(
    launch: &yas_terminal::Launch,
    resolved_cwd: Option<String>,
) -> Result<PreparedTerminalLaunch, Status> {
    let (command, argv, list_command) = match &launch.command {
        yas_terminal::Command::DefaultShell => (None, None, None),
        yas_terminal::Command::Argv(arguments) => {
            let arguments = arguments
                .iter()
                .map(|argument| {
                    std::str::from_utf8(argument)
                        .map(str::to_owned)
                        .map_err(|_| Status::Invalid)
                })
                .collect::<Result<Vec<_>, _>>()?;
            let display = arguments
                .iter()
                .map(|argument| shell_escape_display(argument))
                .collect::<Vec<_>>()
                .join(" ");
            (None, Some(arguments), Some(display))
        }
        yas_terminal::Command::ShellCommand(command) => {
            (Some(command.clone()), None, Some(command.clone()))
        }
    };
    let dir = match &launch.cwd {
        yas_terminal::Cwd::ServerDefault => None,
        yas_terminal::Cwd::Path(path) => Some(
            std::str::from_utf8(path)
                .map_err(|_| Status::Invalid)?
                .to_owned(),
        ),
        yas_terminal::Cwd::Terminal(_) => resolved_cwd,
    };
    let mut exact_env = Vec::with_capacity(launch.environment.len());
    for entry in &launch.environment {
        if entry.key.is_empty()
            || entry.key.contains(&0)
            || entry.key.contains(&b'=')
            || matches!(&entry.value, yas_terminal::EnvironmentValue::Set(value) if value.contains(&0))
        {
            return Err(Status::Invalid);
        }
        #[cfg(windows)]
        {
            std::str::from_utf8(&entry.key).map_err(|_| Status::Invalid)?;
            if let yas_terminal::EnvironmentValue::Set(value) = &entry.value {
                std::str::from_utf8(value).map_err(|_| Status::Invalid)?;
            }
        }
        exact_env.push((
            entry.key.clone(),
            match &entry.value {
                yas_terminal::EnvironmentValue::Set(value) => Some(value.clone()),
                yas_terminal::EnvironmentValue::Remove => None,
            },
        ));
    }
    let environment_base = match launch.environment_base {
        yas_terminal::EnvironmentBase::Server => super::pty::ChildEnvironmentBase::Server,
        yas_terminal::EnvironmentBase::Empty => super::pty::ChildEnvironmentBase::Empty,
    };
    let deadline_after_ns = launch
        .extensions
        .0
        .iter()
        .find(|extension| {
            extension.tag == yas_wire::schema::terminal::LAUNCH_DEADLINE_AFTER_NS_EXTENSION as u16
        })
        .map(|extension| {
            let bytes: [u8; 8] = extension
                .value
                .as_slice()
                .try_into()
                .map_err(|_| Status::Invalid)?;
            let value = u64::from_le_bytes(bytes);
            (value != 0).then_some(value).ok_or(Status::Invalid)
        })
        .transpose()?;
    Ok(PreparedTerminalLaunch {
        spec: super::pty::OwnedChildSpec {
            command,
            argv,
            dir,
            env: Vec::new(),
            env_remove: Vec::new(),
            environment_base,
            exact_env: Some(exact_env),
        },
        list_command,
        deadline_after_ns,
    })
}

fn compare_terminal_environment_keys(
    left: &[u8],
    right: &[u8],
) -> Result<std::cmp::Ordering, Status> {
    #[cfg(unix)]
    {
        Ok(left.cmp(right))
    }
    #[cfg(windows)]
    {
        use windows_sys::Win32::Globalization::{
            CSTR_GREATER_THAN, CSTR_LESS_THAN, CompareStringOrdinal,
        };
        let left: Vec<u16> = std::str::from_utf8(left)
            .map_err(|_| Status::Invalid)?
            .encode_utf16()
            .collect();
        let right: Vec<u16> = std::str::from_utf8(right)
            .map_err(|_| Status::Invalid)?
            .encode_utf16()
            .collect();
        Ok(
            match unsafe {
                CompareStringOrdinal(
                    left.as_ptr(),
                    left.len() as i32,
                    right.as_ptr(),
                    right.len() as i32,
                    1,
                )
            } {
                CSTR_LESS_THAN => std::cmp::Ordering::Less,
                CSTR_GREATER_THAN => std::cmp::Ordering::Greater,
                _ => std::cmp::Ordering::Equal,
            },
        )
    }
}

fn validate_terminal_environment_order(
    entries: &[yas_terminal::EnvironmentEntry],
) -> Result<(), Status> {
    let mut previous: Option<&[u8]> = None;
    for entry in entries {
        if let Some(previous) = previous
            && compare_terminal_environment_keys(previous, &entry.key)? != std::cmp::Ordering::Less
        {
            return Err(Status::Invalid);
        }
        previous = Some(&entry.key);
    }
    Ok(())
}

fn sort_terminal_environment(entries: &mut [yas_terminal::EnvironmentEntry]) {
    entries.sort_by(|left, right| {
        compare_terminal_environment_keys(&left.key, &right.key)
            .unwrap_or_else(|_| left.key.cmp(&right.key))
    });
}

fn overlay_terminal_environment(
    entries: &mut Vec<yas_terminal::EnvironmentEntry>,
    key: Vec<u8>,
    value: Vec<u8>,
) -> Result<(), Status> {
    let mut index = 0;
    while index < entries.len() {
        if compare_terminal_environment_keys(&entries[index].key, &key)?
            == std::cmp::Ordering::Equal
        {
            entries.remove(index);
        } else {
            index += 1;
        }
    }
    entries.push(yas_terminal::EnvironmentEntry {
        key,
        value: yas_terminal::EnvironmentValue::Set(value),
    });
    Ok(())
}

fn shell_escape_display(argument: &str) -> String {
    if !argument.is_empty()
        && argument
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"_+-./:@%=".contains(&byte))
    {
        return argument.to_owned();
    }
    format!("'{}'", argument.replace('\'', "'\\''"))
}

#[allow(clippy::too_many_arguments)]
fn install_terminal_child(
    pty: &mut super::Pty,
    new_handle: super::pty::PtyHandle,
    new_reader: super::PtyReaderHandle,
    new_byte_rx: mpsc::Receiver<super::PtyInput>,
    prepared: &PreparedTerminalLaunch,
    rows: u16,
    cols: u16,
    scrollback: usize,
    retire_running_predecessor: bool,
) {
    let old_handle = std::mem::replace(&mut pty.handle, new_handle);
    let old_reader = std::mem::replace(&mut pty.reader_handle, new_reader);
    pty.byte_rx = new_byte_rx;
    if retire_running_predecessor {
        super::pty::close_pty(&old_handle);
        super::pty::abandon_pty_pid(
            &old_handle,
            std::time::Instant::now() + Duration::from_secs(2),
        );
    }
    drop(old_reader);
    pty.driver = Box::new(yas_terminal_driver::TerminalDriver::new(
        rows, cols, scrollback,
    ));
    pty.ready_frames.clear();
    pty.dirty = true;
    pty.snapshot_not_before = None;
    pty.snapshot_by = None;
    pty.lflag_cache = super::pty::pty_lflag(&pty.handle);
    pty.lflag_last = std::time::Instant::now();
    pty.last_title_send = std::time::Instant::now();
    pty.title_pending = false;
    pty.last_used_rows_sent = 0;
    pty.last_scrolled_lines = 0;
    pty.deadline = prepared
        .deadline_after_ns
        .and_then(|ns| std::time::Instant::now().checked_add(Duration::from_nanos(ns)));
    pty.stop_deadline = None;
    pty.exit_drain_deadline = None;
    pty.exit_reason = yas_terminal_model::EXIT_REASON_NORMAL;
    pty.exited = false;
    pty.exited_at = None;
    pty.generation = pty.generation.max(1).saturating_add(1);
    pty.exit_status = yas_terminal_model::EXIT_STATUS_UNKNOWN;
    pty.command.clone_from(&prepared.list_command);
    pty.spec = prepared.spec.clone();
    pty.osc7_cwd = None;
    pty.journal.reset();
    pty.osc_carry.clear();
}

fn terminal_launch_app_handle(extensions: &Extensions) -> Result<Option<u64>, Status> {
    let Some(extension) = extensions.0.iter().find(|extension| {
        extension.tag == yas_wire::schema::terminal::LAUNCH_APP_HANDLE_EXTENSION as u16
    }) else {
        return Ok(None);
    };
    let bytes: [u8; 8] = extension
        .value
        .as_slice()
        .try_into()
        .map_err(|_| Status::Invalid)?;
    let handle = u64::from_le_bytes(bytes);
    if handle == 0 {
        return Err(Status::Invalid);
    }
    Ok(Some(handle))
}

fn terminal_create_resource_tag(extensions: &Extensions) -> Result<String, Status> {
    let Some(extension) = extensions.0.iter().find(|extension| {
        extension.tag == yas_wire::schema::terminal::CREATE_RESOURCE_TAG_EXTENSION as u16
    }) else {
        return Ok(String::new());
    };
    if extension.value.len() > MAX_TERMINAL_RESOURCE_TAG_BYTES {
        return Err(Status::ResourceExhausted);
    }
    String::from_utf8(extension.value.clone()).map_err(|_| Status::Invalid)
}

fn terminal_create_initial_view(
    extensions: &Extensions,
) -> Result<Option<yas_terminal::InitialViewRequest>, Status> {
    let Some(extension) = extensions.0.iter().find(|extension| {
        extension.tag == yas_wire::schema::terminal::CREATE_INITIAL_VIEW_EXTENSION as u16
    }) else {
        return Ok(None);
    };
    let request =
        yas_terminal::InitialViewRequest::decode(&extension.value).map_err(|_| Status::Invalid)?;
    if has_unknown_required(&request.extensions, &[]) || !request.codec_versions.contains(&1) {
        return Err(Status::Unsupported);
    }
    Ok(Some(request))
}

#[cfg(target_os = "linux")]
fn desktop_backend_status(status: u8) -> Status {
    match status {
        ::yas_desktop::STATUS_OK => Status::Ok,
        ::yas_desktop::STATUS_UNKNOWN_ID => Status::NotFound,
        ::yas_desktop::STATUS_WRONG_TYPE | ::yas_desktop::STATUS_INVALID => Status::Invalid,
        ::yas_desktop::STATUS_BUDGET => Status::ResourceExhausted,
        ::yas_desktop::STATUS_CONFLICT => Status::Conflict,
        _ => Status::Internal,
    }
}

#[cfg(target_os = "linux")]
fn media_input_status(status: super::media_input::InputStatus) -> Status {
    match status {
        super::media_input::InputStatus::Ok => Status::Ok,
        super::media_input::InputStatus::Invalid => Status::Invalid,
        super::media_input::InputStatus::Conflict => Status::Conflict,
        super::media_input::InputStatus::Permission => Status::Unavailable,
        super::media_input::InputStatus::Unavailable => Status::Unavailable,
    }
}

const fn selection_store_status(error: SelectionStoreError) -> Status {
    match error {
        SelectionStoreError::Conflict => Status::Conflict,
        SelectionStoreError::Stale => Status::Stale,
        SelectionStoreError::NotFound => Status::NotFound,
        SelectionStoreError::ResourceExhausted => Status::ResourceExhausted,
    }
}

fn selection_drag_items_fit_state(items: &[yas_selection::DragItem]) -> bool {
    yas_selection::CompleteEntity::Drag(yas_selection::DragRecord {
        drag_handle: 1,
        revision: 1,
        owner_session: [u8::MAX; 16],
        source_actions: yas_wire::schema::selection::ACTION_COPY as u16,
        selected_action: 0,
        target_surface: 0,
        items: items.to_vec(),
        extensions: Extensions::default(),
    })
    .state_record(RecordKind::Add)
    .ok()
    .map(|record| state_snapshot_record_event(1, 1, record))
    .and_then(|event| event.encode().ok())
    .is_some_and(|payload| payload.len() <= LEGACY_STATE_EVENT_PAYLOAD_BYTES)
}

const fn terminal_query_status(error: &super::yas_terminal_queries::Error) -> Status {
    match error {
        super::yas_terminal_queries::Error::Invalid(_) => Status::Invalid,
        super::yas_terminal_queries::Error::NotFound => Status::NotFound,
        super::yas_terminal_queries::Error::Stale => Status::Stale,
        super::yas_terminal_queries::Error::TooLarge => Status::ResourceExhausted,
        super::yas_terminal_queries::Error::Internal => Status::Internal,
    }
}

fn terminal_query_exceeds_initial_credit(
    kind: u16,
    byte_len: usize,
    initial_receive_credit: u64,
) -> bool {
    kind == yas_wire::schema::terminal::request::CWD
        && u64::try_from(byte_len).unwrap_or(u64::MAX) > initial_receive_credit
}

fn apply_terminal_feedback(
    view: &mut TerminalView,
    feedback: &yas_terminal::ViewFeedback,
) -> Result<bool, ()> {
    let last_sent = view.next_sequence.wrapping_sub(1);
    let Some(_) = terminal_feedback_advance(
        view.acknowledged_sequence,
        last_sent,
        feedback.presented_sequence,
    )?
    else {
        // Feedback is cumulative; an older report cannot revoke newer
        // presentation credit or queue state. The ambiguous half-range is
        // outside the negotiated <=255-frame serial window and is stale too.
        return Ok(false);
    };
    let had_credit = terminal_view_has_frame_credit(view);
    view.acknowledged_sequence = feedback.presented_sequence;
    view.decoder_queue_depth = feedback.decoder_queue_depth;
    view.available_frame_slots = feedback.available_frame_slots;
    Ok(!had_credit && terminal_view_has_frame_credit(view))
}

fn terminal_feedback_advance(
    acknowledged: u32,
    last_sent: u32,
    presented: u32,
) -> Result<Option<u32>, ()> {
    let sent = last_sent.wrapping_sub(acknowledged);
    debug_assert!(sent <= u32::from(TERMINAL_MAX_INFLIGHT_FRAMES));
    let advance = presented.wrapping_sub(acknowledged);
    if advance <= sent {
        Ok(Some(advance))
    } else if advance >= 0x8000_0000 {
        Ok(None)
    } else {
        Err(())
    }
}

fn terminal_view_has_frame_credit(view: &TerminalView) -> bool {
    let last_sent = view.next_sequence.wrapping_sub(1);
    let outstanding = last_sent.wrapping_sub(view.acknowledged_sequence);
    outstanding < u32::from(view.max_inflight_frames)
        && view.available_frame_slots != 0
        && view.decoder_queue_depth < view.queue_target
}

fn terminal_view_note_owed_frame(
    view: &mut TerminalView,
    final_state: bool,
    guard: &super::yas_terminal_backend::FrameGuard,
) {
    view.frame_owed = true;
    view.frame_owed_final_guard = final_state.then(|| guard.clone());
}

fn terminal_frame_from_state(
    view: &mut TerminalView,
    state: &yas_terminal_model::FrameState,
) -> Option<yas_terminal::TerminalFrame> {
    let source_cells = state
        .cells()
        .as_chunks::<{ yas_terminal_model::CELL_SIZE }>()
        .0
        .to_vec();
    let source_rows = usize::from(state.rows());
    let source_cols = usize::from(state.cols());
    // View dimensions are an offer, not a separate terminal grid. Publish
    // the shared PTY dimensions so cursor, scrollback and page navigation
    // describe the same rows; padding to a larger viewer invents blank rows.
    let rows = usize::from(view.rows.min(state.rows()));
    let cols = usize::from(view.cols.min(state.cols()));
    let mut cells = vec![[0; yas_terminal_model::CELL_SIZE]; rows.checked_mul(cols)?];
    for row in 0..rows.min(source_rows) {
        let copy_cols = cols.min(source_cols);
        let source = row.checked_mul(source_cols)?;
        let target = row.checked_mul(cols)?;
        cells[target..target + copy_cols]
            .copy_from_slice(&source_cells[source..source + copy_cols]);
    }
    let mut line_flags = vec![0; rows];
    let line_count = rows.min(state.line_flags().len());
    line_flags[..line_count].copy_from_slice(&state.line_flags()[..line_count]);
    let mut overflow = BTreeMap::new();
    for (&index, value) in state.overflow() {
        let row = index / source_cols.max(1);
        let col = index % source_cols.max(1);
        if row < rows && col < cols {
            overflow.insert(row * cols + col, value.clone());
        }
    }
    let mut cell_links = vec![0; rows.checked_mul(cols)?];
    for row in 0..rows.min(source_rows) {
        let copy_cols = cols.min(source_cols);
        let source = row.checked_mul(source_cols)?;
        let target = row.checked_mul(cols)?;
        let available = state
            .cell_links()
            .len()
            .saturating_sub(source)
            .min(copy_cols);
        if available != 0 {
            cell_links[target..target + available]
                .copy_from_slice(&state.cell_links()[source..source + available]);
        }
    }
    let mut components = Vec::new();
    if line_flags.iter().any(|flags| *flags != 0) {
        components.push(yas_terminal::Component {
            kind: yas_wire::schema::terminal::COMPONENT_LINE_FLAGS as u8,
            required: false,
            body: terminal_line_flags_component(&line_flags),
        });
    }
    if !overflow.is_empty() {
        components.push(yas_terminal::Component {
            kind: yas_wire::schema::terminal::COMPONENT_OVERFLOW_STRINGS as u8,
            required: false,
            body: terminal_overflow_component(&overflow),
        });
    }
    if cell_links.iter().any(|link| *link != 0) {
        components.push(yas_terminal::Component {
            kind: yas_wire::schema::terminal::COMPONENT_HYPERLINKS as u8,
            required: false,
            body: terminal_hyperlink_component(&cell_links, state.link_uris()),
        });
    }
    let mut frame_flags = yas_wire::schema::terminal::FRAME_KEYFRAME as u16
        | yas_wire::schema::terminal::FRAME_DIMENSIONS as u16
        | yas_wire::schema::terminal::FRAME_CURSOR as u16
        | yas_wire::schema::terminal::FRAME_MODES as u16
        | yas_wire::schema::terminal::FRAME_SCROLLBACK as u16
        | yas_wire::schema::terminal::FRAME_VIEW_OFFSET as u16
        | yas_wire::schema::terminal::FRAME_TITLE as u16;
    if !components.is_empty() {
        frame_flags |= yas_wire::schema::terminal::FRAME_COMPONENTS as u16;
    }
    if view.final_state {
        frame_flags |= yas_wire::schema::terminal::FRAME_FINAL_STATE as u16;
    }
    let mut grid = yas_terminal::Grid {
        dimensions: Some((rows as u16, cols as u16)),
        cursor: Some((
            state.cursor_row().min((rows as u16).saturating_sub(1)),
            state.cursor_col().min((cols as u16).saturating_sub(1)),
        )),
        modes: Some(state.mode()),
        scrollback_lines: Some(state.scrollback_lines()),
        scroll_offset: Some(view.scroll_offset),
        title: Some(state.title().to_owned()),
        operations: vec![yas_terminal::GridOperation::PatchRun {
            start_cell: 0,
            cells,
        }],
        components,
    };
    // The view declared `frame_bound` at OPEN_VIEW and its peer reserved
    // exactly that much; a frame that does not fit must shrink rather than
    // overrun the reservation. Every component here is optional, and the
    // grid without them is bounded by the cells the declaration was sized on.
    let grid_payload = match grid.encode_codec1(frame_flags, view.frame_bound, None) {
        Ok(payload) => payload,
        Err(_) if !grid.components.is_empty() => {
            grid.components.clear();
            frame_flags &= !(yas_wire::schema::terminal::FRAME_COMPONENTS as u16);
            grid.encode_codec1(frame_flags, view.frame_bound, None)
                .ok()?
        }
        Err(_) => return None,
    };
    let sequence = view.next_sequence;
    view.next_sequence = sequence.wrapping_add(1);
    Some(yas_terminal::TerminalFrame {
        view_id: view_id_nonzero(view),
        frame_sequence: sequence,
        frame_flags,
        base_sequence: None,
        grid_payload,
    })
}

fn encode_terminal_frame_wire_events(
    frame: &yas_terminal::TerminalFrame,
    peer_max_frame: u32,
    peer_max_encoded: u32,
) -> Result<Vec<(u16, Vec<u8>)>, ()> {
    let logical = frame.encode_logical_body().map_err(|_| ())?;
    if logical.len() > peer_max_encoded as usize {
        return Err(());
    }
    let maximum = peer_max_frame.min(peer_max_encoded) as usize;
    let frame_header =
        FrameHeader::event(family::TERMINAL, yas_wire::schema::terminal::event::FRAME);
    let ordinary_len = frame_header
        .encoded_len()
        .checked_add(8)
        .and_then(|length| length.checked_add(logical.len()))
        .ok_or(())?;
    if logical.len() <= yas_wire::frame::HARD_MAX_BULK_CHUNK as usize && ordinary_len <= maximum {
        return Ok(vec![(
            yas_wire::schema::terminal::event::FRAME,
            frame.encode().map_err(|_| ())?,
        )]);
    }

    let chunk_header = FrameHeader::event(
        family::TERMINAL,
        yas_wire::schema::terminal::event::FRAME_CHUNK,
    );
    let chunk_bytes = maximum
        .checked_sub(chunk_header.encoded_len().checked_add(16).ok_or(())?)
        .filter(|available| *available != 0)
        .map(|available| available.min(yas_wire::frame::HARD_MAX_BULK_CHUNK as usize))
        .ok_or(())?;
    let chunk_count = u16::try_from(logical.len().div_ceil(chunk_bytes)).map_err(|_| ())?;
    let logical_frame_len = u32::try_from(logical.len()).map_err(|_| ())?;
    logical
        .chunks(chunk_bytes)
        .enumerate()
        .map(|(index, chunk)| {
            let payload = yas_terminal::FrameChunk {
                view_id: frame.view_id,
                frame_sequence: frame.frame_sequence,
                chunk_index: u16::try_from(index).map_err(|_| ())?,
                chunk_count,
                logical_frame_len,
                chunk: chunk.to_vec(),
            }
            .encode()
            .map_err(|_| ())?;
            Ok((yas_wire::schema::terminal::event::FRAME_CHUNK, payload))
        })
        .collect()
}

async fn enqueue_terminal_frame_wire_events(
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
    wire_events: Vec<(u16, Vec<u8>)>,
    completion: Arc<TerminalFrameWriteCompletion>,
    guard: super::yas_terminal_backend::FrameWriteGuard,
) -> Result<bool, ()> {
    if wire_events.is_empty() {
        return Err(());
    }
    let event_count = wire_events.len();
    let mut written = Some(completion);
    for (index, (kind, payload)) in wire_events.into_iter().enumerate() {
        if cancellation.is_cancelled() {
            return Ok(false);
        }
        let mut header = FrameHeader::event(family::TERMINAL, kind);
        header.sensitive = true;
        let confirmation = (index + 1 == event_count).then(|| {
            written
                .take()
                .expect("last Terminal frame Event has write receipt")
        });
        let result = tokio::select! {
            biased;
            _ = cancellation.cancelled() => return Ok(false),
            result = out.send_terminal_queued(
                Frame { header, payload },
                confirmation,
                guard.clone(),
            ) => result,
        };
        if result.is_err() {
            return if cancellation.is_cancelled() {
                Ok(false)
            } else {
                Err(())
            };
        }
    }
    Ok(true)
}

/// Upper bound on one codec 1 grid frame for a `rows` x `cols` Terminal view.
///
/// This is both what the view declares to its peer and the byte budget its
/// frames are encoded against, so the declaration holds by construction. The
/// caller clamps the result to the peer's negotiated `receive_max_decoded`.
///
/// Cells are rounded up to [`TERMINAL_FRAME_CELL_BUCKET`] so that a view keeps
/// the same bound across the small growths a resize is made of; a bound sized
/// to the exact geometry makes every single one of them a refused
/// CONFIGURE_VIEW and a reopened view.
fn terminal_view_frame_bound(rows: u16, cols: u16) -> u32 {
    let cells = u32::from(rows).saturating_mul(u32::from(cols));
    let cells = cells
        .div_ceil(TERMINAL_FRAME_CELL_BUCKET)
        .saturating_mul(TERMINAL_FRAME_CELL_BUCKET);
    cells
        .saturating_mul(TERMINAL_CELL_BYTES)
        .saturating_add(TERMINAL_FRAME_PREFIX_BYTES)
        .saturating_add(TERMINAL_FRAME_TITLE_ALLOWANCE)
        .saturating_add(TERMINAL_FRAME_COMPONENT_ALLOWANCE)
        .max(TERMINAL_FRAME_FLOOR)
}

/// Bytes a codec 1 keyframe cannot shed for this geometry.
///
/// Optional components are already dropped by `terminal_frame_from_state`
/// when they do not fit. CONFIGURE_VIEW therefore only needs to reopen a view
/// when its cells and required state exceed the bound the peer reserved; using
/// the preferred opening bound here also charged every resize for optional
/// component headroom and made an ordinary maximize rebuild the whole view.
fn terminal_view_required_frame_bound(rows: u16, cols: u16) -> u32 {
    u32::from(rows)
        .saturating_mul(u32::from(cols))
        .saturating_mul(TERMINAL_CELL_BYTES)
        .saturating_add(TERMINAL_FRAME_PREFIX_BYTES)
        .saturating_add(TERMINAL_FRAME_TITLE_ALLOWANCE)
}

fn view_id_nonzero(view: &TerminalView) -> u32 {
    // Views are keyed by their ID in `TerminalRuntime`; preserve it in the
    // value as well once the bridge starts emitting frames.
    view.view_id
}

fn put_terminal_uleb(out: &mut Vec<u8>, mut value: u32) {
    loop {
        let mut byte = (value & 0x7f) as u8;
        value >>= 7;
        if value != 0 {
            byte |= 0x80;
        }
        out.push(byte);
        if value == 0 {
            return;
        }
    }
}

fn terminal_line_flags_component(flags: &[u8]) -> Vec<u8> {
    let mut runs = Vec::new();
    let mut index = 0usize;
    while index < flags.len() {
        if flags[index] == 0 {
            index += 1;
            continue;
        }
        let start = index;
        let value = flags[index];
        index += 1;
        while index < flags.len() && flags[index] == value {
            index += 1;
        }
        runs.push((start, index - start, value));
    }
    let mut out = Vec::new();
    put_terminal_uleb(&mut out, u32::try_from(runs.len()).unwrap_or(u32::MAX));
    for (start, length, flags) in runs {
        put_terminal_uleb(&mut out, u32::try_from(start).unwrap_or(u32::MAX));
        put_terminal_uleb(&mut out, u32::try_from(length).unwrap_or(u32::MAX));
        out.push(flags);
    }
    out
}

fn terminal_overflow_component(overflow: &std::collections::BTreeMap<usize, String>) -> Vec<u8> {
    let mut out = Vec::new();
    put_terminal_uleb(&mut out, u32::try_from(overflow.len()).unwrap_or(u32::MAX));
    for (&index, value) in overflow {
        put_terminal_uleb(&mut out, u32::try_from(index).unwrap_or(u32::MAX));
        put_terminal_uleb(&mut out, u32::try_from(value.len()).unwrap_or(u32::MAX));
        out.extend_from_slice(value.as_bytes());
    }
    out
}

fn terminal_hyperlink_component(
    cell_links: &[u16],
    links: &std::collections::BTreeMap<u16, String>,
) -> Vec<u8> {
    let mut out = Vec::new();
    put_terminal_uleb(&mut out, u32::try_from(links.len()).unwrap_or(u32::MAX));
    for (&id, uri) in links {
        put_terminal_uleb(&mut out, u32::from(id));
        put_terminal_uleb(&mut out, u32::try_from(uri.len()).unwrap_or(u32::MAX));
        out.extend_from_slice(uri.as_bytes());
    }
    let mut runs = Vec::new();
    let mut index = 0usize;
    while index < cell_links.len() {
        if cell_links[index] == 0 || !links.contains_key(&cell_links[index]) {
            index += 1;
            continue;
        }
        let start = index;
        let id = cell_links[index];
        index += 1;
        while index < cell_links.len() && cell_links[index] == id {
            index += 1;
        }
        runs.push((start, index - start, id));
    }
    put_terminal_uleb(&mut out, u32::try_from(runs.len()).unwrap_or(u32::MAX));
    for (start, length, id) in runs {
        put_terminal_uleb(&mut out, u32::try_from(start).unwrap_or(u32::MAX));
        put_terminal_uleb(&mut out, u32::try_from(length).unwrap_or(u32::MAX));
        put_terminal_uleb(&mut out, u32::from(id));
    }
    out
}

