async fn run_extension_watch(
    subscription_id: u32,
    service: super::yas_extension::Runtime,
    mut snapshot: super::yas_extension::Snapshot,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let mut revision = snapshot.revision;
    if send_extension_state_event(
        subscription_id,
        Phase::SnapshotBegin,
        0,
        revision,
        Vec::new(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    for record in snapshot.records.drain(..) {
        let Ok(record) = record.state_record(RecordKind::Add) else {
            return;
        };
        if send_extension_state_event(
            subscription_id,
            Phase::SnapshotRecords,
            revision,
            revision,
            vec![record],
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
        )
        .await
        .is_err()
        {
            return;
        }
    }
    if send_extension_state_event(
        subscription_id,
        Phase::SnapshotEnd,
        revision,
        revision,
        Vec::new(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        snapshot = tokio::select! {
            result = service.changed(revision, monotonic_ns) => match result {
                Ok(snapshot) => snapshot,
                Err(_) => return,
            },
            _ = cancellation.cancelled() => return,
        };
        let next = snapshot.revision;
        if send_extension_state_event(
            subscription_id,
            Phase::Reset,
            revision,
            next,
            Vec::new(),
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
        )
        .await
        .is_err()
            || send_extension_state_event(
                subscription_id,
                Phase::SnapshotBegin,
                0,
                next,
                Vec::new(),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
        {
            return;
        }
        for record in snapshot.records.drain(..) {
            let Ok(record) = record.state_record(RecordKind::Add) else {
                return;
            };
            if send_extension_state_event(
                subscription_id,
                Phase::SnapshotRecords,
                next,
                next,
                vec![record],
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
            {
                return;
            }
        }
        if send_extension_state_event(
            subscription_id,
            Phase::SnapshotEnd,
            next,
            next,
            Vec::new(),
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
        )
        .await
        .is_err()
        {
            return;
        }
        revision = next;
    }
}

fn truncate_utf8_from_budget(value: &str, budget: &mut usize, field_limit: usize) -> String {
    let maximum = (*budget).min(field_limit);
    let value = truncate_utf8(value, maximum);
    *budget = budget.saturating_sub(value.len());
    value
}

fn bounded_lsp_state_entity(mut entity: yas_lsp_wire::StateEntity) -> yas_lsp_wire::StateEntity {
    match &mut entity {
        yas_lsp_wire::StateEntity::Backend(record) => {
            record.last_message =
                truncate_utf8(&record.last_message, MAX_LSP_STATE_SERVER_MESSAGE_BYTES);
        }
        yas_lsp_wire::StateEntity::Diagnostics(record) => {
            let mut budget = MAX_LSP_STATE_DIAGNOSTIC_TEXT_BYTES;
            for diagnostic in &mut record.diagnostics {
                diagnostic.code = truncate_utf8_from_budget(
                    &diagnostic.code,
                    &mut budget,
                    yas_wire::schema::lsp::MAX_DIAGNOSTIC_CODE_BYTES as usize,
                );
                diagnostic.source = truncate_utf8_from_budget(
                    &diagnostic.source,
                    &mut budget,
                    yas_wire::schema::lsp::MAX_LANGUAGE_BYTES as usize,
                );
                diagnostic.message = truncate_utf8_from_budget(
                    &diagnostic.message,
                    &mut budget,
                    yas_wire::schema::lsp::MAX_DIAGNOSTIC_MESSAGE_BYTES as usize,
                );
            }
        }
        yas_lsp_wire::StateEntity::Buffer(_) => {}
    }
    entity
}

fn lsp_state_record(
    entity: yas_lsp_wire::StateEntity,
    kind: RecordKind,
) -> Result<yas_wire::state::Record, ()> {
    bounded_lsp_state_entity(entity)
        .state_record(kind)
        .map_err(|_| ())
}

