fn git_watched_query_record(
    outcome: Result<super::yas_git_adapter::QueryData, super::yas_git_adapter::Error>,
    kind: RecordKind,
) -> Result<yas_wire::state::Record, ()> {
    let value = match outcome {
        Ok(data) => {
            let mut records = Vec::with_capacity(data.records.len());
            for item in data.records {
                let super::yas_git_adapter::QueryItem::Record(record) = item else {
                    return Err(());
                };
                records.push(record.encode_typed().map_err(|_| ())?);
            }
            let flags = if matches!(data.next_cursor, yas_git_wire::QueryCursor::Start) {
                0
            } else {
                yas_wire::schema::git::QUERY_PAGE_MORE as u16
            };
            yas_git_wire::WatchedQueryValue {
                status: Status::Ok,
                detail: String::new(),
                page: Some(yas_git_wire::QueryPage {
                    next_cursor: data.next_cursor,
                    total_hint: data.total_hint,
                    flags,
                    delivery: yas_git_wire::PageDelivery::Inline(records),
                    extensions: Extensions::default(),
                }),
            }
        }
        Err(error) => yas_git_wire::WatchedQueryValue {
            status: error.status,
            detail: if error.detail.is_empty() {
                "Git watched query failed".to_owned()
            } else {
                truncate_utf8(&error.detail, MAX_GIT_QUERY_STATE_DETAIL_BYTES)
            },
            page: None,
        },
    };
    Ok(yas_wire::state::Record {
        kind,
        required: false,
        body: value.encode().map_err(|_| ())?,
    })
}

fn git_query_state_payload(
    subscription_id: u32,
    phase: Phase,
    from_revision: u64,
    to_revision: u64,
    records: Vec<yas_wire::state::Record>,
) -> Result<Vec<u8>, ()> {
    yas_git_wire::QueryState {
        query_subscription_id: subscription_id,
        event: StateEvent {
            subscription_id,
            phase,
            flags: 0,
            from_revision,
            to_revision,
            records,
        },
    }
    .encode()
    .map_err(|_| ())
}

fn bounded_git_query_record(
    subscription_id: u32,
    phase: Phase,
    from_revision: u64,
    to_revision: u64,
    record: yas_wire::state::Record,
    limit: StateEventLimit,
) -> Result<yas_wire::state::Record, ()> {
    if git_query_state_payload(
        subscription_id,
        phase,
        from_revision,
        to_revision,
        vec![record.clone()],
    )
    .is_ok_and(|payload| payload.len() <= limit.max_payload_bytes)
    {
        return Ok(record);
    }
    let fallback = yas_wire::state::Record {
        kind: record.kind,
        required: false,
        body: yas_git_wire::WatchedQueryValue {
            status: Status::ResourceExhausted,
            detail: "Git watched query page exceeds the State publication limit".to_owned(),
            page: None,
        }
        .encode()
        .map_err(|_| ())?,
    };
    git_query_state_payload(
        subscription_id,
        phase,
        from_revision,
        to_revision,
        vec![fallback.clone()],
    )
    .is_ok_and(|payload| payload.len() <= limit.max_payload_bytes)
    .then_some(fallback)
    .ok_or(())
}

#[allow(clippy::too_many_arguments)]
async fn send_git_query_state_event(
    subscription_id: u32,
    phase: Phase,
    from_revision: u64,
    to_revision: u64,
    records: Vec<yas_wire::state::Record>,
    limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    let payload =
        git_query_state_payload(subscription_id, phase, from_revision, to_revision, records)?;
    if payload.len() > limit.max_payload_bytes {
        return Err(());
    }
    let end = sent_bytes.checked_add(payload.len() as u64).ok_or(())?;
    if !control.wait_through(end, cancellation).await {
        return Err(());
    }
    let mut header = FrameHeader::event(family::GIT, yas_git_wire::event_kind::QUERY_STATE);
    header.sensitive = true;
    tokio::select! {
        result = out.send(Frame { header, payload }) => result.map_err(|_| ())?,
        _ = cancellation.cancelled() => return Err(()),
    }
    if !control.record_sent(end) {
        return Err(());
    }
    *sent_bytes = end;
    Ok(())
}

async fn run_git_query_watch(
    subscription_id: u32,
    mut watch: super::yas_git_adapter::QueryWatch,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let mut revision = 1u64;
    let mut snapshot = true;
    loop {
        let update = tokio::select! {
            update = watch.next() => update,
            _ = cancellation.cancelled() => return,
        };
        let Some(update) = update else {
            return;
        };
        let kind = if snapshot {
            RecordKind::Add
        } else {
            RecordKind::Replace
        };
        let Ok(record) = git_watched_query_record(update.result, kind) else {
            return;
        };
        if snapshot {
            let Ok(record) = bounded_git_query_record(
                subscription_id,
                Phase::SnapshotRecords,
                revision,
                revision,
                record,
                event_limit,
            ) else {
                return;
            };
            if send_git_query_state_event(
                subscription_id,
                Phase::SnapshotBegin,
                0,
                revision,
                Vec::new(),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
                || send_git_query_state_event(
                    subscription_id,
                    Phase::SnapshotRecords,
                    revision,
                    revision,
                    vec![record],
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                || send_git_query_state_event(
                    subscription_id,
                    Phase::SnapshotEnd,
                    revision,
                    revision,
                    Vec::new(),
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
            {
                return;
            }
            snapshot = false;
        } else {
            let next = revision.saturating_add(1).max(1);
            let Ok(record) = bounded_git_query_record(
                subscription_id,
                Phase::Delta,
                revision,
                next,
                record,
                event_limit,
            ) else {
                return;
            };
            if send_git_query_state_event(
                subscription_id,
                Phase::Delta,
                revision,
                next,
                vec![record],
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
            {
                return;
            }
            revision = next;
        }
        watch.acknowledge(update.update_id);
    }
}

async fn run_git_watch(
    subscription_id: u32,
    mut revision: u64,
    mut watch: super::yas_git_adapter::Watch,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    if send_git_snapshot(
        subscription_id,
        revision,
        Vec::new(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        let event = tokio::select! {
            event = watch.next() => event,
            _ = cancellation.cancelled() => return,
        };
        let Some(event) = event else {
            return;
        };
        match event {
            Err(_) => return,
            Ok(super::yas_git_adapter::WatchEvent::Closed(closed)) => {
                let _ = send_event_with_sensitivity(
                    &out,
                    family::GIT,
                    yas_git_wire::event_kind::CLOSED,
                    &closed,
                    &cancellation,
                    true,
                )
                .await;
                return;
            }
            Ok(super::yas_git_adapter::WatchEvent::Snapshot { state_id, records }) => {
                let next = revision.saturating_add(1).max(1);
                if send_git_state_event(
                    subscription_id,
                    Phase::Reset,
                    revision,
                    next,
                    Vec::new(),
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                if send_git_snapshot(
                    subscription_id,
                    next,
                    records,
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                revision = next;
                watch.acknowledge(state_id);
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn run_lsp_watch(
    subscription_id: u32,
    workspace_handle: u64,
    session: super::yas_lsp_adapter::Session,
    mut watch: super::yas_lsp_adapter::Watch,
    mut updates: tokio::sync::watch::Receiver<u64>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let mut revision = 1u64;
    let mut backend = Vec::new();
    let mut diagnostics = Vec::new();
    if send_lsp_snapshot(
        subscription_id,
        revision,
        session
            .buffer_snapshot(workspace_handle)
            .unwrap_or_default(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    enum Input {
        Backend(Option<Result<super::yas_lsp_adapter::WatchEvent, super::yas_lsp_adapter::Error>>),
        Buffer(Result<(), tokio::sync::watch::error::RecvError>),
    }
    loop {
        let input = tokio::select! {
            event = watch.next() => Input::Backend(event),
            update = updates.changed() => Input::Buffer(update),
            _ = cancellation.cancelled() => return,
        };
        let event = match input {
            Input::Buffer(Ok(())) => {
                let next = revision.saturating_add(1).max(1);
                if send_lsp_state_event(
                    subscription_id,
                    Phase::Reset,
                    revision,
                    next,
                    Vec::new(),
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                let mut entities = session
                    .buffer_snapshot(workspace_handle)
                    .unwrap_or_default();
                entities.extend(backend.iter().cloned());
                entities.extend(diagnostics.iter().cloned());
                if send_lsp_snapshot(
                    subscription_id,
                    next,
                    entities,
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                revision = next;
                continue;
            }
            Input::Buffer(Err(_)) => return,
            Input::Backend(Some(event)) => event,
            Input::Backend(None) => return,
        };
        match event {
            Err(_) => return,
            Ok(super::yas_lsp_adapter::WatchEvent::Snapshot {
                stream,
                update_id,
                entities,
            }) => {
                match stream {
                    super::yas_lsp_adapter::WatchStream::Backend => backend = entities,
                    super::yas_lsp_adapter::WatchStream::Diagnostics => diagnostics = entities,
                }
                let next = revision.saturating_add(1).max(1);
                if send_lsp_state_event(
                    subscription_id,
                    Phase::Reset,
                    revision,
                    next,
                    Vec::new(),
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                let mut entities = session
                    .buffer_snapshot(workspace_handle)
                    .unwrap_or_default();
                entities.extend(backend.iter().cloned());
                entities.extend(diagnostics.iter().cloned());
                if send_lsp_snapshot(
                    subscription_id,
                    next,
                    entities,
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                revision = next;
                watch.acknowledge(stream, update_id);
            }
        }
    }
}

async fn run_fs_watch(
    subscription_id: u32,
    mut watch: super::yas_fs::Watch,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let mut revision = 1u64;
    let mut snapshot = true;
    if send_fs_state_event(
        subscription_id,
        Phase::SnapshotBegin,
        0,
        revision,
        Vec::new(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        let update = tokio::select! {
            update = watch.recv() => match update {
                Some(Ok(update)) => update,
                Some(Err(_)) | None => return,
            },
            _ = cancellation.cancelled() => return,
        };
        if update.reset && !snapshot {
            let next = revision.saturating_add(1).max(1);
            if send_fs_state_event(
                subscription_id,
                Phase::Reset,
                revision,
                next,
                Vec::new(),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
                || send_fs_state_event(
                    subscription_id,
                    Phase::SnapshotBegin,
                    0,
                    next,
                    Vec::new(),
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
            {
                return;
            }
            revision = next;
            snapshot = true;
        }
        let complete_kind = if snapshot {
            RecordKind::Add
        } else {
            RecordKind::Replace
        };
        let mut records = Vec::with_capacity(update.mutations.len());
        for mutation in update.mutations {
            let Ok(record) = mutation.state_record(complete_kind) else {
                return;
            };
            records.push(record);
        }
        if snapshot {
            for record in records {
                if send_fs_state_event(
                    subscription_id,
                    Phase::SnapshotRecords,
                    revision,
                    revision,
                    vec![record],
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
            }
        } else if records.is_empty() {
            let next = revision.saturating_add(1).max(1);
            if send_fs_state_event(
                subscription_id,
                Phase::Delta,
                revision,
                next,
                Vec::new(),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
            {
                return;
            }
            revision = next;
        } else {
            // A delta transition is complete in one STATE frame. If the
            // filesystem watcher produced several records, advance the
            // adapter-owned revision once per bounded frame instead of
            // repeating one `from_revision`, which would look like a gap to
            // a client after it applied the first record.
            for record in records {
                let next = revision.saturating_add(1).max(1);
                if send_fs_state_event(
                    subscription_id,
                    Phase::Delta,
                    revision,
                    next,
                    vec![record],
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                revision = next;
            }
        }
        if update.snapshot_end && snapshot {
            if send_fs_state_event(
                subscription_id,
                Phase::SnapshotEnd,
                revision,
                revision,
                Vec::new(),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
            {
                return;
            }
            snapshot = false;
        }
        // The outer FlowControl has already charged this update against the
        // peer's bounded State credit. Releasing the filesystem watcher here
        // lets it produce the next bounded batch without buffering an extra
        // copy.
        if watch.ack(update.update_id).is_err() {
            return;
        }
    }
}

fn truncate_utf8(value: &str, maximum: usize) -> String {
    if value.len() <= maximum {
        return value.to_owned();
    }
    let mut end = maximum;
    while !value.is_char_boundary(end) {
        end -= 1;
    }
    value[..end].to_owned()
}

#[allow(clippy::too_many_arguments)]
fn spawn_byte_transfer_with_sensitivity(
    transfer_id: u32,
    bytes: Vec<u8>,
    control: Arc<FlowControl>,
    out: FrameSender,
    internal: mpsc::Sender<Internal>,
    cancellation: ConnectionCancellation,
    permit: Option<OwnedSemaphorePermit>,
    sensitive: bool,
) {
    tokio::spawn(async move {
        let _permit = permit;
        let mut offset = 0u64;
        for chunk in bytes.chunks(TRANSFER_CHUNK) {
            let end = match offset.checked_add(chunk.len() as u64) {
                Some(end) => end,
                None => break,
            };
            if !control.wait_through(end, &cancellation).await {
                let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                return;
            }
            let data = ByteData {
                transfer_id,
                offset,
                data: chunk.to_vec(),
            };
            if send_event_with_sensitivity(
                &out,
                family::TRANSFER,
                yas_wire::schema::transfer::event::BYTE_DATA,
                &data,
                &cancellation,
                sensitive,
            )
            .await
            .is_err()
            {
                let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                return;
            }
            if !control.record_sent(end) {
                let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                return;
            }
            offset = end;
        }
        let close = Close {
            transfer_id,
            final_data_bytes: offset,
            status: Status::Ok.code(),
            detail: Vec::new(),
        };
        let _ = send_event_with_sensitivity(
            &out,
            family::TRANSFER,
            yas_wire::schema::transfer::event::CLOSE,
            &close,
            &cancellation,
            sensitive,
        )
        .await;
        let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
    });
}

fn spawn_extension_follow(
    transfer_id: u32,
    mut stream: super::yas_extension::FollowStream,
    control: Arc<FlowControl>,
    out: FrameSender,
    internal: mpsc::Sender<Internal>,
    cancellation: ConnectionCancellation,
) {
    tokio::spawn(async move {
        let mut total_sent = 0u64;
        let mut message_sequence = 0u64;
        loop {
            let item = tokio::select! {
                item = stream.next() => item,
                _ = control.cancelled(&cancellation) => {
                    let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                    return;
                }
            };
            match item {
                Some(super::yas_extension::FollowItem::Batch(batch)) => {
                    let Ok(message) = batch.encode() else {
                        break;
                    };
                    let mut fragment_offset = 0u64;
                    for (index, chunk) in message.chunks(TRANSFER_CHUNK).enumerate() {
                        let Some(end) = total_sent.checked_add(chunk.len() as u64) else {
                            break;
                        };
                        if !control.wait_through(end, &cancellation).await {
                            let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                            return;
                        }
                        let fragment_end = fragment_offset.saturating_add(chunk.len() as u64);
                        let event = MessageData {
                            transfer_id,
                            sequence: message_sequence,
                            fragment_offset,
                            start: index == 0,
                            end: fragment_end == message.len() as u64,
                            data: chunk.to_vec(),
                        };
                        if send_event_with_sensitivity(
                            &out,
                            family::TRANSFER,
                            yas_wire::schema::transfer::event::MESSAGE_DATA,
                            &event,
                            &cancellation,
                            true,
                        )
                        .await
                        .is_err()
                            || !control.record_sent(end)
                        {
                            let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                            return;
                        }
                        total_sent = end;
                        fragment_offset = fragment_end;
                    }
                    message_sequence = message_sequence.saturating_add(1);
                }
                Some(super::yas_extension::FollowItem::Complete { .. }) => {
                    let close = Close {
                        transfer_id,
                        final_data_bytes: total_sent,
                        status: Status::Ok.code(),
                        detail: Vec::new(),
                    };
                    let _ = send_event_with_sensitivity(
                        &out,
                        family::TRANSFER,
                        yas_wire::schema::transfer::event::CLOSE,
                        &close,
                        &cancellation,
                        true,
                    )
                    .await;
                    let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
                    return;
                }
                None => break,
            }
        }
        if !control.is_cancelled() && !cancellation.is_cancelled() {
            let _ = send_event_with_sensitivity(
                &out,
                family::TRANSFER,
                yas_wire::schema::transfer::event::RESET,
                &Reset {
                    transfer_id,
                    status: Status::Unavailable.code(),
                    detail: Vec::new(),
                },
                &cancellation,
                true,
            )
            .await;
        }
        let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
    });
}

fn spawn_message_transfer(
    transfer_id: u32,
    messages: Vec<Vec<u8>>,
    control: Arc<FlowControl>,
    out: FrameSender,
    internal: mpsc::Sender<Internal>,
    cancellation: ConnectionCancellation,
    sensitive: bool,
) {
    spawn_message_transfer_inner(
        transfer_id,
        messages,
        control,
        out,
        internal,
        cancellation,
        sensitive,
        None,
    );
}

fn spawn_message_transfer_confirmed(
    transfer_id: u32,
    messages: Vec<Vec<u8>>,
    control: Arc<FlowControl>,
    out: FrameSender,
    internal: mpsc::Sender<Internal>,
    cancellation: ConnectionCancellation,
    sensitive: bool,
) -> oneshot::Receiver<bool> {
    let (published, receiver) = oneshot::channel();
    spawn_message_transfer_inner(
        transfer_id,
        messages,
        control,
        out,
        internal,
        cancellation,
        sensitive,
        Some(published),
    );
    receiver
}

#[allow(clippy::too_many_arguments)]
fn spawn_message_transfer_inner(
    transfer_id: u32,
    messages: Vec<Vec<u8>>,
    control: Arc<FlowControl>,
    out: FrameSender,
    internal: mpsc::Sender<Internal>,
    cancellation: ConnectionCancellation,
    sensitive: bool,
    completion: Option<oneshot::Sender<bool>>,
) {
    tokio::spawn(async move {
        let confirm_close = completion.is_some();
        let published = async {
            let mut total_sent = 0u64;
            for (sequence, message) in messages.into_iter().enumerate() {
                let sequence = sequence as u64;
                let mut fragment_offset = 0u64;
                for (index, chunk) in message.chunks(TRANSFER_CHUNK).enumerate() {
                    let end = total_sent.checked_add(chunk.len() as u64).ok_or(())?;
                    if !control.wait_through(end, &cancellation).await {
                        return Err(());
                    }
                    let fragment_end = fragment_offset + chunk.len() as u64;
                    let data = MessageData {
                        transfer_id,
                        sequence,
                        fragment_offset,
                        start: index == 0,
                        end: fragment_end == message.len() as u64,
                        data: chunk.to_vec(),
                    };
                    send_event_with_sensitivity(
                        &out,
                        family::TRANSFER,
                        yas_wire::schema::transfer::event::MESSAGE_DATA,
                        &data,
                        &cancellation,
                        sensitive,
                    )
                    .await?;
                    if !control.record_sent(end) {
                        return Err(());
                    }
                    total_sent = end;
                    fragment_offset = fragment_end;
                }
            }
            let close = Close {
                transfer_id,
                final_data_bytes: total_sent,
                status: Status::Ok.code(),
                detail: Vec::new(),
            };
            if confirm_close {
                send_event_confirmed_with_sensitivity(
                    &out,
                    family::TRANSFER,
                    yas_wire::schema::transfer::event::CLOSE,
                    &close,
                    &cancellation,
                    sensitive,
                )
                .await?;
            } else {
                send_event_with_sensitivity(
                    &out,
                    family::TRANSFER,
                    yas_wire::schema::transfer::event::CLOSE,
                    &close,
                    &cancellation,
                    sensitive,
                )
                .await?;
            }
            Ok::<(), ()>(())
        }
        .await
        .is_ok();
        if let Some(completion) = completion {
            let _ = completion.send(published);
        }
        let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
    });
}

#[allow(clippy::too_many_arguments)]
fn spawn_font_fetch(
    transfer_id: u32,
    catalogue: Arc<FontCatalog>,
    content_hash: [u8; 32],
    expected_len: u64,
    control: Arc<FlowControl>,
    out: FrameSender,
    internal: mpsc::Sender<Internal>,
    cancellation: ConnectionCancellation,
    permit: OwnedSemaphorePermit,
) {
    tokio::spawn(async move {
        let fetched =
            tokio::task::spawn_blocking(move || catalogue.fetch_face(&content_hash)).await;
        match fetched {
            Ok(Ok(bytes))
                if bytes.len() as u64 == expected_len
                    && blake3::hash(&bytes).as_bytes() == &content_hash =>
            {
                spawn_byte_transfer(
                    transfer_id,
                    bytes,
                    control,
                    out,
                    internal,
                    cancellation,
                    Some(permit),
                );
            }
            outcome => {
                let status = match outcome {
                    Ok(Err(FontFetchError::NotFound)) => Status::NotFound,
                    Ok(Err(FontFetchError::Changed)) => Status::Stale,
                    Ok(Err(FontFetchError::DisabledByPolicy))
                    | Ok(Err(FontFetchError::RestrictedEmbedding)) => Status::Unavailable,
                    Ok(Err(FontFetchError::TooLarge)) => Status::ResourceExhausted,
                    Ok(Err(FontFetchError::Io | FontFetchError::Invalid)) => Status::Io,
                    Ok(Ok(_)) | Err(_) => Status::Internal,
                };
                let reset = Reset {
                    transfer_id,
                    status: status.code(),
                    detail: Vec::new(),
                };
                let _ = send_event(
                    &out,
                    family::TRANSFER,
                    yas_wire::schema::transfer::event::RESET,
                    &reset,
                    &cancellation,
                )
                .await;
                drop(permit);
                let _ = internal.send(Internal::TransferFinished(transfer_id)).await;
            }
        }
    });
}

async fn send_event<T: Encode>(
    out: &FrameSender,
    family_id: u16,
    kind: u16,
    value: &T,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_event_with_sensitivity(out, family_id, kind, value, cancellation, false).await
}

async fn send_event_with_sensitivity<T: Encode>(
    out: &FrameSender,
    family_id: u16,
    kind: u16,
    value: &T,
    cancellation: &ConnectionCancellation,
    sensitive: bool,
) -> Result<(), ()> {
    let payload = value.encode().map_err(|_| ())?;
    let mut header = FrameHeader::event(family_id, kind);
    header.sensitive = sensitive
        || yas_wire::schema::operation(family_id, Class::Event as u8, kind).is_some_and(
            |operation| operation.sensitive == yas_wire::schema::transport::policy::REQUIRED,
        );
    let frame = Frame { header, payload };
    tokio::select! {
        result = out.send(frame) => result.map_err(|_| ()),
        _ = cancellation.cancelled() => Err(()),
    }
}

async fn send_event_confirmed_with_sensitivity<T: Encode>(
    out: &FrameSender,
    family_id: u16,
    kind: u16,
    value: &T,
    cancellation: &ConnectionCancellation,
    sensitive: bool,
) -> Result<(), ()> {
    let payload = value.encode().map_err(|_| ())?;
    let mut header = FrameHeader::event(family_id, kind);
    header.sensitive = sensitive
        || yas_wire::schema::operation(family_id, Class::Event as u8, kind).is_some_and(
            |operation| operation.sensitive == yas_wire::schema::transport::policy::REQUIRED,
        );
    let frame = Frame { header, payload };
    tokio::select! {
        result = out.send_confirmed(frame) => result.map_err(|_| ()),
        _ = cancellation.cancelled() => Err(()),
    }
}

fn net_connect_status(error: super::net::NativeConnectError) -> Status {
    match error {
        super::net::NativeConnectError::Permission => Status::Unavailable,
        super::net::NativeConnectError::NotFound(_detail) => Status::NotFound,
        super::net::NativeConnectError::Refused(_detail)
        | super::net::NativeConnectError::Io(_detail) => Status::Io,
    }
}

fn socket_address(address: std::net::SocketAddr, datagram: bool) -> yas_net::Address {
    let host = address.ip().to_string();
    let port = address.port();
    if datagram {
        yas_net::Address::Udp { host, port }
    } else {
        yas_net::Address::Tcp { host, port }
    }
}

#[allow(clippy::too_many_arguments)]
fn spawn_native_tcp(
    flow_handle: u64,
    transfer_id: u32,
    stream: Box<dyn super::net::NativeIo>,
    mut input: mpsc::Receiver<NetTcpInput>,
    flow: Arc<FlowControl>,
    internal: mpsc::Sender<Internal>,
    connection: ConnectionCancellation,
    cancellation: ConnectionCancellation,
) {
    let (mut reader, mut writer) = tokio::io::split(stream);
    let writer_internal = internal.clone();
    let writer_connection = connection.clone();
    let writer_cancel = cancellation.clone();
    tokio::spawn(async move {
        let mut written = 0u64;
        loop {
            let command = tokio::select! {
                command = input.recv() => command,
                _ = writer_connection.cancelled() => return,
                _ = writer_cancel.cancelled() => return,
            };
            let Some(command) = command else { return };
            match command {
                NetTcpInput::Early(bytes) => {
                    if let Err(error) = writer.write_all(&bytes).await {
                        let _ = writer_internal
                            .send(Internal::NetFailed {
                                flow_handle,
                                detail: error.to_string(),
                            })
                            .await;
                        return;
                    }
                }
                NetTcpInput::Data(bytes) => {
                    if let Err(error) = writer.write_all(&bytes).await {
                        let _ = writer_internal
                            .send(Internal::NetFailed {
                                flow_handle,
                                detail: error.to_string(),
                            })
                            .await;
                        return;
                    }
                    written = written.saturating_add(bytes.len() as u64);
                    if writer_internal
                        .send(Internal::NetTcpWritten {
                            transfer_id,
                            cumulative_written: written,
                        })
                        .await
                        .is_err()
                    {
                        return;
                    }
                }
                NetTcpInput::Close => {
                    let _ = writer.shutdown().await;
                    return;
                }
            }
        }
    });

    tokio::spawn(async move {
        let mut offset = 0u64;
        let mut buffer = vec![0u8; TRANSFER_CHUNK];
        loop {
            let Some(available) = flow
                .available(offset, TRANSFER_CHUNK, &connection, &cancellation)
                .await
            else {
                return;
            };
            let read = tokio::select! {
                read = reader.read(&mut buffer[..available]) => read,
                _ = connection.cancelled() => return,
                _ = cancellation.cancelled() => return,
            };
            match read {
                Ok(0) => {
                    let _ = internal
                        .send(Internal::NetTcpEof {
                            transfer_id,
                            final_data_bytes: offset,
                        })
                        .await;
                    return;
                }
                Ok(count) => {
                    let data = buffer[..count].to_vec();
                    if internal
                        .send(Internal::NetTcpData {
                            transfer_id,
                            offset,
                            data,
                        })
                        .await
                        .is_err()
                    {
                        return;
                    }
                    offset = offset.saturating_add(count as u64);
                }
                Err(error) => {
                    let _ = internal
                        .send(Internal::NetFailed {
                            flow_handle,
                            detail: error.to_string(),
                        })
                        .await;
                    return;
                }
            }
        }
    });
}

#[allow(clippy::too_many_arguments)]
fn spawn_native_message(
    flow_handle: u64,
    transfer_id: u32,
    socket: NativeMessageSocket,
    mut input: mpsc::Receiver<NetMessageInput>,
    flow: Arc<FlowControl>,
    max_message_bytes: u64,
    internal: mpsc::Sender<Internal>,
    connection: ConnectionCancellation,
    cancellation: ConnectionCancellation,
) {
    let writer_socket = socket.clone();
    let writer_internal = internal.clone();
    let writer_connection = connection.clone();
    let writer_cancel = cancellation.clone();
    tokio::spawn(async move {
        let mut written = 0u64;
        loop {
            let command = tokio::select! {
                command = input.recv() => command,
                _ = writer_connection.cancelled() => return,
                _ = writer_cancel.cancelled() => return,
            };
            let Some(command) = command else { return };
            match command {
                NetMessageInput::Early(bytes) => match writer_socket.send(&bytes).await {
                    Ok(count) if count == bytes.len() => {}
                    Ok(_) => {
                        let _ = writer_internal
                            .send(Internal::NetFailed {
                                flow_handle,
                                detail: "partial native message write".to_owned(),
                            })
                            .await;
                        return;
                    }
                    Err(error) => {
                        let _ = writer_internal
                            .send(Internal::NetFailed {
                                flow_handle,
                                detail: error.to_string(),
                            })
                            .await;
                        return;
                    }
                },
                NetMessageInput::Message(bytes) => match writer_socket.send(&bytes).await {
                    Ok(count) if count == bytes.len() => {
                        written = written.saturating_add(count as u64);
                        if writer_internal
                            .send(Internal::NetMessageWritten {
                                transfer_id,
                                cumulative_written: written,
                            })
                            .await
                            .is_err()
                        {
                            return;
                        }
                    }
                    Ok(_) => {
                        let _ = writer_internal
                            .send(Internal::NetFailed {
                                flow_handle,
                                detail: "partial native message write".to_owned(),
                            })
                            .await;
                        return;
                    }
                    Err(error) => {
                        let _ = writer_internal
                            .send(Internal::NetFailed {
                                flow_handle,
                                detail: error.to_string(),
                            })
                            .await;
                        return;
                    }
                },
                NetMessageInput::Close => {
                    let _ = writer_socket.shutdown_write();
                    return;
                }
            }
        }
    });

    tokio::spawn(async move {
        let maximum = usize::try_from(max_message_bytes)
            .unwrap_or(usize::MAX)
            .min(NET_MAX_MESSAGE_BYTES as usize);
        let mut buffer = vec![0u8; maximum.saturating_add(1)];
        let mut offset = 0u64;
        let mut sequence = 0u64;
        loop {
            let read = tokio::select! {
                read = socket.recv(&mut buffer) => read,
                _ = connection.cancelled() => return,
                _ = cancellation.cancelled() => return,
            };
            match read {
                Ok(0) => {
                    let _ = internal
                        .send(Internal::NetMessageEof {
                            transfer_id,
                            final_data_bytes: offset,
                        })
                        .await;
                    return;
                }
                Ok(count) if count > maximum => {
                    let _ = internal
                        .send(Internal::NetFailed {
                            flow_handle,
                            detail: "native message exceeds negotiated maximum".to_owned(),
                        })
                        .await;
                    return;
                }
                Ok(count) => {
                    let Some(end) = offset.checked_add(count as u64) else {
                        return;
                    };
                    if !flow.wait_through(end, &connection).await {
                        return;
                    }
                    if internal
                        .send(Internal::NetMessage {
                            transfer_id,
                            sequence,
                            data: buffer[..count].to_vec(),
                        })
                        .await
                        .is_err()
                    {
                        return;
                    }
                    offset = end;
                    sequence = sequence.wrapping_add(1);
                }
                Err(error) => {
                    let _ = internal
                        .send(Internal::NetFailed {
                            flow_handle,
                            detail: error.to_string(),
                        })
                        .await;
                    return;
                }
            }
        }
    });
}

fn spawn_native_udp(
    flow_handle: u64,
    socket: NativeDatagramSocket,
    queue: Arc<super::net::DgramQueue>,
    stats: Arc<NetStats>,
    internal: mpsc::Sender<Internal>,
    connection: ConnectionCancellation,
    cancellation: ConnectionCancellation,
) {
    tokio::spawn(async move {
        let mut receive = vec![0u8; yas_net::MAX_DATAGRAM_PAYLOAD + 1];
        let mut sequence = 0u64;
        let mut interval = tokio::time::interval(NET_STATS_INTERVAL);
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                _ = connection.cancelled() => return,
                _ = cancellation.cancelled() => return,
                _ = interval.tick() => {
                    let _ = internal.try_send(Internal::NetDatagramStats(flow_handle));
                }
                outgoing = queue.pop() => {
                    let Some(payload) = outgoing else { return };
                    match socket.send(&payload).await {
                        Ok(_) => {
                            stats.client_to_peer_delivered.fetch_add(1, Ordering::Relaxed);
                        }
                        Err(error) => {
                            stats.transport_errors.fetch_add(1, Ordering::Relaxed);
                            let _ = internal.send(Internal::NetFailed {
                                flow_handle,
                                detail: error.to_string(),
                            }).await;
                            return;
                        }
                    }
                }
                incoming = socket.recv(&mut receive) => match incoming {
                    Ok(count) if count > yas_net::MAX_DATAGRAM_PAYLOAD => {
                        stats.peer_oversized_drops.fetch_add(1, Ordering::Relaxed);
                        sequence = sequence.wrapping_add(1);
                    }
                    Ok(count) => {
                        let event = Internal::NetDatagram {
                            flow_handle,
                            sequence,
                            payload: receive[..count].to_vec(),
                        };
                        sequence = sequence.wrapping_add(1);
                        match internal.try_send(event) {
                            Ok(()) => {}
                            Err(tokio::sync::mpsc::error::TrySendError::Full(_)) => {
                                stats.peer_congestive_drops.fetch_add(1, Ordering::Relaxed);
                            }
                            Err(tokio::sync::mpsc::error::TrySendError::Closed(_)) => return,
                        }
                    }
                    Err(error) => {
                        stats.transport_errors.fetch_add(1, Ordering::Relaxed);
                        let _ = internal.send(Internal::NetFailed {
                            flow_handle,
                            detail: error.to_string(),
                        }).await;
                        return;
                    }
                }
            }
        }
    });
}

fn net_datagram_stats(
    flow_handle: u64,
    flow: &NetUdpFlow,
    final_stats: bool,
) -> yas_net::DatagramStats {
    yas_net::DatagramStats {
        flow_handle,
        revision: flow.stats.revision.fetch_add(1, Ordering::Relaxed) + 1,
        final_stats,
        client_to_peer_delivered: flow.stats.client_to_peer_delivered.load(Ordering::Relaxed),
        peer_to_client_delivered: flow.stats.peer_to_client_delivered.load(Ordering::Relaxed),
        client_oversized_drops: flow.stats.client_oversized_drops.load(Ordering::Relaxed),
        peer_oversized_drops: flow.stats.peer_oversized_drops.load(Ordering::Relaxed),
        client_congestive_drops: flow
            .stats
            .client_congestive_drops
            .load(Ordering::Relaxed)
            .saturating_add(flow.queue.dropped()),
        peer_congestive_drops: flow.stats.peer_congestive_drops.load(Ordering::Relaxed),
        transport_errors: flow.stats.transport_errors.load(Ordering::Relaxed),
        extensions: Extensions::default(),
    }
}

fn kv_hash_field(hasher: &mut blake3::Hasher, bytes: &[u8]) {
    hasher.update(&(bytes.len() as u64).to_le_bytes());
    hasher.update(bytes);
}

fn kv_hash_precondition(hasher: &mut blake3::Hasher, value: &yas_kv::Precondition) {
    match value {
        yas_kv::Precondition::Any => {
            hasher.update(&[0]);
        }
        yas_kv::Precondition::Absent => {
            hasher.update(&[1]);
        }
        yas_kv::Precondition::Hash(hash) => {
            hasher.update(&[2]);
            hasher.update(hash);
        }
        yas_kv::Precondition::Revision(revision) => {
            hasher.update(&[3]);
            hasher.update(&revision.to_le_bytes());
        }
        yas_kv::Precondition::HashAndRevision {
            content_hash,
            modification_revision,
        } => {
            hasher.update(&[4]);
            hasher.update(content_hash);
            hasher.update(&modification_revision.to_le_bytes());
        }
    }
}

fn kv_operation_fingerprint(
    kind: u16,
    durable: bool,
    prefix: &[u8],
    extensions: &Extensions,
    mutations: &[yas_kv::Mutation],
    runtime: &KvRuntime,
    retained_stage_witnesses: &[super::kv::NativeStageWitness],
) -> Result<[u8; 32], Status> {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"yas.kv.operation.v1\0");
    hasher.update(&kind.to_le_bytes());
    hasher.update(&[u8::from(durable)]);
    kv_hash_field(&mut hasher, prefix);
    let extension_bytes = extensions.encode().map_err(|_| Status::Invalid)?;
    kv_hash_field(&mut hasher, &extension_bytes);
    hasher.update(&(mutations.len() as u64).to_le_bytes());
    let mut staged_ordinal = 0u16;
    for mutation in mutations {
        match mutation {
            yas_kv::Mutation::Put {
                relative_key,
                precondition,
                value,
                extensions,
            } => {
                hasher.update(&[0]);
                kv_hash_field(&mut hasher, relative_key);
                kv_hash_precondition(&mut hasher, precondition);
                match value {
                    yas_kv::ValueSource::Inline(bytes) => {
                        hasher.update(&[0]);
                        kv_hash_field(&mut hasher, bytes);
                    }
                    yas_kv::ValueSource::Staged(handle) => {
                        hasher.update(&[1]);
                        let metadata = runtime
                            .stages
                            .get(handle)
                            .map(|stage| {
                                if stage.sealed {
                                    Ok((stage.byte_len, stage.content_hash))
                                } else {
                                    Err(Status::Busy)
                                }
                            })
                            .or_else(|| {
                                runtime
                                    .consumed_stages
                                    .get(handle)
                                    .map(|stage| Ok((stage.byte_len, stage.content_hash)))
                            })
                            .or_else(|| {
                                retained_stage_witnesses
                                    .iter()
                                    .find(|witness| {
                                        witness.ordinal == staged_ordinal
                                            && witness.original_handle == *handle
                                    })
                                    .map(|witness| Ok((witness.byte_len, witness.content_hash)))
                            })
                            .ok_or(Status::NotFound)??;
                        staged_ordinal = staged_ordinal.checked_add(1).ok_or(Status::Invalid)?;
                        hasher.update(&metadata.0.to_le_bytes());
                        hasher.update(&metadata.1);
                    }
                }
                let extension_bytes = extensions.encode().map_err(|_| Status::Invalid)?;
                kv_hash_field(&mut hasher, &extension_bytes);
            }
            yas_kv::Mutation::Delete {
                relative_key,
                precondition,
                extensions,
            } => {
                hasher.update(&[1]);
                kv_hash_field(&mut hasher, relative_key);
                kv_hash_precondition(&mut hasher, precondition);
                let extension_bytes = extensions.encode().map_err(|_| Status::Invalid)?;
                kv_hash_field(&mut hasher, &extension_bytes);
            }
        }
    }
    Ok(*hasher.finalize().as_bytes())
}

fn encode_kv_commit(kind: u16, commit: &super::kv::NativeCommit) -> Result<Vec<u8>, ()> {
    let results = commit
        .results
        .iter()
        .map(|result| yas_kv::MutationResult {
            status: result.status,
            modification_revision: result.modification_revision,
            modified_unix_ns: i64::try_from(result.mtime_ns).unwrap_or(i64::MAX),
            content_hash: result.content_hash,
            byte_len: result.byte_len,
            extensions: Extensions::default(),
        })
        .collect::<Vec<_>>();
    if kind == yas_wire::schema::kv::request::BATCH {
        yas_kv::BatchResult {
            store_revision: commit.store_revision,
            results,
            extensions: Extensions::default(),
        }
        .encode()
        .map_err(|_| ())
    } else {
        let result = results.into_iter().next().ok_or(())?;
        result.encode().map_err(|_| ())
    }
}

#[cfg(target_os = "linux")]
fn media_audio_format(codec: u16, channels: u16) -> yas_media::MediaFormat {
    yas_media::MediaFormat {
        codec,
        channels,
        sample_rate: 48_000,
        width: 0,
        height: 0,
        frame_rate_milli: 0,
        extensions: Extensions::default(),
    }
}

#[cfg(target_os = "linux")]
fn media_video_format(codec: u16) -> yas_media::MediaFormat {
    yas_media::MediaFormat {
        codec,
        channels: 0,
        sample_rate: 0,
        width: 1_920,
        height: 1_080,
        frame_rate_milli: 30_000,
        extensions: Extensions::default(),
    }
}

#[cfg(target_os = "linux")]
fn media_camera_formats(codecs: u8) -> Vec<yas_media::MediaFormat> {
    [
        (
            MEDIA_VIDEO_CODEC_MJPEG,
            yas_wire::schema::media::CODEC_MJPEG as u16,
        ),
        (
            MEDIA_VIDEO_CODEC_H264,
            yas_wire::schema::media::CODEC_H264 as u16,
        ),
        (
            MEDIA_VIDEO_CODEC_AV1,
            yas_wire::schema::media::CODEC_AV1 as u16,
        ),
        (
            MEDIA_VIDEO_CODEC_H264_444,
            yas_wire::schema::media::CODEC_H264_444 as u16,
        ),
        (
            MEDIA_VIDEO_CODEC_AV1_444,
            yas_wire::schema::media::CODEC_AV1_444 as u16,
        ),
    ]
    .into_iter()
    .filter(|(mask, _)| codecs & mask != 0)
    .map(|(_, codec)| media_video_format(codec))
    .collect()
}

#[cfg(target_os = "linux")]
fn media_device_record(
    previous: Option<&yas_media::DeviceRecord>,
    device_handle: u64,
    kind: u8,
    available: bool,
    name: &str,
    formats: Vec<yas_media::MediaFormat>,
) -> yas_media::DeviceRecord {
    let revision = previous.map_or(1, |record| record.revision);
    let mut next = yas_media::DeviceRecord {
        device_handle,
        revision,
        kind,
        state: if available {
            yas_wire::schema::media::DEVICE_AVAILABLE as u8
        } else {
            yas_wire::schema::media::DEVICE_UNAVAILABLE as u8
        },
        flags: yas_wire::schema::media::DEVICE_DEFAULT as u16,
        name: name.to_owned(),
        formats,
        extensions: Extensions::default(),
    };
    if previous.is_some_and(|record| record != &next) {
        next.revision = revision.saturating_add(1).max(1);
    }
    next
}

#[cfg(target_os = "linux")]
fn rebuild_media_devices(runtime: &mut MediaRuntime) -> bool {
    let backend = runtime.backend_state.as_ref();
    let old = runtime.catalogue.devices.clone();
    let output = media_device_record(
        old.get(&MEDIA_OUTPUT_DEVICE_HANDLE),
        MEDIA_OUTPUT_DEVICE_HANDLE,
        yas_wire::schema::media::KIND_AUDIO_OUTPUT as u8,
        backend.is_some_and(|state| state.pipewire_available),
        "Default audio output",
        vec![media_audio_format(
            yas_wire::schema::media::CODEC_OPUS as u16,
            2,
        )],
    );
    let microphone = media_device_record(
        old.get(&MEDIA_MICROPHONE_DEVICE_HANDLE),
        MEDIA_MICROPHONE_DEVICE_HANDLE,
        yas_wire::schema::media::KIND_MICROPHONE as u8,
        backend.is_some_and(|state| state.microphone_available),
        "Viewer microphone",
        vec![
            media_audio_format(yas_wire::schema::media::CODEC_PCM_S16LE as u16, 1),
            media_audio_format(yas_wire::schema::media::CODEC_OPUS as u16, 1),
        ],
    );
    let mut camera_formats = media_camera_formats(runtime.backend_video_codecs);
    if camera_formats.is_empty() {
        camera_formats.push(media_video_format(
            yas_wire::schema::media::CODEC_MJPEG as u16,
        ));
    }
    let camera = media_device_record(
        old.get(&MEDIA_CAMERA_DEVICE_HANDLE),
        MEDIA_CAMERA_DEVICE_HANDLE,
        yas_wire::schema::media::KIND_CAMERA as u8,
        backend.is_some_and(|state| state.camera_available),
        "Viewer camera",
        camera_formats,
    );
    runtime.catalogue.devices = [output, microphone, camera]
        .into_iter()
        .map(|record| (record.device_handle, record))
        .collect();
    let changed = runtime.catalogue.devices != old;
    if changed {
        runtime.catalogue.revision = runtime.catalogue.revision.saturating_add(1).max(1);
    }
    changed
}

#[cfg(target_os = "linux")]
fn media_input_kind_codec(
    kind: u8,
    codec: u16,
) -> Option<(
    super::media_input::InputKind,
    super::media_input::InputCodec,
)> {
    if kind == yas_wire::schema::media::KIND_MICROPHONE as u8 {
        return match codec {
            value if value == yas_wire::schema::media::CODEC_PCM_S16LE as u16 => Some((
                super::media_input::InputKind::Microphone,
                super::media_input::InputCodec::PcmS16Le,
            )),
            value if value == yas_wire::schema::media::CODEC_OPUS as u16 => Some((
                super::media_input::InputKind::Microphone,
                super::media_input::InputCodec::Opus,
            )),
            _ => None,
        };
    }
    if kind != yas_wire::schema::media::KIND_CAMERA as u8 {
        return None;
    }
    match codec {
        value if value == yas_wire::schema::media::CODEC_MJPEG as u16 => Some((
            super::media_input::InputKind::Camera,
            super::media_input::InputCodec::Mjpeg,
        )),
        value if value == yas_wire::schema::media::CODEC_H264 as u16 => Some((
            super::media_input::InputKind::Camera,
            super::media_input::InputCodec::H264,
        )),
        value if value == yas_wire::schema::media::CODEC_AV1 as u16 => Some((
            super::media_input::InputKind::Camera,
            super::media_input::InputCodec::Av1,
        )),
        value if value == yas_wire::schema::media::CODEC_H264_444 as u16 => Some((
            super::media_input::InputKind::Camera,
            super::media_input::InputCodec::H264Cs444,
        )),
        value if value == yas_wire::schema::media::CODEC_AV1_444 as u16 => Some((
            super::media_input::InputKind::Camera,
            super::media_input::InputCodec::Av1Cs444,
        )),
        _ => None,
    }
}

#[cfg(target_os = "linux")]
fn media_input_payloads(kind: u8, codec: u16, bytes: &[u8]) -> Result<Vec<Vec<u8>>, ()> {
    if kind != yas_wire::schema::media::KIND_MICROPHONE as u8
        || codec != yas_wire::schema::media::CODEC_OPUS as u16
    {
        return (!bytes.is_empty()).then(|| vec![bytes.to_vec()]).ok_or(());
    }
    if bytes.len() < 6 {
        return Err(());
    }
    let count = usize::from(u16::from_le_bytes([bytes[0], bytes[1]]));
    if count == 0 || bytes[2..4] != [0, 0] {
        return Err(());
    }
    let mut cursor = 4usize;
    let mut packets = Vec::with_capacity(count);
    for _ in 0..count {
        let length_end = cursor.checked_add(2).ok_or(())?;
        let length = usize::from(u16::from_le_bytes(
            bytes
                .get(cursor..length_end)
                .ok_or(())?
                .try_into()
                .map_err(|_| ())?,
        ));
        cursor = length_end;
        if length == 0 || length > 1_275 {
            return Err(());
        }
        let end = cursor.checked_add(length).ok_or(())?;
        packets.push(bytes.get(cursor..end).ok_or(())?.to_vec());
        cursor = end;
    }
    if cursor != bytes.len() {
        return Err(());
    }
    Ok(packets)
}

#[cfg(target_os = "linux")]
fn media_format_is_supported(
    device: &yas_media::DeviceRecord,
    offered: &yas_media::MediaFormat,
) -> bool {
    device
        .formats
        .iter()
        .any(|format| format.codec == offered.codec)
        && match device.kind {
            value if value == yas_wire::schema::media::KIND_AUDIO_OUTPUT as u8 => {
                offered.codec == yas_wire::schema::media::CODEC_OPUS as u16
                    && offered.sample_rate == 48_000
                    && offered.channels == 2
            }
            value if value == yas_wire::schema::media::KIND_MICROPHONE as u8 => {
                offered.sample_rate == 48_000 && offered.channels == 1
            }
            value if value == yas_wire::schema::media::KIND_CAMERA as u8 => {
                offered.width <= u32::from(u16::MAX)
                    && offered.height <= u32::from(u16::MAX)
                    && offered.frame_rate_milli.is_multiple_of(1_000)
                    && offered.frame_rate_milli / 1_000 <= 120
            }
            _ => false,
        }
}

#[cfg(target_os = "linux")]
fn media_operation_fingerprint(kind: u16, payload: &[u8]) -> [u8; 32] {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"yas.media.operation.v1\0");
    hasher.update(&kind.to_le_bytes());
    hasher.update(payload);
    *hasher.finalize().as_bytes()
}

#[cfg(target_os = "linux")]
fn media_store_asset(runtime: &mut MediaRuntime, bytes: &[u8]) -> Option<[u8; 32]> {
    if bytes.is_empty() || bytes.len() > ::yas_desktop::MPRIS_ARTWORK_MAX {
        return None;
    }
    let hash = *blake3::hash(bytes).as_bytes();
    if runtime.assets.contains_key(&hash) {
        return Some(hash);
    }
    let next = runtime.asset_bytes.checked_add(bytes.len())?;
    if next > MAX_MEDIA_ASSET_BYTES {
        return None;
    }
    runtime.assets.insert(hash, Arc::new(bytes.to_vec()));
    runtime.asset_bytes = next;
    Some(hash)
}

#[cfg(target_os = "linux")]
fn media_player_record(
    runtime: &mut MediaRuntime,
    player: &::yas_desktop::MprisPlayer,
) -> Option<yas_media::PlayerRecord> {
    let mut extensions = Extensions::default();
    match &player.artwork {
        ::yas_desktop::MprisArtwork::Png(bytes) => {
            if let Some(hash) = media_store_asset(runtime, bytes) {
                extensions.0.push(Extension {
                    tag: yas_wire::schema::media::PLAYER_ALBUM_ART_HASH_EXTENSION as u16,
                    required: false,
                    value: hash.to_vec(),
                });
            }
        }
        ::yas_desktop::MprisArtwork::Url(url) if ::yas_desktop::artwork_url_allowed(url) => {
            extensions.0.push(Extension {
                tag: yas_wire::schema::media::PLAYER_ALBUM_ART_URL_EXTENSION as u16,
                required: false,
                value: url.as_bytes().to_vec(),
            });
        }
        ::yas_desktop::MprisArtwork::None | ::yas_desktop::MprisArtwork::Url(_) => {}
    }
    extensions
        .0
        .push(yas_media::player_active_extension(player.active));
    extensions.0.sort_by_key(|extension| extension.tag);
    Some(yas_media::PlayerRecord {
        player_handle: runtime.player_handle(player.player_id)?,
        revision: u64::from(player.revision).max(1),
        state: player.playback_status as u16,
        flags: player.capability_flags,
        position_us: player.position_us.max(0),
        duration_us: player.length_us.max(-1),
        identity: truncate_utf8(&player.identity, u16::MAX as usize),
        desktop_entry: truncate_utf8(&player.desktop_entry, u16::MAX as usize),
        title: truncate_utf8(&player.title, u16::MAX as usize),
        artist: truncate_utf8(&player.artists.join(", "), u16::MAX as usize),
        album: truncate_utf8(&player.album, u16::MAX as usize),
        extensions,
    })
}

#[cfg(target_os = "linux")]
fn rebuild_media_players(runtime: &mut MediaRuntime) -> bool {
    let players = runtime.mpris.players.values().cloned().collect::<Vec<_>>();
    let mut next = BTreeMap::new();
    let live_backend_ids = players
        .iter()
        .map(|player| player.player_id)
        .collect::<BTreeSet<_>>();
    for player in players {
        let Some(record) = media_player_record(runtime, &player) else {
            continue;
        };
        next.insert(record.player_handle, record);
    }
    runtime
        .player_handles
        .retain(|backend_id, _| live_backend_ids.contains(backend_id));
    runtime
        .player_backend_ids
        .retain(|_, backend_id| live_backend_ids.contains(backend_id));
    if next == runtime.catalogue.players {
        return false;
    }
    runtime.catalogue.players = next;
    runtime.catalogue.revision = runtime.catalogue.revision.saturating_add(1).max(1);
    true
}

#[cfg(target_os = "linux")]
fn media_player_action_kind(action: u16) -> Option<::yas_desktop::PlayerCommandKind> {
    match action {
        value if value == yas_wire::schema::media::PLAYER_ACTION_PLAY as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Play)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_PAUSE as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Pause)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_PLAY_PAUSE as u16 => {
            Some(::yas_desktop::PlayerCommandKind::PlayPause)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_STOP as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Stop)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_NEXT as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Next)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_PREVIOUS as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Previous)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_SEEK as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Seek)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_SET_POSITION as u16 => {
            Some(::yas_desktop::PlayerCommandKind::SetPosition)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_SET_VOLUME as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Volume)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_SET_SHUFFLE as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Shuffle)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_SET_LOOP as u16 => {
            Some(::yas_desktop::PlayerCommandKind::LoopStatus)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_SET_RATE as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Rate)
        }
        value if value == yas_wire::schema::media::PLAYER_ACTION_RAISE as u16 => {
            Some(::yas_desktop::PlayerCommandKind::Raise)
        }
        _ => None,
    }
}

#[cfg(target_os = "linux")]
type MediaPortalReplyParts = (
    ::yas_desktop::PortalResponseDecision,
    Vec<u16>,
    Vec<::yas_desktop::PortalResponseChoice>,
    Option<MediaPortalGrant>,
);

#[cfg(target_os = "linux")]
fn media_portal_reply_parts(
    request: &yas_media::PortalReply,
    resolved_surfaces: Option<&[u16]>,
) -> Result<MediaPortalReplyParts, Status> {
    match (request.decision, &request.metadata) {
        (decision, yas_media::PortalReplyMetadata::Empty)
            if decision == yas_wire::schema::media::PORTAL_DECISION_DENY as u8 =>
        {
            Ok((
                ::yas_desktop::PortalResponseDecision::Deny,
                Vec::new(),
                Vec::new(),
                None,
            ))
        }
        (decision, yas_media::PortalReplyMetadata::Empty)
            if decision == yas_wire::schema::media::PORTAL_DECISION_CANCEL as u8 =>
        {
            Ok((
                ::yas_desktop::PortalResponseDecision::Cancelled,
                Vec::new(),
                Vec::new(),
                None,
            ))
        }
        (decision, yas_media::PortalReplyMetadata::AccessGrant(metadata))
            if decision == yas_wire::schema::media::PORTAL_DECISION_GRANT as u8
                && request.kind == yas_wire::schema::media::PORTAL_KIND_ACCESS as u16 =>
        {
            let choices = metadata
                .choices
                .iter()
                .map(|choice| ::yas_desktop::PortalResponseChoice {
                    id: choice.id.clone(),
                    value: choice.value.clone(),
                })
                .collect();
            Ok((
                ::yas_desktop::PortalResponseDecision::Grant,
                Vec::new(),
                choices,
                Some(MediaPortalGrant::Access(metadata.clone())),
            ))
        }
        (decision, yas_media::PortalReplyMetadata::ScreenCastGrant(metadata))
            if decision == yas_wire::schema::media::PORTAL_DECISION_GRANT as u8
                && request.kind == yas_wire::schema::media::PORTAL_KIND_SCREENCAST as u16 =>
        {
            let surfaces = resolved_surfaces
                .filter(|surfaces| surfaces.len() == metadata.surface_handles.len())
                .ok_or(Status::Invalid)?
                .to_vec();
            Ok((
                ::yas_desktop::PortalResponseDecision::Grant,
                surfaces,
                Vec::new(),
                Some(MediaPortalGrant::ScreenCast),
            ))
        }
        _ => Err(Status::Invalid),
    }
}

#[cfg(target_os = "linux")]
fn media_portal_reply_matches(
    record: &yas_media::PortalRecord,
    reply: &yas_media::PortalReply,
) -> bool {
    if reply.decision != yas_wire::schema::media::PORTAL_DECISION_GRANT as u8 {
        return matches!(reply.metadata, yas_media::PortalReplyMetadata::Empty);
    }
    match (&record.metadata, &reply.metadata) {
        (
            yas_media::PortalRecordMetadata::Request(yas_media::PortalRequestMetadata::Access(
                request,
            )),
            yas_media::PortalReplyMetadata::AccessGrant(grant),
        ) => {
            grant.choices.len() == request.choices.len()
                && grant.choices.iter().all(|answer| {
                    request.choices.iter().any(|choice| {
                        choice.id == answer.id
                            && choice.options.iter().any(|option| {
                                option.id == answer.value || option.value == answer.value
                            })
                    })
                })
        }
        (
            yas_media::PortalRecordMetadata::Request(yas_media::PortalRequestMetadata::ScreenCast(
                request,
            )),
            yas_media::PortalReplyMetadata::ScreenCastGrant(grant),
        ) => {
            (!grant.surface_handles.is_empty())
                && (request.multiple || grant.surface_handles.len() == 1)
                && grant.surface_handles.iter().all(|surface| {
                    request
                        .candidates
                        .iter()
                        .any(|candidate| candidate.surface_handle == *surface)
                })
        }
        _ => false,
    }
}

#[cfg(target_os = "linux")]
fn media_portal_text(value: &str, maximum: usize, fallback: &str) -> String {
    let value = value.replace('\0', "");
    let value = if value.is_empty() { fallback } else { &value };
    truncate_utf8(value, maximum)
}

#[cfg(target_os = "linux")]
fn media_portal_request(
    runtime: &mut MediaRuntime,
    request: ::yas_desktop::PortalRequest,
    surface_handles: &HashMap<u16, u64>,
) -> Result<
    (
        yas_media::PortalRequest,
        yas_media::PortalRecord,
        MediaPortal,
    ),
    (),
> {
    let string_max = yas_media::Limits::HARD.max_portal_string_bytes as usize;
    let body_max = yas_media::Limits::HARD.max_portal_body_bytes as usize;
    let (request_id, app_id, parent_surface_id, kind, metadata) = match request {
        ::yas_desktop::PortalRequest::Access(request) => {
            let mut ids = BTreeSet::new();
            let choices = request
                .choices
                .into_iter()
                .filter_map(|choice| {
                    if choice.id.is_empty()
                        || choice.id.as_bytes().contains(&0)
                        || !ids.insert(choice.id.clone())
                    {
                        return None;
                    }
                    let mut option_ids = BTreeSet::new();
                    let options = choice
                        .options
                        .into_iter()
                        .filter_map(|option| {
                            (!option.id.is_empty()
                                && !option.value.is_empty()
                                && !option.id.as_bytes().contains(&0)
                                && !option.value.as_bytes().contains(&0)
                                && option_ids.insert(option.id.clone()))
                            .then(|| yas_media::PortalChoiceValue {
                                id: truncate_utf8(&option.id, string_max),
                                value: truncate_utf8(&option.value, string_max),
                            })
                        })
                        .collect::<Vec<_>>();
                    if options.is_empty() {
                        return None;
                    }
                    let initial = if options
                        .iter()
                        .any(|option| option.id == choice.initial_value)
                    {
                        truncate_utf8(&choice.initial_value, string_max)
                    } else {
                        String::new()
                    };
                    Some(yas_media::PortalChoice {
                        id: truncate_utf8(&choice.id, string_max),
                        label: media_portal_text(&choice.label, string_max, "Choice"),
                        initial,
                        options,
                    })
                })
                .take(yas_media::Limits::HARD.max_portal_choices as usize)
                .collect();
            let app_id = media_portal_text(&request.app_id, string_max, "unknown");
            (
                request.request_id,
                app_id.clone(),
                request.parent_surface_id,
                yas_wire::schema::media::PORTAL_KIND_ACCESS as u16,
                yas_media::PortalRequestMetadata::Access(yas_media::AccessRequestMetadata {
                    deadline_server_ns: monotonic_ns()
                        .saturating_add(u64::from(request.deadline_ms).saturating_mul(1_000_000))
                        .max(1),
                    parent_surface_handle: request
                        .parent_surface_id
                        .and_then(|backend_id| surface_handles.get(&backend_id).copied()),
                    app_id,
                    title: media_portal_text(&request.title, string_max, "Access request"),
                    subtitle: media_portal_text(&request.subtitle, string_max, ""),
                    body: media_portal_text(&request.body, body_max, ""),
                    deny_label: media_portal_text(&request.deny_label, string_max, "Deny"),
                    grant_label: media_portal_text(&request.grant_label, string_max, "Allow"),
                    icon_name: media_portal_text(&request.icon_name, string_max, ""),
                    choices,
                }),
            )
        }
        ::yas_desktop::PortalRequest::ScreenCast(request) => {
            let app_id = media_portal_text(&request.app_id, string_max, "unknown");
            let candidates = request
                .candidates
                .into_iter()
                .filter_map(|candidate| {
                    Some(yas_media::ScreenCastCandidate {
                        surface_handle: surface_handles.get(&candidate.surface_id).copied()?,
                        width: u32::from(candidate.width.max(1)),
                        height: u32::from(candidate.height.max(1)),
                        title: media_portal_text(&candidate.title, string_max, "Surface"),
                        app_id: media_portal_text(&candidate.app_id, string_max, &app_id),
                        thumbnail_hash: media_store_asset(runtime, &candidate.thumbnail_png),
                    })
                })
                .take(yas_media::Limits::HARD.max_screencast_candidates as usize)
                .collect::<Vec<_>>();
            if candidates.is_empty() {
                return Err(());
            }
            (
                request.request_id,
                app_id.clone(),
                request.parent_surface_id,
                yas_wire::schema::media::PORTAL_KIND_SCREENCAST as u16,
                yas_media::PortalRequestMetadata::ScreenCast(
                    yas_media::ScreenCastRequestMetadata {
                        deadline_server_ns: monotonic_ns()
                            .saturating_add(
                                u64::from(request.deadline_ms).saturating_mul(1_000_000),
                            )
                            .max(1),
                        parent_surface_handle: request
                            .parent_surface_id
                            .and_then(|backend_id| surface_handles.get(&backend_id).copied()),
                        app_id,
                        multiple: request.multiple,
                        candidates,
                    },
                ),
            )
        }
    };
    let portal_handle = alloc_presentation_handle().ok_or(())?;
    let revision = runtime
        .catalogue
        .portals
        .get(&portal_handle)
        .map_or(1, |record| record.revision.saturating_add(1).max(1));
    let event = yas_media::PortalRequest {
        portal_handle,
        revision,
        kind,
        flags: 0,
        application_handle: 0,
        metadata: metadata.clone(),
        extensions: Extensions::default(),
    };
    let record = yas_media::PortalRecord {
        portal_handle,
        revision,
        kind,
        state: yas_wire::schema::media::PORTAL_PENDING as u16,
        owner_session: runtime.owner_session,
        metadata: yas_media::PortalRecordMetadata::Request(metadata),
        extensions: Extensions::default(),
    };
    let portal = MediaPortal {
        request_id,
        application_id: app_id,
        selected_surfaces: Vec::new(),
        screencast_session_id: None,
        stream_handles: Vec::new(),
    };
    let _ = parent_surface_id;
    event.encode().map_err(|_| ())?;
    record.encode().map_err(|_| ())?;
    Ok((event, record, portal))
}

#[cfg(target_os = "linux")]
fn media_state_records(
    catalogue: &MediaCatalogue,
    kind: RecordKind,
) -> Result<Vec<yas_wire::state::Record>, ()> {
    let mut records = Vec::new();
    for record in catalogue.devices.values() {
        records.push(
            yas_media::CompleteEntity::Device(record.clone())
                .state_record(kind)
                .map_err(|_| ())?,
        );
    }
    for record in catalogue.leases.values() {
        records.push(
            yas_media::CompleteEntity::Lease(record.clone())
                .state_record(kind)
                .map_err(|_| ())?,
        );
    }
    for record in catalogue.portals.values() {
        records.push(
            yas_media::CompleteEntity::Portal(Box::new(record.clone()))
                .state_record(kind)
                .map_err(|_| ())?,
        );
    }
    for record in catalogue.players.values() {
        records.push(
            yas_media::CompleteEntity::Player(record.clone())
                .state_record(kind)
                .map_err(|_| ())?,
        );
    }
    Ok(records)
}

#[cfg(target_os = "linux")]
fn media_delta_records(
    old: &MediaCatalogue,
    new: &MediaCatalogue,
) -> Result<Vec<yas_wire::state::Record>, ()> {
    let mut records = Vec::new();
    macro_rules! diff_media_entities {
        ($old:expr, $new:expr, $entity:expr, $complete:path) => {{
            for (&handle, previous) in $old {
                if !$new.contains_key(&handle) {
                    records.push(
                        yas_media::RemovedEntity {
                            entity_kind: $entity as u16,
                            handle,
                            revision: previous.revision.saturating_add(1).max(1),
                        }
                        .state_record()
                        .map_err(|_| ())?,
                    );
                }
            }
            for (&handle, record) in $new {
                let kind = match $old.get(&handle) {
                    None => Some(RecordKind::Add),
                    Some(previous) if previous != record => Some(RecordKind::Replace),
                    Some(_) => None,
                };
                if let Some(kind) = kind {
                    records.push(
                        $complete(record.clone())
                            .state_record(kind)
                            .map_err(|_| ())?,
                    );
                }
            }
        }};
    }
    diff_media_entities!(
        &old.devices,
        &new.devices,
        yas_wire::schema::media::ENTITY_DEVICE,
        yas_media::CompleteEntity::Device
    );
    diff_media_entities!(
        &old.leases,
        &new.leases,
        yas_wire::schema::media::ENTITY_LEASE,
        yas_media::CompleteEntity::Lease
    );
    for (&handle, previous) in &old.portals {
        if !new.portals.contains_key(&handle) {
            records.push(
                yas_media::RemovedEntity {
                    entity_kind: yas_wire::schema::media::ENTITY_PORTAL as u16,
                    handle,
                    revision: previous.revision.saturating_add(1).max(1),
                }
                .state_record()
                .map_err(|_| ())?,
            );
        }
    }
    for (&handle, record) in &new.portals {
        let kind = match old.portals.get(&handle) {
            None => Some(RecordKind::Add),
            Some(previous) if previous != record => Some(RecordKind::Replace),
            Some(_) => None,
        };
        if let Some(kind) = kind {
            records.push(
                yas_media::CompleteEntity::Portal(Box::new(record.clone()))
                    .state_record(kind)
                    .map_err(|_| ())?,
            );
        }
    }
    diff_media_entities!(
        &old.players,
        &new.players,
        yas_wire::schema::media::ENTITY_PLAYER,
        yas_media::CompleteEntity::Player
    );
    Ok(records)
}

#[allow(clippy::too_many_arguments)]
#[cfg(target_os = "linux")]
async fn send_media_state_event(
    subscription_id: u32,
    phase: Phase,
    from_revision: u64,
    to_revision: u64,
    records: Vec<yas_wire::state::Record>,
    limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_bounded_state_event_with_sensitivity(
        family::MEDIA,
        yas_media::event_kind::STATE,
        &StateEvent {
            subscription_id,
            phase,
            flags: 0,
            from_revision,
            to_revision,
            records,
        },
        limit,
        sent_bytes,
        control,
        out,
        cancellation,
        true,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
#[cfg(target_os = "linux")]
async fn send_media_snapshot(
    subscription_id: u32,
    catalogue: &MediaCatalogue,
    event_limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_media_state_event(
        subscription_id,
        Phase::SnapshotBegin,
        0,
        catalogue.revision,
        Vec::new(),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
    )
    .await?;
    for record in media_state_records(catalogue, RecordKind::Add)? {
        send_media_state_event(
            subscription_id,
            Phase::SnapshotRecords,
            catalogue.revision,
            catalogue.revision,
            vec![record],
            event_limit,
            sent_bytes,
            control,
            out,
            cancellation,
        )
        .await?;
    }
    send_media_state_event(
        subscription_id,
        Phase::SnapshotEnd,
        catalogue.revision,
        catalogue.revision,
        Vec::new(),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
    )
    .await
}

#[cfg(target_os = "linux")]
async fn run_media_watch(
    subscription_id: u32,
    mut updates: tokio::sync::watch::Receiver<MediaCatalogue>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut catalogue = updates.borrow_and_update().clone();
    let mut sent_bytes = 0u64;
    if send_media_snapshot(
        subscription_id,
        &catalogue,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        tokio::select! {
            changed = updates.changed() => if changed.is_err() { return; },
            _ = cancellation.cancelled() => return,
        }
        let next = updates.borrow_and_update().clone();
        if next.revision <= catalogue.revision {
            continue;
        }
        let Ok(records) = media_delta_records(&catalogue, &next) else {
            return;
        };
        let delta = StateEvent {
            subscription_id,
            phase: Phase::Delta,
            flags: 0,
            from_revision: catalogue.revision,
            to_revision: next.revision,
            records,
        };
        let result = if let Some(reset) = state_delta_reset(&delta, event_limit) {
            if send_bounded_state_event_with_sensitivity(
                family::MEDIA,
                yas_media::event_kind::STATE,
                &reset,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                true,
            )
            .await
            .is_err()
            {
                return;
            }
            send_media_snapshot(
                subscription_id,
                &next,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
        } else {
            send_bounded_state_event_with_sensitivity(
                family::MEDIA,
                yas_media::event_kind::STATE,
                &delta,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                true,
            )
            .await
        };
        if result.is_err() {
            return;
        }
        catalogue = next;
    }
}

#[cfg(target_os = "linux")]
fn try_desktop_backend_command(
    compositor: &mut super::SharedCompositor,
    command: ::yas_desktop::Command,
) -> bool {
    #[cfg(test)]
    {
        compositor.native_desktop_commands.push(command);
        true
    }
    #[cfg(not(test))]
    {
        compositor
            .desktop_bus
            .as_ref()
            .is_some_and(|bus| bus.try_command(command))
    }
}

// Keep the three fixed, boot-lifetime Media device handles outside the
// boot-monotonic namespace used by dynamic Desktop and Media resources.
#[cfg(target_os = "linux")]
static NEXT_PRESENTATION_HANDLE: AtomicU64 = AtomicU64::new(1 << 32);

#[cfg(target_os = "linux")]
fn alloc_presentation_handle() -> Option<u64> {
    NEXT_PRESENTATION_HANDLE
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |next| {
            next.checked_add(1)
        })
        .ok()
}

#[cfg(target_os = "linux")]
fn desktop_operation_fingerprint(kind: u16, payload: &[u8]) -> [u8; 32] {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"yas.desktop.operation.v1\0");
    hasher.update(&kind.to_le_bytes());
    hasher.update(payload);
    *hasher.finalize().as_bytes()
}

#[cfg(target_os = "linux")]
fn desktop_store_asset(assets: &mut HashMap<[u8; 32], Arc<Vec<u8>>>, bytes: &[u8]) -> [u8; 32] {
    if bytes.is_empty() {
        return [0; 32];
    }
    let hash = *blake3::hash(bytes).as_bytes();
    if !assets.contains_key(&hash) {
        if assets.len() >= MAX_DESKTOP_ASSETS
            && let Some(stale) = assets.keys().next().copied()
        {
            assets.remove(&stale);
        }
        assets.insert(hash, Arc::new(bytes.to_vec()));
    }
    hash
}

#[cfg(target_os = "linux")]
fn desktop_catalogue_mutation_count(
    old: &DesktopCatalogue,
    tray: &BTreeMap<u64, yas_desktop::TrayRecord>,
    notifications: &BTreeMap<u64, yas_desktop::NotificationRecord>,
) -> u64 {
    let tray_changes = old
        .tray
        .iter()
        .filter(|(handle, record)| tray.get(handle) != Some(*record))
        .count()
        + tray
            .keys()
            .filter(|handle| !old.tray.contains_key(handle))
            .count();
    let notification_changes = old
        .notifications
        .iter()
        .filter(|(handle, record)| notifications.get(handle) != Some(*record))
        .count()
        + notifications
            .keys()
            .filter(|handle| !old.notifications.contains_key(handle))
            .count();
    u64::try_from(tray_changes.saturating_add(notification_changes)).unwrap_or(u64::MAX)
}

#[cfg(target_os = "linux")]
fn rebuild_desktop_runtime(runtime: &mut DesktopRuntime) -> Result<bool, ()> {
    let tray_handles = runtime.tray_handles.clone();
    let tray_backend_ids = runtime.tray_backend_ids.clone();
    let notification_handles = runtime.notification_handles.clone();
    let notification_backend_ids = runtime.notification_backend_ids.clone();
    let notification_action_handles = runtime.notification_action_handles.clone();
    let assets = runtime.assets.clone();
    let notification_actions = runtime.notification_actions.clone();
    let notification_expiry = runtime.notification_expiry.clone();
    let menus = runtime.menus.clone();
    let result = rebuild_desktop_runtime_inner(runtime);
    if result.is_err() {
        runtime.tray_handles = tray_handles;
        runtime.tray_backend_ids = tray_backend_ids;
        runtime.notification_handles = notification_handles;
        runtime.notification_backend_ids = notification_backend_ids;
        runtime.notification_action_handles = notification_action_handles;
        runtime.assets = assets;
        runtime.notification_actions = notification_actions;
        runtime.notification_expiry = notification_expiry;
        runtime.menus = menus;
    }
    result
}

#[cfg(target_os = "linux")]
fn rebuild_desktop_runtime_inner(runtime: &mut DesktopRuntime) -> Result<bool, ()> {
    let tray_items = runtime.backend.tray.values().cloned().collect::<Vec<_>>();
    let notifications = runtime
        .backend
        .notifications
        .values()
        .cloned()
        .collect::<Vec<_>>();
    let mut tray = BTreeMap::new();
    let mut live_tray_ids = BTreeSet::new();
    for item in tray_items {
        live_tray_ids.insert(item.tray_id);
        let handle = runtime.tray_handle(item.tray_id).ok_or(())?;
        let revision = u64::from(item.revision).max(1);
        let menu_revision = runtime
            .menus
            .get(&handle)
            .map_or(revision, |menu| menu.exposed_revision);
        let record = yas_desktop::TrayRecord {
            tray_handle: handle,
            revision,
            menu_revision,
            status: item.status,
            title: truncate_utf8(
                if item.title.is_empty() {
                    &item.tooltip_title
                } else {
                    &item.title
                },
                MAX_DESKTOP_STATE_TRAY_TITLE_BYTES,
            ),
            icon_hash: desktop_store_asset(&mut runtime.assets, &item.icon.png),
            extensions: Extensions::default(),
        };
        // Encoding is the canonical validation gate for a backend record.
        record.encode().map_err(|_| ())?;
        tray.insert(handle, record);
    }
    runtime
        .tray_handles
        .retain(|backend_id, _| live_tray_ids.contains(backend_id));
    runtime
        .tray_backend_ids
        .retain(|_, backend_id| live_tray_ids.contains(backend_id));
    runtime.menus.retain(|handle, _| tray.contains_key(handle));

    let mut notification_records = BTreeMap::new();
    let mut notification_actions = HashMap::new();
    let mut live_expiries = BTreeSet::new();
    let mut live_notification_ids = BTreeSet::new();
    let mut live_action_keys = BTreeSet::new();
    for notification in notifications {
        live_notification_ids.insert(notification.notification_id);
        let handle = runtime
            .notification_handle(notification.notification_id)
            .ok_or(())?;
        let revision = u64::from(notification.revision).max(1);
        let expiry_key = (handle, revision);
        live_expiries.insert(expiry_key);
        let expires_server_ns = if notification.timeout_ms == 0 {
            0
        } else {
            *runtime
                .notification_expiry
                .entry(expiry_key)
                .or_insert_with(|| {
                    monotonic_ns().saturating_add(u64::from(notification.timeout_ms) * 1_000_000)
                })
        };
        let mut text_budget = MAX_DESKTOP_STATE_NOTIFICATION_TEXT_BYTES;
        let application = truncate_utf8_from_budget(
            if notification.app_name.is_empty() {
                &notification.desktop_entry
            } else {
                &notification.app_name
            },
            &mut text_budget,
            u16::MAX as usize,
        );
        let summary =
            truncate_utf8_from_budget(&notification.summary, &mut text_budget, u16::MAX as usize);
        let body = truncate_utf8_from_budget(
            &notification.body,
            &mut text_budget,
            MAX_DESKTOP_STATE_NOTIFICATION_BODY_BYTES,
        );
        let mut actions = Vec::new();
        for action in notification
            .actions
            .iter()
            .filter(|action| action.key != "default")
            .take(yas_wire::schema::desktop::MAX_NOTIFICATION_ACTIONS as usize)
        {
            let action_key = (
                notification.notification_id,
                notification.revision,
                action.key.clone(),
            );
            live_action_keys.insert(action_key.clone());
            let action_handle =
                if let Some(&handle) = runtime.notification_action_handles.get(&action_key) {
                    handle
                } else {
                    let handle = alloc_presentation_handle().ok_or(())?;
                    runtime
                        .notification_action_handles
                        .insert(action_key, handle);
                    handle
                };
            actions.push(yas_desktop::NotificationButton {
                action_handle,
                label: truncate_utf8_from_budget(
                    &action.label,
                    &mut text_budget,
                    MAX_DESKTOP_STATE_NOTIFICATION_ACTION_LABEL_BYTES,
                ),
            });
            notification_actions.insert((handle, revision, action_handle), action.key.clone());
        }
        let mut flags = 0u16;
        if notification.flags & ::yas_desktop::NOTIFICATION_RESIDENT != 0 {
            flags |= yas_wire::schema::desktop::NOTIFICATION_RESIDENT as u16;
        }
        if notification.flags & ::yas_desktop::NOTIFICATION_TRANSIENT != 0 {
            flags |= yas_wire::schema::desktop::NOTIFICATION_TRANSIENT as u16;
        }
        let mut extensions = Vec::new();
        if !notification.image.png.is_empty() {
            let hash = desktop_store_asset(&mut runtime.assets, &notification.image.png);
            extensions.push(yas_desktop::notification_content_image_hash_extension(hash));
        }
        if !notification.icon.png.is_empty() {
            let hash = desktop_store_asset(&mut runtime.assets, &notification.icon.png);
            extensions.push(yas_desktop::notification_application_icon_hash_extension(
                hash,
            ));
        }
        let record = yas_desktop::NotificationRecord {
            notification_handle: handle,
            revision,
            flags,
            urgency: notification.urgency,
            expires_server_ns,
            application,
            summary,
            body,
            actions,
            extensions: Extensions(extensions),
        };
        record.encode().map_err(|_| ())?;
        notification_records.insert(handle, record);
    }
    runtime
        .notification_handles
        .retain(|backend_id, _| live_notification_ids.contains(backend_id));
    runtime
        .notification_backend_ids
        .retain(|_, backend_id| live_notification_ids.contains(backend_id));
    runtime
        .notification_action_handles
        .retain(|key, _| live_action_keys.contains(key));
    runtime
        .notification_expiry
        .retain(|key, _| live_expiries.contains(key));
    runtime.notification_actions = notification_actions;
    if tray == runtime.catalogue.tray && notification_records == runtime.catalogue.notifications {
        return Ok(false);
    }
    let changes =
        desktop_catalogue_mutation_count(&runtime.catalogue, &tray, &notification_records).max(1);
    runtime.catalogue.revision = runtime.catalogue.revision.saturating_add(changes).max(1);
    runtime.catalogue.tray = tray;
    runtime.catalogue.notifications = notification_records;
    while runtime.catalogue.removed_notifications.len()
        > yas_desktop::Limits::HARD.max_notifications as usize * 2
    {
        runtime.catalogue.removed_notifications.pop_first();
    }
    Ok(true)
}

#[cfg(target_os = "linux")]
fn desktop_menu_tree(
    menu: &::yas_desktop::TrayMenu,
    tray_handle: u64,
    exposed_revision: u64,
    assets: &mut HashMap<[u8; 32], Arc<Vec<u8>>>,
) -> Result<(yas_desktop::MenuTree, HashMap<u64, i32>), ()> {
    if menu.nodes.is_empty() || menu.nodes.len() > yas_desktop::Limits::HARD.max_menu_nodes as usize
    {
        return Err(());
    }
    let mut nodes = Vec::with_capacity(menu.nodes.len());
    let mut items = HashMap::new();
    let mut node_handles = HashMap::with_capacity(menu.nodes.len());
    for node in &menu.nodes {
        if node_handles
            .insert(node.id, alloc_presentation_handle().ok_or(())?)
            .is_some()
        {
            return Err(());
        }
    }
    for (index, node) in menu.nodes.iter().enumerate() {
        let node_handle = node_handles[&node.id];
        let root = index == 0;
        let separator = node.flags & ::yas_desktop::MENU_NODE_SEPARATOR != 0;
        let submenu = node.flags & ::yas_desktop::MENU_NODE_SUBMENU != 0;
        let kind = if root {
            yas_wire::schema::desktop::MENU_NODE_ROOT as u8
        } else if separator {
            yas_wire::schema::desktop::MENU_NODE_SEPARATOR as u8
        } else if submenu {
            yas_wire::schema::desktop::MENU_NODE_SUBMENU as u8
        } else {
            yas_wire::schema::desktop::MENU_NODE_ITEM as u8
        };
        let mut flags = 0u8;
        if node.flags & ::yas_desktop::MENU_NODE_VISIBLE != 0 {
            flags |= yas_wire::schema::desktop::MENU_VISIBLE as u8;
        }
        if node.flags & ::yas_desktop::MENU_NODE_ENABLED != 0 {
            flags |= yas_wire::schema::desktop::MENU_ENABLED as u8;
        }
        if node.toggle_state > 0 {
            flags |= yas_wire::schema::desktop::MENU_CHECKED as u8;
        }
        if node.flags & ::yas_desktop::MENU_NODE_RADIO != 0 {
            flags |= yas_wire::schema::desktop::MENU_RADIO as u8;
        }
        let clickable = !root
            && !separator
            && flags
                & (yas_wire::schema::desktop::MENU_VISIBLE as u8
                    | yas_wire::schema::desktop::MENU_ENABLED as u8)
                == yas_wire::schema::desktop::MENU_VISIBLE as u8
                    | yas_wire::schema::desktop::MENU_ENABLED as u8;
        let action_handle = if clickable { node_handle } else { 0 };
        if clickable {
            items.insert(action_handle, node.id);
        }
        nodes.push(yas_desktop::MenuNode {
            node_handle,
            parent_handle: if root {
                0
            } else {
                node_handles.get(&node.parent_id).copied().ok_or(())?
            },
            kind,
            flags,
            position: u32::from(node.position),
            action_handle,
            label: if separator {
                String::new()
            } else {
                node.label.clone()
            },
            shortcut: String::new(),
            icon_hash: desktop_store_asset(assets, &node.icon.png),
            extensions: Extensions::default(),
        });
    }
    let tree = yas_desktop::MenuTree {
        tray_handle,
        tray_revision: u64::from(menu.tray_revision).max(1),
        menu_revision: exposed_revision,
        nodes,
        extensions: Extensions::default(),
    };
    tree.encode().map_err(|_| ())?;
    Ok((tree, items))
}

#[cfg(target_os = "linux")]
fn desktop_state_records(
    catalogue: &DesktopCatalogue,
    datasets: u8,
    kind: RecordKind,
) -> Result<Vec<yas_wire::state::Record>, ()> {
    let mut records = Vec::new();
    if datasets & yas_wire::schema::desktop::WATCH_TRAY as u8 != 0 {
        for record in catalogue.tray.values() {
            records.push(
                yas_desktop::CompleteEntity::Tray(record.clone())
                    .state_record(kind)
                    .map_err(|_| ())?,
            );
        }
    }
    if datasets & yas_wire::schema::desktop::WATCH_NOTIFICATIONS as u8 != 0 {
        for record in catalogue.notifications.values() {
            records.push(
                yas_desktop::CompleteEntity::Notification(record.clone())
                    .state_record(kind)
                    .map_err(|_| ())?,
            );
        }
    }
    Ok(records)
}

#[cfg(target_os = "linux")]
fn desktop_delta_records(
    old: &DesktopCatalogue,
    new: &DesktopCatalogue,
    datasets: u8,
) -> Result<Vec<yas_wire::state::Record>, ()> {
    let mut records = Vec::new();
    if datasets & yas_wire::schema::desktop::WATCH_TRAY as u8 != 0 {
        for (&handle, previous) in &old.tray {
            if !new.tray.contains_key(&handle) {
                records.push(
                    yas_desktop::RemovedEntity::Tray {
                        handle,
                        revision: previous.revision.saturating_add(1).max(1),
                    }
                    .state_record()
                    .map_err(|_| ())?,
                );
            }
        }
        for (&handle, record) in &new.tray {
            let kind = match old.tray.get(&handle) {
                None => Some(RecordKind::Add),
                Some(previous) if previous != record => Some(RecordKind::Replace),
                Some(_) => None,
            };
            if let Some(kind) = kind {
                records.push(
                    yas_desktop::CompleteEntity::Tray(record.clone())
                        .state_record(kind)
                        .map_err(|_| ())?,
                );
            }
        }
    }
    if datasets & yas_wire::schema::desktop::WATCH_NOTIFICATIONS as u8 != 0 {
        for (&handle, previous) in &old.notifications {
            if !new.notifications.contains_key(&handle) {
                let (revision, close_reason) =
                    new.removed_notifications.get(&handle).copied().unwrap_or((
                        previous.revision.saturating_add(1).max(1),
                        yas_wire::schema::desktop::NOTIFICATION_CLOSED_UNDEFINED as u8,
                    ));
                records.push(
                    yas_desktop::RemovedEntity::Notification {
                        handle,
                        revision,
                        close_reason,
                    }
                    .state_record()
                    .map_err(|_| ())?,
                );
            }
        }
        for (&handle, record) in &new.notifications {
            let kind = match old.notifications.get(&handle) {
                None => Some(RecordKind::Add),
                Some(previous) if previous != record => Some(RecordKind::Replace),
                Some(_) => None,
            };
            if let Some(kind) = kind {
                records.push(
                    yas_desktop::CompleteEntity::Notification(record.clone())
                        .state_record(kind)
                        .map_err(|_| ())?,
                );
            }
        }
    }
    Ok(records)
}

#[allow(clippy::too_many_arguments)]
#[cfg(target_os = "linux")]
async fn send_desktop_state_event(
    subscription_id: u32,
    phase: Phase,
    from_revision: u64,
    to_revision: u64,
    records: Vec<yas_wire::state::Record>,
    limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_bounded_state_event_with_sensitivity(
        family::DESKTOP,
        yas_desktop::event_kind::STATE,
        &StateEvent {
            subscription_id,
            phase,
            flags: 0,
            from_revision,
            to_revision,
            records,
        },
        limit,
        sent_bytes,
        control,
        out,
        cancellation,
        true,
    )
    .await
}

#[cfg(target_os = "linux")]
async fn run_desktop_watch(
    subscription_id: u32,
    datasets: u8,
    mut updates: tokio::sync::watch::Receiver<DesktopCatalogue>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut catalogue = updates.borrow_and_update().clone();
    let mut sent_bytes = 0u64;
    if send_desktop_state_event(
        subscription_id,
        Phase::SnapshotBegin,
        0,
        catalogue.revision,
        Vec::new(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    let Ok(records) = desktop_state_records(&catalogue, datasets, RecordKind::Add) else {
        return;
    };
    for record in records {
        if send_desktop_state_event(
            subscription_id,
            Phase::SnapshotRecords,
            catalogue.revision,
            catalogue.revision,
            vec![record],
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
        )
        .await
        .is_err()
        {
            return;
        }
    }
    if send_desktop_state_event(
        subscription_id,
        Phase::SnapshotEnd,
        catalogue.revision,
        catalogue.revision,
        Vec::new(),
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        tokio::select! {
            changed = updates.changed() => if changed.is_err() { return; },
            _ = cancellation.cancelled() => return,
        }
        let next = updates.borrow_and_update().clone();
        if next.revision <= catalogue.revision {
            continue;
        }
        let Ok(records) = desktop_delta_records(&catalogue, &next, datasets) else {
            return;
        };
        if records.is_empty() {
            if send_desktop_state_event(
                subscription_id,
                Phase::Delta,
                catalogue.revision,
                next.revision,
                Vec::new(),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
            .is_err()
            {
                return;
            }
        } else {
            let mut from_revision = catalogue.revision;
            let last = records.len().saturating_sub(1);
            for (index, record) in records.into_iter().enumerate() {
                let to_revision = if index == last {
                    next.revision
                } else {
                    from_revision.saturating_add(1).min(next.revision)
                };
                if send_desktop_state_event(
                    subscription_id,
                    Phase::Delta,
                    from_revision,
                    to_revision,
                    vec![record],
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                )
                .await
                .is_err()
                {
                    return;
                }
                from_revision = to_revision;
            }
        }
        catalogue = next;
    }
}

fn has_unknown_required(extensions: &Extensions, supported: &[u16]) -> bool {
    extensions
        .0
        .iter()
        .any(|extension| extension.required && !supported.contains(&extension.tag))
}

const fn channel_status(error: ChannelError) -> Status {
    match error {
        ChannelError::Unavailable => Status::Unavailable,
        ChannelError::Conflict | ChannelError::Stale => Status::Conflict,
        ChannelError::NotFound => Status::NotFound,
        ChannelError::ResourceExhausted | ChannelError::Backpressured => Status::ResourceExhausted,
    }
}

const fn status_to_channel_error(status: Status) -> ChannelError {
    match status {
        Status::NotFound => ChannelError::NotFound,
        Status::Unavailable => ChannelError::Unavailable,
        Status::ResourceExhausted => ChannelError::ResourceExhausted,
        _ => ChannelError::Conflict,
    }
}

fn channel_listener_record(
    listener: &super::channel::NativeListener,
    kind: RecordKind,
) -> Result<yas_wire::state::Record, ()> {
    yas_channel::ListenerRecord {
        listener_handle: listener.listener_handle,
        generation: listener.generation,
        owner_kind: if listener.owner_extension {
            yas_channel::OwnerKind::Extension
        } else {
            yas_channel::OwnerKind::Session
        },
        owner_session: listener.owner_session,
        name: listener.name.clone(),
        metadata: listener.metadata.clone(),
        extensions: Extensions::default(),
    }
    .state_record(kind)
    .map_err(|_| ())
}

async fn send_channel_snapshot(
    subscription_id: u32,
    catalogue: &ChannelCatalogue,
    event_limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_bounded_state_event_with_sensitivity(
        family::CHANNEL,
        yas_wire::schema::channel::event::STATE,
        &StateEvent {
            subscription_id,
            phase: Phase::SnapshotBegin,
            flags: 0,
            from_revision: 0,
            to_revision: catalogue.revision,
            records: Vec::new(),
        },
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        true,
    )
    .await?;
    for listener in &catalogue.listeners {
        send_bounded_state_event_with_sensitivity(
            family::CHANNEL,
            yas_wire::schema::channel::event::STATE,
            &StateEvent {
                subscription_id,
                phase: Phase::SnapshotRecords,
                flags: 0,
                from_revision: catalogue.revision,
                to_revision: catalogue.revision,
                records: vec![channel_listener_record(listener, RecordKind::Add)?],
            },
            event_limit,
            sent_bytes,
            control,
            out,
            cancellation,
            true,
        )
        .await?;
    }
    send_bounded_state_event_with_sensitivity(
        family::CHANNEL,
        yas_wire::schema::channel::event::STATE,
        &StateEvent {
            subscription_id,
            phase: Phase::SnapshotEnd,
            flags: 0,
            from_revision: catalogue.revision,
            to_revision: catalogue.revision,
            records: Vec::new(),
        },
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        true,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn run_channel_watch(
    subscription_id: u32,
    state: AppState,
    mut catalogue: ChannelCatalogue,
    mut updates: tokio::sync::watch::Receiver<u64>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0;
    if send_channel_snapshot(
        subscription_id,
        &catalogue,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        tokio::select! {
            result = updates.changed() => if result.is_err() { return; },
            _ = cancellation.cancelled() => return,
        }
        let next = {
            let shared = state.session.lock().await;
            shared.channels.native_catalogue()
        };
        if next.revision <= catalogue.revision {
            continue;
        }
        let old = catalogue
            .listeners
            .iter()
            .map(|listener| (listener.listener_handle, listener))
            .collect::<HashMap<_, _>>();
        let new = next
            .listeners
            .iter()
            .map(|listener| (listener.listener_handle, listener))
            .collect::<HashMap<_, _>>();
        let mut records = Vec::new();
        for listener in &catalogue.listeners {
            if !new.contains_key(&listener.listener_handle) {
                let Ok(record) = (yas_channel::RemovedListener {
                    listener_handle: listener.listener_handle,
                    generation: listener.generation,
                })
                .state_record() else {
                    return;
                };
                records.push(record);
            }
        }
        for listener in &next.listeners {
            let kind = match old.get(&listener.listener_handle) {
                None => Some(RecordKind::Add),
                Some(previous) if *previous != listener => Some(RecordKind::Replace),
                Some(_) => None,
            };
            if let Some(kind) = kind {
                let Ok(record) = channel_listener_record(listener, kind) else {
                    return;
                };
                records.push(record);
            }
        }
        let event = StateEvent {
            subscription_id,
            phase: Phase::Delta,
            flags: 0,
            from_revision: catalogue.revision,
            to_revision: next.revision,
            records,
        };
        let result = if let Some(reset) = state_delta_reset(&event, event_limit) {
            if send_bounded_state_event_with_sensitivity(
                family::CHANNEL,
                yas_wire::schema::channel::event::STATE,
                &reset,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                true,
            )
            .await
            .is_err()
            {
                return;
            }
            send_channel_snapshot(
                subscription_id,
                &next,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
        } else {
            send_bounded_state_event_with_sensitivity(
                family::CHANNEL,
                yas_wire::schema::channel::event::STATE,
                &event,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                true,
            )
            .await
        };
        if result.is_err() {
            return;
        }
        catalogue = next;
    }
}

fn kv_state_record(
    entry: &super::kv::NativeEntry,
    prefix: &[u8],
    inline_max: u32,
    kind: RecordKind,
) -> Result<yas_wire::state::Record, ()> {
    let relative_key = entry.key.strip_prefix(prefix).ok_or(())?.to_vec();
    yas_kv::EntryRecord {
        relative_key,
        content_hash: entry.content_hash,
        byte_len: entry.value.len() as u64,
        modification_revision: entry.modification_revision,
        modified_unix_ns: i64::try_from(entry.mtime_ns).unwrap_or(i64::MAX),
        inline_value: (entry.value.len() as u64 <= u64::from(inline_max))
            .then(|| entry.value.as_ref().clone()),
        extensions: Extensions::default(),
    }
    .state_record(kind)
    .map_err(|_| ())
}

#[allow(clippy::too_many_arguments)]
async fn send_kv_snapshot(
    subscription_id: u32,
    prefix: &[u8],
    inline_max: u32,
    revision: u64,
    entries: &[super::kv::NativeEntry],
    limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    for event in [
        StateEvent {
            subscription_id,
            phase: Phase::SnapshotBegin,
            flags: 0,
            from_revision: 0,
            to_revision: revision,
            records: Vec::new(),
        },
        StateEvent {
            subscription_id,
            phase: Phase::SnapshotEnd,
            flags: 0,
            from_revision: revision,
            to_revision: revision,
            records: Vec::new(),
        },
    ] {
        if event.phase == Phase::SnapshotEnd {
            for entry in entries {
                let record = kv_state_record(entry, prefix, inline_max, RecordKind::Add)?;
                send_bounded_state_event_with_sensitivity(
                    family::KV,
                    yas_wire::schema::kv::event::STATE,
                    &StateEvent {
                        subscription_id,
                        phase: Phase::SnapshotRecords,
                        flags: 0,
                        from_revision: revision,
                        to_revision: revision,
                        records: vec![record],
                    },
                    limit,
                    sent_bytes,
                    control,
                    out,
                    cancellation,
                    true,
                )
                .await?;
            }
        }
        send_bounded_state_event_with_sensitivity(
            family::KV,
            yas_wire::schema::kv::event::STATE,
            &event,
            limit,
            sent_bytes,
            control,
            out,
            cancellation,
            true,
        )
        .await?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
async fn run_kv_watch(
    subscription_id: u32,
    prefix: Vec<u8>,
    inline_max: u32,
    mut snapshot: super::kv::NativeWatch,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    if send_kv_snapshot(
        subscription_id,
        &prefix,
        inline_max,
        snapshot.revision,
        &snapshot.entries,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    let mut revision = snapshot.revision;
    loop {
        let change = tokio::select! {
            change = snapshot.changes.recv() => change,
            _ = cancellation.cancelled() => return,
        };
        match change {
            Ok(change) => {
                if change.to_revision <= revision {
                    continue;
                }
                let mut records = Vec::new();
                for change in change.records {
                    match change {
                        super::kv::NativeChangeRecord::Upsert { entry, added }
                            if entry.key.starts_with(&prefix) =>
                        {
                            let kind = if added {
                                RecordKind::Add
                            } else {
                                RecordKind::Replace
                            };
                            let Ok(record) = kv_state_record(&entry, &prefix, inline_max, kind)
                            else {
                                return;
                            };
                            records.push(record);
                        }
                        super::kv::NativeChangeRecord::Remove {
                            key,
                            modification_revision,
                        } if key.starts_with(&prefix) => {
                            let Ok(record) = (yas_kv::RemovedEntry {
                                relative_key: key[prefix.len()..].to_vec(),
                                modification_revision,
                            })
                            .state_record() else {
                                return;
                            };
                            records.push(record);
                        }
                        _ => {}
                    }
                }
                let delta = StateEvent {
                    subscription_id,
                    phase: Phase::Delta,
                    flags: 0,
                    from_revision: change.from_revision,
                    to_revision: change.to_revision,
                    records,
                };
                if state_delta_reset(&delta, event_limit).is_some() {
                    let fresh = super::kv::native_watch(&prefix);
                    let reset = state_reset_event(subscription_id, revision, fresh.revision);
                    if send_bounded_state_event_with_sensitivity(
                        family::KV,
                        yas_wire::schema::kv::event::STATE,
                        &reset,
                        event_limit,
                        &mut sent_bytes,
                        &control,
                        &out,
                        &cancellation,
                        true,
                    )
                    .await
                    .is_err()
                        || send_kv_snapshot(
                            subscription_id,
                            &prefix,
                            inline_max,
                            fresh.revision,
                            &fresh.entries,
                            event_limit,
                            &mut sent_bytes,
                            &control,
                            &out,
                            &cancellation,
                        )
                        .await
                        .is_err()
                    {
                        return;
                    }
                    revision = fresh.revision;
                    snapshot = fresh;
                } else {
                    if send_bounded_state_event_with_sensitivity(
                        family::KV,
                        yas_wire::schema::kv::event::STATE,
                        &delta,
                        event_limit,
                        &mut sent_bytes,
                        &control,
                        &out,
                        &cancellation,
                        true,
                    )
                    .await
                    .is_err()
                    {
                        return;
                    }
                    revision = change.to_revision;
                }
            }
            Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {
                let fresh = super::kv::native_watch(&prefix);
                if send_bounded_state_event_with_sensitivity(
                    family::KV,
                    yas_wire::schema::kv::event::STATE,
                    &state_reset_event(subscription_id, revision, fresh.revision),
                    event_limit,
                    &mut sent_bytes,
                    &control,
                    &out,
                    &cancellation,
                    true,
                )
                .await
                .is_err()
                    || send_kv_snapshot(
                        subscription_id,
                        &prefix,
                        inline_max,
                        fresh.revision,
                        &fresh.entries,
                        event_limit,
                        &mut sent_bytes,
                        &control,
                        &out,
                        &cancellation,
                    )
                    .await
                    .is_err()
                {
                    return;
                }
                revision = fresh.revision;
                snapshot = fresh;
            }
            Err(tokio::sync::broadcast::error::RecvError::Closed) => return,
        }
    }
}

fn relay_route_state_record(
    route: &super::relay::RelayRouteDescriptor,
    kind: RecordKind,
) -> Result<yas_wire::state::Record, ()> {
    yas_wire::relay::RouteRecord {
        route_handle: route.route_handle,
        generation: route.generation,
        availability: route.availability,
        transport_hint: route.transport_hint,
        is_default: route.is_default,
        name: route.name.clone(),
        label: route.label.clone(),
        description: route.description.clone(),
        extensions: Extensions::default(),
    }
    .state_record(kind)
    .map_err(|_| ())
}

fn relay_snapshot_after_announcement(
    catalogue: &RelayRouteCatalog,
    revisions: &mut tokio::sync::watch::Receiver<u64>,
    previous_revision: u64,
) -> Option<super::relay::RelayRouteSnapshot> {
    let announced_revision = *revisions.borrow_and_update();
    if announced_revision <= previous_revision {
        return None;
    }
    let snapshot = catalogue.snapshot();
    (snapshot.revision > previous_revision).then_some(snapshot)
}

#[allow(clippy::too_many_arguments)]
async fn run_relay_watch(
    subscription_id: u32,
    catalogue: Arc<RelayRouteCatalog>,
    initial: super::relay::RelayRouteSnapshot,
    mut revisions: tokio::sync::watch::Receiver<u64>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let mut previous_revision = initial.revision;
    if send_relay_snapshot(
        subscription_id,
        &initial,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    loop {
        tokio::select! {
            changed = revisions.changed() => if changed.is_err() { return },
            _ = cancellation.cancelled() => return,
        }
        let Some(snapshot) =
            relay_snapshot_after_announcement(&catalogue, &mut revisions, previous_revision)
        else {
            continue;
        };
        if send_bounded_state_event_with_sensitivity(
            family::RELAY,
            yas_wire::schema::relay::event::STATE,
            &state_reset_event(subscription_id, previous_revision, snapshot.revision),
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
            false,
        )
        .await
        .is_err()
        {
            return;
        }
        if send_relay_snapshot(
            subscription_id,
            &snapshot,
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
        )
        .await
        .is_err()
        {
            return;
        }
        previous_revision = snapshot.revision;
    }
}

#[allow(clippy::too_many_arguments)]
async fn send_relay_snapshot(
    subscription_id: u32,
    snapshot: &super::relay::RelayRouteSnapshot,
    event_limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_bounded_state_event_with_sensitivity(
        family::RELAY,
        yas_wire::schema::relay::event::STATE,
        &state_snapshot_begin_event(subscription_id, snapshot.revision),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        false,
    )
    .await?;
    for route in &snapshot.routes {
        send_bounded_state_event_with_sensitivity(
            family::RELAY,
            yas_wire::schema::relay::event::STATE,
            &state_snapshot_record_event(
                subscription_id,
                snapshot.revision,
                relay_route_state_record(route, RecordKind::Add)?,
            ),
            event_limit,
            sent_bytes,
            control,
            out,
            cancellation,
            false,
        )
        .await?;
    }
    send_bounded_state_event_with_sensitivity(
        family::RELAY,
        yas_wire::schema::relay::event::STATE,
        &state_snapshot_end_event(subscription_id, snapshot.revision),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        false,
    )
    .await
}

fn font_state_records(
    catalogue: &FontCatalog,
    generation: u64,
) -> Result<Vec<yas_wire::state::Record>, ()> {
    catalogue
        .summaries()
        .into_iter()
        .enumerate()
        .map(|(index, summary)| {
            let font_handle = u64::try_from(index)
                .ok()
                .and_then(|index| index.checked_add(1))
                .ok_or(())?;
            yas_wire::font::FamilyRecord {
                font_handle,
                generation,
                flags: summary.flags,
                face_count: summary.face_count,
                family: summary.family,
                display: summary.display_name,
                extensions: Extensions::default(),
            }
            .state_record(RecordKind::Add)
            .map_err(|_| ())
        })
        .collect()
}

async fn run_font_watch(
    subscription_id: u32,
    dynamic_catalogue: super::font::Catalog,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let mut revisions = dynamic_catalogue.subscribe();
    loop {
        let snapshot = dynamic_catalogue.current();
        let revision = snapshot.revision;
        let catalogue = snapshot.catalog;
        if send_bounded_state_event_with_sensitivity(
            family::FONT,
            yas_wire::schema::font::event::STATE,
            &state_snapshot_begin_event(subscription_id, revision),
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
            false,
        )
        .await
        .is_err()
        {
            return;
        }
        let Ok(records) = font_state_records(&catalogue, revision) else {
            return;
        };
        for record in records {
            if send_bounded_state_event_with_sensitivity(
                family::FONT,
                yas_wire::schema::font::event::STATE,
                &state_snapshot_record_event(subscription_id, revision, record),
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
            .is_err()
            {
                return;
            }
        }
        if send_bounded_state_event_with_sensitivity(
            family::FONT,
            yas_wire::schema::font::event::STATE,
            &state_snapshot_end_event(subscription_id, revision),
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
            false,
        )
        .await
        .is_err()
        {
            return;
        }
        tokio::select! {
            changed = revisions.changed() => if changed.is_err() { return; },
            _ = cancellation.cancelled() => return,
        }
    }
}

async fn run_terminal_watch(
    subscription_id: u32,
    mut updates: tokio::sync::watch::Receiver<TerminalCatalogue>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    let initial = updates.borrow().clone();
    if send_terminal_snapshot(
        subscription_id,
        &initial,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    let mut revision = initial.revision;
    loop {
        tokio::select! {
            changed = updates.changed() => {
                if changed.is_err() {
                    return;
                }
            }
            _ = cancellation.cancelled() => return,
        }
        let snapshot = updates.borrow_and_update().clone();
        if snapshot.revision <= revision {
            continue;
        }
        let reset = StateEvent {
            subscription_id,
            phase: Phase::Reset,
            flags: 0,
            from_revision: revision,
            to_revision: snapshot.revision,
            records: Vec::new(),
        };
        if send_bounded_state_event_with_sensitivity(
            family::TERMINAL,
            yas_wire::schema::terminal::event::STATE,
            &reset,
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
            false,
        )
        .await
        .is_err()
        {
            return;
        }
        if send_terminal_snapshot(
            subscription_id,
            &snapshot,
            event_limit,
            &mut sent_bytes,
            &control,
            &out,
            &cancellation,
        )
        .await
        .is_err()
        {
            return;
        }
        revision = snapshot.revision;
    }
}

fn client_delta_event(
    subscription_id: u32,
    previous: &ClientCatalogue,
    current: &ClientCatalogue,
) -> Result<StateEvent, ()> {
    let keys = previous
        .records
        .keys()
        .chain(current.records.keys())
        .copied()
        .collect::<BTreeSet<_>>();
    let mut records = Vec::new();
    for session_id in keys {
        let record = match (
            previous.records.get(&session_id),
            current.records.get(&session_id),
        ) {
            (None, Some(record)) => record.state_record(RecordKind::Add),
            (Some(_), None) => yas_client::RemovedClient { session_id }.state_record(),
            (Some(previous), Some(current)) if previous != current => {
                current.state_record(RecordKind::Replace)
            }
            _ => continue,
        }
        .map_err(|_| ())?;
        records.push(record);
    }
    Ok(StateEvent {
        subscription_id,
        phase: Phase::Delta,
        flags: 0,
        from_revision: previous.revision,
        to_revision: current.revision,
        records,
    })
}

async fn run_client_watch(
    subscription_id: u32,
    mut updates: tokio::sync::watch::Receiver<Option<ClientCatalogue>>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let initial = loop {
        if let Some(catalogue) = updates.borrow_and_update().clone() {
            break catalogue;
        }
        tokio::select! {
            changed = updates.changed() => {
                if changed.is_err() {
                    return;
                }
            }
            _ = cancellation.cancelled() => return,
        }
    };
    let mut sent_bytes = 0u64;
    if send_client_snapshot(
        subscription_id,
        &initial,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    let mut previous = initial;
    loop {
        tokio::select! {
            changed = updates.changed() => {
                if changed.is_err() {
                    return;
                }
            }
            _ = cancellation.cancelled() => return,
        }
        let Some(current) = updates.borrow_and_update().clone() else {
            continue;
        };
        if current.revision <= previous.revision {
            continue;
        }
        let Ok(event) = client_delta_event(subscription_id, &previous, &current) else {
            return;
        };
        let result = if let Some(reset) = state_delta_reset(&event, event_limit) {
            if send_bounded_state_event_with_sensitivity(
                family::CLIENT,
                yas_wire::schema::client::event::STATE,
                &reset,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
            .is_err()
            {
                return;
            }
            send_client_snapshot(
                subscription_id,
                &current,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
        } else {
            send_bounded_state_event_with_sensitivity(
                family::CLIENT,
                yas_wire::schema::client::event::STATE,
                &event,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
        };
        if result.is_err() {
            return;
        }
        previous = current;
    }
}

async fn send_surface_eos(
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
    view_id: u32,
    sequence: u64,
    codec_version: u16,
) -> Result<oneshot::Receiver<()>, ()> {
    let now = monotonic_ns();
    let payload = yas_surface::SurfaceFrame {
        view_id,
        sequence,
        base_sequence: 0,
        capture_ns: now,
        presentation_ns: now,
        flags: yas_wire::schema::surface::FRAME_KEYFRAME as u16
            | yas_wire::schema::surface::FRAME_END_OF_STREAM as u16,
        codec_version,
        fragment_index: 0,
        fragment_count: 1,
        complete_len: 4,
        payload: vec![0; 4],
    }
    .encode()
    .map_err(|_| ())?;
    let frame = Frame {
        header: FrameHeader {
            sensitive: true,
            ..FrameHeader::event(family::SURFACE, yas_wire::schema::surface::event::FRAME)
        },
        payload,
    };
    tokio::select! {
        result = out.send_with_receipt(frame) => result.map_err(|_| ()),
        _ = cancellation.cancelled() => Err(()),
    }
}

async fn run_registered_surface_watch(
    subscription_id: u32,
    updates: tokio::sync::watch::Receiver<SurfaceCatalogue>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
    #[cfg(test)] publication_probe: Option<Arc<SurfaceWatchPublicationProbe>>,
) {
    let failure_control = Arc::clone(&control);
    let failure_cancellation = cancellation.clone();
    run_surface_watch(
        subscription_id,
        updates,
        event_limit,
        control,
        out,
        cancellation,
        #[cfg(test)]
        publication_probe,
    )
    .await;
    // A live subscription cannot recover after its State producer exits:
    // keeping its sender registered makes later updates disappear silently
    // until reload. Normal UNWATCH cancels FlowControl before aborting this
    // task, so only an unexpected exit tears down the connection and lets the
    // peer establish a fresh authoritative watch.
    if !failure_control.is_cancelled() {
        failure_cancellation.cancel();
    }
}

async fn run_surface_watch(
    subscription_id: u32,
    mut updates: tokio::sync::watch::Receiver<SurfaceCatalogue>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
    #[cfg(test)] publication_probe: Option<Arc<SurfaceWatchPublicationProbe>>,
) {
    let mut sent_bytes = 0u64;
    let initial = updates.borrow_and_update().clone();
    if send_surface_snapshot(
        subscription_id,
        &initial,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    let mut previous = initial;
    loop {
        tokio::select! {
            changed = updates.changed() => {
                if changed.is_err() {
                    return;
                }
            }
            _ = cancellation.cancelled() => return,
        }
        let current = updates.borrow_and_update().clone();
        if current.revision <= previous.revision {
            continue;
        }
        let handles = previous
            .records
            .keys()
            .chain(current.records.keys())
            .copied()
            .collect::<BTreeSet<_>>();
        let mut records = Vec::new();
        for surface_handle in handles {
            let record = match (
                previous.records.get(&surface_handle),
                current.records.get(&surface_handle),
            ) {
                (None, Some(record)) => record.state_record(RecordKind::Add),
                (Some(record), None) => yas_surface::RemovedSurface {
                    surface_handle,
                    revision: record.revision.saturating_add(1).max(1),
                }
                .state_record(),
                (Some(previous), Some(current)) if previous != current => {
                    current.state_record(RecordKind::Replace)
                }
                _ => continue,
            };
            let Ok(record) = record else {
                return;
            };
            records.push(record);
        }
        let delta = StateEvent {
            subscription_id,
            phase: Phase::Delta,
            flags: 0,
            from_revision: previous.revision,
            to_revision: current.revision,
            records,
        };
        let result = if let Some(reset) = state_delta_reset(&delta, event_limit) {
            if send_bounded_state_event_with_sensitivity(
                family::SURFACE,
                yas_wire::schema::surface::event::STATE,
                &reset,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
            .is_err()
            {
                return;
            }
            send_surface_snapshot(
                subscription_id,
                &current,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
        } else {
            send_bounded_state_event_with_sensitivity(
                family::SURFACE,
                yas_wire::schema::surface::event::STATE,
                &delta,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
        };
        if result.is_err() {
            return;
        }
        #[cfg(test)]
        if let Some(probe) = &publication_probe {
            probe.published();
        }
        previous = current;
    }
}

#[allow(clippy::too_many_arguments)]
async fn send_client_snapshot(
    subscription_id: u32,
    catalogue: &ClientCatalogue,
    event_limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_bounded_state_event_with_sensitivity(
        family::CLIENT,
        yas_wire::schema::client::event::STATE,
        &state_snapshot_begin_event(subscription_id, catalogue.revision),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        false,
    )
    .await?;
    for record in catalogue.records.values() {
        send_bounded_state_event_with_sensitivity(
            family::CLIENT,
            yas_wire::schema::client::event::STATE,
            &state_snapshot_record_event(
                subscription_id,
                catalogue.revision,
                record.state_record(RecordKind::Add).map_err(|_| ())?,
            ),
            event_limit,
            sent_bytes,
            control,
            out,
            cancellation,
            false,
        )
        .await?;
    }
    send_bounded_state_event_with_sensitivity(
        family::CLIENT,
        yas_wire::schema::client::event::STATE,
        &state_snapshot_end_event(subscription_id, catalogue.revision),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        false,
    )
    .await
}

