async fn run_selection_watch(
    subscription_id: u32,
    initial: SelectionSnapshot,
    mut updates: tokio::sync::watch::Receiver<SelectionSnapshot>,
    event_limit: StateEventLimit,
    control: Arc<FlowControl>,
    out: FrameSender,
    cancellation: ConnectionCancellation,
) {
    let mut sent_bytes = 0u64;
    if send_selection_snapshot(
        subscription_id,
        &initial,
        event_limit,
        &mut sent_bytes,
        &control,
        &out,
        &cancellation,
    )
    .await
    .is_err()
    {
        return;
    }
    let mut previous = initial;
    loop {
        tokio::select! {
            changed = updates.changed() => {
                if changed.is_err() {
                    return;
                }
            }
            _ = cancellation.cancelled() => return,
        }
        let Some(current) = selection_snapshot_after_announcement(&mut updates, previous.revision)
        else {
            continue;
        };
        let mut records = Vec::new();
        for (&slot, current_slot) in &current.slots {
            let kind = match previous.slots.get(&slot) {
                None => RecordKind::Add,
                Some(previous_slot) if previous_slot.record != current_slot.record => {
                    RecordKind::Replace
                }
                _ => continue,
            };
            let Ok(record) =
                yas_selection::CompleteEntity::Slot(current_slot.record.clone()).state_record(kind)
            else {
                return;
            };
            records.push(record);
        }
        let drag_handles = previous
            .drags
            .keys()
            .chain(current.drags.keys())
            .copied()
            .collect::<BTreeSet<_>>();
        for drag_handle in drag_handles {
            let record = match (
                previous.drags.get(&drag_handle),
                current.drags.get(&drag_handle),
            ) {
                (None, Some(record)) => yas_selection::CompleteEntity::Drag(record.clone())
                    .state_record(RecordKind::Add),
                (Some(previous), Some(current)) if previous != current => {
                    yas_selection::CompleteEntity::Drag(current.clone())
                        .state_record(RecordKind::Replace)
                }
                (Some(previous), None) => yas_selection::RemovedEntity::Drag {
                    drag_handle,
                    revision: previous.revision,
                }
                .state_record(),
                _ => continue,
            };
            let Ok(record) = record else {
                return;
            };
            records.push(record);
        }
        let delta = StateEvent {
            subscription_id,
            phase: Phase::Delta,
            flags: 0,
            from_revision: previous.revision,
            to_revision: current.revision,
            records,
        };
        let result = if let Some(reset) = state_delta_reset(&delta, event_limit) {
            if send_bounded_state_event_with_sensitivity(
                family::SELECTION,
                yas_wire::schema::selection::event::STATE,
                &reset,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
            .is_err()
            {
                return;
            }
            send_selection_snapshot(
                subscription_id,
                &current,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
            )
            .await
        } else {
            send_bounded_state_event_with_sensitivity(
                family::SELECTION,
                yas_wire::schema::selection::event::STATE,
                &delta,
                event_limit,
                &mut sent_bytes,
                &control,
                &out,
                &cancellation,
                false,
            )
            .await
        };
        if result.is_err() {
            return;
        }
        previous = current;
    }
}

fn selection_snapshot_after_announcement(
    updates: &mut tokio::sync::watch::Receiver<SelectionSnapshot>,
    previous_revision: u64,
) -> Option<SelectionSnapshot> {
    let current = updates.borrow_and_update().clone();
    (current.revision > previous_revision).then_some(current)
}

#[allow(clippy::too_many_arguments)]
async fn send_selection_snapshot(
    subscription_id: u32,
    snapshot: &SelectionSnapshot,
    event_limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
) -> Result<(), ()> {
    send_bounded_state_event_with_sensitivity(
        family::SELECTION,
        yas_wire::schema::selection::event::STATE,
        &state_snapshot_begin_event(subscription_id, snapshot.revision),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        false,
    )
    .await?;
    for slot in snapshot.slots.values() {
        let record = yas_selection::CompleteEntity::Slot(slot.record.clone())
            .state_record(RecordKind::Add)
            .map_err(|_| ())?;
        send_bounded_state_event_with_sensitivity(
            family::SELECTION,
            yas_wire::schema::selection::event::STATE,
            &state_snapshot_record_event(subscription_id, snapshot.revision, record),
            event_limit,
            sent_bytes,
            control,
            out,
            cancellation,
            false,
        )
        .await?;
    }
    for drag in snapshot.drags.values() {
        let record = yas_selection::CompleteEntity::Drag(drag.clone())
            .state_record(RecordKind::Add)
            .map_err(|_| ())?;
        send_bounded_state_event_with_sensitivity(
            family::SELECTION,
            yas_wire::schema::selection::event::STATE,
            &state_snapshot_record_event(subscription_id, snapshot.revision, record),
            event_limit,
            sent_bytes,
            control,
            out,
            cancellation,
            false,
        )
        .await?;
    }
    send_bounded_state_event_with_sensitivity(
        family::SELECTION,
        yas_wire::schema::selection::event::STATE,
        &state_snapshot_end_event(subscription_id, snapshot.revision),
        event_limit,
        sent_bytes,
        control,
        out,
        cancellation,
        false,
    )
    .await
}

