#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct StateEventLimit {
    max_payload_bytes: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BoundedStateFamily {
    Client,
    Selection,
    #[cfg_attr(not(target_os = "linux"), allow(dead_code))]
    Desktop,
    #[cfg_attr(not(target_os = "linux"), allow(dead_code))]
    Media,
    Relay,
    Font,
    Lsp,
    Extension,
    Git,
    GitQuery,
    Channel,
    Process,
    Kv,
    Surface,
    Terminal,
    Fs,
}

impl StateEventLimit {
    fn new(peer_receive: ReceiveLimits, credit_window: u64) -> Self {
        let header_bytes = yas_wire::schema::transport::EVENT_HEADER_BYTES as u64;
        let wire_payload = u64::from(peer_receive.max_frame).saturating_sub(header_bytes);
        let decoded_payload = u64::from(peer_receive.max_decoded).saturating_sub(header_bytes);
        let max_payload_bytes = credit_window.min(wire_payload).min(decoded_payload);
        Self {
            max_payload_bytes: usize::try_from(max_payload_bytes).unwrap_or(usize::MAX),
        }
    }

    fn contains(self, event: &StateEvent) -> bool {
        event
            .encode()
            .is_ok_and(|payload| payload.len() <= self.max_payload_bytes)
    }
}

fn state_snapshot_begin_event(subscription_id: u32, revision: u64) -> StateEvent {
    StateEvent {
        subscription_id,
        phase: Phase::SnapshotBegin,
        flags: 0,
        from_revision: 0,
        to_revision: revision,
        records: Vec::new(),
    }
}

fn state_snapshot_record_event(
    subscription_id: u32,
    revision: u64,
    record: yas_wire::state::Record,
) -> StateEvent {
    StateEvent {
        subscription_id,
        phase: Phase::SnapshotRecords,
        flags: 0,
        from_revision: revision,
        to_revision: revision,
        records: vec![record],
    }
}

fn state_snapshot_end_event(subscription_id: u32, revision: u64) -> StateEvent {
    StateEvent {
        subscription_id,
        phase: Phase::SnapshotEnd,
        flags: 0,
        from_revision: revision,
        to_revision: revision,
        records: Vec::new(),
    }
}

fn maximal_process_state_record() -> yas_wire::state::Record {
    yas_process_wire::ProcessRecord {
        process_handle: 1,
        lifecycle: yas_wire::schema::process::LIFECYCLE_EXITED as u8,
        stream_state: 0,
        flags: yas_wire::schema::process::SPAWN_DETACHABLE as u16,
        native_pid: 1,
        owner_session: [1; 16],
        argv0: vec![b'x'; yas_process_wire::MAX_ARG_LEN],
        stdin_received: u64::MAX,
        stdout_produced: u64::MAX,
        stderr_produced: u64::MAX,
        retention_deadline_server_ns: u64::MAX,
        exit: Some(yas_process_wire::ExitRecord {
            kind: yas_process_wire::ExitKind::Other,
            reason: yas_wire::schema::process::EXIT_REASON_UNKNOWN as u8,
            code: 0,
            exited_server_ns: u64::MAX,
            detail: vec![b'x'; 4096],
        }),
        extensions: Extensions::default(),
    }
    .state_record(RecordKind::Add)
    .expect("maximum server Process record is valid")
}

fn maximal_kv_state_record() -> yas_wire::state::Record {
    yas_kv::EntryRecord {
        relative_key: vec![b'k'; yas_kv::MAX_KEY_BYTES],
        content_hash: [u8::MAX; 32],
        byte_len: yas_kv::MAX_INLINE_BYTES as u64,
        modification_revision: u64::MAX,
        modified_unix_ns: i64::MAX,
        inline_value: Some(vec![u8::MAX; yas_kv::MAX_INLINE_BYTES]),
        extensions: Extensions::default(),
    }
    .state_record(RecordKind::Add)
    .expect("maximum server KV record is valid")
}

fn maximal_surface_record(surface_handle: u64, revision: u64) -> yas_surface::SurfaceRecord {
    let mut extensions = vec![
        Extension {
            tag: yas_wire::schema::surface::STATE_ACTIVATION_REVISION_EXTENSION as u16,
            required: false,
            value: u64::MAX.to_le_bytes().to_vec(),
        },
        yas_surface::CursorState::Custom {
            hotspot_x: i32::MAX,
            hotspot_y: i32::MAX,
            width: u32::MAX,
            height: u32::MAX,
            scale_120: u16::MAX,
            png: vec![u8::MAX; yas_wire::schema::surface::MAX_INLINE_CURSOR_BYTES as usize],
        }
        .extension()
        .expect("maximum server Surface cursor is valid"),
        yas_surface::TextInputState {
            enabled: true,
            requested: true,
            content_hint: u32::MAX,
            content_purpose: u32::MAX,
            cursor_rect: Some(yas_surface::CursorRect {
                x: i32::MAX,
                y: i32::MAX,
                width: i32::MAX,
                height: i32::MAX,
            }),
        }
        .extension()
        .expect("maximum server Surface text-input state is valid"),
    ];
    extensions.push(Extension {
        tag: yas_wire::schema::surface::STATE_TEXT_INPUT_REQUEST_REVISION_EXTENSION as u16,
        required: false,
        value: u64::MAX.to_le_bytes().to_vec(),
    });
    extensions.sort_unstable_by_key(|extension| extension.tag);
    yas_surface::SurfaceRecord {
        surface_handle,
        revision,
        parent_handle: u64::MAX,
        app_handle: u64::MAX,
        lifecycle: u8::MAX,
        composite_width: u32::MAX,
        composite_height: u32::MAX,
        logical_width_32_32: i64::MAX,
        logical_height_32_32: i64::MAX,
        application_id: "a".repeat(u16::MAX as usize),
        title: "t".repeat(u16::MAX as usize),
        extensions: Extensions(extensions),
    }
}

fn maximal_surface_state_record() -> yas_wire::state::Record {
    maximal_surface_record(1, u64::MAX)
        .state_record(RecordKind::Add)
        .expect("maximum server Surface record is valid")
}

fn maximal_terminal_state_record() -> yas_wire::state::Record {
    let mut extensions = vec![
        Extension {
            tag: yas_wire::schema::terminal::STATE_TITLE_EXTENSION as u16,
            required: false,
            value: vec![b't'; MAX_TERMINAL_STATE_TITLE_BYTES],
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_CWD_EXTENSION as u16,
            required: false,
            value: vec![b'c'; MAX_TERMINAL_STATE_CWD_BYTES],
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_COMMAND_DISPLAY_EXTENSION as u16,
            required: false,
            value: vec![b'x'; MAX_TERMINAL_STATE_COMMAND_DISPLAY_BYTES],
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_EXIT_EXTENSION as u16,
            required: false,
            value: yas_terminal::ExitRecord::Other {
                detail: String::from("exit status unavailable"),
            }
            .encode()
            .expect("maximum server Terminal exit record is valid"),
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_DEADLINE_SERVER_NS_EXTENSION as u16,
            required: false,
            value: u64::MAX.to_le_bytes().to_vec(),
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_APP_HANDLE_EXTENSION as u16,
            required: false,
            value: u64::MAX.to_le_bytes().to_vec(),
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_JOURNAL_CURSOR_EXTENSION as u16,
            required: false,
            value: u64::MAX.to_le_bytes().to_vec(),
        },
        Extension {
            tag: yas_wire::schema::terminal::STATE_RESOURCE_TAG_EXTENSION as u16,
            required: false,
            value: vec![b'r'; MAX_TERMINAL_RESOURCE_TAG_BYTES],
        },
    ];
    extensions.sort_unstable_by_key(|extension| extension.tag);
    yas_terminal::TerminalRecord {
        terminal_handle: u64::MAX,
        lifecycle: yas_terminal::Lifecycle::Exited,
        rows: u16::MAX,
        cols: u16::MAX,
        generation: u32::MAX,
        used_rows: u32::MAX,
        extensions: Extensions(extensions),
    }
    .state_record(RecordKind::Add)
    .expect("maximum server Terminal record is valid")
}

fn maximal_fs_path(fill: u8) -> yas_fs_wire::Path {
    let component_count = yas_fs_wire::MAX_PATH_COMPONENTS;
    let base = yas_fs_wire::MAX_PATH_BYTES / component_count;
    let remainder = yas_fs_wire::MAX_PATH_BYTES % component_count;
    let components = (0..component_count)
        .map(|index| vec![fill; base + usize::from(index < remainder)])
        .collect::<Vec<_>>();
    debug_assert!(
        components.iter().all(|component| !component.is_empty()
            && component.len() <= yas_fs_wire::MAX_COMPONENT_BYTES)
    );
    yas_fs_wire::Path { components }
}

fn maximal_fs_entry(path: yas_fs_wire::Path) -> yas_fs_wire::EntryRecord {
    yas_fs_wire::EntryRecord {
        path,
        entry_revision: u64::MAX,
        flags: 0,
        mode: u32::MAX,
        modified_unix_ns: i64::MAX,
        body: yas_fs_wire::EntryBody::Symlink {
            content_hash: [u8::MAX; 32],
            target: vec![b't'; yas_fs_wire::MAX_PATH_BYTES],
        },
        extensions: Extensions(vec![
            yas_fs_wire::operation_id_extension([u8::MAX; 16])
                .expect("maximum FS operation ID extension is valid"),
        ]),
    }
}

fn maximal_fs_state_records() -> Vec<yas_wire::state::Record> {
    let path = maximal_fs_path(b'p');
    let file = yas_fs_wire::EntryRecord {
        path: path.clone(),
        entry_revision: u64::MAX,
        flags: 0,
        mode: u32::MAX,
        modified_unix_ns: i64::MAX,
        body: yas_fs_wire::EntryBody::File {
            byte_len: yas_fs_wire::MAX_INLINE_BYTES as u64,
            content_hash: [u8::MAX; 32],
            inline_content: Some(vec![u8::MAX; yas_fs_wire::MAX_INLINE_BYTES]),
        },
        extensions: Extensions(vec![
            yas_fs_wire::operation_id_extension([u8::MAX; 16])
                .expect("maximum FS operation ID extension is valid"),
        ]),
    };
    let symlink = maximal_fs_entry(path.clone());
    [
        yas_fs_wire::StateMutation::Complete(file),
        yas_fs_wire::StateMutation::Complete(symlink.clone()),
        yas_fs_wire::StateMutation::Patch(yas_fs_wire::EntryPatch {
            path: path.clone(),
            observed_revision: u64::MAX,
            fields: yas_wire::schema::fs::PATCH_FIELDS as u16,
            replacement: symlink,
        }),
        yas_fs_wire::StateMutation::Move(yas_fs_wire::MoveRecord {
            from: path.clone(),
            to: maximal_fs_path(b'q'),
            operation_id: Some([u8::MAX; 16]),
        }),
        yas_fs_wire::StateMutation::Remove(yas_fs_wire::RemoveRecord {
            path,
            removed_revision: u64::MAX,
            operation_id: Some([u8::MAX; 16]),
        }),
    ]
    .into_iter()
    .map(|mutation| {
        mutation
            .state_record(RecordKind::Add)
            .expect("maximum server FS record is valid")
    })
    .collect()
}

fn state_family_minimum_payload(family: BoundedStateFamily) -> usize {
    static PROCESS: LazyLock<usize> = LazyLock::new(|| {
        state_snapshot_record_event(1, 1, maximal_process_state_record())
            .encode()
            .expect("maximum Process snapshot Event encodes")
            .len()
    });
    static KV: LazyLock<usize> = LazyLock::new(|| {
        state_snapshot_record_event(1, 1, maximal_kv_state_record())
            .encode()
            .expect("maximum KV snapshot Event encodes")
            .len()
    });
    static SURFACE: LazyLock<usize> = LazyLock::new(|| {
        state_snapshot_record_event(1, 1, maximal_surface_state_record())
            .encode()
            .expect("maximum Surface snapshot Event encodes")
            .len()
    });
    static TERMINAL: LazyLock<usize> = LazyLock::new(|| {
        state_snapshot_record_event(1, 1, maximal_terminal_state_record())
            .encode()
            .expect("maximum Terminal snapshot Event encodes")
            .len()
    });
    static FS: LazyLock<usize> = LazyLock::new(|| {
        maximal_fs_state_records()
            .into_iter()
            .map(|record| {
                state_snapshot_record_event(1, 1, record)
                    .encode()
                    .expect("maximum FS State Event encodes")
                    .len()
            })
            .max()
            .expect("FS has bounded State record variants")
    });
    match family {
        BoundedStateFamily::Client
        | BoundedStateFamily::Selection
        | BoundedStateFamily::Desktop
        | BoundedStateFamily::Media
        | BoundedStateFamily::Relay
        | BoundedStateFamily::Font
        | BoundedStateFamily::Lsp
        | BoundedStateFamily::Extension
        | BoundedStateFamily::Git
        | BoundedStateFamily::GitQuery
        | BoundedStateFamily::Channel => LEGACY_STATE_EVENT_PAYLOAD_BYTES,
        BoundedStateFamily::Process => *PROCESS,
        BoundedStateFamily::Kv => *KV,
        BoundedStateFamily::Surface => *SURFACE,
        BoundedStateFamily::Terminal => *TERMINAL,
        BoundedStateFamily::Fs => *FS,
    }
}

fn state_snapshot_is_admissible<I, E>(
    family: BoundedStateFamily,
    subscription_id: u32,
    revision: u64,
    records: I,
    limit: StateEventLimit,
) -> bool
where
    I: IntoIterator<Item = Result<yas_wire::state::Record, E>>,
{
    limit.max_payload_bytes >= state_family_minimum_payload(family)
        && limit.contains(&state_snapshot_begin_event(subscription_id, revision))
        && records.into_iter().all(|record| {
            record.is_ok_and(|record| {
                limit.contains(&state_snapshot_record_event(
                    subscription_id,
                    revision,
                    record,
                ))
            })
        })
        && limit.contains(&state_snapshot_end_event(subscription_id, revision))
}

fn state_reset_event(subscription_id: u32, from_revision: u64, to_revision: u64) -> StateEvent {
    StateEvent {
        subscription_id,
        phase: Phase::Reset,
        flags: 0,
        from_revision,
        to_revision,
        records: Vec::new(),
    }
}

fn state_delta_reset(delta: &StateEvent, limit: StateEventLimit) -> Option<StateEvent> {
    debug_assert_eq!(delta.phase, Phase::Delta);
    (!limit.contains(delta)).then(|| {
        state_reset_event(
            delta.subscription_id,
            delta.from_revision,
            delta.to_revision,
        )
    })
}

#[allow(clippy::too_many_arguments)]
async fn send_bounded_state_event_with_sensitivity(
    family_id: u16,
    kind: u16,
    event: &StateEvent,
    limit: StateEventLimit,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
    sensitive: bool,
) -> Result<(), ()> {
    if !limit.contains(event) {
        return Err(());
    }
    send_state_event_with_sensitivity(
        family_id,
        kind,
        event,
        sent_bytes,
        control,
        out,
        cancellation,
        sensitive,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn send_state_event_with_sensitivity(
    family_id: u16,
    kind: u16,
    event: &StateEvent,
    sent_bytes: &mut u64,
    control: &FlowControl,
    out: &FrameSender,
    cancellation: &ConnectionCancellation,
    sensitive: bool,
) -> Result<(), ()> {
    let payload = event.encode().map_err(|_| ())?;
    let end = sent_bytes.checked_add(payload.len() as u64).ok_or(())?;
    if !control.wait_through(end, cancellation).await {
        return Err(());
    }
    let mut header = FrameHeader::event(family_id, kind);
    header.sensitive = sensitive
        || yas_wire::schema::operation(family_id, Class::Event as u8, kind).is_some_and(
            |operation| operation.sensitive == yas_wire::schema::transport::policy::REQUIRED,
        );
    let frame = Frame { header, payload };
    tokio::select! {
        result = out.send(frame) => result.map_err(|_| ())?,
        _ = cancellation.cancelled() => return Err(()),
    }
    if !control.record_sent(end) {
        return Err(());
    }
    *sent_bytes = end;
    Ok(())
}

