    fn guest_state_event_limit() -> StateEventLimit {
        StateEventLimit::new(
            ReceiveLimits {
                max_frame: SERVER_MAX_FRAME,
                max_decoded: SERVER_MAX_DECODED,
                max_datagram: 0,
                max_buffered: TEST_PEER_MAX_BUFFERED,
            },
            u64::from(SERVER_MAX_FRAME),
        )
    }

    fn assert_oversized_delta_has_bounded_reset_snapshot(
        family: BoundedStateFamily,
        records: Vec<yas_wire::state::Record>,
    ) {
        let limit = guest_state_event_limit();
        assert_eq!(
            limit.max_payload_bytes,
            SERVER_MAX_FRAME as usize - yas_wire::schema::transport::EVENT_HEADER_BYTES,
        );
        let delta = StateEvent {
            subscription_id: 7,
            phase: Phase::Delta,
            flags: 0,
            from_revision: 41,
            to_revision: 42,
            records: records.clone(),
        };
        assert!(delta.encode().unwrap().len() > limit.max_payload_bytes);
        assert!(state_snapshot_is_admissible(
            family,
            7,
            42,
            records.iter().cloned().map(Ok::<_, ()>),
            limit,
        ));
        let minimum = state_family_minimum_payload(family);
        assert!(minimum <= limit.max_payload_bytes);
        assert!(!state_snapshot_is_admissible(
            family,
            7,
            42,
            records.iter().cloned().map(Ok::<_, ()>),
            StateEventLimit {
                max_payload_bytes: minimum - 1,
            },
        ));
        let reset = state_delta_reset(&delta, limit).expect("maximal Delta must fall back");
        assert_eq!(reset.phase, Phase::Reset);
        assert_eq!(reset.from_revision, 41);
        assert_eq!(reset.to_revision, 42);
        assert!(reset.records.is_empty());
        assert!(limit.contains(&reset));

        let begin = StateEvent {
            subscription_id: 7,
            phase: Phase::SnapshotBegin,
            flags: 0,
            from_revision: 0,
            to_revision: 42,
            records: Vec::new(),
        };
        assert!(limit.contains(&begin));
        for record in records {
            let event = StateEvent {
                subscription_id: 7,
                phase: Phase::SnapshotRecords,
                flags: 0,
                from_revision: 42,
                to_revision: 42,
                records: vec![record],
            };
            assert!(
                limit.contains(&event),
                "one maximal record must fit the peer frame and credit window",
            );
        }
        let end = StateEvent {
            subscription_id: 7,
            phase: Phase::SnapshotEnd,
            flags: 0,
            from_revision: 42,
            to_revision: 42,
            records: Vec::new(),
        };
        assert!(limit.contains(&end));
    }

