    fn git_stash_projection_bounds_arbitrary_raw_bytes() {
        let original = vec![0xff; yas_wire::schema::git::MAX_MESSAGE_BYTES as usize];
        let record = yas_git_wire::EntityRecord {
            entity_kind: yas_wire::schema::git::ENTITY_STASH as u16,
            key: 1u32.to_le_bytes().to_vec(),
            revision: 1,
            body: yas_git_wire::EntityBody::Stash(yas_git_wire::StashEntityBody {
                object: yas_git_wire::ObjectId {
                    algorithm: yas_wire::schema::git::OBJECT_SHA1 as u8,
                    bytes: vec![0x80; 20],
                },
                created_unix_seconds: i64::MAX,
                timezone_minutes: i16::MAX,
                message: original,
            }),
            extensions: Extensions::default(),
        };
        let record = git_state_record(record, RecordKind::Add).unwrap();
        let decoded = yas_git_wire::EntityRecord::decode(&record.body).unwrap();
        let yas_git_wire::EntityBody::Stash(stash) = decoded.body else {
            panic!("stash projection changed entity kind");
        };
        assert_eq!(stash.message.len(), MAX_GIT_STATE_STASH_MESSAGE_BYTES);
        assert!(stash.message.iter().all(|byte| *byte == 0xff));
        assert!(
            state_snapshot_record_event(1, 1, record)
                .encode()
                .unwrap()
                .len()
                <= LEGACY_STATE_EVENT_PAYLOAD_BYTES,
        );
    }

