    #[tokio::test]
    async fn oversized_surface_delta_emits_reset_and_rolling_bounded_snapshot() {
        let initial = SurfaceCatalogue {
            revision: 1,
            records: BTreeMap::new(),
        };
        let (updates, updates_rx) = tokio::sync::watch::channel(initial);
        let window = u64::from(SERVER_MAX_FRAME);
        let flow_budget = Arc::new(CreditBudget::new(window));
        let control = Arc::new(FlowControl::new(window, flow_budget));
        let limit = guest_state_event_limit();
        let cancellation = ConnectionCancellation::default();
        let mut outbound = test_outbound(
            OUTBOUND_URGENT_BUFFERED,
            OUTBOUND_CONTROL_BUFFERED,
            u64::from(SERVER_MAX_DECODED),
        );
        let task = tokio::spawn(run_surface_watch(
            7,
            updates_rx,
            limit,
            Arc::clone(&control),
            outbound.sender.clone(),
            cancellation.clone(),
            None,
        ));
        let mut cumulative_bytes = 0;

        let (begin, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(begin.phase, Phase::SnapshotBegin);
        assert_eq!((begin.from_revision, begin.to_revision), (0, 1));
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);
        let (end, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(end.phase, Phase::SnapshotEnd);
        assert_eq!((end.from_revision, end.to_revision), (1, 1));
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);

        updates
            .send(SurfaceCatalogue {
                revision: 2,
                records: (1..=7)
                    .map(|surface_handle| {
                        (surface_handle, maximal_surface_record(surface_handle, 2))
                    })
                    .collect(),
            })
            .unwrap();

        let (reset, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(reset.phase, Phase::Reset);
        assert_eq!((reset.from_revision, reset.to_revision), (1, 2));
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);
        let (begin, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(begin.phase, Phase::SnapshotBegin);
        assert_eq!((begin.from_revision, begin.to_revision), (0, 2));
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);
        for _ in 0..7 {
            let (records, payload_bytes) =
                next_surface_state_frame(&mut outbound, &cancellation, limit).await;
            assert_eq!(records.phase, Phase::SnapshotRecords);
            assert_eq!((records.from_revision, records.to_revision), (2, 2));
            assert_eq!(records.records.len(), 1);
            roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);
        }
        let (end, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(end.phase, Phase::SnapshotEnd);
        assert_eq!((end.from_revision, end.to_revision), (2, 2));
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);
        assert!(cumulative_bytes > window, "test must roll State credit");

        cancellation.cancel();
        timeout(TEST_TIMEOUT, task).await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn coalesced_surface_revision_emits_empty_delta_before_next_change() {
        let initial = SurfaceCatalogue {
            revision: 1,
            records: BTreeMap::new(),
        };
        let (updates, updates_rx) = tokio::sync::watch::channel(initial);
        let limit = guest_state_event_limit();
        let begin_bytes = state_snapshot_begin_event(7, 1).encode().unwrap().len() as u64;
        let window = u64::from(SERVER_MAX_FRAME);
        let flow_budget = Arc::new(CreditBudget::new(window));
        let control = Arc::new(FlowControl::new(begin_bytes, flow_budget));
        let cancellation = ConnectionCancellation::default();
        let mut outbound = test_outbound(
            OUTBOUND_URGENT_BUFFERED,
            OUTBOUND_CONTROL_BUFFERED,
            u64::from(SERVER_MAX_DECODED),
        );
        let task = tokio::spawn(run_surface_watch(
            7,
            updates_rx,
            limit,
            Arc::clone(&control),
            outbound.sender.clone(),
            cancellation.clone(),
            None,
        ));
        let mut cumulative_bytes = 0;

        let (begin, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(begin.phase, Phase::SnapshotBegin);
        cumulative_bytes += payload_bytes as u64;
        assert_eq!(cumulative_bytes, begin_bytes);

        updates
            .send(SurfaceCatalogue {
                revision: 2,
                records: BTreeMap::from([(1, maximal_surface_record(1, 2))]),
            })
            .unwrap();
        updates
            .send(SurfaceCatalogue {
                revision: 3,
                records: BTreeMap::new(),
            })
            .unwrap();
        assert!(control.grant(cumulative_bytes.saturating_add(window)));

        let (end, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(end.phase, Phase::SnapshotEnd);
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);
        let (empty, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(empty.phase, Phase::Delta);
        assert_eq!((empty.from_revision, empty.to_revision), (1, 3));
        assert!(empty.records.is_empty());
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);

        updates
            .send(SurfaceCatalogue {
                revision: 4,
                records: BTreeMap::from([(1, maximal_surface_record(1, 4))]),
            })
            .unwrap();
        let (next, payload_bytes) =
            next_surface_state_frame(&mut outbound, &cancellation, limit).await;
        assert_eq!(next.phase, Phase::Delta);
        assert_eq!((next.from_revision, next.to_revision), (3, 4));
        assert_eq!(next.records.len(), 1);
        roll_state_credit(&control, &mut cumulative_bytes, payload_bytes, window);

        cancellation.cancel();
        timeout(TEST_TIMEOUT, task).await.unwrap().unwrap();
    }

    #[cfg(unix)]
    async fn assert_empty_common_watch_admission_rollback(
        family_id: u16,
        state_kind: u16,
        watch_kind: u16,
        unwatch_kind: u16,
        bounded_family: BoundedStateFamily,
    ) {
        async fn next_result_ignoring_state(
            client: &mut DuplexStream,
            codec: &FrameCodec,
            family_id: u16,
            state_kind: u16,
            result_kind: u16,
            request_id: u32,
        ) -> ResultPrefix {
            loop {
                let frame = next_frame(client, codec).await;
                if frame.header.class == Class::Result {
                    assert_eq!(frame.header.family, family_id);
                    assert_eq!(frame.header.kind, result_kind);
                    assert_eq!(frame.header.request_id, Some(request_id));
                    return ResultPrefix::decode(&frame.payload).unwrap();
                }
                assert_eq!(frame.header.family, family_id);
                assert_eq!(frame.header.kind, state_kind);
                assert_eq!(frame.header.class, Class::Event);
                StateEvent::decode(&frame.payload).unwrap();
            }
        }

        let minimum = state_family_minimum_payload(bounded_family) as u64;
        let peer_max_buffered = minimum.saturating_mul(MAX_WATCHES as u64);
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut client, codec, _, server_task) = start_registered_session_with_outbound_max(
            state,
            &[family_id],
            peer_max_buffered,
            minimum + 1,
        )
        .await;

        for request_id in 10..10 + MAX_WATCHES as u32 + 1 {
            write_request(
                &mut client,
                &codec,
                family_id,
                watch_kind,
                request_id,
                &Watch {
                    initial_credit: 1,
                    resume: None,
                    extensions: Extensions::default(),
                },
            )
            .await;
            assert_eq!(
                next_result_ignoring_state(
                    &mut client,
                    &codec,
                    family_id,
                    state_kind,
                    watch_kind,
                    request_id,
                )
                .await
                .status,
                Status::ResourceExhausted,
            );
        }

        write_request(
            &mut client,
            &codec,
            family_id,
            watch_kind,
            100,
            &Watch {
                initial_credit: minimum,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let accepted =
            next_result_ignoring_state(&mut client, &codec, family_id, state_kind, watch_kind, 100)
                .await;
        assert_eq!(accepted.status, Status::Ok);
        let subscription_id = WatchResult::decode(&accepted.body).unwrap().subscription_id;
        loop {
            let frame = next_frame(&mut client, &codec).await;
            assert_eq!(frame.header.family, family_id);
            assert_eq!(frame.header.kind, state_kind);
            assert_eq!(frame.header.class, Class::Event);
            let event = StateEvent::decode(&frame.payload).unwrap();
            if event.phase == Phase::SnapshotEnd {
                break;
            }
        }

        for request_id in 200..200 + MAX_WATCHES as u32 + 1 {
            write_request(
                &mut client,
                &codec,
                family_id,
                watch_kind,
                request_id,
                &Watch {
                    initial_credit: minimum,
                    resume: None,
                    extensions: Extensions::default(),
                },
            )
            .await;
            assert_eq!(
                next_result_ignoring_state(
                    &mut client,
                    &codec,
                    family_id,
                    state_kind,
                    watch_kind,
                    request_id,
                )
                .await
                .status,
                Status::ResourceExhausted,
            );
        }

        write_request(
            &mut client,
            &codec,
            family_id,
            unwatch_kind,
            300,
            &Unwatch { subscription_id },
        )
        .await;
        assert_eq!(
            next_result_ignoring_state(
                &mut client,
                &codec,
                family_id,
                state_kind,
                unwatch_kind,
                300,
            )
            .await
            .status,
            Status::Ok,
        );

        write_request(
            &mut client,
            &codec,
            family_id,
            watch_kind,
            400,
            &Watch {
                initial_credit: minimum,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_result_ignoring_state(
                &mut client,
                &codec,
                family_id,
                state_kind,
                watch_kind,
                400,
            )
            .await
            .status,
            Status::Ok,
        );

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

