    #[test]
    fn resource_replay_horizon_pins_live_entries_and_evicts_retired_fifo() {
        #[derive(Clone, Copy)]
        struct Replay {
            live: bool,
        }

        let live_id = [1; 16];
        let first_retired = [2; 16];
        let second_retired = [3; 16];
        let replacement = [4; 16];
        let mut values = HashMap::new();
        let mut order = VecDeque::new();
        for (operation_id, replay) in [
            (live_id, Replay { live: true }),
            (first_retired, Replay { live: false }),
            (second_retired, Replay { live: false }),
        ] {
            insert_operation_replay(&mut values, &mut order, operation_id, replay);
        }

        assert!(make_operation_replay_room(
            &mut values,
            &mut order,
            3,
            0,
            |replay| replay.live,
        ));
        assert!(values.contains_key(&live_id));
        assert!(!values.contains_key(&first_retired));
        assert!(values.contains_key(&second_retired));
        insert_operation_replay(&mut values, &mut order, replacement, Replay { live: false });
        assert_eq!(values.len(), 3);

        values.get_mut(&live_id).unwrap().live = false;
        assert!(make_operation_replay_room(
            &mut values,
            &mut order,
            3,
            0,
            |replay| replay.live,
        ));
        assert!(!values.contains_key(&live_id));
        assert_eq!(values.len(), 2);
    }

    #[test]
    fn resource_replay_horizons_exceed_their_live_resource_caps() {
        for (family, replay_capacity, live_capacity) in [
            (
                "Process",
                MAX_PROCESS_OPERATION_REPLAYS,
                yas_process_wire::Limits::HARD.max_processes_per_session as usize,
            ),
            (
                "Selection",
                MAX_SELECTION_OPERATION_REPLAYS,
                MAX_SELECTION_STAGES,
            ),
            (
                "Channel",
                MAX_CHANNEL_OPERATION_REPLAYS,
                yas_wire::schema::channel::MAX_LISTENERS_PER_SESSION as usize,
            ),
            (
                "Events",
                MAX_EVENTS_OPERATION_REPLAYS,
                yas_wire::schema::events::MAX_STREAMS_PER_SESSION as usize,
            ),
            (
                "Net",
                MAX_NET_OPERATION_REPLAYS,
                yas_wire::schema::net::MAX_FLOWS_PER_SESSION as usize,
            ),
        ] {
            assert!(
                replay_capacity > live_capacity,
                "{family} must always admit a settlement beyond every live resource replay"
            );
        }
    }

