    #[test]
    fn native_active_subscriptions_are_sorted_valid_and_bounded_by_representation_limit() {
        let terminals = (1..=4095)
            .rev()
            .map(|terminal_handle| yas_client::TerminalSubscription {
                terminal_handle,
                view_id: 1,
                rows: 24,
                columns: 80,
            })
            .collect();
        let surfaces = vec![
            yas_client::SurfaceSubscription {
                surface_handle: 20,
                view_id: 2,
                width: 640,
                height: 360,
                scale_120: 120,
            },
            yas_client::SurfaceSubscription {
                surface_handle: 10,
                view_id: 1,
                width: 320,
                height: 180,
                scale_120: 120,
            },
        ];
        let auxiliary = vec![
            yas_client::AuxiliarySubscription {
                family: family::LSP,
                subscription_id: 9,
                resource_handle: 90,
            },
            yas_client::AuxiliarySubscription {
                family: family::FS,
                subscription_id: 8,
                resource_handle: 80,
            },
        ];

        let bounded = bounded_native_active_subscriptions(terminals, surfaces, auxiliary);

        assert_eq!(bounded.terminals.len(), 4095);
        assert!(
            bounded
                .terminals
                .windows(2)
                .all(|pair| pair[0].terminal_handle < pair[1].terminal_handle)
        );
        assert_eq!(
            bounded.surfaces,
            vec![yas_client::SurfaceSubscription {
                surface_handle: 10,
                view_id: 1,
                width: 320,
                height: 180,
                scale_120: 120,
            }]
        );
        assert!(bounded.auxiliary.is_empty());
        assert_eq!(
            yas_client::ActiveSubscriptions::decode(&bounded.extension().unwrap().value).unwrap(),
            bounded,
        );

        let mixed = bounded_native_active_subscriptions(
            Vec::new(),
            Vec::new(),
            vec![
                yas_client::AuxiliarySubscription {
                    family: family::LSP,
                    subscription_id: 2,
                    resource_handle: 9,
                },
                yas_client::AuxiliarySubscription {
                    family: family::FS,
                    subscription_id: 3,
                    resource_handle: 7,
                },
                yas_client::AuxiliarySubscription {
                    family: family::FS,
                    subscription_id: 1,
                    resource_handle: 8,
                },
            ],
        );
        assert_eq!(
            mixed
                .auxiliary
                .iter()
                .map(|value| (value.family, value.subscription_id, value.resource_handle))
                .collect::<Vec<_>>(),
            vec![(family::FS, 1, 8), (family::FS, 3, 7), (family::LSP, 2, 9)]
        );
    }

    #[test]
    fn native_surface_and_auxiliary_subscription_projection_uses_public_resources() {
        let budget = Arc::new(CreditBudget::new(1));
        let view = NativeSurfaceView {
            surface_handle: 0xfeed,
            surface_id: 7,
            backend_client_id: 8,
            width: 640,
            height: 360,
            max_fps: 60,
            decoder_capacity: 1,
            codec_version: 1,
            next_sequence: 1,
            acknowledged_sequence: 0,
            needs_keyframe: true,
            keyframe_requested: true,
            outbound_credit: budget.try_lease_exact(1).unwrap(),
            last_frame_written: None,
        };
        let surface = native_surface_subscription(9, &view);
        assert_eq!(
            surface,
            yas_client::SurfaceSubscription {
                surface_handle: 0xfeed,
                view_id: 9,
                width: 640,
                height: 360,
                scale_120: 120,
            },
        );

        let fs = HashMap::from([(2, 0xf2)]);
        let git = HashMap::from([(3, 0xf3)]);
        let git_query = HashMap::from([(4, 0xf4)]);
        let lsp = HashMap::from([(5, 0xf5)]);
        let resources = NativeAuxiliaryResources {
            fs: Some(&fs),
            git: Some(&git),
            git_query: Some(&git_query),
            lsp: Some(&lsp),
        };
        assert_eq!(resources.handle(family::KV, 1, Some(0xf1)), 0xf1);
        assert_eq!(resources.handle(family::FS, 2, None), 0xf2);
        assert_eq!(resources.handle(family::GIT, 3, None), 0xf3);
        assert_eq!(resources.handle(family::GIT, 4, None), 0xf4);
        assert_eq!(resources.handle(family::LSP, 5, None), 0xf5);
        assert_eq!(resources.handle(family::CLIENT, 6, None), 0);
        assert_eq!(resources.handle(family::FS, 7, None), 0);

        let snapshot = crate::NativeYasSubscriptionSnapshot {
            active: bounded_native_active_subscriptions(
                Vec::new(),
                vec![surface],
                vec![yas_client::AuxiliarySubscription {
                    family: family::KV,
                    subscription_id: 1,
                    resource_handle: resources.handle(family::KV, 1, Some(0xf1)),
                }],
            ),
            auxiliary_details: yas_client::AuxiliarySubscriptionDetails::default(),
        };
        let shared = NativeYasSubscriptions::default();
        assert!(shared.replace(snapshot.clone()));
        assert_eq!(shared.snapshot(), snapshot);
        assert!(!shared.replace(snapshot));
        shared.clear();
        assert_eq!(
            shared.snapshot(),
            crate::NativeYasSubscriptionSnapshot::default()
        );
    }

    #[test]
    fn client_catalogue_revision_is_one_delta_with_all_changed_records() {
        let first = test_client_record(1);
        let removed = test_client_record(2);
        let added = test_client_record(3);
        let previous = ClientCatalogue {
            revision: 40,
            records: BTreeMap::from([
                (first.session_id, first.clone()),
                (removed.session_id, removed.clone()),
            ]),
        };
        let mut replaced = first.clone();
        replaced.bytes_received = 1;
        let current = ClientCatalogue {
            revision: 41,
            records: BTreeMap::from([
                (replaced.session_id, replaced),
                (added.session_id, added.clone()),
            ]),
        };

        let delta = client_delta_event(7, &previous, &current).unwrap();

        assert_eq!(delta.subscription_id, 7);
        assert_eq!(delta.phase, Phase::Delta);
        assert_eq!(delta.from_revision, 40);
        assert_eq!(delta.to_revision, 41);
        assert_eq!(delta.records.len(), 3);
        assert_eq!(delta.records[0].kind, RecordKind::Replace);
        assert_eq!(delta.records[1].kind, RecordKind::Remove);
        assert_eq!(delta.records[2].kind, RecordKind::Add);
        assert_eq!(
            yas_client::client_from_state_record(&delta.records[0])
                .unwrap()
                .session_id,
            first.session_id,
        );
        assert_eq!(
            yas_client::removal_from_state_record(&delta.records[1])
                .unwrap()
                .session_id,
            removed.session_id,
        );
        assert_eq!(
            yas_client::client_from_state_record(&delta.records[2])
                .unwrap()
                .session_id,
            added.session_id,
        );
    }

