    #[test]
    fn surface_catalogue_masks_only_removals_behind_retirement_boundaries() {
        let initial = SurfaceCatalogue {
            revision: 1,
            records: BTreeMap::from([
                (1, maximal_surface_record(1, 1)),
                (2, maximal_surface_record(2, 1)),
            ]),
        };
        let mut runtime = SurfaceRuntime::new(initial.clone());
        let (updates, mut updates_rx) = tokio::sync::watch::channel(initial.clone());
        runtime.updates.insert(7, updates);
        let first_boundary = runtime.alloc_catalogue_boundary(&[1]).unwrap();
        let second_boundary = runtime.alloc_catalogue_boundary(&[2]).unwrap();

        let removed = SurfaceCatalogue {
            revision: 2,
            records: BTreeMap::new(),
        };
        runtime.catalogue = removed.clone();
        assert!(!runtime.publish_catalogue(removed));
        assert!(!updates_rx.has_changed().unwrap());
        assert_eq!(runtime.published_catalogue, initial);

        let latest = SurfaceCatalogue {
            revision: 3,
            records: BTreeMap::from([(3, maximal_surface_record(3, 3))]),
        };
        runtime.catalogue = latest.clone();
        assert!(runtime.publish_catalogue(latest.clone()));
        assert!(updates_rx.has_changed().unwrap());
        let visible = updates_rx.borrow_and_update().clone();
        assert_eq!(visible.revision, 3);
        assert_eq!(
            visible.records.keys().copied().collect::<Vec<_>>(),
            [1, 2, 3]
        );

        assert!(
            runtime
                .pending_catalogue_boundaries
                .remove(&first_boundary)
                .is_some()
        );
        assert!(runtime.publish_catalogue(latest.clone()));
        assert!(updates_rx.has_changed().unwrap());
        let first_release = updates_rx.borrow_and_update().clone();
        assert_eq!(first_release.revision, 4);
        assert_eq!(
            first_release.records.keys().copied().collect::<Vec<_>>(),
            [2, 3]
        );

        assert!(
            runtime
                .pending_catalogue_boundaries
                .remove(&second_boundary)
                .is_some()
        );
        assert!(runtime.publish_catalogue(runtime.catalogue.clone()));
        assert!(updates_rx.has_changed().unwrap());
        let second_release = updates_rx.borrow_and_update().clone();
        assert_eq!(second_release.revision, 5);
        assert_eq!(
            second_release.records.keys().copied().collect::<Vec<_>>(),
            [3]
        );
        assert_eq!(runtime.published_catalogue, second_release);
    }

