    #[test]
    fn surface_app_endpoint_create_replay_expires_to_stale() {
        let mut runtime = test_surface_runtime();
        let create_operation_id = test_operation_id(1);
        let create_fingerprint = [0x11; 32];
        let create_body = vec![0x21, 0x22, 0x23];
        runtime
            .app_endpoints
            .insert(7, test_surface_app_endpoint(7, 100));
        runtime.record_app_endpoint_create(
            create_operation_id,
            create_fingerprint,
            7,
            create_body.clone(),
        );

        assert_eq!(
            runtime.replay(create_operation_id, create_fingerprint),
            Some((Status::Ok, create_body)),
        );
        assert_eq!(
            runtime.replay(create_operation_id, [0x12; 32]),
            Some((Status::Conflict, Vec::new())),
        );

        let expired = runtime.expire_app_endpoints(100);
        assert_eq!(expired.len(), 1);
        assert!(!runtime.app_endpoints.contains_key(&7));
        assert_eq!(
            runtime.replay(create_operation_id, create_fingerprint),
            Some((Status::Stale, Vec::new())),
        );
        assert_eq!(
            runtime.replay(create_operation_id, [0x12; 32]),
            Some((Status::Conflict, Vec::new())),
            "fingerprint conflicts remain authoritative after expiry",
        );

        let release_operation_id = test_operation_id(2);
        let release_fingerprint = [0x31; 32];
        assert!(
            runtime
                .release_app_endpoint(7, release_operation_id, release_fingerprint)
                .unwrap()
                .is_none(),
            "expiry already disposed the live endpoint",
        );
        runtime.update_replay_status(release_operation_id, Status::Ok);
        assert_eq!(
            runtime.replay(release_operation_id, release_fingerprint),
            Some((Status::Ok, Vec::new())),
        );
        assert_eq!(
            runtime.replay(release_operation_id, [0x32; 32]),
            Some((Status::Conflict, Vec::new())),
        );
        assert_eq!(runtime.operations.len(), 1);
    }

    #[test]
    fn surface_app_endpoint_failed_cleanup_keeps_exact_retry_authority() {
        let mut runtime = test_surface_runtime();
        let create_operation_id = test_operation_id(70_000);
        let create_fingerprint = [0x71; 32];
        runtime
            .app_endpoints
            .insert(71, test_surface_app_endpoint(71, u64::MAX));
        runtime.record_app_endpoint_create(create_operation_id, create_fingerprint, 71, vec![0x72]);
        let release_operation_id = test_operation_id(70_001);
        let release_fingerprint = [0x73; 32];
        let endpoint = runtime
            .release_app_endpoint(71, release_operation_id, release_fingerprint)
            .unwrap()
            .expect("first cleanup attempt owns endpoint");

        // Model a command-submission JoinError: the endpoint remains retained
        // but no longer grants launch environment, and the exact RELEASE is
        // deliberately not a settled replay yet.
        runtime.restore_retiring_app_endpoint(71, endpoint);
        assert!(runtime.app_endpoint_environment(71).is_none());
        assert_eq!(
            runtime.replay(create_operation_id, create_fingerprint),
            Some((Status::Stale, Vec::new())),
        );
        assert_eq!(
            runtime.replay(release_operation_id, release_fingerprint),
            None,
        );
        assert_eq!(
            runtime.replay(release_operation_id, [0x74; 32]),
            Some((Status::Conflict, Vec::new())),
        );

        let endpoint = runtime
            .release_app_endpoint(71, release_operation_id, release_fingerprint)
            .unwrap()
            .expect("exact retry reacquires cleanup ownership");
        drop(endpoint);
        runtime.update_replay_status(release_operation_id, Status::Ok);
        assert_eq!(
            runtime.replay(release_operation_id, release_fingerprint),
            Some((Status::Ok, Vec::new())),
        );
        assert!(!runtime.app_endpoints.contains_key(&71));
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn surface_app_endpoint_add_failure_unlinks_and_cannot_publish() {
        let directory = tempfile::tempdir().unwrap();
        for (name, submission, expected) in [
            (
                "application-rejected",
                Ok(AppSocketAddSubmission::Rejected),
                Status::Unavailable,
            ),
            (
                "disconnected",
                Ok(AppSocketAddSubmission::Disconnected),
                Status::Unavailable,
            ),
            ("join-error", Err(()), Status::Internal),
        ] {
            let path = directory.path().join(name);
            std::fs::write(&path, b"").unwrap();
            assert_eq!(
                complete_app_socket_add_submission(&path, submission),
                Err(expected),
            );
            assert!(!path.exists(), "failed Add socket path remains published");
        }

        assert!(
            complete_app_socket_remove_submission(Ok(AppSocketRemoveSubmission::Applied)).is_ok()
        );
        assert!(
            complete_app_socket_remove_submission(Ok(AppSocketRemoveSubmission::Disconnected))
                .is_ok()
        );
        assert!(complete_app_socket_remove_submission(Err(())).is_err());
    }

    #[test]
    fn surface_app_endpoint_release_uses_its_create_slot_at_replay_capacity() {
        let mut runtime = test_surface_runtime();
        let create_operation_id = test_operation_id(1);
        let create_fingerprint = [0x41; 32];
        runtime
            .app_endpoints
            .insert(9, test_surface_app_endpoint(9, u64::MAX));
        runtime.record_app_endpoint_create(
            create_operation_id,
            create_fingerprint,
            9,
            vec![0x51, 0x52],
        );
        for value in 2..=MAX_SURFACE_OPERATION_REPLAYS as u64 {
            runtime.record_replay(
                test_operation_id(value),
                [u8::try_from(value).unwrap_or(0xff); 32],
                Status::Ok,
                value.to_le_bytes().to_vec(),
            );
        }
        assert_eq!(runtime.operations.len(), MAX_SURFACE_OPERATION_REPLAYS);

        let release_operation_id = test_operation_id(10_000);
        let release_fingerprint = [0x61; 32];
        let released = runtime
            .release_app_endpoint(9, release_operation_id, release_fingerprint)
            .expect("a live endpoint owns a cleanup replay slot");
        assert!(released.is_some());
        drop(released);
        runtime.update_replay_status(release_operation_id, Status::Ok);
        assert_eq!(runtime.operations.len(), MAX_SURFACE_OPERATION_REPLAYS);
        assert!(!runtime.app_endpoints.contains_key(&9));
        assert_eq!(
            runtime.replay(create_operation_id, create_fingerprint),
            Some((Status::Stale, Vec::new())),
        );
        assert_eq!(
            runtime.replay(release_operation_id, release_fingerprint),
            Some((Status::Ok, Vec::new())),
        );
        assert_eq!(
            runtime.replay(release_operation_id, [0x62; 32]),
            Some((Status::Conflict, Vec::new())),
        );
        assert!(
            matches!(
                runtime.release_app_endpoint(9, test_operation_id(10_001), [0x63; 32]),
                Err(Status::ResourceExhausted),
            ),
            "a second fresh cleanup identity cannot displace either settlement",
        );
        assert_eq!(runtime.operations.len(), MAX_SURFACE_OPERATION_REPLAYS);
    }

    #[test]
    fn surface_resource_replays_are_per_live_target_kind_and_independent_of_endpoint_cap() {
        let mut runtime = test_surface_runtime();
        add_test_surface_record(&mut runtime, 41);
        for value in 1..=MAX_SURFACE_OPERATION_REPLAYS as u64 {
            runtime.record_replay(
                test_operation_id(value),
                [u8::try_from(value).unwrap_or(0xff); 32],
                Status::Ok,
                value.to_le_bytes().to_vec(),
            );
        }
        assert_eq!(runtime.operations.len(), MAX_SURFACE_OPERATION_REPLAYS);

        let resize_kind = yas_wire::schema::surface::request::RESIZE;
        let mut latest_resize = ([0; 16], [0; 32], Vec::new());
        for value in 0..300u64 {
            let operation_id = test_operation_id(10_000 + value);
            let fingerprint = [u8::try_from(value).unwrap_or(0xff); 32];
            let body = value.to_le_bytes().to_vec();
            runtime.record_resource_replay(
                41,
                resize_kind,
                operation_id,
                fingerprint,
                Status::Ok,
                body.clone(),
            );
            latest_resize = (operation_id, fingerprint, body);
        }
        assert_eq!(runtime.resource_operations.len(), 1);
        assert_eq!(runtime.operations.len(), MAX_SURFACE_OPERATION_REPLAYS);
        assert_eq!(
            runtime.replay(latest_resize.0, latest_resize.1),
            Some((Status::Ok, latest_resize.2.clone())),
        );
        assert_eq!(runtime.replay(test_operation_id(10_000), [0; 32]), None);

        let focus_operation_id = test_operation_id(20_000);
        runtime.record_resource_replay(
            41,
            yas_wire::schema::surface::request::FOCUS,
            focus_operation_id,
            [0xa1; 32],
            Status::Ok,
            vec![0xa2],
        );
        let close_operation_id = test_operation_id(20_001);
        runtime.record_resource_replay(
            41,
            yas_wire::schema::surface::request::CLOSE,
            close_operation_id,
            [0xb1; 32],
            Status::Ok,
            Vec::new(),
        );
        assert_eq!(runtime.resource_operations.len(), 3);
        assert_eq!(
            runtime.replay(latest_resize.0, [0xcc; 32]),
            Some((Status::Conflict, Vec::new())),
            "one retained operation ID conflicts across payloads and kinds",
        );
        assert!(runtime.has_resource_replay(41, yas_wire::schema::surface::request::CLOSE));

        // A failed successor never calls the success-only replacement path,
        // so the prior settlement remains the retry authority.
        assert_eq!(runtime.replay(test_operation_id(30_000), [0xd1; 32]), None);
        assert_eq!(
            runtime.replay(focus_operation_id, [0xa1; 32]),
            Some((Status::Ok, vec![0xa2])),
        );

        runtime.retire_surface_replays(41);
        assert!(runtime.resource_operations.is_empty());
        assert_eq!(runtime.replay(latest_resize.0, latest_resize.1), None);
        assert_eq!(runtime.replay(focus_operation_id, [0xa1; 32]), None);
        assert_eq!(runtime.replay(close_operation_id, [0xb1; 32]), None);
        assert_eq!(runtime.operations.len(), MAX_SURFACE_OPERATION_REPLAYS);
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "multi_thread")]
    async fn surface_app_endpoint_wire_replay_is_live_scoped() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut client, codec, _hello, server_task) =
            start_registered_session(state, &[family::SURFACE]).await;
        let create = yas_surface::CreateAppEndpoint {
            operation_id: test_operation_id(20_000),
            application_id: "yas.replay.test".to_owned(),
            extensions: Extensions::default(),
        };

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
            10,
            &create,
        )
        .await;
        let created = next_sensitive_result(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
            10,
        )
        .await;
        assert_eq!(created.status, Status::Ok);
        let created_value = yas_surface::CreateAppEndpointResult::decode(&created.body).unwrap();

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
            11,
            &create,
        )
        .await;
        let replayed = next_sensitive_result(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
            11,
        )
        .await;
        assert_eq!(replayed, created);

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
            12,
            &yas_surface::CreateAppEndpoint {
                operation_id: create.operation_id,
                application_id: "yas.replay.conflict".to_owned(),
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
                12,
            )
            .await
            .status,
            Status::Conflict,
        );

        let release = yas_surface::ReleaseAppEndpoint {
            app_handle: created_value.app_handle,
            operation_id: test_operation_id(20_001),
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::RELEASE_APP_ENDPOINT,
            13,
            &release,
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::RELEASE_APP_ENDPOINT,
                13,
            )
            .await
            .status,
            Status::Ok,
        );

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
            14,
            &create,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::CREATE_APP_ENDPOINT,
                14,
            )
            .await
            .status,
            Status::Stale,
        );

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::RELEASE_APP_ENDPOINT,
            15,
            &release,
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::RELEASE_APP_ENDPOINT,
                15,
            )
            .await
            .status,
            Status::Ok,
        );

        let mut conflicting_release = release;
        conflicting_release.app_handle = conflicting_release.app_handle.saturating_add(1);
        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::RELEASE_APP_ENDPOINT,
            16,
            &conflicting_release,
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::RELEASE_APP_ENDPOINT,
                16,
            )
            .await
            .status,
            Status::Conflict,
        );

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn lsp_watch_no_ack_commit_flood_is_coalesced() {
        let (updates, mut receiver) = tokio::sync::watch::channel(0u64);
        // Model a peer whose State credit is exhausted: the watcher has not
        // polled `changed`, while BUFFER_COMMIT continues to invalidate it.
        for _ in 0..100_000 {
            mark_lsp_watch_dirty(&updates);
        }
        receiver.changed().await.unwrap();
        assert_eq!(*receiver.borrow_and_update(), 100_000);

        // Once the blocked watcher resumes, all prior commits are represented
        // by one latest-snapshot wakeup; a subsequent burst is likewise one.
        for _ in 0..1_000 {
            mark_lsp_watch_dirty(&updates);
        }
        receiver.changed().await.unwrap();
        assert_eq!(*receiver.borrow_and_update(), 101_000);
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn lsp_committed_buffers_hold_exact_aggregate_receive_credit() {
        const RECEIVE_LIMIT: u64 = 512 * 1024;

        let root = tempfile::tempdir().unwrap();
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut client, codec, _, server_task) = start_registered_session_with_receive(
            state,
            &[family::TRANSFER, family::LSP],
            RECEIVE_LIMIT,
        )
        .await;

        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::OPEN,
            10,
            &yas_lsp_wire::Open {
                source: yas_lsp_wire::WorkspaceSource::PlatformPath(
                    root.path().to_string_lossy().as_bytes().to_vec(),
                ),
                open_mode: yas_wire::schema::lsp::OPEN_AUTO_DISCOVER as u8,
                diagnostics_settle_ms: 0,
                language: String::new(),
                profile: String::new(),
                initialization_options: Vec::new(),
                extensions: Extensions::default(),
            },
        )
        .await;
        let opened = next_sensitive_result(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::OPEN,
            10,
        )
        .await;
        assert_eq!(opened.status, Status::Ok);
        let workspace_handle = yas_lsp_wire::OpenResult::decode(&opened.body)
            .unwrap()
            .workspace_handle;
        let baseline = server_diagnostics(&mut client, &codec, 11)
            .await
            .aggregate_receive_buffered;

        let first_content = vec![b'a'; 12 * 1024];
        let first_put = yas_lsp_wire::BufferPut {
            workspace_handle,
            operation_id: [0x11; 16],
            expected_revision: 0,
            path: yas_fs_wire::Path {
                components: vec![b"inline.rs".to_vec()],
            },
            content: first_content.clone(),
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_PUT,
            12,
            &first_put,
        )
        .await;
        let first = next_sensitive_result(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_PUT,
            12,
        )
        .await;
        assert_eq!(first.status, Status::Ok);
        let first = yas_lsp_wire::BufferIdentity::decode(&first.body).unwrap();
        assert_eq!(
            server_diagnostics(&mut client, &codec, 13)
                .await
                .aggregate_receive_buffered,
            baseline + first_content.len() as u64,
        );

        let second_content = vec![b'b'; 28 * 1024];
        let second_put = yas_lsp_wire::BufferPut {
            workspace_handle,
            operation_id: [0x12; 16],
            expected_revision: first.buffer_revision,
            path: yas_fs_wire::Path {
                components: vec![b"inline.rs".to_vec()],
            },
            content: second_content.clone(),
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_PUT,
            14,
            &second_put,
        )
        .await;
        let second = next_sensitive_result(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_PUT,
            14,
        )
        .await;
        assert_eq!(second.status, Status::Ok);
        let second = yas_lsp_wire::BufferIdentity::decode(&second.body).unwrap();
        assert_eq!(
            server_diagnostics(&mut client, &codec, 15)
                .await
                .aggregate_receive_buffered,
            baseline + second_content.len() as u64,
        );

        // Replaying an older successful PUT must not replace the reservation
        // owned by the newer live revision.
        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_PUT,
            16,
            &first_put,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::LSP,
                yas_lsp_wire::request_kind::BUFFER_PUT,
                16,
            )
            .await
            .status,
            Status::Ok,
        );
        assert_eq!(
            server_diagnostics(&mut client, &codec, 17)
                .await
                .aggregate_receive_buffered,
            baseline + second_content.len() as u64,
        );

        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_CLOSE,
            18,
            &yas_lsp_wire::BufferClose {
                buffer_handle: second.buffer_handle,
                expected_revision: second.buffer_revision,
                operation_id: [0x13; 16],
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::LSP,
                yas_lsp_wire::request_kind::BUFFER_CLOSE,
                18,
            )
            .await
            .status,
            Status::Ok,
        );
        assert_eq!(
            server_diagnostics(&mut client, &codec, 19)
                .await
                .aggregate_receive_buffered,
            baseline,
        );

        let staged_content = vec![b'c'; 32 * 1024];
        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_BEGIN,
            20,
            &yas_lsp_wire::BufferBegin {
                workspace_handle,
                expected_revision: 0,
                path: yas_fs_wire::Path {
                    components: vec![b"staged.rs".to_vec()],
                },
                byte_len: staged_content.len() as u64,
                content_hash: *blake3::hash(&staged_content).as_bytes(),
                initial_send_credit: staged_content.len() as u64,
                extensions: Extensions::default(),
            },
        )
        .await;
        let begun = next_sensitive_result(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_BEGIN,
            20,
        )
        .await;
        assert_eq!(begun.status, Status::Ok);
        let begun = yas_lsp_wire::BufferBeginResult::decode(&begun.body).unwrap();
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::BYTE_DATA,
            &ByteData {
                transfer_id: begun.descriptor.transfer_id,
                offset: 0,
                data: staged_content.clone(),
            },
        )
        .await;
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::CLOSE,
            &Close {
                transfer_id: begun.descriptor.transfer_id,
                final_data_bytes: staged_content.len() as u64,
                status: Status::Ok.code(),
                detail: Vec::new(),
            },
        )
        .await;
        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::BUFFER_COMMIT,
            21,
            &yas_lsp_wire::BufferCommit {
                staging_handle: begun.staging_handle,
                operation_id: [0x14; 16],
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::LSP,
                yas_lsp_wire::request_kind::BUFFER_COMMIT,
                21,
            )
            .await
            .status,
            Status::Ok,
        );
        let staged_buffered = server_diagnostics(&mut client, &codec, 22)
            .await
            .aggregate_receive_buffered;
        assert_eq!(staged_buffered, baseline + staged_content.len() as u64);

        write_request(
            &mut client,
            &codec,
            family::LSP,
            yas_lsp_wire::request_kind::CLOSE,
            23,
            &yas_lsp_wire::Close {
                workspace_handle,
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::LSP,
                yas_lsp_wire::request_kind::CLOSE,
                23,
            )
            .await
            .status,
            Status::Ok,
        );
        let after_workspace_close = server_diagnostics(&mut client, &codec, 24)
            .await
            .aggregate_receive_buffered;
        assert!(
            staged_buffered.saturating_sub(after_workspace_close) >= staged_content.len() as u64,
            "workspace close did not release its committed buffer reservation",
        );

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    async fn start_session(
        services: Services,
        family_ids: &[u16],
    ) -> (
        DuplexStream,
        FrameCodec,
        ServerHello,
        tokio::task::JoinHandle<()>,
    ) {
        start_session_with_receive(services, family_ids, TEST_PEER_MAX_BUFFERED).await
    }

    async fn start_session_with_receive(
        services: Services,
        family_ids: &[u16],
        max_buffered: u64,
    ) -> (
        DuplexStream,
        FrameCodec,
        ServerHello,
        tokio::task::JoinHandle<()>,
    ) {
        let (mut client, server) = tokio::io::duplex(2 * 1024 * 1024);
        let cancellation = ConnectionCancellation::default();
        let task = tokio::spawn(serve(server, services, cancellation));
        let (codec, server_hello) =
            handshake_with_receive(&mut client, family_ids, max_buffered).await;
        (client, codec, server_hello, task)
    }

    async fn start_registered_session(
        state: AppState,
        family_ids: &[u16],
    ) -> (
        DuplexStream,
        FrameCodec,
        ServerHello,
        tokio::task::JoinHandle<()>,
    ) {
        start_registered_session_with_receive(state, family_ids, TEST_PEER_MAX_BUFFERED).await
    }

    async fn start_registered_session_with_receive(
        state: AppState,
        family_ids: &[u16],
        max_buffered: u64,
    ) -> (
        DuplexStream,
        FrameCodec,
        ServerHello,
        tokio::task::JoinHandle<()>,
    ) {
        let (mut client, server) = tokio::io::duplex(4 * 1024 * 1024);
        let cancellation = ConnectionCancellation::default();
        let registration = state
            .connections
            .register(cancellation.clone())
            .expect("test session registers");
        let mut services = Services::from_state(&state);
        services.receive_max_buffered_override = Some(max_buffered);
        let task = tokio::spawn(serve_registered(
            server,
            services,
            cancellation,
            Some(registration),
            None,
            None,
            ConnectionOrigin::Network,
        ));
        let (codec, server_hello) =
            handshake_with_receive(&mut client, family_ids, max_buffered).await;
        (client, codec, server_hello, task)
    }

