    #[tokio::test]
    async fn sideband_eof_retains_reliable_core_session() {
        let services = test_services(None, unavailable_connector(), None);
        let (mut client, server) = tokio::io::duplex(2 * 1024 * 1024);
        let (side_server, mut side_peer) = tokio::io::duplex(4096);
        let cancellation = ConnectionCancellation::default();
        let datagram = DatagramLink::open(side_server, 1200, cancellation.clone());
        let task = tokio::spawn(serve_registered(
            server,
            services,
            cancellation,
            None,
            None,
            Some(datagram),
            ConnectionOrigin::Network,
        ));
        let (codec, _) = handshake(&mut client, &[]).await;

        side_peer.shutdown().await.unwrap();
        tokio::task::yield_now().await;
        write_request(
            &mut client,
            &codec,
            family::CORE,
            yas_wire::core::request_kind::PING,
            2,
            &Ping {
                sender_monotonic_ns: 7,
            },
        )
        .await;
        let response = timeout(
            TEST_TIMEOUT,
            next_result(
                &mut client,
                &codec,
                family::CORE,
                yas_wire::core::request_kind::PING,
                2,
            ),
        )
        .await
        .expect("reliable Core session survives optional-sideband EOF");
        assert_eq!(response.status, Status::Ok);

        drop(client);
        timeout(TEST_TIMEOUT, task).await.unwrap().unwrap();
    }

