    async fn handshake(client: &mut DuplexStream, family_ids: &[u16]) -> (FrameCodec, ServerHello) {
        handshake_with_receive(client, family_ids, TEST_PEER_MAX_BUFFERED).await
    }

    async fn handshake_with_receive(
        client: &mut DuplexStream,
        family_ids: &[u16],
        max_buffered: u64,
    ) -> (FrameCodec, ServerHello) {
        handshake_with_receive_and_extensions(
            client,
            family_ids,
            max_buffered,
            Extensions::default(),
        )
        .await
    }

    async fn handshake_with_receive_and_extensions(
        client: &mut DuplexStream,
        family_ids: &[u16],
        max_buffered: u64,
        extensions: Extensions,
    ) -> (FrameCodec, ServerHello) {
        handshake_with_receive_datagram_and_extensions(
            client,
            family_ids,
            max_buffered,
            0,
            extensions,
        )
        .await
    }

    async fn handshake_with_receive_datagram_and_extensions(
        client: &mut DuplexStream,
        family_ids: &[u16],
        max_buffered: u64,
        max_datagram: u32,
        extensions: Extensions,
    ) -> (FrameCodec, ServerHello) {
        client.write_all(&yas_wire::PREFACE).await.unwrap();
        let mut offered = family_ids.iter().copied().collect::<BTreeSet<_>>();
        loop {
            let dependencies = offered
                .iter()
                .filter_map(|family_id| {
                    yas_wire::schema::FAMILIES
                        .iter()
                        .find(|metadata| metadata.id == *family_id)
                })
                .flat_map(|metadata| metadata.dependencies.iter().copied())
                .collect::<Vec<_>>();
            let before = offered.len();
            offered.extend(dependencies);
            if offered.len() == before {
                break;
            }
        }
        let hello = ClientHello {
            min_minor: 1,
            max_minor: 1,
            receive: ReceiveLimits {
                max_frame: SERVER_MAX_FRAME,
                max_decoded: SERVER_MAX_DECODED,
                max_datagram,
                max_buffered,
            },
            client_instance: [7; 16],
            client_name: "yas-server-test".to_owned(),
            client_release: "1".to_owned(),
            families: offered
                .into_iter()
                .map(|family_id| FamilyOffer {
                    family_id,
                    versions: vec![1],
                    required: true,
                })
                .collect(),
            codecs: Vec::new(),
            extensions,
        };
        let frame = Frame {
            header: FrameHeader::request(family::CORE, yas_wire::core::request_kind::HELLO, 1),
            payload: hello.encode().unwrap(),
        };
        client
            .write_all(&FrameCodec::pre_hello().encode_stream(&frame).unwrap())
            .await
            .unwrap();
        let codec = FrameCodec::new(FrameLimits::recommended(), []).unwrap();
        let response = next_frame(client, &codec).await;
        assert_eq!(
            response.header,
            FrameHeader::result(family::CORE, yas_wire::core::request_kind::HELLO, 1)
        );
        let prefix = ResultPrefix::decode(&response.payload).unwrap();
        assert_eq!(prefix.status, Status::Ok);
        let server_hello = ServerHello::decode(&prefix.body).unwrap();
        (codec, server_hello)
    }

