    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn read_only_native_session_advertises_and_enforces_passive_authority() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut client, codec, hello, server_task) =
            start_registered_read_only_session(state, &[family::TRANSFER, family::TERMINAL]).await;

        let core = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::CORE)
            .unwrap();
        assert!(core.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_wire::core::request_kind::PING
                && operation.server_accepts
        }));
        assert!(!core.operations.iter().any(|operation| {
            operation.class == Class::Request
                && matches!(
                    operation.kind,
                    yas_wire::core::request_kind::CLIENT_UPDATE
                        | yas_wire::core::request_kind::SHUTDOWN
                )
        }));

        let transfer = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::TRANSFER)
            .unwrap();
        let byte_data = transfer
            .operations
            .iter()
            .find(|operation| {
                operation.class == Class::Event
                    && operation.kind == yas_wire::schema::transfer::event::BYTE_DATA
            })
            .unwrap();
        assert!(!byte_data.server_accepts);
        assert!(byte_data.server_sends);
        assert!(transfer.operations.iter().any(|operation| {
            operation.class == Class::Event
                && operation.kind == yas_wire::schema::transfer::event::CREDIT
                && operation.server_accepts
        }));

        let terminal = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::TERMINAL)
            .unwrap();
        assert!(terminal.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_wire::schema::terminal::request::READ
                && operation.server_accepts
        }));
        assert!(!terminal.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_wire::schema::terminal::request::CREATE
        }));

        // A forged mutating Request is settled as UNSUPPORTED by the server's
        // descriptor gate before its operation payload can run.
        let create = yas_terminal::Create {
            rows: 24,
            cols: 80,
            operation_id: [0x52; 16],
            launch: yas_terminal::Launch {
                command: yas_terminal::Command::Argv(vec![b"/bin/true".to_vec()]),
                cwd: yas_terminal::Cwd::ServerDefault,
                environment_base: yas_terminal::EnvironmentBase::Server,
                environment: Vec::new(),
                extensions: Extensions::default(),
            },
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::TERMINAL,
            yas_wire::schema::terminal::request::CREATE,
            10,
            &create,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::TERMINAL,
                yas_wire::schema::terminal::request::CREATE,
                10,
            )
            .await
            .status,
            Status::Unsupported
        );

        // Passive transfer credit is accepted (unknown IDs are a safe no-op),
        // and a subsequent PING proves that the session remains healthy.
        write_event(
            &mut client,
            &codec,
            family::TRANSFER,
            yas_wire::schema::transfer::event::CREDIT,
            &Credit {
                transfer_id: 0xdead_beef,
                cumulative_limit: 4096,
            },
        )
        .await;
        write_request(
            &mut client,
            &codec,
            family::CORE,
            yas_wire::core::request_kind::PING,
            11,
            &Ping {
                sender_monotonic_ns: 0,
            },
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::CORE,
                yas_wire::core::request_kind::PING,
                11,
            )
            .await
            .status,
            Status::Ok
        );

        // Forged mutating Events are fatal protocol violations rather than
        // silently ignored input.
        write_sensitive_event(
            &mut client,
            &codec,
            family::TERMINAL,
            yas_wire::schema::terminal::event::INPUT,
            &Extensions::default(),
        )
        .await;
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    async fn write_request<T: Encode>(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        family_id: u16,
        kind: u16,
        request_id: u32,
        value: &T,
    ) {
        let mut header = FrameHeader::request(family_id, kind, request_id);
        if yas_wire::schema::operation(family_id, Class::Request as u8, kind).is_some_and(
            |operation| operation.sensitive == yas_wire::schema::transport::policy::REQUIRED,
        ) {
            header.sensitive = true;
        }
        let frame = Frame {
            header,
            payload: value.encode().unwrap(),
        };
        client
            .write_all(&codec.encode_stream(&frame).unwrap())
            .await
            .unwrap();
    }

    async fn write_event<T: Encode>(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        family_id: u16,
        kind: u16,
        value: &T,
    ) {
        let mut header = FrameHeader::event(family_id, kind);
        header.sensitive = yas_wire::schema::operation(family_id, Class::Event as u8, kind)
            .is_some_and(|operation| {
                operation.sensitive == yas_wire::schema::transport::policy::REQUIRED
            });
        if family_id == family::TRANSFER
            && matches!(
                kind,
                yas_wire::schema::transfer::event::CLOSE | yas_wire::schema::transfer::event::RESET
            )
        {
            // All test-side CLOSE/RESET frames target descriptors carrying
            // SENSITIVE_CONTENT; that requirement is dynamic rather than
            // part of the static Transfer operation metadata.
            header.sensitive = true;
        }
        let frame = Frame {
            header,
            payload: value.encode().unwrap(),
        };
        client
            .write_all(&codec.encode_stream(&frame).unwrap())
            .await
            .unwrap();
    }

    async fn write_sensitive_event<T: Encode>(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        family_id: u16,
        kind: u16,
        value: &T,
    ) {
        let frame = Frame {
            header: FrameHeader {
                sensitive: true,
                ..FrameHeader::event(family_id, kind)
            },
            payload: value.encode().unwrap(),
        };
        client
            .write_all(&codec.encode_stream(&frame).unwrap())
            .await
            .unwrap();
    }

    async fn next_raw_frame(client: &mut DuplexStream, codec: &FrameCodec) -> Frame {
        timeout(TEST_TIMEOUT, read_frame(client, codec))
            .await
            .expect("native YAS frame timed out")
            .expect("native YAS frame read failed")
            .expect("native YAS session closed")
    }

    async fn next_frame(client: &mut DuplexStream, codec: &FrameCodec) -> Frame {
        loop {
            let frame = next_raw_frame(client, codec).await;
            if frame.header.family != family::CORE || frame.header.class != Class::Event {
                return frame;
            }
            match frame.header.kind {
                yas_wire::core::event_kind::SESSION_UPDATE => {
                    let update = SessionUpdate::decode(&frame.payload)
                        .expect("server emitted a valid SESSION_UPDATE");
                    assert!(update.catalog_revision > 1);
                }
                yas_wire::core::event_kind::FAMILY_UPDATE => {
                    let update = FamilyUpdate::decode(&frame.payload)
                        .expect("server emitted a valid FAMILY_UPDATE");
                    assert!(update.catalog_revision > 1);
                }
                _ => return frame,
            }
        }
    }

    async fn next_result(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        family_id: u16,
        kind: u16,
        request_id: u32,
    ) -> ResultPrefix {
        let frame = next_frame(client, codec).await;
        assert_eq!(
            frame.header,
            FrameHeader::result(family_id, kind, request_id)
        );
        ResultPrefix::decode(&frame.payload).unwrap()
    }

    async fn server_diagnostics(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        request_id: u32,
    ) -> yas_wire::core::ServerDiagnostics {
        let frame = Frame {
            header: FrameHeader::request(
                family::CORE,
                yas_wire::core::request_kind::SESSION_INFO,
                request_id,
            ),
            payload: Vec::new(),
        };
        client
            .write_all(&codec.encode_stream(&frame).unwrap())
            .await
            .unwrap();
        let result = next_result(
            client,
            codec,
            family::CORE,
            yas_wire::core::request_kind::SESSION_INFO,
            request_id,
        )
        .await;
        assert_eq!(result.status, Status::Ok);
        SessionInfo::decode(&result.body)
            .unwrap()
            .server_diagnostics()
            .unwrap()
            .expect("SESSION_INFO server diagnostics")
    }

    async fn wait_for_server_diagnostics_to_clear(
        registry: &super::super::ServerDiagnosticsRegistry,
    ) {
        let cleared = yas_wire::core::ServerDiagnostics {
            active_sessions: 0,
            relay_active: 0,
            relay_pending: 0,
            aggregate_receive_limit: 0,
            aggregate_receive_buffered: 0,
        };
        let result = timeout(TEST_TIMEOUT, async {
            while registry.snapshot() != cleared {
                tokio::time::sleep(Duration::from_millis(1)).await;
            }
        })
        .await;
        assert!(
            result.is_ok(),
            "server diagnostics did not clear: {:?}",
            registry.snapshot(),
        );
    }

    async fn next_sensitive_result(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        family_id: u16,
        kind: u16,
        request_id: u32,
    ) -> ResultPrefix {
        let frame = next_frame(client, codec).await;
        assert_eq!(
            frame.header,
            FrameHeader {
                sensitive: true,
                ..FrameHeader::result(family_id, kind, request_id)
            }
        );
        ResultPrefix::decode(&frame.payload).unwrap()
    }

    async fn next_extension_result(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        kind: u16,
        request_id: u32,
    ) -> ResultPrefix {
        loop {
            let frame = next_frame(client, codec).await;
            if frame.header
                == (FrameHeader {
                    sensitive: true,
                    ..FrameHeader::result(family::EXTENSION, kind, request_id)
                })
            {
                return ResultPrefix::decode(&frame.payload).unwrap();
            }
            assert!(
                frame.header.family == family::TRANSFER
                    || (frame.header.family == family::EXTENSION
                        && frame.header.class == Class::Event
                        && frame.header.kind == yas_extension_wire::event_kind::STATE),
                "unexpected frame while waiting for Extension Result: {:?}",
                frame.header
            );
        }
    }

    async fn next_goaway(client: &mut DuplexStream, codec: &FrameCodec) -> GoAway {
        let frame = next_frame(client, codec).await;
        assert_eq!(
            frame.header,
            FrameHeader::event(family::CORE, yas_wire::core::event_kind::GOAWAY)
        );
        GoAway::decode(&frame.payload).unwrap()
    }

    async fn next_terminal_result(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        kind: u16,
        request_id: u32,
        frames: &mut Vec<yas_terminal::TerminalFrame>,
    ) -> ResultPrefix {
        loop {
            let frame = next_frame(client, codec).await;
            let mut expected = FrameHeader::result(family::TERMINAL, kind, request_id);
            expected.sensitive =
                yas_wire::schema::operation(family::TERMINAL, Class::Request as u8, kind)
                    .is_some_and(|operation| {
                        operation.sensitive == yas_wire::schema::transport::policy::REQUIRED
                    });
            if frame.header == expected {
                return ResultPrefix::decode(&frame.payload).unwrap();
            }
            if frame.header
                == (FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::TERMINAL, yas_wire::schema::terminal::event::FRAME)
                })
            {
                frames.push(yas_terminal::TerminalFrame::decode(&frame.payload).unwrap());
                continue;
            }
            panic!(
                "unexpected native frame while awaiting Terminal Result: {:?}",
                frame.header
            );
        }
    }

    async fn next_client_result(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        kind: u16,
        request_id: u32,
    ) -> ResultPrefix {
        loop {
            let frame = next_frame(client, codec).await;
            let mut expected = FrameHeader::result(family::CLIENT, kind, request_id);
            expected.sensitive =
                yas_wire::schema::operation(family::CLIENT, Class::Request as u8, kind)
                    .is_some_and(|operation| {
                        operation.sensitive == yas_wire::schema::transport::policy::REQUIRED
                    });
            if frame.header == expected {
                return ResultPrefix::decode(&frame.payload).unwrap();
            }
            assert_eq!(frame.header.family, family::CLIENT);
            assert_eq!(frame.header.kind, yas_wire::schema::client::event::STATE);
            assert_eq!(frame.header.class, Class::Event);
            assert!(frame.header.sensitive);
            StateEvent::decode(&frame.payload).expect("interleaved Client STATE is typed");
        }
    }

    async fn next_terminal_frame_for(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        view_id: u32,
        frames: &mut Vec<yas_terminal::TerminalFrame>,
    ) -> yas_terminal::TerminalFrame {
        if let Some(index) = frames.iter().position(|frame| frame.view_id == view_id) {
            return frames.remove(index);
        }
        loop {
            let frame = next_frame(client, codec).await;
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::TERMINAL, yas_wire::schema::terminal::event::FRAME,)
                }
            );
            let frame = yas_terminal::TerminalFrame::decode(&frame.payload).unwrap();
            if frame.view_id == view_id {
                return frame;
            }
            frames.push(frame);
        }
    }

    async fn acknowledge_terminal_frame(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        frame: &yas_terminal::TerminalFrame,
    ) {
        write_event(
            client,
            codec,
            family::TERMINAL,
            yas_wire::schema::terminal::event::FRAME_ACK,
            &yas_terminal::ViewFeedback {
                view_id: frame.view_id,
                presented_sequence: frame.frame_sequence,
                decoder_queue_depth: 0,
                available_frame_slots: 1,
            },
        )
        .await;
    }

    #[cfg(unix)]
    async fn terminal_frame_with_title(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        mut frame: yas_terminal::TerminalFrame,
        frames: &mut Vec<yas_terminal::TerminalFrame>,
        title: &str,
    ) -> yas_terminal::TerminalFrame {
        timeout(TEST_TIMEOUT, async {
            loop {
                if frame
                    .decode_grid_codec1(SERVER_MAX_DECODED, None)
                    .unwrap()
                    .title
                    .as_deref()
                    == Some(title)
                {
                    return frame;
                }
                // Shell startup and PTY echo can arrive in separate frames.
                // Return credit until the shell has produced the marker.
                acknowledge_terminal_frame(client, codec, &frame).await;
                let next = next_terminal_frame_for(client, codec, frame.view_id, frames).await;
                assert_eq!(next.frame_sequence, frame.frame_sequence.wrapping_add(1));
                frame = next;
            }
        })
        .await
        .expect("Terminal produced the expected title")
    }

    #[test]
    fn terminal_feedback_serial_window_accepts_wrap_and_ignores_stale_half_range() {
        assert_eq!(terminal_feedback_advance(u32::MAX, 0, 0), Ok(Some(1)),);
        assert_eq!(terminal_feedback_advance(0, 0, u32::MAX), Ok(None),);
        assert_eq!(
            terminal_feedback_advance(7, 7, 7u32.wrapping_add(0x8000_0000)),
            Ok(None),
        );
        assert_eq!(terminal_feedback_advance(7, 7, 8), Err(()));
    }

    async fn collect_byte_transfer(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        transfer_id: u32,
    ) -> Vec<u8> {
        let mut bytes = Vec::new();
        loop {
            let frame = next_frame(client, codec).await;
            assert_eq!(frame.header.family, family::TRANSFER);
            match frame.header.kind {
                yas_wire::schema::transfer::event::BYTE_DATA => {
                    let data = ByteData::decode(&frame.payload).unwrap();
                    assert_eq!(data.transfer_id, transfer_id);
                    assert_eq!(data.offset, bytes.len() as u64);
                    bytes.extend_from_slice(&data.data);
                }
                yas_wire::schema::transfer::event::CLOSE => {
                    let close = Close::decode(&frame.payload).unwrap();
                    assert_eq!(close.transfer_id, transfer_id);
                    assert_eq!(close.final_data_bytes, bytes.len() as u64);
                    assert_eq!(Status::from_code(close.status), Status::Ok);
                    return bytes;
                }
                kind => panic!("unexpected Transfer event {kind}"),
            }
        }
    }

    async fn next_kv_result_collecting_state(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        kind: u16,
        request_id: u32,
    ) -> (ResultPrefix, Vec<StateEvent>) {
        let mut state = Vec::new();
        loop {
            let frame = next_frame(client, codec).await;
            if frame.header.family == family::KV
                && frame.header.class == Class::Result
                && frame.header.kind == kind
                && frame.header.request_id == Some(request_id)
            {
                let expected_sensitive =
                    yas_wire::schema::operation(family::KV, Class::Request as u8, kind)
                        .is_some_and(|operation| {
                            operation.sensitive == yas_wire::schema::transport::policy::REQUIRED
                        });
                assert_eq!(
                    frame.header.sensitive, expected_sensitive,
                    "KV Result sensitivity disagrees with schema for kind {kind}"
                );
                return (ResultPrefix::decode(&frame.payload).unwrap(), state);
            }
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::KV, yas_wire::schema::kv::event::STATE,)
                }
            );
            state.push(StateEvent::decode(&frame.payload).unwrap());
        }
    }

