    #[cfg(target_os = "linux")]
    async fn next_selection_delta(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        pending: &mut Vec<StateEvent>,
    ) -> StateEvent {
        if let Some(index) = pending.iter().position(|event| event.phase == Phase::Delta) {
            return pending.remove(index);
        }
        loop {
            let frame = next_frame(client, codec).await;
            assert_eq!(frame.header.family, family::SELECTION);
            assert_eq!(frame.header.kind, yas_wire::schema::selection::event::STATE);
            assert!(frame.header.sensitive);
            let event = StateEvent::decode(&frame.payload).unwrap();
            if event.phase == Phase::Delta {
                return event;
            }
        }
    }

    async fn next_kv_delta(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        pending: &mut Vec<StateEvent>,
    ) -> StateEvent {
        loop {
            if let Some(index) = pending.iter().position(|event| event.phase == Phase::Delta) {
                let event = pending.remove(index);
                if !event.records.is_empty() {
                    return event;
                }
                continue;
            }
            let frame = next_frame(client, codec).await;
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::KV, yas_wire::schema::kv::event::STATE)
                }
            );
            let event = StateEvent::decode(&frame.payload).unwrap();
            assert_eq!(event.phase, Phase::Delta);
            if !event.records.is_empty() {
                return event;
            }
        }
    }

    fn assert_no_kv_records(events: &[StateEvent]) {
        assert!(
            events
                .iter()
                .all(|event| event.phase == Phase::Delta && event.records.is_empty())
        );
    }

    async fn write_sensitive_transfer_event<T: Encode>(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        kind: u16,
        value: &T,
    ) {
        let mut header = FrameHeader::event(family::TRANSFER, kind);
        header.sensitive = true;
        client
            .write_all(
                &codec
                    .encode_stream(&Frame {
                        header,
                        payload: value.encode().unwrap(),
                    })
                    .unwrap(),
            )
            .await
            .unwrap();
    }

