    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "multi_thread")]
    async fn desktop_watch_menu_actions_and_asset_transfer_are_native() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let large_icon = vec![0x5a; yas_desktop::Limits::HARD.max_inline_asset_bytes as usize + 1];
        {
            let mut shared = state.session.lock().await;
            shared.ensure_compositor(false, Arc::new(|| {}), "");
            shared
                .compositor
                .as_mut()
                .unwrap()
                .native_media_state_override = Some(super::super::MediaBackendState {
                pipewire_available: true,
                microphone_available: false,
                camera_available: false,
                screencasts: Vec::new(),
            });
            let desktop = &mut shared.compositor.as_mut().unwrap().desktop_state;
            desktop.tray.insert(
                7,
                ::yas_desktop::TrayItem {
                    tray_id: 7,
                    revision: 11,
                    status: ::yas_desktop::TRAY_STATUS_ACTIVE,
                    category: ::yas_desktop::TRAY_CATEGORY_APPLICATION_STATUS,
                    flags: ::yas_desktop::TRAY_HAS_MENU,
                    app_id: "yas.desktop.test".to_owned(),
                    title: "Native tray".to_owned(),
                    tooltip_title: String::new(),
                    tooltip_body: String::new(),
                    icon: ::yas_desktop::PngImage {
                        width: 8,
                        height: 8,
                        png: large_icon.clone(),
                    },
                },
            );
            desktop.notifications.insert(
                9,
                ::yas_desktop::Notification {
                    notification_id: 9,
                    revision: 3,
                    urgency: ::yas_desktop::NOTIFICATION_URGENCY_NORMAL,
                    flags: ::yas_desktop::NOTIFICATION_RESIDENT,
                    timeout_ms: 5_000,
                    app_name: "yas-test".to_owned(),
                    desktop_entry: "yas.test".to_owned(),
                    summary: "typed notification".to_owned(),
                    body: "native Desktop state".to_owned(),
                    icon: ::yas_desktop::PngImage::default(),
                    image: ::yas_desktop::PngImage::default(),
                    actions: vec![
                        ::yas_desktop::NotificationAction {
                            key: "default".to_owned(),
                            label: "Open".to_owned(),
                        },
                        ::yas_desktop::NotificationAction {
                            key: "accept".to_owned(),
                            label: "Accept".to_owned(),
                        },
                    ],
                },
            );
        }

        let (mut client, codec, hello, server_task) =
            start_registered_session(state.clone(), &[family::TRANSFER, family::DESKTOP]).await;
        let descriptor = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::DESKTOP)
            .expect("Desktop negotiated");
        assert_eq!(descriptor.runtime_state, RuntimeState::Available);
        assert_eq!(
            yas_desktop::Limits::from_extensions(&descriptor.limits).unwrap(),
            yas_desktop::Limits::HARD,
        );

        write_request(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::WATCH,
            10,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let watch = next_result(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::WATCH,
            10,
        )
        .await;
        assert_eq!(watch.status, Status::Ok);
        let watch = WatchResult::decode(&watch.body).unwrap();
        let mut tray = None;
        let mut notification = None;
        let mut snapshot_end = false;
        while tray.is_none() || notification.is_none() || !snapshot_end {
            let frame = next_frame(&mut client, &codec).await;
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::DESKTOP, yas_desktop::event_kind::STATE)
                }
            );
            let event = StateEvent::decode(&frame.payload).unwrap();
            assert_eq!(event.subscription_id, watch.subscription_id);
            snapshot_end |= event.phase == Phase::SnapshotEnd;
            for record in &event.records {
                match yas_desktop::decode_state_record(record).unwrap() {
                    yas_desktop::StateMutation::Complete(yas_desktop::CompleteEntity::Tray(
                        value,
                    )) => tray = Some(value),
                    yas_desktop::StateMutation::Complete(
                        yas_desktop::CompleteEntity::Notification(value),
                    ) => notification = Some(value),
                    _ => {}
                }
            }
        }
        let tray = tray.unwrap();
        let notification = notification.unwrap();
        assert_ne!(tray.tray_handle, 0);
        assert_eq!(tray.title, "Native tray");
        assert_ne!(notification.notification_handle, 0);
        assert_ne!(notification.notification_handle, tray.tray_handle);
        assert_eq!(notification.actions.len(), 1);
        assert_eq!(notification.actions[0].label, "Accept");

        write_request(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::FETCH_ASSET,
            11,
            &yas_desktop::FetchAsset {
                content_hash: tray.icon_hash,
                initial_receive_credit: large_icon.len() as u64,
                extensions: Extensions::default(),
            },
        )
        .await;
        let fetched = next_sensitive_result(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::FETCH_ASSET,
            11,
        )
        .await;
        assert_eq!(fetched.status, Status::Ok);
        let fetched = yas_desktop::AssetResult::decode(&fetched.body).unwrap();
        let Delivery::Transfer(transfer) = fetched.0.delivery else {
            panic!("large Desktop asset must use Transfer");
        };
        assert!(transfer.sensitive_content().unwrap());
        assert_eq!(
            collect_byte_transfer(&mut client, &codec, transfer.transfer_id).await,
            large_icon,
        );

        write_request(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::GET_MENU,
            12,
            &yas_desktop::GetMenu {
                tray_handle: tray.tray_handle,
                tray_revision: tray.revision,
                menu_revision: tray.menu_revision,
                initial_receive_credit: 64 * 1024,
                extensions: Extensions::default(),
            },
        )
        .await;
        {
            let mut shared = state.session.lock().await;
            shared.compositor.as_mut().unwrap().desktop_menus.insert(
                7,
                ::yas_desktop::TrayMenu {
                    tray_id: 7,
                    tray_revision: 11,
                    menu_revision: 23,
                    status: ::yas_desktop::TRAY_MENU_OK,
                    nodes: vec![
                        ::yas_desktop::MenuNode {
                            id: 0,
                            parent_id: 0,
                            position: 0,
                            flags: ::yas_desktop::MENU_NODE_VISIBLE,
                            toggle_state: 0,
                            label: "root".to_owned(),
                            icon: ::yas_desktop::PngImage::default(),
                        },
                        ::yas_desktop::MenuNode {
                            id: 42,
                            parent_id: 0,
                            position: 0,
                            flags: ::yas_desktop::MENU_NODE_VISIBLE
                                | ::yas_desktop::MENU_NODE_ENABLED,
                            toggle_state: 0,
                            label: "Run".to_owned(),
                            icon: ::yas_desktop::PngImage::default(),
                        },
                    ],
                },
            );
        }
        let menu = next_sensitive_result(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::GET_MENU,
            12,
        )
        .await;
        assert_eq!(menu.status, Status::Ok);
        let menu = yas_desktop::MenuResult::decode(&menu.body).unwrap();
        let Delivery::Inline(menu) = menu.0.delivery else {
            panic!("small Desktop menu must be inline");
        };
        let menu = yas_desktop::MenuTree::decode(&menu).unwrap();
        assert_eq!(menu.tray_handle, tray.tray_handle);
        assert_eq!(menu.menu_revision, tray.menu_revision);
        assert_eq!(menu.nodes[1].label, "Run");
        assert_ne!(menu.nodes[1].action_handle, 0);

        let action = yas_desktop::TrayAction {
            tray_handle: tray.tray_handle,
            tray_revision: tray.revision,
            menu_revision: tray.menu_revision,
            operation_id: [0x66; 16],
            action_kind: yas_wire::schema::desktop::TRAY_ACTION_MENU_ITEM as u8,
            flags: 0,
            value: 0,
            item_handle: menu.nodes[1].action_handle,
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::TRAY_ACTION,
            13,
            &action,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::DESKTOP,
                yas_desktop::request_kind::TRAY_ACTION,
                13,
            )
            .await
            .status,
            Status::Ok,
        );
        write_request(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::TRAY_ACTION,
            14,
            &action,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::DESKTOP,
                yas_desktop::request_kind::TRAY_ACTION,
                14,
            )
            .await
            .status,
            Status::Ok,
        );
        let conflicting = yas_desktop::TrayAction {
            action_kind: yas_wire::schema::desktop::TRAY_ACTION_ACTIVATE as u8,
            menu_revision: 0,
            item_handle: 0,
            ..action
        };
        write_request(
            &mut client,
            &codec,
            family::DESKTOP,
            yas_desktop::request_kind::TRAY_ACTION,
            15,
            &conflicting,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::DESKTOP,
                yas_desktop::request_kind::TRAY_ACTION,
                15,
            )
            .await
            .status,
            Status::Conflict,
        );

        let commands = {
            let shared = state.session.lock().await;
            shared
                .compositor
                .as_ref()
                .unwrap()
                .native_desktop_commands
                .clone()
        };
        assert!(matches!(
            commands.as_slice(),
            [
                ::yas_desktop::Command::NativeTray(::yas_desktop::TrayCommand {
                    tray_id: 7,
                    kind: ::yas_desktop::TrayCommandKind::OpenMenu,
                    ..
                }),
                ::yas_desktop::Command::NativeTray(::yas_desktop::TrayCommand {
                    tray_id: 7,
                    kind: ::yas_desktop::TrayCommandKind::MenuItem,
                    menu_revision: 23,
                    value: 42,
                    ..
                })
            ]
        ));

        drop(client);
        timeout(TEST_TIMEOUT, server_task)
            .await
            .expect("Desktop session stops")
            .unwrap();
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn extension_attempt_context_is_first_native_application_frame() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let context = yas_extension_wire::AttemptContext {
            extension_handle: 11,
            generation: 12,
            definition_revision: 13,
            attempt: 14,
            task_id: 15,
            flags: (yas_wire::schema::extension::DEFINITION_ENABLED
                | yas_wire::schema::extension::DEFINITION_DESIRED_RUNNING)
                as u16,
            runtime: yas_extension_wire::Runtime::Wasmi,
            content_hash: [0x44; 32],
            name: "native-attempt".to_owned(),
            argv: vec![b"--typed-yas".to_vec()],
            extensions: Extensions::default(),
        };
        let cancellation = ConnectionCancellation::default();
        let registration = state
            .connections
            .register(cancellation.clone())
            .expect("attempt registers");
        let (mut client, server) = tokio::io::duplex(1024 * 1024);
        let server_state = state.clone();
        let expected = context.clone();
        let server_task = tokio::spawn(serve_attempt_stream(
            server,
            server_state,
            cancellation,
            registration,
            context,
        ));

        let (codec, hello) = handshake(
            &mut client,
            &[family::TRANSFER, family::CHANNEL, family::EXTENSION],
        )
        .await;
        let descriptor = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::EXTENSION)
            .expect("attempt Extension descriptor");
        assert_eq!(
            descriptor.runtime_state,
            if state.extensions.advertised() {
                RuntimeState::Available
            } else {
                RuntimeState::Unavailable
            },
        );
        let limits = yas_extension_wire::Limits::from_extensions(&descriptor.limits).unwrap();
        let family_limits = state.extensions.native_family_limits();
        let runtime_limits = state.extensions.native_runtime_limits();
        assert_eq!(
            limits.max_definitions,
            u32::try_from(family_limits.max_definitions).unwrap()
        );
        assert_eq!(
            limits.max_follows_per_session,
            u32::try_from(family_limits.max_follows_per_session).unwrap()
        );
        assert_eq!(
            limits.max_running_attempts,
            u32::try_from(family_limits.max_running_attempts).unwrap()
        );
        assert_eq!(limits.max_memory_bytes, runtime_limits.memory_bytes);
        let attempt_context = descriptor
            .operations
            .iter()
            .find(|operation| {
                operation.class == Class::Event
                    && operation.kind == yas_extension_wire::event_kind::ATTEMPT_CONTEXT
            })
            .expect("attempt context capability");
        assert!(!attempt_context.server_accepts);
        assert!(attempt_context.server_sends);
        let attempt_output = descriptor
            .operations
            .iter()
            .find(|operation| {
                operation.class == Class::Event
                    && operation.kind == yas_extension_wire::event_kind::ATTEMPT_OUTPUT
            })
            .expect("attempt output capability");
        assert!(attempt_output.server_accepts);
        assert!(!attempt_output.server_sends);
        assert!(descriptor.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_extension_wire::request_kind::OBJECT_BEGIN
                && operation.server_accepts
        }));
        assert!(descriptor.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_extension_wire::request_kind::REGISTER_COMMAND
                && operation.server_accepts
        }));

        // The HELLO Result was consumed by `handshake`; the very next outer
        // YAS frame is the typed, sensitive context. No YAS INIT or other
        // application packet can precede it.
        let frame = next_frame(&mut client, &codec).await;
        assert_eq!(
            frame.header,
            FrameHeader {
                sensitive: true,
                ..FrameHeader::event(
                    family::EXTENSION,
                    yas_extension_wire::event_kind::ATTEMPT_CONTEXT,
                )
            }
        );
        assert_eq!(
            yas_extension_wire::AttemptContext::decode(&frame.payload).unwrap(),
            expected,
        );

        // The ordinary listener exposes the complete external Extension
        // surface, but never emits the embedded-attempt-only context.
        let ordinary = ClientHello {
            min_minor: 1,
            max_minor: 1,
            receive: ReceiveLimits {
                max_frame: SERVER_MAX_FRAME,
                max_decoded: SERVER_MAX_DECODED,
                max_datagram: 0,
                max_buffered: SERVER_MAX_BUFFERED,
            },
            client_instance: [9; 16],
            client_name: "ordinary".to_owned(),
            client_release: "1".to_owned(),
            families: [family::TRANSFER, family::CHANNEL, family::EXTENSION]
                .into_iter()
                .map(|family_id| FamilyOffer {
                    family_id,
                    versions: vec![1],
                    required: true,
                })
                .collect(),
            codecs: Vec::new(),
            extensions: Extensions::default(),
        };
        let ordinary = negotiate(&ordinary, &Services::from_state(&state), false, 0)
            .expect("external Extension negotiates with its dependencies");
        let extension = ordinary
            .descriptors
            .iter()
            .find(|descriptor| descriptor.family_id == family::EXTENSION)
            .expect("external Extension descriptor");
        assert!(extension.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_extension_wire::request_kind::OBJECT_BEGIN
                && operation.server_accepts
        }));
        assert!(!extension.operations.iter().any(|operation| {
            operation.class == Class::Event
                && operation.kind == yas_extension_wire::event_kind::ATTEMPT_CONTEXT
        }));
        assert!(!extension.operations.iter().any(|operation| {
            operation.class == Class::Event
                && operation.kind == yas_extension_wire::event_kind::ATTEMPT_OUTPUT
        }));
        assert!(!extension.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_extension_wire::request_kind::REGISTER_COMMAND
        }));

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn extension_object_deploy_reconnect_control_and_follow_are_native() {
        struct TempRoot(PathBuf);

        impl TempRoot {
            fn new() -> Self {
                static NEXT: AtomicU64 = AtomicU64::new(0);
                let serial = NEXT.fetch_add(1, Ordering::Relaxed);
                let path = std::env::temp_dir()
                    .join(format!("yas-extension-e2e-{}-{serial}", std::process::id()));
                std::fs::create_dir(&path).unwrap();
                Self(path)
            }
        }

        impl Drop for TempRoot {
            fn drop(&mut self) {
                let _ = std::fs::remove_dir_all(&self.0);
            }
        }

        let root = TempRoot::new();
        let extensions = super::super::extension::ExtensionService::persistent_for_test(&root.0);
        let initial = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let mut inner = Arc::try_unwrap(initial)
            .ok()
            .expect("fresh test AppState is uniquely owned");
        inner.config.allow_persistent_extensions = true;
        inner.extensions = Arc::clone(&extensions);
        let state = Arc::new(inner);

        let module = wat::parse_str(
            "(module (memory (export \"memory\") 1) \
             (func (export \"yas_main\") (result i32) i32.const 0))",
        )
        .unwrap();
        let content_hash = *blake3::hash(&module).as_bytes();
        let families = [family::TRANSFER, family::CHANNEL, family::EXTENSION];
        let (mut client, codec, hello, first_task) =
            start_registered_session(state.clone(), &families).await;
        let descriptor = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::EXTENSION)
            .expect("Extension negotiated");
        assert_eq!(descriptor.runtime_state, RuntimeState::Available);
        for kind in [
            yas_extension_wire::request_kind::WATCH,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            yas_extension_wire::request_kind::OBJECT_COMMIT,
            yas_extension_wire::request_kind::DEPLOY,
            yas_extension_wire::request_kind::CONTROL,
            yas_extension_wire::request_kind::FOLLOW,
        ] {
            assert!(descriptor.operations.iter().any(|operation| {
                operation.class == Class::Request
                    && operation.kind == kind
                    && operation.server_accepts
            }));
        }

        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::WATCH,
            50,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let watched = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::WATCH,
            50,
        )
        .await;
        assert_eq!(watched.status, Status::Ok);
        let watch = WatchResult::decode(&watched.body).unwrap();
        loop {
            let frame = next_frame(&mut client, &codec).await;
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::EXTENSION, yas_extension_wire::event_kind::STATE,)
                }
            );
            let event = StateEvent::decode(&frame.payload).unwrap();
            assert_eq!(event.subscription_id, watch.subscription_id);
            if event.phase == Phase::SnapshotEnd {
                break;
            }
        }

        let begin_request = yas_extension_wire::ObjectBegin {
            operation_id: [0x81; 16],
            content_hash,
            byte_len: module.len() as u64,
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            51,
            &begin_request,
        )
        .await;
        let began = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            51,
        )
        .await;
        assert_eq!(began.status, Status::Ok);
        let began_body = began.body.clone();
        let began = yas_extension_wire::ObjectBeginResult::decode(&began.body).unwrap();
        assert_eq!(
            began.disposition,
            yas_extension_wire::ObjectDisposition::Upload
        );
        let upload = began.descriptor.as_ref().expect("new object uploads");
        assert!(upload.sensitive_content().unwrap());
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            60,
            &begin_request,
        )
        .await;
        let begin_replay = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            60,
        )
        .await;
        assert_eq!(begin_replay.status, Status::Ok);
        assert_eq!(begin_replay.body, began_body);

        let mut conflicting_begin = begin_request.clone();
        conflicting_begin.byte_len += 1;
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            61,
            &conflicting_begin,
        )
        .await;
        assert_eq!(
            next_extension_result(
                &mut client,
                &codec,
                yas_extension_wire::request_kind::OBJECT_BEGIN,
                61,
            )
            .await
            .status,
            Status::Conflict,
        );
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::BYTE_DATA,
            &ByteData {
                transfer_id: upload.transfer_id,
                offset: 0,
                data: module.clone(),
            },
        )
        .await;
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::CLOSE,
            &Close {
                transfer_id: upload.transfer_id,
                final_data_bytes: module.len() as u64,
                status: Status::Ok.code(),
                detail: Vec::new(),
            },
        )
        .await;
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            63,
            &begin_request,
        )
        .await;
        assert_eq!(
            next_extension_result(
                &mut client,
                &codec,
                yas_extension_wire::request_kind::OBJECT_BEGIN,
                63,
            )
            .await
            .status,
            Status::Stale,
        );
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::OBJECT_COMMIT,
            52,
            &yas_extension_wire::ObjectCommit {
                staging_handle: began.staging_handle,
                operation_id: [0x82; 16],
                content_hash,
                byte_len: module.len() as u64,
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_extension_result(
                &mut client,
                &codec,
                yas_extension_wire::request_kind::OBJECT_COMMIT,
                52,
            )
            .await
            .status,
            Status::Ok,
        );

        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::OBJECT_BEGIN,
            62,
            &begin_request,
        )
        .await;
        assert_eq!(
            next_extension_result(
                &mut client,
                &codec,
                yas_extension_wire::request_kind::OBJECT_BEGIN,
                62,
            )
            .await
            .status,
            Status::Stale,
        );

        let deploy = yas_extension_wire::Deploy {
            operation_id: [0x83; 16],
            expected_extension_handle: 0,
            expected_generation: 0,
            expected_definition_revision: 0,
            flags: (yas_wire::schema::extension::DEFINITION_PERSISTENT
                | yas_wire::schema::extension::DEFINITION_ENABLED
                | yas_wire::schema::extension::DEFINITION_DESIRED_RUNNING
                | yas_wire::schema::extension::DEFINITION_DETACHED) as u16,
            runtime: yas_extension_wire::Runtime::Wasmi,
            restart_policy: yas_extension_wire::RestartPolicy::Never,
            name: "yas-native-replay".to_owned(),
            content_hash,
            argv: Vec::new(),
            runtime_limits: yas_extension_wire::RuntimeLimits {
                memory_bytes: 0,
                stack_bytes: 0,
                max_active_jobs: 0,
                max_pending_jobs: 0,
                max_job_bytes: 0,
                slow_consumer_timeout_ns: 0,
                extensions: Extensions::default(),
            },
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::DEPLOY,
            53,
            &deploy,
        )
        .await;

        // Do not read the Result. Poll the semantic authority until the
        // persistent mutation committed, then drop the connection to model a
        // lost response.
        let committed = timeout(TEST_TIMEOUT, async {
            loop {
                if let Some(definition) = extensions
                    .native_snapshot()
                    .await
                    .into_iter()
                    .find(|definition| definition.name == deploy.name)
                {
                    break definition;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("persistent DEPLOY commits");
        let deployed_identity = yas_extension_wire::DefinitionIdentity {
            extension_handle: committed.extension_handle,
            generation: committed.generation,
            definition_revision: committed.definition_revision,
            extensions: Extensions::default(),
        };
        drop(client);
        timeout(TEST_TIMEOUT, first_task).await.unwrap().unwrap();

        let (mut client, codec, _, second_task) =
            start_registered_session(state.clone(), &families).await;
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::DEPLOY,
            60,
            &deploy,
        )
        .await;
        let replayed_deploy = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::DEPLOY,
            60,
        )
        .await;
        assert_eq!(replayed_deploy.status, Status::Ok);
        assert_eq!(
            replayed_deploy.body,
            deployed_identity.encode().unwrap(),
            "reconnect replays the exact committed identity",
        );
        let definitions = extensions.native_snapshot().await;
        assert_eq!(definitions.len(), 1);
        assert_eq!(
            definitions[0].definition_revision, deployed_identity.definition_revision,
            "replay does not repeat the mutation",
        );

        let attempt = timeout(TEST_TIMEOUT, async {
            loop {
                let attempt = extensions
                    .native_snapshot()
                    .await
                    .into_iter()
                    .find(|definition| {
                        definition.extension_handle == deployed_identity.extension_handle
                    })
                    .map(|definition| definition.attempt.max(definition.last_running_attempt))
                    .unwrap_or(0);
                if attempt != 0 {
                    break attempt;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("desired Extension attempt starts");
        let follow = yas_extension_wire::Follow {
            extension_handle: deployed_identity.extension_handle,
            generation: deployed_identity.generation,
            attempt,
            from_sequence: 0,
            initial_receive_credit: 1024 * 1024,
            extensions: Extensions::default(),
        };
        for request_id in [61, 62] {
            write_request(
                &mut client,
                &codec,
                family::EXTENSION,
                yas_extension_wire::request_kind::FOLLOW,
                request_id,
                &follow,
            )
            .await;
            let followed = next_extension_result(
                &mut client,
                &codec,
                yas_extension_wire::request_kind::FOLLOW,
                request_id,
            )
            .await;
            assert_eq!(followed.status, Status::Ok);
            let followed = yas_extension_wire::FollowResult::decode(&followed.body).unwrap();
            write_sensitive_transfer_event(
                &mut client,
                &codec,
                yas_wire::schema::transfer::event::RESET,
                &Reset {
                    transfer_id: followed.descriptor.transfer_id,
                    status: Status::Cancelled.code(),
                    detail: Vec::new(),
                },
            )
            .await;
            tokio::time::sleep(Duration::from_millis(20)).await;
        }

        let stale_control = yas_extension_wire::Control {
            extension_handle: deployed_identity.extension_handle,
            generation: deployed_identity.generation,
            expected_definition_revision: deployed_identity.definition_revision + 99,
            operation_id: [0x84; 16],
            action: yas_extension_wire::ControlAction::Disable,
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::CONTROL,
            63,
            &stale_control,
        )
        .await;
        let stale = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::CONTROL,
            63,
        )
        .await;
        assert_eq!(stale.status, Status::Conflict);
        assert!(stale.body.is_empty());

        let valid_control = yas_extension_wire::Control {
            expected_definition_revision: deployed_identity.definition_revision,
            operation_id: [0x85; 16],
            ..stale_control.clone()
        };
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::CONTROL,
            64,
            &valid_control,
        )
        .await;
        let controlled = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::CONTROL,
            64,
        )
        .await;
        assert_eq!(controlled.status, Status::Ok);
        let controlled_body = controlled.body;
        let controlled_identity =
            yas_extension_wire::DefinitionIdentity::decode(&controlled_body).unwrap();
        assert_eq!(
            controlled_identity.extension_handle,
            deployed_identity.extension_handle
        );
        let disabled = extensions
            .native_snapshot()
            .await
            .into_iter()
            .find(|definition| definition.extension_handle == deployed_identity.extension_handle)
            .unwrap();
        assert_eq!(
            disabled.flags & yas_wire::schema::extension::DEFINITION_ENABLED as u8,
            0,
            "the intervening CONTROL changed persistent desired state",
        );
        drop(client);
        timeout(TEST_TIMEOUT, second_task).await.unwrap().unwrap();

        let (mut client, codec, _, third_task) =
            start_registered_session(state.clone(), &families).await;
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::CONTROL,
            70,
            &stale_control,
        )
        .await;
        let stale_replay = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::CONTROL,
            70,
        )
        .await;
        assert_eq!(stale_replay.status, Status::Conflict);
        assert!(stale_replay.body.is_empty());
        write_request(
            &mut client,
            &codec,
            family::EXTENSION,
            yas_extension_wire::request_kind::CONTROL,
            71,
            &valid_control,
        )
        .await;
        let control_replay = next_extension_result(
            &mut client,
            &codec,
            yas_extension_wire::request_kind::CONTROL,
            71,
        )
        .await;
        assert_eq!(control_replay.status, Status::Ok);
        assert_eq!(control_replay.body, controlled_body);

        drop(client);
        timeout(TEST_TIMEOUT, third_task).await.unwrap().unwrap();
        extensions.shutdown().await;
        drop(state);
        drop(extensions);
    }

    #[test]
    fn post_handshake_core_descriptor_only_claims_live_operations() {
        let hello = ClientHello {
            min_minor: 1,
            max_minor: 1,
            receive: ReceiveLimits::recommended(0),
            client_instance: [1; 16],
            client_name: "descriptor-test".to_owned(),
            client_release: "1".to_owned(),
            families: Vec::new(),
            codecs: Vec::new(),
            extensions: Extensions::default(),
        };
        let negotiated = negotiate(
            &hello,
            &test_services(None, unavailable_connector(), None),
            false,
            0,
        )
        .unwrap();
        let core = negotiated
            .descriptors
            .iter()
            .find(|descriptor| descriptor.family_id == family::CORE)
            .unwrap();
        assert_eq!(
            core.operations
                .iter()
                .map(|operation| (operation.class, operation.kind))
                .collect::<Vec<_>>(),
            vec![
                (Class::Request, yas_wire::core::request_kind::PING),
                (Class::Request, yas_wire::core::request_kind::CANCEL),
                (Class::Request, yas_wire::core::request_kind::SESSION_INFO,),
                (Class::Request, yas_wire::core::request_kind::CLIENT_UPDATE,),
                (Class::Event, yas_wire::core::event_kind::SESSION_UPDATE,),
                (Class::Event, yas_wire::core::event_kind::FAMILY_UPDATE,),
            ],
        );
        assert!(
            core.operations
                .iter()
                .all(|operation| match operation.class {
                    Class::Request =>
                        operation.server_accepts
                            && operation.server_sends
                                == (operation.kind == yas_wire::core::request_kind::PING),
                    Class::Event => !operation.server_accepts && operation.server_sends,
                    Class::Result => false,
                })
        );
    }

    #[tokio::test]
    async fn core_catalogue_update_is_monotonic_and_reflected_by_session_info() {
        let mut services = test_services(None, unavailable_connector(), None);
        services.receive_max_buffered_override = Some(SERVER_MAX_BUFFERED * 2);
        let (mut client, codec, hello, task) = start_session(services, &[]).await;

        let update_frame = next_raw_frame(&mut client, &codec).await;
        assert_eq!(
            update_frame.header,
            FrameHeader::event(family::CORE, yas_wire::core::event_kind::SESSION_UPDATE)
        );
        let update = SessionUpdate::decode(&update_frame.payload).unwrap();
        assert_eq!(update.catalog_revision, 2);
        assert_eq!(update.receive.max_buffered, SERVER_MAX_BUFFERED);
        update
            .validate_after(1, &hello.receive)
            .expect("SESSION_UPDATE is a contiguous valid reduction");

        let request = Frame {
            header: FrameHeader::request(
                family::CORE,
                yas_wire::core::request_kind::SESSION_INFO,
                2,
            ),
            payload: Vec::new(),
        };
        client
            .write_all(&codec.encode_stream(&request).unwrap())
            .await
            .unwrap();
        let response = next_raw_frame(&mut client, &codec).await;
        assert_eq!(
            response.header,
            FrameHeader::result(family::CORE, yas_wire::core::request_kind::SESSION_INFO, 2,)
        );
        let result = ResultPrefix::decode(&response.payload).unwrap();
        assert_eq!(result.status, Status::Ok);
        let info = SessionInfo::decode(&result.body).unwrap();
        assert_eq!(info.catalog_revision, update.catalog_revision);
        assert_eq!(info.receive, update.receive);
        let reported = info
            .server_diagnostics()
            .unwrap()
            .expect("SESSION_INFO reports server-wide diagnostics");
        assert_eq!(reported.active_sessions, 1);
        assert_eq!(reported.relay_active, 0);
        assert_eq!(reported.relay_pending, 0);
        assert_eq!(reported.aggregate_receive_limit, SERVER_MAX_BUFFERED);
        assert!(reported.aggregate_receive_buffered > 0);
        assert!(reported.aggregate_receive_buffered <= reported.aggregate_receive_limit);
        info.validate_after(
            &hello.session_id,
            update.catalog_revision,
            &update.receive,
            &hello.families,
        )
        .unwrap();

        drop(client);
        timeout(TEST_TIMEOUT, task).await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn server_diagnostics_aggregate_and_release_multiple_sessions() {
        let services = test_services(None, unavailable_connector(), None);
        let registry = Arc::clone(&services.diagnostics);
        let (mut first, first_codec, _, first_task) = start_session(services.clone(), &[]).await;
        let (second, _, _, second_task) = start_session(services, &[]).await;

        let both = server_diagnostics(&mut first, &first_codec, 20).await;
        assert_eq!(both.active_sessions, 2);
        assert_eq!(both.aggregate_receive_limit, SERVER_MAX_BUFFERED * 2);
        assert!(both.aggregate_receive_buffered > 0);
        assert!(both.aggregate_receive_buffered <= both.aggregate_receive_limit);

        drop(second);
        timeout(TEST_TIMEOUT, second_task).await.unwrap().unwrap();
        let one = server_diagnostics(&mut first, &first_codec, 21).await;
        assert_eq!(one.active_sessions, 1);
        assert_eq!(one.aggregate_receive_limit, SERVER_MAX_BUFFERED);
        assert!(one.aggregate_receive_buffered > 0);
        assert!(one.aggregate_receive_buffered <= one.aggregate_receive_limit);

        drop(first);
        timeout(TEST_TIMEOUT, first_task).await.unwrap().unwrap();
        wait_for_server_diagnostics_to_clear(&registry).await;
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn core_shutdown_orders_result_broadcast_and_boot_replay() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut initiator, initiator_codec, initiator_hello, initiator_task) =
            start_registered_session(state.clone(), &[]).await;
        let (mut peer, peer_codec, peer_hello, peer_task) =
            start_registered_session(state.clone(), &[]).await;

        for hello in [&initiator_hello, &peer_hello] {
            let core = hello
                .families
                .iter()
                .find(|descriptor| descriptor.family_id == family::CORE)
                .expect("Core descriptor");
            assert!(core.operations.iter().any(|operation| {
                operation.class == Class::Request
                    && operation.kind == yas_wire::core::request_kind::SHUTDOWN
                    && operation.server_accepts
                    && !operation.server_sends
            }));
            assert!(core.operations.iter().any(|operation| {
                operation.class == Class::Event
                    && operation.kind == yas_wire::core::event_kind::GOAWAY
                    && !operation.server_accepts
                    && operation.server_sends
            }));
        }

        let shutdown = Shutdown {
            operation_id: [0x31; 16],
            grace_ns: 60_000_000_000,
            reason: "ordered maintenance".to_owned(),
        };
        write_request(
            &mut initiator,
            &initiator_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            10,
            &shutdown,
        )
        .await;

        // The initiator's physical stream contains the correlated Result
        // before its GOAWAY. The coordinator cannot broadcast to the peer
        // until the writer has acknowledged this first frame.
        let result = next_sensitive_result(
            &mut initiator,
            &initiator_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            10,
        )
        .await;
        assert_eq!(result.status, Status::Ok);
        assert!(result.body.is_empty());
        timeout(TEST_TIMEOUT, async {
            while !state.yas_shutdown.is_scheduled() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("Result acknowledgement commits SHUTDOWN before GOAWAY");
        let initiator_goaway = next_goaway(&mut initiator, &initiator_codec).await;
        let peer_goaway = next_goaway(&mut peer, &peer_codec).await;
        assert_eq!(initiator_goaway, peer_goaway);
        assert_eq!(initiator_goaway.status, Status::Ok);

        let late = ConnectionCancellation::default();
        assert!(state.connections.register(late.clone()).is_none());
        assert!(late.is_cancelled(), "ordinary admission is sealed");

        write_request(
            &mut initiator,
            &initiator_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            11,
            &shutdown,
        )
        .await;
        let replay = next_sensitive_result(
            &mut initiator,
            &initiator_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            11,
        )
        .await;
        assert_eq!(replay, result, "exact retry returns the original Result");

        let mismatched = Shutdown {
            reason: "different arguments".to_owned(),
            ..shutdown.clone()
        };
        write_request(
            &mut peer,
            &peer_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            12,
            &mismatched,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut peer,
                &peer_codec,
                family::CORE,
                yas_wire::core::request_kind::SHUTDOWN,
                12,
            )
            .await
            .status,
            Status::Conflict
        );

        let different_operation = Shutdown {
            operation_id: [0x32; 16],
            ..shutdown
        };
        write_request(
            &mut peer,
            &peer_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            13,
            &different_operation,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut peer,
                &peer_codec,
                family::CORE,
                yas_wire::core::request_kind::SHUTDOWN,
                13,
            )
            .await
            .status,
            Status::Unavailable
        );

        drop(initiator);
        drop(peer);
        timeout(TEST_TIMEOUT, initiator_task)
            .await
            .unwrap()
            .unwrap();
        timeout(TEST_TIMEOUT, peer_task).await.unwrap().unwrap();
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn core_shutdown_lost_result_replays_on_drain_only_reconnect() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut first, first_codec, _, first_task) =
            start_registered_session(state.clone(), &[]).await;
        let shutdown = Shutdown {
            operation_id: [0x41; 16],
            grace_ns: 60_000_000_000,
            reason: "lost result".to_owned(),
        };
        write_request(
            &mut first,
            &first_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            20,
            &shutdown,
        )
        .await;
        timeout(TEST_TIMEOUT, async {
            while !state.yas_shutdown.is_scheduled() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("SHUTDOWN is committed despite an unread Result");
        drop(first);
        timeout(TEST_TIMEOUT, first_task).await.unwrap().unwrap();

        let (mut retry, retry_codec, retry_hello, retry_task) =
            start_shutdown_retry_session(state, &[family::ENV]).await;
        let core = retry_hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::CORE)
            .expect("Core descriptor");
        assert!(core.operations.iter().any(|operation| {
            operation.class == Class::Request
                && operation.kind == yas_wire::core::request_kind::SHUTDOWN
        }));
        // Race an ordinary advertised family Request with the inherited
        // GOAWAY. The registration latch is set before the session loop, so
        // selection order cannot let it reach Env dispatch.
        write_request(
            &mut retry,
            &retry_codec,
            family::ENV,
            yas_wire::schema::env::request::GET,
            22,
            &yas_wire::env::Get::default(),
        )
        .await;
        let mut saw_goaway = false;
        let mut saw_refusal = false;
        while !saw_goaway || !saw_refusal {
            let frame = next_frame(&mut retry, &retry_codec).await;
            if frame.header == FrameHeader::event(family::CORE, yas_wire::core::event_kind::GOAWAY)
            {
                assert_eq!(GoAway::decode(&frame.payload).unwrap().status, Status::Ok);
                saw_goaway = true;
                continue;
            }
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::result(family::ENV, yas_wire::schema::env::request::GET, 22,)
                }
            );
            assert_eq!(
                ResultPrefix::decode(&frame.payload).unwrap().status,
                Status::Unavailable
            );
            saw_refusal = true;
        }
        write_request(
            &mut retry,
            &retry_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            21,
            &shutdown,
        )
        .await;
        let replay = next_sensitive_result(
            &mut retry,
            &retry_codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            21,
        )
        .await;
        assert_eq!(replay.status, Status::Ok);
        assert!(replay.body.is_empty());

        drop(retry);
        timeout(TEST_TIMEOUT, retry_task).await.unwrap().unwrap();
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn core_shutdown_deadline_ends_native_drain_and_starts_common_cleanup() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut client, codec, _, server_task) =
            start_registered_session(state.clone(), &[]).await;
        write_request(
            &mut client,
            &codec,
            family::CORE,
            yas_wire::core::request_kind::SHUTDOWN,
            30,
            &Shutdown {
                operation_id: [0x51; 16],
                grace_ns: 100_000_000,
                reason: "short drain".to_owned(),
            },
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::CORE,
                yas_wire::core::request_kind::SHUTDOWN,
                30,
            )
            .await
            .status,
            Status::Ok
        );
        let goaway = next_goaway(&mut client, &codec).await;
        assert!(goaway.close_deadline_server_ns >= monotonic_ns());

        timeout(TEST_TIMEOUT, server_task)
            .await
            .expect("native session ends at its Core deadline")
            .unwrap();
        timeout(TEST_TIMEOUT, async {
            while !state.connections.cleanup_started.load(Ordering::Acquire) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("deadline enters common server cleanup");
        assert!(state.connections.is_shutting_down());
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn retained_upload_bytes_share_one_cross_family_budget() {
        const SELECTION_BYTES: usize = 13 * 1024 * 1024;
        const KV_BYTES: u64 = 4 * 1024 * 1024;

        let mut services = test_services(None, unavailable_connector(), None);
        services.selection = Some(SelectionStore::new());
        let (mut client, codec, _, server_task) =
            start_session(services, &[family::TRANSFER, family::SELECTION, family::KV]).await;

        let selection_bytes = vec![0x5a; SELECTION_BYTES];
        write_request(
            &mut client,
            &codec,
            family::SELECTION,
            yas_wire::schema::selection::request::SET_BEGIN,
            10,
            &yas_selection::SetBegin {
                slot: yas_wire::schema::selection::SLOT_CLIPBOARD as u8,
                operation_id: [0x61; 16],
                items: vec![yas_selection::UploadItem {
                    mime: "application/octet-stream".to_owned(),
                    byte_len: SELECTION_BYTES as u64,
                    content_hash: *blake3::hash(&selection_bytes).as_bytes(),
                    initial_receive_credit: SELECTION_BYTES as u64,
                }],
                extensions: Extensions::default(),
            },
        )
        .await;
        let begin = next_sensitive_result(
            &mut client,
            &codec,
            family::SELECTION,
            yas_wire::schema::selection::request::SET_BEGIN,
            10,
        )
        .await;
        assert_eq!(begin.status, Status::Ok);
        let begin = yas_selection::SetBeginResult::decode(&begin.body).unwrap();
        let selection_transfer = begin.descriptors[0].transfer_id;
        let mut offset = 0u64;
        for chunk in selection_bytes.chunks(TRANSFER_CHUNK) {
            write_sensitive_transfer_event(
                &mut client,
                &codec,
                yas_wire::schema::transfer::event::BYTE_DATA,
                &ByteData {
                    transfer_id: selection_transfer,
                    offset,
                    data: chunk.to_vec(),
                },
            )
            .await;
            offset += chunk.len() as u64;
        }
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::CLOSE,
            &Close {
                transfer_id: selection_transfer,
                final_data_bytes: SELECTION_BYTES as u64,
                status: Status::Ok.code(),
                detail: Vec::new(),
            },
        )
        .await;

        let kv_stage = yas_kv::StageValue {
            byte_len: KV_BYTES,
            content_hash: [0x22; 32],
            extensions: Extensions::default(),
        };
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::STAGE_VALUE,
            11,
            &kv_stage,
        )
        .await;
        assert_eq!(
            next_sensitive_result(
                &mut client,
                &codec,
                family::KV,
                yas_wire::schema::kv::request::STAGE_VALUE,
                11,
            )
            .await
            .status,
            Status::ResourceExhausted,
        );

        // RESET retires the uncommitted Selection stage and releases its
        // retained reservation, so another family's stage can be admitted.
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::RESET,
            &Reset {
                transfer_id: selection_transfer,
                status: Status::Cancelled.code(),
                detail: Vec::new(),
            },
        )
        .await;
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::STAGE_VALUE,
            12,
            &kv_stage,
        )
        .await;
        let admitted = next_sensitive_result(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::STAGE_VALUE,
            12,
        )
        .await;
        assert_eq!(admitted.status, Status::Ok);
        let admitted = yas_kv::StageValueResult::decode(&admitted.body).unwrap();
        write_sensitive_transfer_event(
            &mut client,
            &codec,
            yas_wire::schema::transfer::event::RESET,
            &Reset {
                transfer_id: admitted.transfer.transfer_id,
                status: Status::Cancelled.code(),
                detail: Vec::new(),
            },
        )
        .await;

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[tokio::test]
    async fn ordinary_inbound_frames_backpressure_on_decoded_byte_budget() {
        let codec = FrameCodec::new(FrameLimits::recommended(), []).unwrap();
        let ping = Ping {
            sender_monotonic_ns: 7,
        }
        .encode()
        .unwrap();
        let first_frame = Frame {
            header: FrameHeader::request(family::CORE, yas_wire::core::request_kind::PING, 10),
            payload: ping.clone(),
        };
        let second_frame = Frame {
            header: FrameHeader::request(family::CORE, yas_wire::core::request_kind::PING, 11),
            payload: ping,
        };
        let decoded_len = (first_frame.header.encoded_len() + first_frame.payload.len()) as u64;
        let encoded = [
            codec.encode_stream(&first_frame).unwrap(),
            codec.encode_stream(&second_frame).unwrap(),
        ]
        .concat();
        let (mut writer, mut reader) = tokio::io::duplex(4096);
        writer.write_all(&encoded).await.unwrap();

        let budget = Arc::new(CreditBudget::new(decoded_len));
        let transfers = Arc::new(InboundTransferRegistry::new());
        let cancellation = ConnectionCancellation::default();
        let first = read_frame_budgeted(&mut reader, &codec, &budget, &transfers, &cancellation)
            .await
            .unwrap()
            .unwrap();
        let task = tokio::spawn({
            let codec = codec.clone();
            let budget = Arc::clone(&budget);
            let transfers = Arc::clone(&transfers);
            let cancellation = cancellation.clone();
            async move {
                read_frame_budgeted(&mut reader, &codec, &budget, &transfers, &cancellation).await
            }
        });
        let mut task = Box::pin(task);
        assert!(timeout(Duration::from_millis(25), &mut task).await.is_err());
        drop(first);
        let second = timeout(TEST_TIMEOUT, &mut task)
            .await
            .unwrap()
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(second.frame.header.request_id, Some(11));
    }

    #[tokio::test]
    async fn pipelined_transfer_data_waits_for_descriptor_registration() {
        let codec = FrameCodec::new(FrameLimits::recommended(), []).unwrap();
        let data = ByteData {
            transfer_id: 2,
            offset: 0,
            data: vec![0x5a; 64],
        };
        let frame = Frame {
            header: FrameHeader::event(
                family::TRANSFER,
                yas_wire::schema::transfer::event::BYTE_DATA,
            ),
            payload: data.encode().unwrap(),
        };
        let decoded_len = (frame.header.encoded_len() + frame.payload.len()) as u64;
        let (mut writer, mut reader) = tokio::io::duplex(4096);
        writer
            .write_all(&codec.encode_stream(&frame).unwrap())
            .await
            .unwrap();

        let budget = Arc::new(CreditBudget::new(decoded_len));
        let reserved_flow = budget.lease(decoded_len);
        let transfers = Arc::new(InboundTransferRegistry::new());
        let cancellation = ConnectionCancellation::default();
        let task = tokio::spawn({
            let codec = codec.clone();
            let budget = Arc::clone(&budget);
            let transfers = Arc::clone(&transfers);
            let cancellation = cancellation.clone();
            async move {
                read_frame_budgeted(&mut reader, &codec, &budget, &transfers, &cancellation).await
            }
        });
        let mut task = Box::pin(task);
        assert!(timeout(Duration::from_millis(25), &mut task).await.is_err());
        transfers.replace(BTreeSet::from([data.transfer_id]));
        let queued = timeout(TEST_TIMEOUT, &mut task)
            .await
            .unwrap()
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(queued.frame.payload, frame.payload);
        assert!(queued._credit.is_none());
        drop(reserved_flow);
    }

    #[tokio::test]
    async fn compressed_transfer_data_is_rejected_before_decoded_allocation() {
        let codec =
            FrameCodec::new(FrameLimits::recommended(), [yas_wire::frame::LZ4_CODEC]).unwrap();
        // Encode an otherwise legal compressed frame, then mutate its clear
        // header as a malicious peer could. The public codec deliberately
        // refuses to construct compressed Transfer DATA itself.
        let mut header = FrameHeader::event(family::CORE, u16::MAX);
        header.compressed = true;
        let frame = Frame {
            header,
            payload: ByteData {
                transfer_id: 2,
                offset: 0,
                data: vec![0x5a; 4096],
            }
            .encode()
            .unwrap(),
        };
        let (mut writer, mut reader) = tokio::io::duplex(4096);
        let mut encoded = codec.encode_stream(&frame).unwrap();
        encoded[4..6].copy_from_slice(&family::TRANSFER.to_le_bytes());
        encoded[6..8].copy_from_slice(&yas_wire::schema::transfer::event::BYTE_DATA.to_le_bytes());
        writer.write_all(&encoded).await.unwrap();
        let budget = Arc::new(CreditBudget::new(8192));
        let transfers = Arc::new(InboundTransferRegistry::new());
        let cancellation = ConnectionCancellation::default();
        let error = match read_frame_budgeted(
            &mut reader,
            &codec,
            &budget,
            &transfers,
            &cancellation,
        )
        .await
        {
            Err(error) => error,
            Ok(_) => panic!("compressed Transfer DATA was accepted"),
        };
        assert_eq!(error.kind(), io::ErrorKind::InvalidData);
        assert_eq!(budget.reserved.load(Ordering::Acquire), 0);
    }

    struct TestOutbound {
        sender: FrameSender,
        receivers: OutboundReceivers,
        urgent_budget: Arc<CreditBudget>,
        control_budget: Arc<CreditBudget>,
        data_budget: Arc<CreditBudget>,
    }

    fn test_outbound(urgent_max: u64, control_max: u64, data_max: u64) -> TestOutbound {
        let urgent_budget = Arc::new(CreditBudget::new(urgent_max));
        let control_budget = Arc::new(CreditBudget::new(control_max));
        let data_budget = Arc::new(CreditBudget::new(data_max));
        let (urgent_tx, urgent_rx) = mpsc::channel(OUTBOUND_URGENT_QUEUE);
        let (control_tx, control_rx) = mpsc::channel(OUTBOUND_CONTROL_QUEUE);
        let (data_tx, data_rx) = mpsc::channel(OUTBOUND_DATA_QUEUE);
        let sender = FrameSender::with_lanes(
            urgent_tx,
            Arc::clone(&urgent_budget),
            control_tx,
            Arc::clone(&control_budget),
            data_tx,
            Arc::clone(&data_budget),
        );
        TestOutbound {
            sender,
            receivers: OutboundReceivers::new(urgent_rx, control_rx, data_rx),
            urgent_budget,
            control_budget,
            data_budget,
        }
    }

    fn decoded_len(frame: &Frame) -> u64 {
        (frame.header.encoded_len() + frame.payload.len()) as u64
    }

    fn data_frame(transfer_id: u32, marker: u8, bytes: usize) -> Frame {
        Frame {
            header: FrameHeader::event(
                family::TRANSFER,
                yas_wire::schema::transfer::event::BYTE_DATA,
            ),
            payload: ByteData {
                transfer_id,
                offset: 0,
                data: vec![marker; bytes],
            }
            .encode()
            .unwrap(),
        }
    }

    fn control_result(family_id: u16, request_id: u32, marker: u8) -> Frame {
        Frame {
            header: FrameHeader::result(family_id, 1, request_id),
            payload: vec![marker],
        }
    }

    fn urgent_goaway(marker: u8) -> Frame {
        Frame {
            header: FrameHeader::event(family::CORE, yas_wire::core::event_kind::GOAWAY),
            payload: vec![marker],
        }
    }

    async fn wait_for_queued(
        receivers: &OutboundReceivers,
        urgent: usize,
        control: usize,
        data: usize,
    ) {
        timeout(TEST_TIMEOUT, async {
            while receivers.urgent.len() != urgent
                || receivers.control.len() != control
                || receivers.data.len() != data
            {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("outbound frames entered their lanes");
    }

    #[test]
    fn terminal_frame_fragmentation_uses_the_canonical_logical_boundary() {
        let bulk = yas_wire::frame::HARD_MAX_BULK_CHUNK as usize;
        let terminal_frame = |grid_len| yas_terminal::TerminalFrame {
            view_id: 7,
            frame_sequence: 11,
            frame_flags: yas_wire::schema::terminal::FRAME_CURSOR as u16,
            base_sequence: None,
            grid_payload: vec![0x5a; grid_len],
        };

        // The logical body is flags + grid. Exactly one canonical bulk chunk
        // remains an ordinary FRAME when the peer's wire frame admits it.
        let exact = terminal_frame(bulk - 2);
        assert_eq!(exact.encode_logical_body().unwrap().len(), bulk);
        let encoded =
            encode_terminal_frame_wire_events(&exact, SERVER_MAX_FRAME, SERVER_MAX_DECODED)
                .unwrap();
        assert_eq!(encoded.len(), 1);
        assert_eq!(encoded[0].0, yas_wire::schema::terminal::event::FRAME);
        assert_eq!(
            yas_terminal::TerminalFrame::decode(&encoded[0].1).unwrap(),
            exact,
        );

        // One byte beyond the logical boundary is fragmented even though its
        // grid alone still fits the ordinary FRAME codec's 64 KiB field cap.
        let fragmented = terminal_frame(bulk - 1);
        let logical = fragmented.encode_logical_body().unwrap();
        assert_eq!(logical.len(), bulk + 1);
        let encoded =
            encode_terminal_frame_wire_events(&fragmented, SERVER_MAX_FRAME, SERVER_MAX_DECODED)
                .unwrap();
        assert_eq!(encoded.len(), 2);
        let chunks = encoded
            .iter()
            .map(|(kind, payload)| {
                assert_eq!(*kind, yas_wire::schema::terminal::event::FRAME_CHUNK);
                yas_terminal::FrameChunk::decode(payload).unwrap()
            })
            .collect::<Vec<_>>();
        assert_eq!(chunks[0].chunk.len(), bulk);
        assert_eq!(chunks[1].chunk.len(), 1);
        assert_eq!(chunks[0].chunk_count, 2);
        assert_eq!(chunks[1].chunk_index, 1);
        assert_eq!(chunks[0].logical_frame_len, (bulk + 1) as u32);
        assert_eq!(
            chunks
                .iter()
                .flat_map(|chunk| chunk.chunk.iter().copied())
                .collect::<Vec<_>>(),
            logical,
        );

        // Real browser-sized keyframes can also exceed the ordinary FRAME
        // field cap itself. Fragmentation must not call that encoder first.
        let large_grid = terminal_frame(bulk + 1);
        assert!(large_grid.encode().is_err());
        let large_logical = large_grid.encode_logical_body().unwrap();
        let encoded =
            encode_terminal_frame_wire_events(&large_grid, SERVER_MAX_FRAME, SERVER_MAX_DECODED)
                .unwrap();
        assert_eq!(encoded.len(), 2);
        assert!(
            encoded
                .iter()
                .all(|(kind, _)| { *kind == yas_wire::schema::terminal::event::FRAME_CHUNK })
        );
        assert_eq!(
            encoded
                .iter()
                .flat_map(|(_, payload)| {
                    yas_terminal::FrameChunk::decode(payload).unwrap().chunk
                })
                .collect::<Vec<_>>(),
            large_logical,
        );

        // A logical frame larger than the view's advertised encoded limit is
        // rejected before any wire Event can be admitted.
        assert!(
            encode_terminal_frame_wire_events(
                &fragmented,
                yas_wire::frame::HARD_MAX_BULK_CHUNK,
                yas_wire::frame::HARD_MAX_BULK_CHUNK,
            )
            .is_err()
        );
    }

