    #[test]
    fn outbound_classifier_covers_every_generated_family_and_kind() {
        let expected_data = BTreeSet::from([
            (
                family::TRANSFER,
                yas_wire::schema::transfer::event::BYTE_DATA,
            ),
            (
                family::TRANSFER,
                yas_wire::schema::transfer::event::MESSAGE_DATA,
            ),
            (family::TRANSFER, yas_wire::schema::transfer::event::CLOSE),
            (family::TRANSFER, yas_wire::schema::transfer::event::RESET),
            (family::TERMINAL, yas_wire::schema::terminal::event::FRAME),
            (
                family::TERMINAL,
                yas_wire::schema::terminal::event::FRAME_CHUNK,
            ),
            (family::SURFACE, yas_wire::schema::surface::event::FRAME),
            (family::MEDIA, yas_media::event_kind::FRAME),
            (family::MEDIA, yas_media::event_kind::STREAM_STATUS),
            (family::EVENTS, yas_wire::schema::events::event::RECORD),
            (family::EVENTS, yas_wire::schema::events::event::GAP),
            (
                family::EVENTS,
                yas_wire::schema::events::event::STREAM_STOPPED,
            ),
            (family::NET, yas_wire::schema::net::event::DATAGRAM),
            (family::NET, yas_wire::schema::net::event::DATAGRAM_STATS),
        ]);
        let mut seen_data = BTreeSet::new();
        let mut seen_urgent = false;

        for family_metadata in yas_wire::schema::FAMILIES {
            for operation in family_metadata.operations {
                let class = match operation.class {
                    value if value == yas_wire::schema::transport::class::EVENT => Class::Event,
                    value if value == yas_wire::schema::transport::class::REQUEST => Class::Request,
                    value => panic!("unexpected generated operation class {value}"),
                };
                let frame = Frame {
                    header: match class {
                        Class::Event => FrameHeader::event(family_metadata.id, operation.kind),
                        Class::Request => {
                            FrameHeader::request(family_metadata.id, operation.kind, 1)
                        }
                        Class::Result => unreachable!(),
                    },
                    payload: Vec::new(),
                };
                let expected = if class == Class::Event
                    && family_metadata.id == family::CORE
                    && operation.kind == yas_wire::core::event_kind::GOAWAY
                {
                    seen_urgent = true;
                    OutboundClass::Urgent
                } else if class == Class::Event
                    && expected_data.contains(&(family_metadata.id, operation.kind))
                {
                    seen_data.insert((family_metadata.id, operation.kind));
                    OutboundClass::Data
                } else {
                    OutboundClass::Control
                };
                assert_eq!(
                    classify_outbound(&frame),
                    expected,
                    "{}.{}",
                    family_metadata.name,
                    operation.name
                );

                if class == Class::Request {
                    let result = Frame {
                        header: FrameHeader::result(family_metadata.id, operation.kind, 1),
                        payload: Vec::new(),
                    };
                    assert_eq!(classify_outbound(&result), OutboundClass::Control);
                }
            }
        }
        assert!(seen_urgent, "generated Core GOAWAY was classified");
        assert_eq!(seen_data, expected_data);
        assert_eq!(
            classify_outbound(&Frame {
                header: FrameHeader::event(u16::MAX, u16::MAX),
                payload: Vec::new(),
            }),
            OutboundClass::Control,
            "unknown Events default to control"
        );
    }

    #[tokio::test]
    async fn transfer_terminators_cannot_overtake_causally_prior_data() {
        let transfer_id = 0x44;
        let message = Frame {
            header: FrameHeader::event(
                family::TRANSFER,
                yas_wire::schema::transfer::event::MESSAGE_DATA,
            ),
            payload: MessageData {
                transfer_id,
                sequence: 0,
                fragment_offset: 0,
                start: true,
                end: true,
                data: b"yas".to_vec(),
            }
            .encode()
            .unwrap(),
        };
        let close = Frame {
            header: FrameHeader::event(family::TRANSFER, yas_wire::schema::transfer::event::CLOSE),
            payload: Close {
                transfer_id,
                final_data_bytes: 3,
                status: Status::Ok.code(),
                detail: Vec::new(),
            }
            .encode()
            .unwrap(),
        };
        let reset = Frame {
            header: FrameHeader::event(family::TRANSFER, yas_wire::schema::transfer::event::RESET),
            payload: Reset {
                transfer_id: transfer_id + 1,
                status: Status::Cancelled.code(),
                detail: Vec::new(),
            }
            .encode()
            .unwrap(),
        };
        let mut outbound = test_outbound(1024, 1024, 4096);
        outbound.sender.send(message).await.unwrap();
        outbound.sender.send(close).await.unwrap();
        outbound.sender.send(reset).await.unwrap();
        outbound
            .sender
            .send(control_result(family::CORE, 1, 0xc0))
            .await
            .unwrap();

        let cancellation = ConnectionCancellation::default();
        let control = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(classify_outbound(&control.frame), OutboundClass::Control);
        let message = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(
            message.frame.header.kind,
            yas_wire::schema::transfer::event::MESSAGE_DATA,
        );
        let close = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(
            close.frame.header.kind,
            yas_wire::schema::transfer::event::CLOSE,
        );
        let reset = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(
            reset.frame.header.kind,
            yas_wire::schema::transfer::event::RESET,
        );
    }

