    #[tokio::test]
    async fn media_latest_reliable_receipt_covers_prior_frames_before_close_control() {
        let mut outbound = test_outbound(1024, 1024, 4096);
        let mut header = FrameHeader::event(family::MEDIA, yas_media::event_kind::FRAME);
        header.sensitive = true;
        let first = Frame {
            header,
            payload: vec![1],
        };
        let second = Frame {
            header,
            payload: vec![2],
        };
        let (first_written, first_receipt) = oneshot::channel();
        let (second_written, second_receipt) = oneshot::channel();
        outbound
            .sender
            .send_queued(first, Some(first_written))
            .await
            .unwrap();
        outbound
            .sender
            .send_queued(second, Some(second_written))
            .await
            .unwrap();
        // Replacing the stream's stored receipt drops the older receiver.
        // Data-lane FIFO makes the newest write cover every earlier frame.
        drop(first_receipt);
        let close = tokio::spawn({
            let sender = outbound.sender.clone();
            async move {
                second_receipt.await.unwrap();
                sender.send(control_result(family::MEDIA, 7, 0xc0)).await
            }
        });
        wait_for_queued(&outbound.receivers, 0, 0, 2).await;
        assert!(!close.is_finished());

        let cancellation = ConnectionCancellation::default();
        let mut first = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(classify_outbound(&first.frame), OutboundClass::Data);
        assert_eq!(first.frame.payload, [1]);
        let _ = first
            .written
            .take()
            .expect("first Media write receipt")
            .send(());
        assert!(!close.is_finished());

        let mut second = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(classify_outbound(&second.frame), OutboundClass::Data);
        assert_eq!(second.frame.payload, [2]);
        second
            .written
            .take()
            .expect("latest Media write receipt")
            .send(())
            .unwrap();
        timeout(TEST_TIMEOUT, close)
            .await
            .unwrap()
            .unwrap()
            .unwrap();

        let close = outbound.receivers.recv(&cancellation).await.unwrap();
        assert_eq!(classify_outbound(&close.frame), OutboundClass::Control);
        assert_eq!(close.frame.payload, [0xc0]);
    }

