    #[tokio::test]
    async fn outbound_frames_hold_local_queue_bytes_until_writer_drain() {
        let frame = data_frame(2, 0x5a, 1024);
        let frame_len = decoded_len(&frame);
        let mut outbound = test_outbound(1024, 1024, frame_len);
        outbound.sender.send(frame.clone()).await.unwrap();
        let queued = outbound.receivers.data.recv().await.unwrap();

        let task = tokio::spawn({
            let sender = outbound.sender.clone();
            async move { sender.send(frame).await }
        });
        let mut task = Box::pin(task);
        assert!(timeout(Duration::from_millis(25), &mut task).await.is_err());
        drop(queued);
        timeout(TEST_TIMEOUT, &mut task)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(
            outbound.data_budget.reserved.load(Ordering::Acquire),
            frame_len
        );
        drop(outbound.receivers.data.recv().await.unwrap());
        assert_eq!(outbound.data_budget.reserved.load(Ordering::Acquire), 0);
    }

    #[tokio::test]
    async fn family_controls_bypass_saturated_relay_and_font_transfer_data() {
        // Relay and Font payloads both use ordinary Transfer DATA on this
        // boundary, so distinct transfer IDs model their simultaneously full
        // producer windows.
        let relay_data = data_frame(2, 0x52, 1024);
        let font_data = data_frame(4, 0x46, 1024);
        let data_max = decoded_len(&relay_data) + decoded_len(&font_data);
        let mut outbound = test_outbound(1024, 4096, data_max);
        outbound.sender.send(relay_data.clone()).await.unwrap();
        outbound.sender.send(font_data.clone()).await.unwrap();
        assert!(matches!(
            outbound.sender.try_send(data_frame(6, 0x58, 1)),
            Err(mpsc::error::TrySendError::Full(_))
        ));

        let controls = [
            control_result(family::CORE, 1, 0x00),
            control_result(family::TERMINAL, 2, 0x10),
            control_result(family::SURFACE, 3, 0x20),
            control_result(family::MEDIA, 4, 0x23),
            control_result(family::NET, 5, 0x41),
        ];
        for frame in controls {
            outbound.sender.send(frame).await.unwrap();
        }

        let cancellation = ConnectionCancellation::default();
        for expected in [0x00, 0x10, 0x20, 0x23, 0x41] {
            let queued = outbound.receivers.recv(&cancellation).await.unwrap();
            assert_eq!(classify_outbound(&queued.frame), OutboundClass::Control);
            assert_eq!(queued.frame.payload, [expected]);
            drop(queued);
        }
        for expected in [0x52, 0x46] {
            let queued = outbound.receivers.recv(&cancellation).await.unwrap();
            assert_eq!(classify_outbound(&queued.frame), OutboundClass::Data);
            assert_eq!(
                ByteData::decode(&queued.frame.payload).unwrap().data[0],
                expected
            );
            drop(queued);
        }
        assert_eq!(outbound.control_budget.reserved.load(Ordering::Acquire), 0);
        assert_eq!(outbound.data_budget.reserved.load(Ordering::Acquire), 0);
    }

