    #[test]
    fn kv_stage_replay_metadata_covers_recent_anchor_and_restaged_handles() {
        static NEXT_OPERATION: AtomicU64 = AtomicU64::new(1);

        let mut stages = KvConsumedStages::default();
        for handle in 1..=super::super::kv::MAX_RECENT_OPERATION_REPLAYS as u64 + 1 {
            stages.insert(
                handle,
                KvConsumedStage {
                    byte_len: handle,
                    content_hash: [handle as u8; 32],
                },
            );
        }
        assert_eq!(stages.len(), super::super::kv::MAX_RECENT_OPERATION_REPLAYS,);
        assert!(stages.get(&1).is_none(), "oldest tombstone is evicted");
        assert_eq!(
            stages.get(&2).map(|stage| stage.byte_len),
            Some(2),
            "recent replay metadata remains available",
        );
        let newest = super::super::kv::MAX_RECENT_OPERATION_REPLAYS as u64 + 1;
        assert_eq!(
            stages.get(&newest).map(|stage| stage.content_hash),
            Some([newest as u8; 32]),
        );

        fn staged_put(handle: u64) -> Vec<yas_kv::Mutation> {
            vec![yas_kv::Mutation::Put {
                relative_key: b"key".to_vec(),
                precondition: yas_kv::Precondition::Any,
                value: yas_kv::ValueSource::Staged(handle),
                extensions: Extensions::default(),
            }]
        }

        let metadata = KvConsumedStage {
            byte_len: 19,
            content_hash: [0x5a; 32],
        };
        let mut recent = KvRuntime::new(false);
        recent.consumed_stages.insert(7, metadata);
        let from_recent = kv_operation_fingerprint(
            yas_kv::request_kind::PUT,
            false,
            b"scope/",
            &Extensions::default(),
            &staged_put(7),
            &recent,
            &[],
        )
        .unwrap();

        let evicted = KvRuntime::new(false);
        let from_anchor = kv_operation_fingerprint(
            yas_kv::request_kind::PUT,
            false,
            b"scope/",
            &Extensions::default(),
            &staged_put(7),
            &evicted,
            &[super::super::kv::NativeStageWitness {
                ordinal: 0,
                original_handle: 7,
                byte_len: metadata.byte_len,
                content_hash: metadata.content_hash,
            }],
        )
        .unwrap();

        let mut restaged = KvRuntime::new(false);
        restaged.consumed_stages.insert(8, metadata);
        let from_fresh_handle = kv_operation_fingerprint(
            yas_kv::request_kind::PUT,
            false,
            b"scope/",
            &Extensions::default(),
            &staged_put(8),
            &restaged,
            &[],
        )
        .unwrap();
        assert_eq!(from_recent, from_anchor);
        assert_eq!(from_recent, from_fresh_handle);

        // Persist the staged witness with a live-entry anchor, then prove a
        // retry still reaches the exact replay after the per-session recent
        // tombstone is absent.
        let serial = NEXT_OPERATION.fetch_add(1, Ordering::Relaxed);
        let mut operation_id = [0x4b; 16];
        operation_id[..8].copy_from_slice(&serial.to_le_bytes());
        let key = format!("yas.kv.stage-witness/{serial:x}").into_bytes();
        let value = Arc::new(vec![0x5a; metadata.byte_len as usize]);
        super::super::kv::native_mutate(
            operation_id,
            from_recent,
            false,
            vec![super::super::kv::NativeStageWitness {
                ordinal: 0,
                original_handle: 7,
                byte_len: metadata.byte_len,
                content_hash: metadata.content_hash,
            }],
            vec![super::super::kv::NativeMutation::Put {
                key,
                precondition: yas_kv::Precondition::Any,
                value,
                content_hash: metadata.content_hash,
            }],
        )
        .unwrap();
        let persisted = super::super::kv::native_stage_witnesses(operation_id).unwrap();
        let after_tombstone_eviction = kv_operation_fingerprint(
            yas_kv::request_kind::PUT,
            false,
            b"scope/",
            &Extensions::default(),
            &staged_put(7),
            &KvRuntime::new(false),
            &persisted,
        )
        .unwrap();
        assert_eq!(after_tombstone_eviction, from_recent);
        assert!(
            super::super::kv::native_replay(operation_id, after_tombstone_eviction)
                .unwrap()
                .is_some(),
        );

        assert_eq!(
            kv_operation_fingerprint(
                yas_kv::request_kind::PUT,
                false,
                b"scope/",
                &Extensions::default(),
                &staged_put(8),
                &KvRuntime::new(false),
                &persisted,
            ),
            Err(Status::NotFound),
            "a witness is scoped to its original consumed handle and ordinal",
        );
        let mut changed = staged_put(7);
        let yas_kv::Mutation::Put { relative_key, .. } = &mut changed[0] else {
            unreachable!();
        };
        *relative_key = b"different".to_vec();
        let changed = kv_operation_fingerprint(
            yas_kv::request_kind::PUT,
            false,
            b"scope/",
            &Extensions::default(),
            &changed,
            &KvRuntime::new(false),
            &persisted,
        )
        .unwrap();
        assert_ne!(changed, from_recent);
        assert!(matches!(
            super::super::kv::native_replay(operation_id, changed),
            Err(super::super::kv::NativeMutationError::OperationConflict),
        ));
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn state_watch_limit_scales_with_peer_receive_authority_and_is_bounded() {
        static NEXT_PREFIX: AtomicU64 = AtomicU64::new(1);
        let serial = NEXT_PREFIX.fetch_add(1, Ordering::Relaxed);
        let mut prefix = vec![0xfd];
        prefix.extend_from_slice(
            format!("yas-watch-limit-{}-{serial}/", std::process::id()).as_bytes(),
        );

        let services = test_services(None, unavailable_connector(), None);
        let (mut client, codec, _, server_task) = start_session(services, &[family::KV]).await;
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::OPEN,
            200,
            &yas_kv::Open {
                prefix,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (opened, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::OPEN,
            200,
        )
        .await;
        assert!(state.is_empty());
        assert_eq!(opened.status, Status::Ok);
        let opened = yas_kv::OpenResult::decode(&opened.body).unwrap();

        let watch_limit = watch_limit_for_peer(TEST_PEER_MAX_BUFFERED);
        assert!(watch_limit > BASE_WATCH_LIMIT);
        for index in 0..watch_limit {
            let request_id = 201 + u32::try_from(index).unwrap();
            write_request(
                &mut client,
                &codec,
                family::KV,
                yas_wire::schema::kv::request::WATCH,
                request_id,
                &yas_kv::Watch {
                    namespace_handle: opened.namespace_handle,
                    inline_max: yas_kv::MAX_INLINE_BYTES as u32,
                    state: Watch {
                        initial_credit: 64 * 1024,
                        resume: None,
                        extensions: Extensions::default(),
                    },
                },
            )
            .await;
            let (result, pending) = next_kv_result_collecting_state(
                &mut client,
                &codec,
                yas_wire::schema::kv::request::WATCH,
                request_id,
            )
            .await;
            assert_eq!(result.status, Status::Ok, "watch {index} was refused");
            let watched = WatchResult::decode(&result.body).unwrap();
            let mut snapshot_ended = pending.iter().any(|event| {
                event.subscription_id == watched.subscription_id
                    && event.phase == Phase::SnapshotEnd
            });
            while !snapshot_ended {
                let frame = next_frame(&mut client, &codec).await;
                assert_eq!(frame.header.family, family::KV);
                assert_eq!(frame.header.kind, yas_wire::schema::kv::event::STATE);
                let event = StateEvent::decode(&frame.payload).unwrap();
                snapshot_ended = event.subscription_id == watched.subscription_id
                    && event.phase == Phase::SnapshotEnd;
            }
        }

        let request_id = 201 + u32::try_from(watch_limit).unwrap();
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::WATCH,
            request_id,
            &yas_kv::Watch {
                namespace_handle: opened.namespace_handle,
                inline_max: yas_kv::MAX_INLINE_BYTES as u32,
                state: Watch {
                    initial_credit: 64 * 1024,
                    resume: None,
                    extensions: Extensions::default(),
                },
            },
        )
        .await;
        let (refused, _) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::WATCH,
            request_id,
        )
        .await;
        assert_eq!(refused.status, Status::ResourceExhausted);

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn kv_native_watch_cas_staging_transfer_and_atomic_batch() {
        static NEXT_PREFIX: AtomicU64 = AtomicU64::new(1);
        let serial = NEXT_PREFIX.fetch_add(1, Ordering::Relaxed);
        let mut prefix = vec![0xff];
        prefix.extend_from_slice(format!("yas-kv-{}-{serial}/", std::process::id()).as_bytes());

        let services = test_services(None, unavailable_connector(), None);
        let (mut client, codec, hello, server_task) =
            start_session(services, &[family::TRANSFER, family::KV]).await;
        let descriptor = hello
            .families
            .iter()
            .find(|descriptor| descriptor.family_id == family::KV)
            .expect("KV negotiated");
        assert_eq!(descriptor.runtime_state, RuntimeState::Available);
        assert_eq!(
            yas_kv::Limits::from_extensions(&descriptor.limits).unwrap(),
            super::super::kv::native_limits(),
        );

        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::OPEN,
            100,
            &yas_kv::Open {
                prefix: prefix.clone(),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (opened, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::OPEN,
            100,
        )
        .await;
        assert!(state.is_empty());
        assert_eq!(opened.status, Status::Ok);
        let opened = yas_kv::OpenResult::decode(&opened.body).unwrap();

        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::WATCH,
            101,
            &yas_kv::Watch {
                namespace_handle: opened.namespace_handle,
                inline_max: yas_kv::MAX_INLINE_BYTES as u32,
                state: Watch {
                    initial_credit: 4 * 1024 * 1024,
                    resume: None,
                    extensions: Extensions::default(),
                },
            },
        )
        .await;
        let (watch, _) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::WATCH,
            101,
        )
        .await;
        assert_eq!(watch.status, Status::Ok);
        let watch = WatchResult::decode(&watch.body).unwrap();
        assert_ne!(watch.subscription_id, 0);
        let begin = next_frame(&mut client, &codec).await;
        assert!(begin.header.sensitive);
        assert_eq!(
            StateEvent::decode(&begin.payload).unwrap().phase,
            Phase::SnapshotBegin
        );
        let end = next_frame(&mut client, &codec).await;
        assert!(end.header.sensitive);
        assert_eq!(
            StateEvent::decode(&end.payload).unwrap().phase,
            Phase::SnapshotEnd
        );

        let raw_key = vec![0xfe, b'k'];
        let inline = b"native-value".to_vec();
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::PUT,
            102,
            &yas_kv::Put {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x21; 16],
                durable: true,
                relative_key: raw_key.clone(),
                precondition: yas_kv::Precondition::Absent,
                value: yas_kv::ValueSource::Inline(inline.clone()),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (put, mut pending_state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::PUT,
            102,
        )
        .await;
        assert_eq!(put.status, Status::Ok);
        let put = yas_kv::MutationResult::decode(&put.body).unwrap();
        assert_eq!(put.status, Status::Ok);
        assert_eq!(put.content_hash, *blake3::hash(&inline).as_bytes());
        let delta = next_kv_delta(&mut client, &codec, &mut pending_state).await;
        assert_eq!(delta.records.len(), 1);
        assert_eq!(delta.records[0].kind, RecordKind::Add);
        let watched = yas_kv::entry_from_state_record(&delta.records[0]).unwrap();
        assert_eq!(watched.relative_key, raw_key);
        assert_eq!(watched.inline_value.as_deref(), Some(inline.as_slice()));

        // Lost-Result retry returns the exact committed outcome without a
        // second mutation or STATE delta. Reusing the operation ID with
        // different canonical arguments is a request-level conflict.
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::PUT,
            121,
            &yas_kv::Put {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x21; 16],
                durable: true,
                relative_key: vec![0xfe, b'k'],
                precondition: yas_kv::Precondition::Absent,
                value: yas_kv::ValueSource::Inline(inline.clone()),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (replayed, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::PUT,
            121,
        )
        .await;
        assert_no_kv_records(&state);
        assert_eq!(yas_kv::MutationResult::decode(&replayed.body).unwrap(), put);
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::PUT,
            122,
            &yas_kv::Put {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x21; 16],
                durable: true,
                relative_key: vec![0xfe, b'k'],
                precondition: yas_kv::Precondition::Any,
                value: yas_kv::ValueSource::Inline(b"different".to_vec()),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (operation_conflict, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::PUT,
            122,
        )
        .await;
        assert_no_kv_records(&state);
        assert_eq!(operation_conflict.status, Status::Conflict);
        assert!(operation_conflict.body.is_empty());

        // Stale CAS returns a typed conflict and changes neither value nor
        // store state.
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::PUT,
            103,
            &yas_kv::Put {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x22; 16],
                durable: false,
                relative_key: vec![0xfe, b'k'],
                precondition: yas_kv::Precondition::Hash([0; 32]),
                value: yas_kv::ValueSource::Inline(b"wrong".to_vec()),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (conflict, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::PUT,
            103,
        )
        .await;
        assert_no_kv_records(&state);
        let conflict = yas_kv::MutationResult::decode(&conflict.body).unwrap();
        assert_eq!(conflict.status, Status::Conflict);
        assert_eq!(conflict.content_hash, put.content_hash);

        // A conflict in the second item rolls the whole batch back, including
        // the otherwise-valid first item.
        let batch_key = b"batch-new".to_vec();
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::BATCH,
            104,
            &yas_kv::Batch {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x23; 16],
                durable: false,
                mutations: vec![
                    yas_kv::Mutation::Put {
                        relative_key: batch_key.clone(),
                        precondition: yas_kv::Precondition::Absent,
                        value: yas_kv::ValueSource::Inline(b"would-land".to_vec()),
                        extensions: Extensions::default(),
                    },
                    yas_kv::Mutation::Put {
                        relative_key: vec![0xfe, b'k'],
                        precondition: yas_kv::Precondition::Hash([0; 32]),
                        value: yas_kv::ValueSource::Inline(b"nope".to_vec()),
                        extensions: Extensions::default(),
                    },
                ],
                extensions: Extensions::default(),
            },
        )
        .await;
        let (batch, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::BATCH,
            104,
        )
        .await;
        assert_no_kv_records(&state);
        let batch = yas_kv::BatchResult::decode(&batch.body).unwrap();
        assert!(
            batch
                .results
                .iter()
                .all(|result| result.status == Status::Conflict)
        );
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::GET,
            105,
            &yas_kv::Get {
                namespace_handle: opened.namespace_handle,
                relative_key: batch_key,
                initial_receive_credit: 0,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (missing, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::GET,
            105,
        )
        .await;
        assert_no_kv_records(&state);
        assert_eq!(missing.status, Status::NotFound);

        let large = (0..(yas_kv::MAX_INLINE_BYTES + 4096))
            .map(|index| (index.wrapping_mul(31) & 0xff) as u8)
            .collect::<Vec<_>>();
        let large_hash = *blake3::hash(&large).as_bytes();
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::STAGE_VALUE,
            106,
            &yas_kv::StageValue {
                byte_len: large.len() as u64,
                content_hash: large_hash,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (stage, _) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::STAGE_VALUE,
            106,
        )
        .await;
        assert_eq!(stage.status, Status::Ok);
        let stage = yas_kv::StageValueResult::decode(&stage.body).unwrap();
        assert!(stage.transfer.sensitive_content().unwrap());
        assert_eq!(stage.transfer.receiver_send_credit, large.len() as u64);
        let mut offset = 0u64;
        for chunk in large.chunks(TRANSFER_CHUNK) {
            write_sensitive_transfer_event(
                &mut client,
                &codec,
                yas_wire::schema::transfer::event::BYTE_DATA,
                &ByteData {
                    transfer_id: stage.transfer.transfer_id,
                    offset,
                    data: chunk.to_vec(),
                },
            )
            .await;
            offset += chunk.len() as u64;
        }
        write_event(
            &mut client,
            &codec,
            family::TRANSFER,
            yas_wire::schema::transfer::event::CLOSE,
            &Close {
                transfer_id: stage.transfer.transfer_id,
                final_data_bytes: large.len() as u64,
                status: Status::Ok.code(),
                detail: Vec::new(),
            },
        )
        .await;
        let large_key = b"large".to_vec();
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::PUT,
            107,
            &yas_kv::Put {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x24; 16],
                durable: false,
                relative_key: large_key.clone(),
                precondition: yas_kv::Precondition::Absent,
                value: yas_kv::ValueSource::Staged(stage.staging_handle),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (stored, mut pending_state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::PUT,
            107,
        )
        .await;
        assert_eq!(
            yas_kv::MutationResult::decode(&stored.body)
                .unwrap()
                .content_hash,
            large_hash
        );
        let delta = next_kv_delta(&mut client, &codec, &mut pending_state).await;
        let entry = yas_kv::entry_from_state_record(&delta.records[0]).unwrap();
        assert_eq!(entry.relative_key, large_key);
        assert!(entry.inline_value.is_none());

        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::GET,
            108,
            &yas_kv::Get {
                namespace_handle: opened.namespace_handle,
                relative_key: b"large".to_vec(),
                initial_receive_credit: large.len() as u64,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (got, state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::GET,
            108,
        )
        .await;
        assert_no_kv_records(&state);
        let got = yas_kv::GetResult::decode(&got.body).unwrap();
        let Delivery::Transfer(transfer) = got.value.delivery else {
            panic!("large KV GET was not transferred");
        };
        assert!(transfer.sensitive_content().unwrap());
        let mut received = Vec::new();
        loop {
            let frame = next_frame(&mut client, &codec).await;
            assert_eq!(frame.header.family, family::TRANSFER);
            match frame.header.kind {
                yas_wire::schema::transfer::event::BYTE_DATA => {
                    assert!(frame.header.sensitive);
                    let data = ByteData::decode(&frame.payload).unwrap();
                    assert_eq!(data.transfer_id, transfer.transfer_id);
                    assert_eq!(data.offset, received.len() as u64);
                    received.extend_from_slice(&data.data);
                }
                yas_wire::schema::transfer::event::CLOSE => {
                    let close = Close::decode(&frame.payload).unwrap();
                    assert_eq!(close.transfer_id, transfer.transfer_id);
                    break;
                }
                kind => panic!("unexpected KV Transfer event {kind}"),
            }
        }
        assert_eq!(received, large);
        assert_eq!(*blake3::hash(&received).as_bytes(), got.value.content_hash);

        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::DELETE,
            109,
            &yas_kv::Delete {
                namespace_handle: opened.namespace_handle,
                operation_id: [0x25; 16],
                durable: false,
                relative_key: vec![0xfe, b'k'],
                precondition: yas_kv::Precondition::Hash(put.content_hash),
                extensions: Extensions::default(),
            },
        )
        .await;
        let (deleted, mut pending_state) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::DELETE,
            109,
        )
        .await;
        assert_eq!(deleted.status, Status::Ok);
        let delta = next_kv_delta(&mut client, &codec, &mut pending_state).await;
        assert_eq!(delta.records[0].kind, RecordKind::Remove);
        let removed = yas_kv::RemovedEntry::from_state_record(&delta.records[0]).unwrap();
        assert_eq!(removed.relative_key, vec![0xfe, b'k']);

        write_event(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::event::STATE_ACK,
            &StateAck {
                subscription_id: watch.subscription_id,
                applied_revision: delta.to_revision,
                cumulative_byte_limit: 8 * 1024 * 1024,
            },
        )
        .await;
        write_request(
            &mut client,
            &codec,
            family::KV,
            yas_wire::schema::kv::request::CLOSE,
            110,
            &yas_kv::Close {
                namespace_handle: opened.namespace_handle,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (closed, _) = next_kv_result_collecting_state(
            &mut client,
            &codec,
            yas_wire::schema::kv::request::CLOSE,
            110,
        )
        .await;
        assert_eq!(closed.status, Status::Ok);

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[tokio::test]
