    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn channel_item_limit_tracks_both_server_credit_clamps() {
        const LISTENER_INGRESS_AUTHORITY: u64 = 3 * 1024 * 1024;
        const CONNECTOR_EGRESS_AUTHORITY: u64 = 2 * 1024 * 1024;
        const PROPOSED_AUTHORITY: u64 = 4 * 1024 * 1024;

        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut listener, listener_codec, _, listener_task) =
            start_registered_session_with_receive(
                state.clone(),
                &[family::TRANSFER, family::CHANNEL],
                LISTENER_INGRESS_AUTHORITY + INBOUND_FLOW_HEADROOM,
            )
            .await;
        let (mut connector, connector_codec, _, connector_task) =
            start_registered_session_with_receive(
                state,
                &[family::TRANSFER, family::CHANNEL],
                CONNECTOR_EGRESS_AUTHORITY,
            )
            .await;

        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            10,
            &yas_channel::Listen {
                operation_id: [0x63; 16],
                name: "native.constrained".to_owned(),
                metadata: Vec::new(),
                extensions: Extensions::default(),
            },
        )
        .await;
        let listened = next_sensitive_result(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            10,
        )
        .await;
        assert_eq!(listened.status, Status::Ok);
        let identity = yas_channel::ListenerIdentity::decode(&listened.body).unwrap();

        write_request(
            &mut connector,
            &connector_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::CONNECT,
            20,
            &yas_channel::Connect {
                listener_handle: identity.listener_handle,
                generation: identity.generation,
                initial_receive_credit: PROPOSED_AUTHORITY,
                metadata: Vec::new(),
                extensions: Extensions::default(),
            },
        )
        .await;
        let connected = next_sensitive_result(
            &mut connector,
            &connector_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::CONNECT,
            20,
        )
        .await;
        assert_eq!(connected.status, Status::Ok);
        let connector_endpoint = yas_channel::ChannelEndpoint::decode(&connected.body).unwrap();
        assert_eq!(
            connector_endpoint.descriptor.sender_send_credit,
            CONNECTOR_EGRESS_AUTHORITY,
        );
        assert_eq!(
            connector_endpoint.descriptor.max_item_bytes,
            CONNECTOR_EGRESS_AUTHORITY,
        );

        let accept_frame = next_frame(&mut listener, &listener_codec).await;
        assert_eq!(
            accept_frame.header,
            FrameHeader {
                sensitive: true,
                ..FrameHeader::event(family::CHANNEL, yas_wire::schema::channel::event::ACCEPT)
            }
        );
        let accepted = yas_channel::Accept::decode(&accept_frame.payload).unwrap();
        assert_eq!(
            accepted.endpoint.descriptor.receiver_send_credit,
            CONNECTOR_EGRESS_AUTHORITY,
        );
        assert_eq!(
            accepted.endpoint.descriptor.max_item_bytes,
            CONNECTOR_EGRESS_AUTHORITY,
        );
        assert_eq!(
            accepted.endpoint.descriptor.max_item_bytes,
            connector_endpoint.descriptor.max_item_bytes,
        );

        drop(connector);
        drop(listener);
        timeout(TEST_TIMEOUT, connector_task)
            .await
            .unwrap()
            .unwrap();
        timeout(TEST_TIMEOUT, listener_task).await.unwrap().unwrap();
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn channel_two_sessions_watch_connect_exchange_and_cleanup() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let (mut listener, listener_codec, listener_hello, listener_task) =
            start_registered_session(state.clone(), &[family::TRANSFER, family::CHANNEL]).await;
        let (mut connector, connector_codec, connector_hello, connector_task) =
            start_registered_session(state, &[family::TRANSFER, family::CHANNEL]).await;
        for hello in [&listener_hello, &connector_hello] {
            let descriptor = hello
                .families
                .iter()
                .find(|descriptor| descriptor.family_id == family::CHANNEL)
                .expect("Channel negotiated");
            assert_eq!(descriptor.runtime_state, RuntimeState::Available);
            assert_eq!(
                yas_channel::Limits::from_extensions(&descriptor.limits).unwrap(),
                yas_channel::Limits {
                    max_mutation_replays: MAX_CHANNEL_OPERATION_REPLAYS as u32,
                    ..yas_channel::Limits::HARD
                },
            );
        }

        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::WATCH,
            10,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (watch, pending_state) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::WATCH,
            10,
        )
        .await;
        assert_eq!(watch.status, Status::Ok);
        let _watch = WatchResult::decode(&watch.body).unwrap();
        let mut snapshot = pending_state;
        while snapshot
            .last()
            .is_none_or(|event| event.phase != Phase::SnapshotEnd)
        {
            snapshot.push(next_channel_state(&mut listener, &listener_codec).await);
        }
        assert_eq!(snapshot.first().unwrap().phase, Phase::SnapshotBegin);
        assert!(snapshot.iter().all(|event| event.records.is_empty()));

        let operation_id = [0x31; 16];
        let listen = yas_channel::Listen {
            operation_id,
            name: "native.echo".to_owned(),
            metadata: b"listener-meta".to_vec(),
            extensions: Extensions::default(),
        };
        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            11,
            &listen,
        )
        .await;
        let (listened, mut state_events) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::LISTEN,
            11,
        )
        .await;
        assert_eq!(listened.status, Status::Ok);
        let identity = yas_channel::ListenerIdentity::decode(&listened.body).unwrap();
        if !state_events.iter().any(|event| event.phase == Phase::Delta) {
            state_events.push(next_channel_state(&mut listener, &listener_codec).await);
        }
        let added = state_events
            .iter()
            .find(|event| event.phase == Phase::Delta)
            .and_then(|event| event.records.first())
            .and_then(|record| yas_channel::ListenerRecord::from_state_record(record).ok())
            .expect("listener ADD delivered");
        assert_eq!(added.listener_handle, identity.listener_handle);
        assert_eq!(added.owner_session, listener_hello.session_id);

        // LISTEN operation IDs replay the exact committed identity.
        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            12,
            &listen,
        )
        .await;
        let (replayed, replay_state) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::LISTEN,
            12,
        )
        .await;
        assert_eq!(replayed.status, Status::Ok);
        assert_eq!(replayed.body, listened.body);
        assert!(replay_state.is_empty());

        let mut conflicting_listen = listen.clone();
        conflicting_listen.metadata = b"conflicting-listener-meta".to_vec();
        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            130,
            &conflicting_listen,
        )
        .await;
        let (conflict, conflict_state) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::LISTEN,
            130,
        )
        .await;
        assert_eq!(conflict.status, Status::Conflict);
        assert!(conflict_state.is_empty());

        let stale = yas_channel::Connect {
            listener_handle: identity.listener_handle,
            generation: identity.generation + 1,
            initial_receive_credit: 1024,
            metadata: b"connector-meta".to_vec(),
            extensions: Extensions::default(),
        };
        write_request(
            &mut connector,
            &connector_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::CONNECT,
            20,
            &stale,
        )
        .await;
        let (stale_result, _) = next_channel_result_collecting_state(
            &mut connector,
            &connector_codec,
            yas_wire::schema::channel::request::CONNECT,
            20,
        )
        .await;
        assert_eq!(stale_result.status, Status::Conflict);

        let connect = yas_channel::Connect {
            generation: identity.generation,
            ..stale
        };
        write_request(
            &mut connector,
            &connector_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::CONNECT,
            21,
            &connect,
        )
        .await;
        let (connected, _) = next_channel_result_collecting_state(
            &mut connector,
            &connector_codec,
            yas_wire::schema::channel::request::CONNECT,
            21,
        )
        .await;
        assert_eq!(connected.status, Status::Ok);
        let connector_endpoint = yas_channel::ChannelEndpoint::decode(&connected.body).unwrap();
        assert_eq!(connector_endpoint.descriptor.receiver_send_credit, 0);
        assert!(connector_endpoint.descriptor.sender_send_credit > 0);
        assert_eq!(
            connector_endpoint.descriptor.max_item_bytes,
            connector_endpoint.descriptor.sender_send_credit,
        );
        let accept_frame = next_frame(&mut listener, &listener_codec).await;
        assert_eq!(
            accept_frame.header,
            FrameHeader {
                sensitive: true,
                ..FrameHeader::event(family::CHANNEL, yas_wire::schema::channel::event::ACCEPT,)
            }
        );
        let accepted = yas_channel::Accept::decode(&accept_frame.payload).unwrap();
        assert_eq!(accepted.listener_handle, identity.listener_handle);
        assert_eq!(accepted.endpoint.descriptor.sender_send_credit, 0);
        assert_eq!(
            accepted.endpoint.descriptor.max_item_bytes,
            accepted.endpoint.descriptor.receiver_send_credit,
        );
        assert_eq!(
            accepted.endpoint.descriptor.max_item_bytes,
            connector_endpoint.descriptor.max_item_bytes,
        );
        assert_eq!(accepted.endpoint.peer_session, connector_hello.session_id);

        for fragment in [
            MessageData {
                transfer_id: accepted.endpoint.descriptor.transfer_id,
                sequence: 7,
                fragment_offset: 0,
                start: true,
                end: false,
                data: b"hello ".to_vec(),
            },
            MessageData {
                transfer_id: accepted.endpoint.descriptor.transfer_id,
                sequence: 7,
                fragment_offset: 6,
                start: false,
                end: true,
                data: b"world".to_vec(),
            },
        ] {
            write_sensitive_transfer_event(
                &mut listener,
                &listener_codec,
                yas_wire::schema::transfer::event::MESSAGE_DATA,
                &fragment,
            )
            .await;
        }
        let mut message = Vec::new();
        for _ in 0..2 {
            let frame = next_frame(&mut connector, &connector_codec).await;
            assert!(frame.header.sensitive);
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(
                        family::TRANSFER,
                        yas_wire::schema::transfer::event::MESSAGE_DATA,
                    )
                }
            );
            let fragment = MessageData::decode(&frame.payload).unwrap();
            assert_eq!(
                fragment.transfer_id,
                connector_endpoint.descriptor.transfer_id
            );
            message.extend_from_slice(&fragment.data);
        }
        assert_eq!(message, b"hello world");

        write_event(
            &mut listener,
            &listener_codec,
            family::TRANSFER,
            yas_wire::schema::transfer::event::CREDIT,
            &Credit {
                transfer_id: accepted.endpoint.descriptor.transfer_id,
                cumulative_limit: 128,
            },
        )
        .await;
        let credit_frame = next_frame(&mut connector, &connector_codec).await;
        let credit = Credit::decode(&credit_frame.payload).unwrap();
        assert_eq!(
            credit.transfer_id,
            connector_endpoint.descriptor.transfer_id
        );
        assert_eq!(credit.cumulative_limit, 128);
        write_sensitive_transfer_event(
            &mut connector,
            &connector_codec,
            yas_wire::schema::transfer::event::MESSAGE_DATA,
            &MessageData {
                transfer_id: connector_endpoint.descriptor.transfer_id,
                sequence: 9,
                fragment_offset: 0,
                start: true,
                end: true,
                data: b"reply".to_vec(),
            },
        )
        .await;
        let reply_frame = next_frame(&mut listener, &listener_codec).await;
        assert!(reply_frame.header.sensitive);
        assert_eq!(
            MessageData::decode(&reply_frame.payload).unwrap().data,
            b"reply"
        );

        // Closing the listener only releases the name; the accepted pair is
        // independent and continues carrying messages.
        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::CLOSE_LISTENER,
            13,
            &identity,
        )
        .await;
        let (closed, mut close_state) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::CLOSE_LISTENER,
            13,
        )
        .await;
        assert_eq!(closed.status, Status::Ok);
        if !close_state.iter().any(|event| event.phase == Phase::Delta) {
            close_state.push(next_channel_state(&mut listener, &listener_codec).await);
        }
        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            131,
            &listen,
        )
        .await;
        let (stale_replay, stale_state) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::LISTEN,
            131,
        )
        .await;
        assert_eq!(stale_replay.status, Status::Stale);
        assert!(stale_state.is_empty());
        write_sensitive_transfer_event(
            &mut listener,
            &listener_codec,
            yas_wire::schema::transfer::event::MESSAGE_DATA,
            &MessageData {
                transfer_id: accepted.endpoint.descriptor.transfer_id,
                sequence: 8,
                fragment_offset: 0,
                start: true,
                end: true,
                data: b"still-live".to_vec(),
            },
        )
        .await;
        let still_live = next_frame(&mut connector, &connector_codec).await;
        assert_eq!(
            MessageData::decode(&still_live.payload).unwrap().data,
            b"still-live"
        );

        let second_listen = yas_channel::Listen {
            operation_id: [0x32; 16],
            name: "native.cleanup".to_owned(),
            metadata: Vec::new(),
            extensions: Extensions::default(),
        };
        write_request(
            &mut listener,
            &listener_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::LISTEN,
            14,
            &second_listen,
        )
        .await;
        let (second, mut second_state) = next_channel_result_collecting_state(
            &mut listener,
            &listener_codec,
            yas_wire::schema::channel::request::LISTEN,
            14,
        )
        .await;
        assert_eq!(second.status, Status::Ok);
        if !second_state.iter().any(|event| event.phase == Phase::Delta) {
            second_state.push(next_channel_state(&mut listener, &listener_codec).await);
        }
        let second_identity = yas_channel::ListenerIdentity::decode(&second.body).unwrap();

        write_request(
            &mut connector,
            &connector_codec,
            family::CHANNEL,
            yas_wire::schema::channel::request::WATCH,
            22,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let (watch, pending) = next_channel_result_collecting_state(
            &mut connector,
            &connector_codec,
            yas_wire::schema::channel::request::WATCH,
            22,
        )
        .await;
        assert_eq!(watch.status, Status::Ok);
        let mut snapshot = pending;
        while snapshot
            .last()
            .is_none_or(|event| event.phase != Phase::SnapshotEnd)
        {
            snapshot.push(next_channel_state(&mut connector, &connector_codec).await);
        }
        assert!(
            snapshot
                .iter()
                .flat_map(|event| &event.records)
                .any(|record| {
                    yas_channel::ListenerRecord::from_state_record(record).is_ok_and(|record| {
                        record.listener_handle == second_identity.listener_handle
                    })
                })
        );

        drop(listener);
        timeout(TEST_TIMEOUT, listener_task).await.unwrap().unwrap();
        let removed = loop {
            let frame = next_frame(&mut connector, &connector_codec).await;
            if frame.header.family == family::CHANNEL {
                let event = StateEvent::decode(&frame.payload).unwrap();
                if event.phase == Phase::Delta {
                    break event;
                }
            } else {
                assert_eq!(frame.header.family, family::TRANSFER);
                assert_eq!(frame.header.kind, yas_wire::schema::transfer::event::RESET);
            }
        };
        assert!(removed.records.iter().any(|record| {
            yas_channel::RemovedListener::from_state_record(record)
                .is_ok_and(|record| record.listener_handle == second_identity.listener_handle)
        }));

        drop(connector);
        timeout(TEST_TIMEOUT, connector_task)
            .await
            .unwrap()
            .unwrap();
    }

    async fn next_client_terminal_subscription_count(
        client: &mut DuplexStream,
        codec: &FrameCodec,
        session_id: [u8; 16],
        expected: usize,
    ) -> yas_client::ActiveSubscriptions {
        timeout(TEST_TIMEOUT, async {
            loop {
                let frame = next_frame(client, codec).await;
                assert_eq!(frame.header.family, family::CLIENT);
                assert_eq!(frame.header.kind, yas_wire::schema::client::event::STATE);
                assert_eq!(frame.header.class, Class::Event);
                assert!(frame.header.sensitive);
                let event = StateEvent::decode(&frame.payload).unwrap();
                for state_record in &event.records {
                    let Ok(record) = yas_client::client_from_state_record(state_record) else {
                        continue;
                    };
                    if record.session_id != session_id {
                        continue;
                    }
                    let active = record
                        .active_subscriptions()
                        .expect("native Client subscription extension is valid")
                        .expect("native Client row carries active subscriptions");
                    if active.terminals.len() == expected {
                        return active;
                    }
                }
            }
        })
        .await
        .expect("Client watcher observed active Terminal subscriptions")
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn client_watch_projects_transactional_terminal_view_lifecycle() {
        let process_service = super::super::process::Server::new(false, true);
        let state = super::super::tests::process_transport::test_state(process_service.clone());
        let (mut watcher, watcher_codec, _watcher_hello, watcher_task) =
            start_registered_session(state.clone(), &[family::CLIENT]).await;
        let (mut target, target_codec, target_hello, target_task) =
            start_registered_session(state.clone(), &[family::TERMINAL]).await;
        assert!(
            target_hello
                .families
                .iter()
                .all(|descriptor| descriptor.family_id != family::CLIENT),
            "the target must publish subscriptions without negotiating Client",
        );

        write_request(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::WATCH,
            1,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let watched = next_result(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::WATCH,
            1,
        )
        .await;
        assert_eq!(watched.status, Status::Ok);
        let subscription_id = WatchResult::decode(&watched.body).unwrap().subscription_id;
        loop {
            let frame = next_frame(&mut watcher, &watcher_codec).await;
            assert_eq!(frame.header.family, family::CLIENT);
            let event = StateEvent::decode(&frame.payload).unwrap();
            assert_eq!(event.subscription_id, subscription_id);
            if event.phase == Phase::SnapshotEnd {
                break;
            }
        }

        let mut pending_frames = Vec::new();
        write_request(
            &mut target,
            &target_codec,
            family::TERMINAL,
            yas_wire::schema::terminal::request::CREATE,
            10,
            &yas_terminal::Create {
                rows: 24,
                cols: 80,
                operation_id: [0x71; 16],
                launch: yas_terminal::Launch {
                    command: yas_terminal::Command::Argv(vec![
                        b"/bin/sh".to_vec(),
                        b"-c".to_vec(),
                        b"exec cat".to_vec(),
                    ]),
                    cwd: yas_terminal::Cwd::ServerDefault,
                    environment_base: yas_terminal::EnvironmentBase::Server,
                    environment: Vec::new(),
                    extensions: Extensions::default(),
                },
                extensions: Extensions::default(),
            },
        )
        .await;
        let created = next_terminal_result(
            &mut target,
            &target_codec,
            yas_wire::schema::terminal::request::CREATE,
            10,
            &mut pending_frames,
        )
        .await;
        assert_eq!(created.status, Status::Ok);
        let created = yas_terminal::CreateResult::decode(&created.body).unwrap();
        let open = |rows, cols| yas_terminal::OpenView {
            terminal_handle: created.terminal_handle,
            rows,
            cols,
            max_fps: 60,
            codec_versions: vec![1],
            extensions: Extensions::default(),
        };

        let mut opened = Vec::new();
        for (request_id, rows, cols) in [(11, 24, 80), (12, 12, 40)] {
            write_request(
                &mut target,
                &target_codec,
                family::TERMINAL,
                yas_wire::schema::terminal::request::OPEN_VIEW,
                request_id,
                &open(rows, cols),
            )
            .await;
            let result = next_terminal_result(
                &mut target,
                &target_codec,
                yas_wire::schema::terminal::request::OPEN_VIEW,
                request_id,
                &mut pending_frames,
            )
            .await;
            assert_eq!(result.status, Status::Ok);
            opened.push(yas_terminal::OpenViewResult::decode(&result.body).unwrap());
        }

        let active = next_client_terminal_subscription_count(
            &mut watcher,
            &watcher_codec,
            target_hello.session_id,
            2,
        )
        .await;
        assert_eq!(
            active.terminals,
            vec![
                yas_client::TerminalSubscription {
                    terminal_handle: created.terminal_handle,
                    view_id: opened[0].view_id,
                    rows: 24,
                    columns: 80,
                },
                yas_client::TerminalSubscription {
                    terminal_handle: created.terminal_handle,
                    view_id: opened[1].view_id,
                    rows: 12,
                    columns: 40,
                },
            ]
        );

        // Keep the connection-local view while invalidating its backend. A
        // rejected CONFIGURE_VIEW must not leak any staged values into the
        // shared Client projection.
        {
            let mut shared = state.session.lock().await;
            let pty_id = shared
                .terminal_backend(created.terminal_handle)
                .expect("created Terminal backend");
            shared.native_terminal_views.remove_backend(pty_id);
        }
        let rejected_configuration = yas_terminal::ConfigureView {
            view_id: opened[0].view_id,
            configuration: yas_terminal::ViewConfiguration {
                rows: Some(33),
                cols: Some(99),
                max_fps: Some(30),
                presentation_metrics: Some(yas_terminal::PresentationMetrics {
                    viewport_width_px: 990,
                    viewport_height_px: 330,
                    cell_width_16_16: 10 << 16,
                    cell_height_16_16: 10 << 16,
                    device_scale_16_16: 1 << 16,
                }),
                queue_target: Some(2),
            },
            extensions: Extensions::default(),
        };
        for request_id in [13, 14] {
            write_request(
                &mut target,
                &target_codec,
                family::TERMINAL,
                yas_wire::schema::terminal::request::CONFIGURE_VIEW,
                request_id,
                &rejected_configuration,
            )
            .await;
            assert_eq!(
                next_terminal_result(
                    &mut target,
                    &target_codec,
                    yas_wire::schema::terminal::request::CONFIGURE_VIEW,
                    request_id,
                    &mut pending_frames,
                )
                .await
                .status,
                Status::NotFound,
            );
        }
        let projected = state
            .session
            .lock()
            .await
            .native_yas_clients
            .get(&target_hello.session_id)
            .expect("target remains catalogued")
            .active_subscriptions
            .snapshot();
        assert_eq!(
            projected
                .active
                .terminals
                .iter()
                .find(|view| view.view_id == opened[0].view_id)
                .copied(),
            Some(yas_client::TerminalSubscription {
                terminal_handle: created.terminal_handle,
                view_id: opened[0].view_id,
                rows: 24,
                columns: 80,
            }),
        );

        for (request_id, view_id, remaining) in [
            (15, opened[0].view_id, 1usize),
            (16, opened[1].view_id, 0usize),
        ] {
            write_request(
                &mut target,
                &target_codec,
                family::TERMINAL,
                yas_wire::schema::terminal::request::CLOSE_VIEW,
                request_id,
                &yas_terminal::CloseView { view_id },
            )
            .await;
            assert_eq!(
                next_terminal_result(
                    &mut target,
                    &target_codec,
                    yas_wire::schema::terminal::request::CLOSE_VIEW,
                    request_id,
                    &mut pending_frames,
                )
                .await
                .status,
                Status::Ok,
            );
            let active = next_client_terminal_subscription_count(
                &mut watcher,
                &watcher_codec,
                target_hello.session_id,
                remaining,
            )
            .await;
            assert_eq!(active.terminals.len(), remaining);
            if remaining == 1 {
                assert_eq!(active.terminals[0].view_id, opened[1].view_id);
            }
        }

        write_request(
            &mut target,
            &target_codec,
            family::TERMINAL,
            yas_wire::schema::terminal::request::CLOSE,
            17,
            &yas_terminal::Close {
                terminal_handle: created.terminal_handle,
                operation_id: [0x72; 16],
            },
        )
        .await;
        assert_eq!(
            next_terminal_result(
                &mut target,
                &target_codec,
                yas_wire::schema::terminal::request::CLOSE,
                17,
                &mut pending_frames,
            )
            .await
            .status,
            Status::Ok,
        );

        drop(target);
        timeout(TEST_TIMEOUT, target_task).await.unwrap().unwrap();
        drop(watcher);
        timeout(TEST_TIMEOUT, watcher_task).await.unwrap().unwrap();
        process_service.shutdown().await;
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn client_watch_disconnect_and_operation_replay_use_typed_yas() {
        let process_server = super::super::tests::process_transport::test_state;
        let state = process_server(super::super::process::Server::new(false, true));
        let (mut watcher, watcher_codec, watcher_hello, watcher_task) =
            start_registered_session(state.clone(), &[family::CLIENT]).await;
        let (target, _target_codec, target_hello, target_task) =
            start_registered_session(state.clone(), &[family::CLIENT]).await;
        for hello in [&watcher_hello, &target_hello] {
            let descriptor = hello
                .families
                .iter()
                .find(|descriptor| descriptor.family_id == family::CLIENT)
                .expect("Client negotiated");
            assert!(descriptor.operations.iter().any(|operation| {
                operation.class == Class::Request
                    && operation.kind == yas_wire::schema::client::request::DISCONNECT
                    && operation.server_accepts
            }));
            assert!(descriptor.operations.iter().any(|operation| {
                operation.class == Class::Event
                    && operation.kind == yas_wire::schema::client::event::STATE
                    && operation.server_sends
            }));
        }
        timeout(TEST_TIMEOUT, async {
            loop {
                let visible_native = state.session.lock().await.native_yas_clients.len();
                if visible_native == 2 {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("native clients registered directly");

        write_request(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::WATCH,
            1,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let watched = next_result(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::WATCH,
            1,
        )
        .await;
        assert_eq!(watched.status, Status::Ok);
        let watched = WatchResult::decode(&watched.body).unwrap();
        let mut records = BTreeMap::new();
        loop {
            let frame = next_frame(&mut watcher, &watcher_codec).await;
            assert_eq!(
                frame.header,
                FrameHeader {
                    sensitive: true,
                    ..FrameHeader::event(family::CLIENT, yas_wire::schema::client::event::STATE,)
                }
            );
            let event = StateEvent::decode(&frame.payload).unwrap();
            assert_eq!(event.subscription_id, watched.subscription_id);
            for state_record in event.records {
                if let Ok(record) = yas_client::client_from_state_record(&state_record) {
                    records.insert(record.session_id, record);
                }
            }
            if event.phase == Phase::SnapshotEnd {
                break;
            }
        }
        assert!(records.contains_key(&watcher_hello.session_id));
        assert!(records.contains_key(&target_hello.session_id));
        assert_eq!(records[&watcher_hello.session_id].client_instance, [7; 16]);

        let operation = yas_client::Disconnect {
            session_id: target_hello.session_id,
            operation_id: [9; 16],
            reason: "native Client test".to_owned(),
        };
        write_request(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::DISCONNECT,
            2,
            &operation,
        )
        .await;
        assert_eq!(
            next_client_result(
                &mut watcher,
                &watcher_codec,
                yas_wire::schema::client::request::DISCONNECT,
                2,
            )
            .await
            .status,
            Status::Ok,
        );
        timeout(TEST_TIMEOUT, target_task)
            .await
            .expect("disconnected native target stops")
            .unwrap();
        drop(target);
        loop {
            let frame = next_frame(&mut watcher, &watcher_codec).await;
            assert_eq!(frame.header.family, family::CLIENT);
            assert_eq!(frame.header.kind, yas_wire::schema::client::event::STATE);
            assert!(frame.header.sensitive);
            let event = StateEvent::decode(&frame.payload).unwrap();
            if event.records.iter().any(|record| {
                yas_client::removal_from_state_record(record)
                    .is_ok_and(|removed| removed.session_id == target_hello.session_id)
            }) {
                break;
            }
        }

        write_request(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::DISCONNECT,
            3,
            &operation,
        )
        .await;
        assert_eq!(
            next_client_result(
                &mut watcher,
                &watcher_codec,
                yas_wire::schema::client::request::DISCONNECT,
                3,
            )
            .await
            .status,
            Status::Ok,
        );
        write_request(
            &mut watcher,
            &watcher_codec,
            family::CLIENT,
            yas_wire::schema::client::request::DISCONNECT,
            4,
            &yas_client::Disconnect {
                reason: "different operation body".to_owned(),
                ..operation
            },
        )
        .await;
        assert_eq!(
            next_client_result(
                &mut watcher,
                &watcher_codec,
                yas_wire::schema::client::request::DISCONNECT,
                4,
            )
            .await
            .status,
            Status::Conflict,
        );

        drop(watcher);
        timeout(TEST_TIMEOUT, watcher_task)
            .await
            .expect("watcher session stops")
            .unwrap();
    }

    #[cfg(unix)]
    fn add_test_surface(shared: &mut super::super::Session, surface_id: u16) -> u64 {
        shared.ensure_compositor(false, Arc::new(|| {}), "");
        shared.compositor.as_mut().unwrap().surfaces.insert(
            surface_id,
            super::super::CachedSurfaceInfo {
                #[cfg(target_os = "linux")]
                surface_id,
                parent_id: 0,
                origin: None,
                width: 640,
                height: 360,
                logical_width: 640,
                logical_height: 360,
                title: "native surface".to_owned(),
                app_id: "yas.test".to_owned(),
            },
        );
        shared
            .surface_handles
            .get_or_insert(surface_id)
            .expect("test Surface handle")
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "multi_thread")]
    async fn surface_focus_with_cursor_keeps_watch_and_catalogue_stable() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let surface_handle = {
            let mut shared = state.session.lock().await;
            let surface_handle = add_test_surface(&mut shared, 7);
            shared
                .compositor
                .as_mut()
                .unwrap()
                .surface_cursors
                .insert(7, yas_surface::CursorState::Named("pointer".to_owned()));
            surface_handle
        };
        let (mut client, codec, _hello, server_task) =
            start_registered_session(state, &[family::SURFACE]).await;

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::WATCH,
            100,
            &Watch {
                initial_credit: 1024 * 1024,
                resume: None,
                extensions: Extensions::default(),
            },
        )
        .await;
        let watched = next_result(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::WATCH,
            100,
        )
        .await;
        assert_eq!(watched.status, Status::Ok);
        let subscription_id = WatchResult::decode(&watched.body).unwrap().subscription_id;
        let catalogue_revision = loop {
            let event = StateEvent::decode(&next_frame(&mut client, &codec).await.payload).unwrap();
            assert_eq!(event.subscription_id, subscription_id);
            if event.phase == Phase::SnapshotEnd {
                break event.to_revision;
            }
        };

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::FOCUS,
            101,
            &yas_surface::Focus {
                surface_handle,
                operation_id: test_operation_id(39_000),
                focused: true,
                extensions: Extensions::default(),
            },
        )
        .await;
        let focused = next_result(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::FOCUS,
            101,
        )
        .await;
        assert_eq!(focused.status, Status::Ok);
        assert_eq!(
            yas_surface::RevisionResult::decode(&focused.body)
                .unwrap()
                .state_revision,
            catalogue_revision,
            "viewer focus must not synthesize application activation state",
        );

        // Before this regression, appending activation tag 1 after the cursor
        // tag 2 made the watch encoder exit and cancel the whole connection.
        let _ = server_diagnostics(&mut client, &codec, 102).await;

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "multi_thread")]
    async fn surface_mutation_replays_supersede_and_close_retires_at_remove() {
        let state = super::super::tests::process_transport::test_state(
            super::super::process::Server::new(false, true),
        );
        let surface_handle = {
            let mut shared = state.session.lock().await;
            add_test_surface(&mut shared, 7)
        };
        let (mut client, codec, _hello, server_task) =
            start_registered_session(state.clone(), &[family::SURFACE]).await;

        let mut current_focus = None;
        for value in 0..300u64 {
            let focus = yas_surface::Focus {
                surface_handle,
                operation_id: test_operation_id(40_000 + value),
                focused: false,
                extensions: Extensions::default(),
            };
            write_request(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::FOCUS,
                1000 + u32::try_from(value).unwrap(),
                &focus,
            )
            .await;
            let result = next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::FOCUS,
                1000 + u32::try_from(value).unwrap(),
            )
            .await;
            assert_eq!(result.status, Status::Ok);
            current_focus = Some((focus, result));
        }
        let (current_focus, current_result) = current_focus.unwrap();

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::FOCUS,
            1400,
            &current_focus,
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::FOCUS,
                1400,
            )
            .await,
            current_result,
            "exact current replay does not advance the catalogue revision",
        );

        let failed_successor = yas_surface::Focus {
            surface_handle,
            operation_id: test_operation_id(50_000),
            focused: false,
            extensions: Extensions(vec![Extension {
                tag: u16::MAX,
                required: true,
                value: Vec::new(),
            }]),
        };
        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::FOCUS,
            1401,
            &failed_successor,
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::FOCUS,
                1401,
            )
            .await
            .status,
            Status::Unsupported,
        );
        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::FOCUS,
            1402,
            &current_focus,
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::FOCUS,
                1402,
            )
            .await,
            current_result,
            "failed successor preserves the prior replay settlement",
        );

        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::RESIZE,
            1403,
            &yas_surface::Resize {
                surface_handle,
                operation_id: current_focus.operation_id,
                logical_width_32_32: 800_i64 << 32,
                logical_height_32_32: 450_i64 << 32,
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::RESIZE,
                1403,
            )
            .await
            .status,
            Status::Conflict,
            "retained operation IDs conflict across Surface mutation kinds",
        );

        let close = yas_surface::Close {
            surface_handle,
            operation_id: test_operation_id(60_000),
            extensions: Extensions::default(),
        };
        for request_id in [1404, 1405] {
            write_request(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::CLOSE,
                request_id,
                &close,
            )
            .await;
            assert_eq!(
                next_result(
                    &mut client,
                    &codec,
                    family::SURFACE,
                    yas_wire::schema::surface::request::CLOSE,
                    request_id,
                )
                .await
                .status,
                Status::Ok,
            );
        }
        write_request(
            &mut client,
            &codec,
            family::SURFACE,
            yas_wire::schema::surface::request::CLOSE,
            1406,
            &yas_surface::Close {
                surface_handle,
                operation_id: test_operation_id(60_001),
                extensions: Extensions::default(),
            },
        )
        .await;
        assert_eq!(
            next_result(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::CLOSE,
                1406,
            )
            .await
            .status,
            Status::Conflict,
            "one fresh CLOSE identity owns the live target",
        );

        state
            .session
            .lock()
            .await
            .compositor
            .as_mut()
            .unwrap()
            .surfaces
            .remove(&7);
        state
            .surface_catalogue_updates
            .send_modify(|revision| *revision = revision.wrapping_add(1));
        timeout(TEST_TIMEOUT, async {
            for request_id in 1500..1600 {
                write_request(
                    &mut client,
                    &codec,
                    family::SURFACE,
                    yas_wire::schema::surface::request::CLOSE,
                    request_id,
                    &close,
                )
                .await;
                let status = next_result(
                    &mut client,
                    &codec,
                    family::SURFACE,
                    yas_wire::schema::surface::request::CLOSE,
                    request_id,
                )
                .await
                .status;
                if status == Status::NotFound {
                    return;
                }
                assert_eq!(status, Status::Ok);
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
            panic!("Surface REMOVE did not retire CLOSE replay");
        })
        .await
        .expect("Surface REMOVE replay retirement");

        drop(client);
        timeout(TEST_TIMEOUT, server_task).await.unwrap().unwrap();
    }

    #[cfg(unix)]
    async fn send_hidden_surface_frame(
        state: &AppState,
        surface_id: u16,
        target: (u16, u16),
        timestamp_ms: u32,
        timestamp_sub_us: u16,
        keyframe: bool,
        data: Vec<u8>,
    ) {
        timeout(TEST_TIMEOUT, async {
            loop {
                let sent = {
                    let shared = state.session.lock().await;
                    shared.clients.values().find_map(|client| {
                        (!client.catalog_visible
                            && client
                                .surface_subs
                                .get(&surface_id)
                                .is_some_and(|subscription| {
                                    subscription.scaled_target == Some(target)
                                }))
                        .then(|| {
                            super::super::yas_surface_backend::enqueue_frame(
                                client,
                                super::super::yas_surface_backend::EncodedFrame {
                                    color_space: yas_compositor::color::OutputColor::Srgb.cicp(),
                                    logical_size: shared
                                        .compositor
                                        .as_ref()
                                        .and_then(|c| c.surfaces.get(&surface_id))
                                        .and_then(super::super::CachedSurfaceInfo::logical_size),
                                    surface_id,
                                    timestamp_ms,
                                    timestamp_sub_us,
                                    width: u32::from(target.0),
                                    height: u32::from(target.1),
                                    codec: super::super::yas_surface_backend::Codec::H264,
                                    keyframe,
                                    data: data.clone(),
                                },
                            )
                            .is_ok()
                        })
                    })
                };
                if sent == Some(true) {
                    return;
                }
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("hidden Surface view subscribed");
    }

    #[cfg(unix)]
    fn large_h264_test_frame(len: usize) -> Vec<u8> {
        let mut data = vec![0x5a; len.max(6)];
        data[..6].copy_from_slice(&[0, 0, 0, 1, 0x65, 0x88]);
        data
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread")]
    async fn surface_open_wait_keeps_resize_cancel_and_disconnect_responsive() {
        for cancel in [false, true] {
            let state = super::super::tests::process_transport::test_state(
                super::super::process::Server::new(false, true),
            );
            let surface_handle = {
                let mut shared = state.session.lock().await;
                add_test_surface(&mut shared, 7)
            };
            let (mut client, codec, hello, server_task) =
                start_registered_session(state.clone(), &[family::SURFACE]).await;
            write_request(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::OPEN_VIEW,
                10,
                &yas_surface::OpenView {
                    surface_handle,
                    width: 320,
                    height: 180,
                    max_fps: 60,
                    decoder_capacity: 3,
                    codec_versions: vec![
                        yas_wire::schema::surface::CODEC_H264_V1 as u16,
                        yas_wire::schema::surface::CODEC_AV1_V1 as u16,
                    ],
                    extensions: Extensions::default(),
                },
            )
            .await;
            // No encoder frame arrives. A replacement pane must still resize and
            // the old connection must release its claims as soon as it closes.
            write_request(
                &mut client,
                &codec,
                family::SURFACE,
                yas_wire::schema::surface::request::RESIZE,
                11,
                &yas_surface::Resize {
                    surface_handle,
                    operation_id: [8; 16],
                    logical_width_32_32: 800_i64 << 32,
                    logical_height_32_32: 450_i64 << 32,
                    extensions: Extensions::default(),
                },
            )
            .await;
            let resized = timeout(
                Duration::from_secs(1),
                next_result(
                    &mut client,
                    &codec,
                    family::SURFACE,
                    yas_wire::schema::surface::request::RESIZE,
                    11,
                ),
            )
            .await
            .expect("RESIZE must not await the 30-second codec timeout");
            assert_eq!(resized.status, Status::Ok);
            assert_eq!(
                state.session.lock().await.native_surface_claims[&(hello.session_id, 7)],
                (800, 450, 120),
            );
            if cancel {
                write_request(
                    &mut client,
                    &codec,
                    family::CORE,
                    yas_wire::core::request_kind::CANCEL,
                    12,
                    &Cancel {
                        target_request_id: 10,
                    },
                )
                .await;
                assert_eq!(
                    next_result(
                        &mut client,
                        &codec,
                        family::CORE,
                        yas_wire::core::request_kind::CANCEL,
                        12,
                    )
                    .await
                    .status,
                    Status::Ok
                );
                let cancelled = next_result(
                    &mut client,
                    &codec,
                    family::SURFACE,
                    yas_wire::schema::surface::request::OPEN_VIEW,
                    10,
                )
                .await;
                assert_eq!(cancelled.status, Status::Cancelled);
            }
            drop(client);
            timeout(Duration::from_secs(1), server_task)
                .await
                .expect("client disconnect must not await codec selection")
                .unwrap();
            timeout(Duration::from_secs(1), async {
                loop {
                    let shared = state.session.lock().await;
                    if shared.clients.is_empty()
                        && !shared
                            .native_surface_claims
                            .contains_key(&(hello.session_id, 7))
                        && !shared.native_yas_clients.contains_key(&hello.session_id)
                    {
                        break;
                    }
                    drop(shared);
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("provisional view and size claim must be released");
        }
    }

    #[cfg(unix)]
